#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_DEVICES 10000

typedef struct {
    int deviceID;
    char status[50];
    time_t lastUpdate;
    float connectionMetrics;
} DeviceStatus;

DeviceStatus devices[MAX_DEVICES];
int deviceCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* updateDeviceStatus(void* arg) {
    int id = *(int*)arg;
    // Simulate fetching real-time connection metrics from REST API
    pthread_mutex_lock(&lock);
    if (id < deviceCount) {
        devices[id].connectionMetrics = (float)(rand() % 100); // Dummy value
        time(&devices[id].lastUpdate);
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* monitorInactiveDevices(void* arg) {
    while (1) {
        sleep(60); // Check every minute
        pthread_mutex_lock(&lock);
        for (int i = 0; i < deviceCount; i++) {
            time_t now, lastUpdate;
            time(&now);
            lastUpdate = devices[i].lastUpdate;
            if (difftime(now, lastUpdate) > 3600) { // If inactive for more than 1 hour
                // Remove or mark as inactive in database
                printf("Device %d is inactive. Cleaning up.\n", devices[i].deviceID);
            }
        }
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void initializeLibrary() {
    pthread_t updateThread, monitorThread;
    int ids[MAX_DEVICES];

    for (int i = 0; i < MAX_DEVICES; i++) {
        devices[i].deviceID = i + 1;
        strcpy(devices[i].status, "Active");
        time(&devices[i].lastUpdate);
    }
    deviceCount = MAX_DEVICES;

    pthread_create(&updateThread, NULL, updateDeviceStatus, (void*)&ids[0]);
    pthread_create(&monitorThread, NULL, monitorInactiveDevices, NULL);

    pthread_join(updateThread, NULL);
    pthread_join(monitorThread, NULL);
}

int main() {
    initializeLibrary();
    return 0;
}
```

