#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <libpq-fe.h>

#define MAX_RECORDS 1000
#define RETRY_COUNT 3
#define CONN_RETRY_INTERVAL 5

typedef struct {
    long offset;
    int key;
    int value;
} Record;

PGconn* connectToDatabase(const char* connInfo) {
    PGconn* conn = PQconnectdb(connInfo);
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        return NULL;
    }
    return conn;
}

int initAndStoreRecords(const char* connInfo, long offsets[], int keys[], int values[]) {
    PGconn* conn = connectToDatabase(connInfo);
    if (!conn) return -1;

    Record records[MAX_RECORDS];
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = rand() % 1000;
    }

    const char* tableName = "my_table";
    const char* createTableSQL = "CREATE TABLE IF NOT EXISTS my_table (id SERIAL PRIMARY KEY, offset BIGINT, key INT, value INT)";
    PGresult* res = PQexec(conn, createTableSQL);
    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Failed to create table: %s", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return -1;
    }
    PQclear(res);

    int batchSize = 100;
    for (int i = 0; i < MAX_RECORDS; i += batchSize) {
        char insertQuery[2048];
        snprintf(insertQuery, sizeof(insertQuery), "INSERT INTO %s (offset, key, value) VALUES ", tableName);
        for (int j = 0; j < batchSize && i + j < MAX_RECORDS; j++) {
            if (j > 0) strncat(insertQuery, ", ", sizeof(insertQuery));
            snprintf(insertQuery + strlen(insertQuery), sizeof(insertQuery) - strlen(insertQuery),
                     "(%ld, %d, %d)", records[i + j].offset, records[i + j].key, records[i + j].value);
        }

        res = PQexec(conn, insertQuery);
        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            fprintf(stderr, "Failed to insert data: %s", PQerrorMessage(conn));
            PQclear(res);
            PQfinish(conn);
            return -1;
        }
        PQclear(res);
    }

    PQfinish(conn);
    return 0;
}
```

