#include <stdarg.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

#define MAX_LOG_RETRIES 3
#define MIN_RETRY_INTERVAL 60
#define CONGESTION_THRESHOLD 1000

typedef struct {
    char logFilePath[256];
    time_t businessStart;
    time_t businessEnd;
    int maxRetryInterval;
    int congestionThreshold;
} LogManager;

LogManager *logManager = NULL;

pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void initLogManager(const char *logPath, int startHour, int endHour) {
    logManager = (LogManager *)malloc(sizeof(LogManager));
    strncpy(logManager->logFilePath, logPath, sizeof(logManager->logFilePath));
    logManager->businessStart = mktime(&(struct tm){0, 0, startHour, 1, 0, 2000});
    logManager->businessEnd = mktime(&(struct tm){0, 0, endHour, 1, 0, 2000});
    logManager->maxRetryInterval = MIN_RETRY_INTERVAL;
    logManager->congestionThreshold = CONGESTION_THRESHOLD;
}

void logConditionalMessage(const char *condition, ...) {
    va_list args;
    va_start(args, condition);

    time_t now = time(NULL);
    struct tm *localTime = localtime(&now);
    int currentHour = localTime->tm_hour;

    pthread_mutex_lock(&logMutex);

    if (strcmp(condition, "databaseActive") == 0 && currentHour >= 9 && currentHour < 17) {
        char message[256];
        vsnprintf(message, sizeof(message), condition, args);
        FILE *file = fopen(logManager->logFilePath, "a");
        if (file != NULL) {
            fprintf(file, "%s\n", message);
            fclose(file);
        } else {
            int retries = 0;
            while (retries < MAX_LOG_RETRIES) {
                sleep(rand() % logManager->maxRetryInterval);
                file = fopen(logManager->logFilePath, "a");
                if (file != NULL) {
                    fprintf(file, "%s\n", message);
                    fclose(file);
                    break;
                }
                retries++;
            }
            if (retries == MAX_LOG_RETRIES) {
                // Fallback to external logging service
                printf("Error: Unable to log message to file after %d retries. Logging asynchronously.\n", MAX_LOG_RETRIES);
            }
        }
    }

    pthread_mutex_unlock(&logMutex);

    va_end(args);
}

void cleanupLogManager() {
    free(logManager);
    pthread_mutex_destroy(&logMutex);
}
