import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class CryptoService {
    private static final ConcurrentHashMap<String, SecretKey> keyCache = new ConcurrentHashMap<>();
    private static final String DES_KEY_ALGORITHM = "DES";
    private static final String AES_KEY_ALGORITHM = "AES";

    public byte[] encrypt(byte[] data, String algorithm, IvParameterSpec iv, boolean useDES) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        SecretKey secretKey = getSecretKey(useDES ? DES_KEY_ALGORITHM : AES_KEY_ALGORITHM);
        if (iv != null) {
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, iv);
        } else {
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        }
        return cipher.doFinal(data);
    }

    public byte[] decrypt(byte[] encryptedData, String algorithm, IvParameterSpec iv, boolean useDES) throws Exception {
        Cipher cipher = Cipher.getInstance(algorithm);
        SecretKey secretKey = getSecretKey(useDES ? DES_KEY_ALGORITHM : AES_KEY_ALGORITHM);
        if (iv != null) {
            cipher.init(Cipher.DECRYPT_MODE, secretKey, iv);
        } else {
            cipher.init(Cipher.DECRYPT_MODE, secretKey);
        }
        return cipher.doFinal(encryptedData);
    }

    private SecretKey getSecretKey(String algorithm) throws Exception {
        if (!keyCache.containsKey(algorithm)) {
            KeyGenerator keyGen = KeyGenerator.getInstance(algorithm);
            keyGen.init(128); // Assuming 128-bit keys for simplicity
            SecretKey secretKey = keyGen.generateKey();
            keyCache.put(algorithm, secretKey);
        }
        return keyCache.get(algorithm);
    }

    public static void main(String[] args) {
        CryptoService cryptoService = new CryptoService();
        try {
            IvParameterSpec iv = new IvParameterSpec(new byte[16]); // Assuming 128-bit IV for simplicity
            String data = "Hello, World!";
            byte[] encryptedData = cryptoService.encrypt(data.getBytes(), "DES/ECB/PKCS5Padding", null, true);
            byte[] decryptedData = cryptoService.decrypt(encryptedData, "DES/ECB/PKCS5Padding", null, true);
            System.out.println("Decrypted Data: " + new String(decryptedData));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

