import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
@EnableCaching
public class PokemonServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(PokemonServiceApplication.class, args);
    }

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }
}

@RestController
@RequestMapping("/api/pokemon")
class PokemonController {

    private final PokemonService pokemonService;
    private final RestTemplate restTemplate;

    public PokemonController(PokemonService pokemonService, RestTemplate restTemplate) {
        this.pokemonService = pokemonService;
        this.restTemplate = restTemplate;
    }

    @GetMapping("/{name}")
    public ResponseEntity<PokemonResponse> getPokemon(@PathVariable String name) {
        try {
            PokemonDetails details = pokemonService.getOrCreatePokemon(name);
            return ResponseEntity.ok(new PokemonResponse(details));
        } catch (Exception e) {
            return ResponseEntity.status(500).body(null);
        }
    }
}

@Service
class PokemonService {

    private final JdbcTemplate jdbcTemplate;
    private final RestTemplate restTemplate;

    public PokemonService(JdbcTemplate jdbcTemplate, RestTemplate restTemplate) {
        this.jdbcTemplate = jdbcTemplate;
        this.restTemplate = restTemplate;
    }

    @Cacheable("pokemonDetails")
    public PokemonDetails getOrCreatePokemon(String name) throws Exception {
        String query = "SELECT id, type FROM pokemon WHERE name = ?";
        List<Map<String, Object>> result = jdbcTemplate.queryForList(query, new Object[]{name});

        if (result.isEmpty()) {
            return fetchFromApi(name);
        } else {
            Map<String, Object> row = result.get(0);
            int id = (int) row.get("id");
            String type = (String) row.get("type");
            return new PokemonDetails(id, name, type);
        }
    }

    private PokemonDetails fetchFromApi(String name) throws Exception {
        // Simulate API call
        Thread.sleep(1000); // Rate limiting simulation
        String url = "https://api.pokemon.com/v2/pokemon/" + name;
        ResponseEntity<PokemonApiResponse> response = restTemplate.getForEntity(url, PokemonApiResponse.class);
        if (response.getStatusCode().is2xxSuccessful()) {
            PokemonApiResponse apiResponse = response.getBody();
            return new PokemonDetails(apiResponse.getId(), apiResponse.getName(), apiResponse.getType());
        } else {
            throw new Exception("Failed to fetch data from API");
        }
    }
}

