#include <openssl/evp.h>
#include <json-c/json.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Define encryption modes
typedef enum {
    ECB,
    CBC,
    GCM
} EncryptionMode;

// Define configuration structure
typedef struct {
    EncryptionMode mode;
    char *key;
    char *iv;
    // Add other configurable parameters as needed
} Config;

// Function to load configuration from JSON file or command line options
Config load_config(const char *config_file, const char **argv) {
    Config config = {0};
    // Load from JSON file
    json_object *json_obj = json_object_from_file(config_file);
    if (json_obj != NULL) {
        json_object *mode_obj;
        if (json_object_object_get_ex(json_obj, "mode", &mode_obj)) {
            int mode_value = json_object_get_int(mode_obj);
            config.mode = (EncryptionMode)mode_value;
        }
        json_object *key_obj;
        if (json_object_object_get_ex(json_obj, "key", &key_obj)) {
            const char *key_str = json_object_get_string(key_obj);
            strcpy(config.key, key_str);
        }
        // Load other parameters as needed
        json_object_put(json_obj);
    }

    // Override with command line options if provided
    for (int i = 1; argv[i] != NULL; i++) {
        if (strcmp(argv[i], "--mode") == 0 && argv[i + 1] != NULL) {
            config.mode = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--key") == 0 && argv[i + 1] != NULL) {
            strcpy(config.key, argv[++i]);
        }
        // Handle other options as needed
    }

    return config;
}

// Function to encrypt data using OpenSSL
int encrypt_data(const char *data, size_t data_len, const Config *config, unsigned char **out_buf, size_t *out_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return -1;

    int ret;
    switch (config->mode) {
        case ECB:
            ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, config->key, NULL);
            break;
        case CBC:
            ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, config->key, (unsigned char *)config->iv);
            break;
        case GCM:
            // Initialize for GCM mode
            break;
        default:
            EVP_CIPHER_CTX_free(ctx);
            return -1;
    }

    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ret = EVP_EncryptUpdate(ctx, *out_buf, out_len, (unsigned char *)data, data_len);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ret = EVP_EncryptFinal_ex(ctx, *out_buf + *out_len, out_len);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *out_len += *out_len; // Adjust length to include padding
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Function to decrypt data using OpenSSL
int decrypt_data(const unsigned char *data, size_t data_len, const Config *config, unsigned char **out_buf, size_t *out_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return -1;

    int ret;
    switch (config->mode) {
        case ECB:
            ret = EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, config->key, NULL);
            break;
        case CBC:
            ret = EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, config->key, (unsigned char *)config->iv);
            break;
        case GCM:
            // Initialize for GCM mode
            break;
        default:
            EVP_CIPHER_CTX_free(ctx);
            return -1;
    }

    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ret = EVP_DecryptUpdate(ctx, *out_buf, out_len, data, data_len);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ret = EVP_DecryptFinal_ex(ctx, *out_buf + *out_len, out_len);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Main function to demonstrate usage
int main(int argc, const char **argv) {
    Config config = load_config("config.json", argv);
    if (config.mode == 0 || strlen(config.key) == 0) {
        fprintf(stderr, "Invalid configuration\n");
        return -1;
    }

    // Encrypt data
    unsigned char *encrypted_data;
    size_t encrypted_len;
    encrypt_data("Hello, World!", 13, &config, &encrypted_data, &encrypted_len);
    printf("Encrypted Data: %.*s\n", (int)encrypted_len, encrypted_data);

    // Decrypt data
    unsigned char *decrypted_data;
    size_t decrypted_len = encrypted_len;
    decrypt_data(encrypted_data, encrypted_len, &config, &decrypted_data, &decrypted_len);
    printf("Decrypted Data: %.*s\n", (int)decrypted_len, decrypted_data);

    // Free allocated memory
    free(encrypted_data);
    free(decrypted_data);

    return 0;
}
```

This code provides a basic structure for a modular C library that supports encryption and decryption using OpenSSL. It includes functions to load configuration from a JSON file or command line options, encrypt data, and decrypt data. The `main` function demonstrates how to use these functions. Additional features such as network requests, caching mechanisms, asynchronous processing, security enhancements, logging, testing, scalability, memory management, error handling, and documentation are not included but can be added based on specific requirements.']

