#include <forward_list>
#include <string>
#include <mutex>
#include <cstdio>

struct LogEntry {
    std::tm timestamp;
    int severity;
    std::string message;
};

void logError(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vsnprintf(errorLog, sizeof(errorLog), format, args);
    va_end(args);
}

std::mutex logMutex;

bool processLogMessages(std::forward_list<LogEntry>& logs, const std::string& severityFilter, const std::string& keywordFilter, const LogEntry& newEntry) {
    auto it = logs.begin();
    while (it != logs.end()) {
        if ((severityFilter.empty() || severityFilter == logSeverityToString(it->severity)) && 
            (keywordFilter.empty() || it->message.find(keywordFilter) != std::string::npos)) {
            logs.insert_after(it, newEntry);
            return true;
        }
        ++it;
    }
    logs.push_back(newEntry);
    return false;
}

void insertLogEntry(std::forward_list<LogEntry>& logs, const LogEntry& newEntry, const std::string& severityFilter = "", const std::string& keywordFilter = "") {
    std::lock_guard<std::mutex> lock(logMutex);
    if (!processLogMessages(logs, severityFilter, keywordFilter, newEntry)) {
        logError("Failed to insert log entry: %s", newEntry.message.c_str());
    }
}
