// Asynchronous task manager
class TaskManager {
private:
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;

public:
    TaskManager() : stop(false) {}

    void enqueueTask(const std::function<void()>& task) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            tasks.push(task);
        }
        condition.notify_one();
    }

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this]{ return !stop || !tasks.empty(); });

            if (stop && tasks.empty()) {
                break;
            }

            auto task = tasks.front();
            tasks.pop();
            lock.unlock();

            try {
                task();
            } catch (const std::exception& e) {
                Logger().log(ERROR, "Task failed: " + std::string(e.what()));
            }
        }
    }

    void start() {
        std::thread([this]{ worker(); }).detach();
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
    }
};

// Main application class
class Application {
private:
    SandeshClient sandeshClient;
    MessageService messageService;
    TaskManager taskManager;
    Logger logger;

public:
    void run() {
        std::default_random_engine generator;
        std::uniform_int_distribution<int> distribution(1, 5);

        while (true) {
            // Simulate service lifecycle events
            if (!sandeshClient.isServiceRunning()) {
                sandeshClient.startService();
                logger.log(INFO, "Service started");
            }

            // Random delay between 1 to 5 seconds
            std::this_thread::sleep_for(std::chrono::seconds(distribution(generator)));

            if (sandeshClient.isServiceRunning()) {
                sandeshClient.stopService();
                logger.log(INFO, "Service stopped");

                // Simulate recovery event with random delay
                std::this_thread::sleep_for(std::chrono::seconds(distribution(generator)));
                sandeshClient.startService();
                logger.log(INFO, "Service restarted");
            }

            // Asynchronously process tasks
            taskManager.enqueueTask([this]{ this->monitorService(); });

            // Simulate high traffic conditions
            for (int i = 0; i < 100; ++i) {
                taskManager.enqueueTask([this]{ this->handleRequest(); });
            }
        }
    }

private:
    void monitorService() {
        if (!sandeshClient.isServiceRunning()) {
            logger.log(CRITICAL, "Service is not running");
            messageService.sendMessage("CRITICAL: Service is not running");
        }
    }

