#include <iostream>
#include <random>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>

namespace rng {

class RandomService {
public:
    static RandomService& get_instance() {
        static std::call_once init_flag;
        std::call_once(init_flag, &RandomService::init);
        return instance;
    }

    int get_random() {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& rng = thread_rng_[std::this_thread::get_id()];
        return std::uniform_int_distribution<>(0, 1000000)(rng);
    }

private:
    RandomService() {
        init_entropy_source();
        init_thread_local_rngs();
    }

    ~RandomService() {
        cleanup_entropy_source();
        for (auto& pair : thread_rng_) {
            pair.second.discard(1000); // Discard unused random numbers
        }
    }

    static void init() {
        instance = *new RandomService;
    }

    void init_entropy_source() {
        entropy_file_.open("/dev/urandom", std::ios::in | std::ios::binary);
        if (!entropy_file_) {
            throw std::runtime_error("Failed to open entropy source");
        }
    }

    void cleanup_entropy_source() {
        entropy_file_.close();
    }

    void init_thread_local_rngs() {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            thread_rng_[std::this_thread::get_id()] = std::mt19937(entropy_source());
        }
    }

    unsigned int entropy_source() {
        unsigned int value;
        entropy_file_.read(reinterpret_cast<char*>(&value), sizeof(value));
        if (!entropy_file_) {
            throw std::runtime_error("Failed to read from entropy source");
        }
        return value;
    }

    static RandomService instance;
    std::mutex mutex_;
    std::unordered_map<std::thread::id, std::mt19937> thread_rng_;
    std::ifstream entropy_file_;
};

RandomService RandomService::instance;

} // namespace rng

int main() {
    auto& random_service = rng::RandomService::get_instance();
    for (int i = 0; i < 10; ++i) {
        std::thread([random_service]() {
            for (int j = 0; j < 100; ++j) {
                std::cout << random_service.get_random() << " ";
            }
            std::cout << std::endl;
        }).detach();
    }

    return 0;
}
```

This code snippet provides a basic implementation of the `RandomService` class within the `rng` namespace. It includes methods for initializing and cleaning up resources, managing thread-local RNG instances using Mersenne Twister, and generating random numbers. The `get_random()` method ensures thread safety by locking a mutex during each call. Error handling is included for cases where the external entropy source fails to open or read data. The library uses thread-local storage to minimize overhead while ensuring that each thread has its own RNG instance.']

