using System.Threading.Tasks;

public class DatabaseManager
{
    private readonly string _connectionString;

    public DatabaseManager(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task ExecuteSecureCommandAsync(string sql, params SqlParameter[] parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            try
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(sql, connection))
                {
                    command.Parameters.AddRange(parameters);
                    var stopwatch = Stopwatch.StartNew();
                    await command.ExecuteNonQueryAsync();
                    stopwatch.Stop();
                    LogCommandExecution("Success", stopwatch.ElapsedMilliseconds);
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == -2) // Timeout
                {
                    LogCommandExecution("Error", "Timeout");
                }
                else
                {
                    LogCommandExecution("Error", ex.Message);
                }
                throw;
            }
            catch (Exception ex)
            {
                LogCommandExecution("Error", $"Unhandled exception: {ex.Message}");
                throw;
            }
        }
    }

    private void LogCommandExecution(string status, object data)
    {
        // Implement logging mechanism here
    }
}

public class SqlParameterFactory
{
    public static SqlParameter CreateParameter(string name, SqlDbType dbType, object value)
    {
        return new SqlParameter(name, dbType) { Value = value };
    }
}
