    public interface IWeatherCache
    {
        Task<T> GetAsync<T>(string key);
        Task SetAsync<T>(string key, T value, TimeSpan expiration);
    }

    public class MemoryWeatherCache : IWeatherCache
    {
        private readonly ConcurrentDictionary<string, (object Value, DateTime Expiration)> _cache = new();

        public async Task<T> GetAsync<T>(string key)
        {
            if (_cache.TryGetValue(key, out var cacheItem) && cacheItem.Expiration > DateTime.UtcNow)
                return (T)cacheItem.Value;

            return default;
        }

        public async Task SetAsync<T>(string key, T value, TimeSpan expiration)
