    [ApiController]
    [Route("api/[controller]")]
    public class WeatherController : ControllerBase
    {
        private readonly IWeatherCache _weatherCache;
        private readonly IWeatherDataFetcher[] _dataFetchers;
        private readonly ICacheInvalidator _cacheInvalidator;

        public WeatherController(IWeatherCache weatherCache, IEnumerable<IWeatherDataFetcher> dataFetchers, ICacheInvalidator cacheInvalidator)
        {
            _weatherCache = weatherCache;
            _dataFetchers = dataFetchers.ToArray();
            _cacheInvalidator = cacheInvalidator;
        }

        [HttpGet("current/{cities}")]
        public async Task<IActionResult> GetCurrentTemperatures(string cities)
        {
            var cityList = cities.Split(',');
            var cacheKey = $"CurrentTemperatures:{string.Join(",", cityList)}";
            if (await _weatherCache.GetAsync<Dictionary<string, double>>(cacheKey) is Dictionary<string, double> cachedData && DateTime.UtcNow < cachedData["Expiration"])
                return Ok(cachedData);

            var tasks = new List<Task<Dictionary<string, double>>>();
            foreach (var dataFetcher in _dataFetchers)
            {
                tasks.Add(dataFetcher.GetCurrentTemperaturesAsync(cityList));
            }

            var results = await Task.WhenAll(tasks);
            var temperatures = new Dictionary<string, double>();
            foreach (var result in results)
            {
                temperatures.AddRange(result);
            }

            var expiration = DateTime.UtcNow.AddMinutes(15);
            await _weatherCache.SetAsync(cacheKey, new { Temperatures = temperatures, Expiration = expiration }, TimeSpan.FromMinutes(15));

            return Ok(new { Temperatures = temperatures, Expiration = expiration });
        }

        [HttpGet("historical/{city}")]
        public async Task<IActionResult> GetHistoricalTemperatures(string city)
        {
            var cacheKey = $"HistoricalTemperatures:{city}";
            if (await _weatherCache.GetAsync<List<Dictionary<string, double>>>(cacheKey) is List<Dictionary<string, double>> cachedData && DateTime.UtcNow < cachedData[0]["Expiration"])
                return Ok(cachedData);

            var tasks = new List<Task<List<Dictionary<string, double>>>>();
            foreach (var dataFetcher in _dataFetchers)
            {
                tasks.Add(dataFetcher.GetHistoricalTemperaturesAsync(city, DateTime.Now.AddDays(-365), DateTime.Now));
            }

            var results = await Task.WhenAll(tasks);
            var temperatures = new List<Dictionary<string, double>>();
            foreach (var result in results)
            {
                temperatures.AddRange(result);
            }

            var expiration = DateTime.UtcNow.AddMinutes(15);
            await _weatherCache.SetAsync(cacheKey, temperatures.Select(t => new { t, Expiration = expiration }).ToList(), TimeSpan.FromMinutes(15));

            return Ok(temperatures);
        }
    }

    public class WeatherResponse
    {
        public string Name { get; set; }
        public Main Main { get; set; }
    }

