using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;

[Route("api/[controller]")]
[ApiController]
public class ResourceController : ControllerBase
{
    private readonly ApplicationDbContext _context;
    private readonly IConfiguration _configuration;
    private readonly IAuthenticationService _authenticationService;
    private readonly INotificationService _notificationService;

    public ResourceController(ApplicationDbContext context, IConfiguration configuration, IAuthenticationService authenticationService, INotificationService notificationService)
    {
        _context = context;
        _configuration = configuration;
        _authenticationService = authenticationService;
        _notificationService = notificationService;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, Resource resource)
    {
        var existingResource = await _context.Resources.FindAsync(id);

        if (existingResource == null)
        {
            return NotFound();
        }

        var user = await _authenticationService.GetCurrentUserAsync(User);
        if (!user.HasRole("Admin"))
        {
            return Forbid();
        }

        ValidateResource(resource);

        // Handle concurrency
        existingResource.Version++;

        _context.Entry(existingResource).CurrentValues.SetValues(resource);
        await _context.SaveChangesAsync();

        await _notificationService.NotifyClients(id, "Updated");

        return Ok(new { message = "Resource updated successfully" });
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        var existingResource = await _context.Resources.FindAsync(id);

        if (existingResource == null)
        {
            return NotFound();
        }

        var user = await _authenticationService.GetCurrentUserAsync(User);
        if (!user.HasRole("Admin"))
        {
            return Forbid();
        }

        // Handle concurrency
        existingResource.Version++;

        _context.Resources.Remove(existingResource);
        await _context.SaveChangesAsync();

        await _notificationService.NotifyClients(id, "Deleted");

        return Ok(new { message = "Resource deleted successfully" });
    }

    private void ValidateResource(Resource resource)
    {
        var validationRules = _configuration.GetSection("ValidationRules").Get<List<ValidationRule>>();
        foreach (var rule in validationRules)
        {
            if (!ruleValidator.IsResourceValid(resource, rule))
            {
                throw new ValidationException(rule.ErrorMessage);
            }
        }
    }
}

