const fs = require('fs').promises;
const path = require('path');
const { retry } = require('async-retry');

class FileStorageService {
  constructor(baseDirs) {
    this.baseDirs = baseDirs;
  }

  async getMetadata(dir) {
    try {
      const files = await fs.readdir(dir);
      return Promise.all(files.map(file => 
        fs.stat(path.join(dir, file)).then(stat => ({ file, stat }))
      ));
    } catch (error) {
      console.error(`Failed to read directory ${dir}:`, error);
      throw error;
    }
  }

  async getContent(metadata) {
    return Promise.all(metadata.map(async item => {
      try {
        const data = await fs.readFile(path.join(item.stat.isDirectory() ? item.file : path.dirname(item.file), item.file));
        return { ...item, content: data };
      } catch (error) {
        console.error(`Failed to read file ${item.file}:`, error);
        throw error;
      }
    }));
  }

  async aggregateMetadata() {
    let allMetadata = [];
    for (const dir of this.baseDirs) {
      try {
        allMetadata.push(...await retry(() => this.getMetadata(dir), { retries: 3 }));
      } catch (error) {
        console.error(`Failed to aggregate metadata for directory ${dir}:`, error);
        // Fallback strategy: continue with the remaining directories
      }
    }
    return allMetadata;
  }

  async aggregateContent() {
    let allMetadata = await this.aggregateMetadata();
    try {
      return retry(() => this.getContent(allMetadata), { retries: 3 });
    } catch (error) {
      console.error(`Failed to aggregate content:`, error);
      throw error;
    }
  }
}

// Usage
const storageService = new FileStorageService(['/path/to/dir1', '/path/to/dir2']);
storageService.aggregateContent().then(console.log).catch(console.error);
```

This code provides a basic implementation of the described library. It uses Node.js's built-in `fs` and `path` modules to interact with the file system asynchronously. The `retry` function from the `async-retry` package is used for handling integration failures with retries and fallback strategies.

The `FileStorageService` class encapsulates the functionality, with methods for reading metadata and content from directories. It uses Promises for asynchronous operations and error-handling mechanisms to ensure no loss of partial results.

Concurrency and resource management are optimized by using Promise.all to handle multiple file read operations concurrently. However, you would need to consider additional optimizations based on your specific use case, such as implementing a queue or limiting the number of concurrent operations.

The library provides a flexible API for integrating with various downstream systems by exposing methods that can be easily called and handled asynchronously. You may want to extend this class with more functionality as needed, such as support for different file storage services, authentication, or additional error handling mechanisms.

Remember to document any assumptions and limitations in your design when using this library in a production environment."]

["```javascript
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import axios from 'axios';
import { Worker, isMainThread, parentPort, workerData } from 'worker_threads';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function runTests(testsDir, config) {
  const testFiles = collectTestFiles(testsDir);
  const workers = createWorkers(testFiles, config);
  executeTests(workers, config);
}

function collectTestFiles(dir) {
  let files = [];
  fs.readdirSync(dir).forEach(file => {
    const filePath = path.join(dir, file);
    if (fs.statSync(filePath).isDirectory()) {
      files = [...files, ...collectTestFiles(filePath)];
    } else if (path.extname(file) === '.test.js') {
      files.push(filePath);
    }
  });
  return files;
}

function createWorkers(testFiles, config) {
  const workers = [];
  testFiles.forEach((file, index) => {
    const worker = new Worker(__filename, {
      workerData: { file, config },
      type: 'module',
    });
    worker.on('message', (result) => handleTestResult(result));
    worker.on('error', (err) => handleError(err));
    workers.push(worker);
  });
  return workers;
}

function executeTests(workers, config) {
  const batchSize = Math.ceil(workers.length / config.maxConcurrency);
  for (let i = 0; i < batchSize; i++) {
    const batch = workers.slice(i * config.maxConcurrency, (i + 1) * config.maxConcurrency);
    batch.forEach(worker => worker.postMessage({ action: 'run' }));
  }
}

function handleTestResult(result) {
  console.log(`Test ${result.id}: ${result.status}`);
}

function handleError(err) {
  console.error('Error:', err.message);
}

if (isMainThread) {
  const testsDir = process.argv[2];
  const config = {
    maxConcurrency: parseInt(process.env.MAX_CONCURRENCY || '10'),
    retryCount: parseInt(process.env.RETRY_COUNT || '3'),
    timeout: parseInt(process.env.TIMEOUT || '5000'),
  };
  runTests(testsDir, config);
} else {
  const { file, config } = workerData;
  import(file).then((module) => {
    module.default(config)
      .then((result) => parentPort.postMessage(result))
      .catch((err) => parentPort.postMessage({ error: err.message }));
  }).catch((err) => parentPort.postMessage({ error: err.message }));
}
