            const sanitizedScripts = scripts.map(script => ({
                key: script.key,
                code: DOMPurify.sanitize(script.code)
            })).filter(script => script.code);

            // Sort scripts by key for scalability and performance
            sanitizedScripts.sort((a, b) => a.key.localeCompare(b.key));

            // Limit the number of scripts to MAX_SCRIPTS
            const limitedScripts = sanitizedScripts.slice(0, MAX_SCRIPTS);

            // Create footer element
            const footer = document.getElementById('footer');

            // Create script elements for each script
            limitedScripts.forEach(script => {
                const scriptElement = document.createElement('script');
                scriptElement.type = 'text/javascript';
                scriptElement.text = script.code;
                footer.appendChild(scriptElement);
            });

            // Log errors asynchronously
            async function logError(error) {
                try {
                    await fetch(ANALYTICS_SERVICE, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ error })
                    });
                } catch (logError) {
                    console.error('Failed to log analytics error:', logError);
                }
            }

            // Fallback for scripts that fail sanitization or loading
            limitedScripts.forEach(script => {
                scriptElement.onerror = async () => {
                    await logError(`Script ${script.key} failed to load`);
                };
            });
        }

        // Example usage
        const scriptObjects = [
            { key: 'script1', code: 'console.log("Hello, world!");' },
            { key: 'script2', code: "document.body.style.backgroundColor = 'red';" }
        ];

        renderFooterScripts(scriptObjects);
    </script>
</body>
</html>
