### JavaScript Function to Copy Bytes from Buffered Data Chunks

```javascript
function copyBytes(dataChunks, numBytes) {
    let result = Buffer.alloc(numBytes);
    let copied = 0;

    for (let i = 0; i < dataChunks.length && copied < numBytes; i++) {
        if (dataChunks[i].length + copied <= numBytes) {
            // Copy the entire chunk
            result.set(dataChunks[i], copied);
            copied += dataChunks[i].length;
        } else {
            // Copy only a portion of the chunk
            result.set(dataChunks[i].slice(0, numBytes - copied), copied);
            copied = numBytes;
        }
    }

    return result;
}
