            output_file(argv[i] + 3);
        } else if (strcmp(argv[i], "--verbose") == 0) {
            verbose_mode = 1;
        } else {
            asynchronous_html_parse(argv[i], "config.txt");
        }
    }

    return EXIT_SUCCESS;
}

void manpage() {
    printf("Man page for the command-line tool\n");
}

void cache_strategies(const char* strategy) {
    printf("Using caching strategy: %s\n", strategy);
}

void output_file(const char* filename) {
    printf("Output will be written to file: %s\n", filename);
}

void asynchronous_html_parse(const char* url, const char* config_file) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_perform(curl);  // Perform the request, res will get the return code

        /* always cleanup */
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    printf("Parsing HTML asynchronously from URL: %s\n", url);
}
