import java.util.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class EventDisjointPairsService {
    private static final Logger logger = LogManager.getLogger(EventDisjointPairsService.class);
    private UnionFind unionFind;

    public EventDisjointPairsService() {
        this.unionFind = new UnionFind();
    }

    public long countDisjointPairs(List<Event> events) {
        if (events == null || events.isEmpty()) {
            return 0;
        }

        events.sort(Comparator.comparingLong(Event::getStartTimestamp));
        for (int i = 1; i < events.size(); i++) {
            unionFind.union(i - 1, i);
        }

        long disjointPairsCount = 0;
        for (int i = 0; i < events.size() - 1; i++) {
            if (!unionFind.isSameSet(i, i + 1)) {
                disjointPairsCount++;
            }
        }

        return disjointPairsCount;
    }

    private static class UnionFind {
        private int[] parent;

        public UnionFind() {
            this.parent = new int[10_000_001];
            for (int i = 0; i < parent.length; i++) {
                parent[i] = i;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }

        public int find(int x) {
            if (parent[x] == x) {
                return x;
            }
            return parent[x] = find(parent[x]);
        }

        public boolean isSameSet(int x, int y) {
            return find(x) == find(y);
        }
    }

    private static class Event {
        private long startTimestamp;
        private long endTimestamp;

        public Event(long startTimestamp, long endTimestamp) {
            this.startTimestamp = startTimestamp;
            this.endTimestamp = endTimestamp;
        }

        public long getStartTimestamp() {
            return startTimestamp;
        }

        public long getEndTimestamp() {
            return endTimestamp;
        }
    }

    public static void main(String[] args) {
        EventDisjointPairsService service = new EventDisjointPairsService();
        List<Event> events = Arrays.asList(
                new Event(1633072800, 1633076400),
                new Event(1633079100, 1633082700),
                new Event(1633085400, 1633089000)
        );
        long startTime = System.currentTimeMillis();
        long disjointPairsCount = service.countDisjointPairs(events);
        long endTime = System.currentTimeMillis();

        logger.info("Disjoint pairs count: {}", disjointPairsCount);
        logger.info("Cumulative processing time in milliseconds: {}", endTime - startTime);
    }
}
