import java.time.Duration;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.http.ResponseEntity;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
@EnableCaching
public class DataProcessingService {

    private final List<String> apiEndpoints = List.of("https://api1.example.com/data", "https://api2.example.com/data");
    private final RestTemplate restTemplate = new RestTemplate();
    private final StringRedisTemplate redisTemplate;
    private ScheduledExecutorService scheduler;

    public DataProcessingService(RedisConnectionFactory redisConnectionFactory) {
        this.redisTemplate = new StringRedisTemplate(redisConnectionFactory);
        this.scheduler = Executors.newScheduledThreadPool(10);
    }

    @Bean
    public RedisConnectionFactory redisConnectionFactory() {
        // Configure and return the Redis connection factory
        return new LettuceConnectionFactory("localhost");
    }

    @Scheduled(fixedRateString = "5m")
    public void fetchAndProcessData() {
        for (String endpoint : apiEndpoints) {
            scheduler.schedule(() -> fetchData(endpoint), getRandomDelay());
        }
    }

    private Duration getRandomDelay() {
        return Duration.ofMinutes((long) (5 + Math.random() * 5));
    }

    private void fetchData(String endpoint) {
        try {
            ResponseEntity<String> response = restTemplate.getForEntity(endpoint, String.class);
            if (response.getStatusCode().is2xxSuccessful()) {
                storeDataInRedis(response.getBody());
            }
        } catch (Exception e) {
            handleApiFailure(endpoint, e);
        }
    }

    private void storeDataInRedis(String data) {
        redisTemplate.opsForValue().set("processed_data", data, Duration.ofHours(24));
    }

    private void handleApiFailure(String endpoint, Exception e) {
        // Log the error and attempt to fetch from cache
        logError(endpoint, e);
        String cachedData = redisTemplate.opsForValue().get("processed_data");
        if (cachedData != null) {
            processCachedData(cachedData);
        }
    }

    private void logError(String endpoint, Exception e) {
