<?php

use Psr\Container\ContainerInterface;
use Psr\Log\LoggerInterface;
use Doctrine\ORM\EntityManager;
use Monolog\Logger;
use Redis;
use GuzzleHttp\Client;

class Microservice
{
    private $container;

    public function __construct(ContainerInterface $container)
    {
        $this->container = $container;
    }

    public function run()
    {
        // Load vendor autoloader based on environment variables
        require_once $this->getAutoloaderPath();

        // Initialize databases and external APIs
        $databases = $this->container->get('databases');
        foreach ($databases as $name => $config) {
            $this->initDatabase($name, $config);
        }

        $apis = $this->container->get('apis');
        foreach ($apis as $name => $config) {
            $this->initApi($name, $config);
        }

        // Initialize distributed caching layer
        $cache = new Redis();
        $cache->connect($this->container->get('cache_config')['host'], $this->container->get('cache_config')['port']);

        // Handle connection retries and resource management
        while (true) {
            try {
                // Perform service logic here
                break;
            } catch (\Exception $e) {
                if ($this->isTransientError($e)) {
                    sleep(1); // Retry after 1 second
                } else {
                    throw $e; // Re-throw for critical errors
                }
            }
        }

        // Log and handle errors robustly
        $logger = $this->container->get('logger');
        try {
            // Perform service logic here
        } catch (\Exception $e) {
            $logger->error($e->getMessage(), ['exception' => $e]);
            throw new \RuntimeException("Service failed", 0, $e);
        }

        // Gracefully degrade under partial failures
        try {
            // Perform critical operations here
        } catch (\Exception $e) {
            $logger->warning("Partial failure: " . $e->getMessage());
            return;
        }
    }

    private function getAutoloaderPath()
    {
        $env = getenv('ENVIRONMENT');
        if ($env === 'production') {
            return __DIR__ . '/vendor/autoload.php';
        } elseif ($env === 'staging') {
            return __DIR__ . '/vendor/dev_autoload.php';
        } else {
            return __DIR__ . '/vendor/dev_autoload.php'; // Default to dev for local development
        }
    }

    private function initDatabase($name, $config)
    {
        $entityManager = EntityManager::create($config['dsn'], $config['params']);
        $this->container->set("database_{$name}", $entityManager);
    }

    private function initApi($name, $config)
    {
        $client = new Client($config);
        $this->container->set("api_{$name}", $client);
    }

    private function isTransientError(\Exception $e)
    {
        // Implement logic to determine if the error is transient
        return strpos($e->getMessage(), 'transient') !== false;
    }
}
