use reqwest::{Client, Error};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

struct ResourceBundle {
    data: String,
}

struct ApiClient {
    client: Client,
    base_url: String,
    auth_token: Option<String>,
    rate_limit_per_minute: u32,
    cache: Arc<Mutex<HashMap<String, ResourceBundle>>>,
    metrics: Metrics,
}

impl ApiClient {
    fn new(base_url: &str, auth_token: Option<&str>, rate_limit_per_minute: u32) -> Self {
        let client = Client::new();
        let base_url = base_url.to_string();
        let cache = Arc::new(Mutex::new(HashMap::new()));
        ApiClient {
            client,
            base_url,
            auth_token: auth_token.map(|s| s.to_string()),
            rate_limit_per_minute,
            cache,
            metrics: Metrics::new(),
        }
    }

    async fn fetch_resource(&self, resource_path: &str) -> Result<ResourceBundle, Error> {
        let url = format!("{}{}", self.base_url, resource_path);
        if let Some(cache_entry) = self.cache.lock().unwrap().get(resource_path) {
            return Ok(cache_entry.clone());
        }

        let start_time = Instant::now();
        let response = match self.client.get(&url).send().await {
            Ok(response) => response,
            Err(e) => {
                self.metrics.record_error();
                return Err(e);
            }
        };

        if !response.status().is_success() {
            self.metrics.record_error();
            return Err(Error::from_str("Failed to fetch resource"));
        }

        let duration = start_time.elapsed();
        self.metrics.record_operation(duration);

        let data = response.text().await?;
        let bundle = ResourceBundle { data };
        self.cache.lock().unwrap().insert(resource_path.to_string(), bundle.clone());
        Ok(bundle)
    }
}

struct Metrics {
    total_operations: u32,
    successful_operations: u32,
    error_count: u32,
}

impl Metrics {
    fn new() -> Self {
        Metrics {
            total_operations: 0,
            successful_operations: 0,
            error_count: 0,
        }
    }

    fn record_operation(&mut self, duration: Duration) {
        self.total_operations += 1;
        println!("Operation took {:?}", duration);
    }

    fn record_error(&mut self) {
        self.error_count += 1;
        println!("Error occurred");
    }

    fn get_metrics(&self) -> &Metrics {
        self
    }
}

#[tokio::main]
async fn main() {
    let api_client = ApiClient::new("https://api.example.com/resources/", Some("token"), 10);

    match api_client.fetch_resource("/bundle.json").await {
        Ok(bundle) => println!("Resource data: {}", bundle.data),
        Err(e) => eprintln!("Failed to fetch resource: {}", e),
    }
}
