<?php

class ClinicStatusUpdater {
    private $databaseClusters = [
        'cluster1' => ['host' => 'db1.example.com', 'port' => 3306],
        'cluster2' => ['host' => 'db2.example.com', 'port' => 3306]
    ];

    private $redis;
    private $loadBalancerIndex = 0;

    public function __construct() {
        $this->redis = new Redis();
        if (!$this->redis->connect('localhost', 6379)) {
            throw new Exception('Failed to connect to Redis');
        }
    }

    public function updateClinicStatusAsync($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate) {
        $dbCluster = $this->getDatabaseCluster();
        try {
            $conn = $this->connectToDatabase($dbCluster);
            if (!$conn) {
                throw new Exception('Failed to connect to database');
            }

            // Update clinic status in the database
            $stmt = $conn->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?");
            $stmt->execute([$newStatus, $lastModifiedIp, $lastModifiedDate, $clinicId]);

            // Invalidate cache for the updated clinic
            $this->redis->del("clinic:{$clinicId}");

            return true;
        } catch (Exception $e) {
            $this->logError($e);
            return false;
        }
    }

    private function getDatabaseCluster() {
        $cluster = $this->databaseClusters[$this->loadBalancerIndex];
        $this->loadBalancerIndex = ($this->loadBalancerIndex + 1) % count($this->databaseClusters);
        return $cluster;
    }

    private function connectToDatabase($dbCluster, $retryCount = 0) {
        try {
            $conn = new mysqli($dbCluster['host'], 'username', 'password', 'dbname', $dbCluster['port']);
            if ($conn->connect_error) {
                throw new Exception("Connection failed: " . $conn->connect_error);
            }
            return $conn;
        } catch (Exception $e) {
            if ($retryCount < 3) {
                sleep(pow(2, $retryCount)); // Exponential backoff
                return $this->connectToDatabase($dbCluster, $retryCount + 1);
            } else {
                throw $e;
            }
        }
    }

    private function logError(Exception $e) {
        error_log("Error: " . $e->getMessage() . "\n" . $e->getTraceAsString());
    }
}

// Example usage
$update = new ClinicStatusUpdater();
$update->updateClinicStatusAsync(123, 'open', '192.168.1.100', date('Y-m-d H:i:s'));
?>
