// auth.rs
use actix_web::{web, HttpResponse};
use oauth2::{AccessTokenResponse, AuthUrl, ClientId, ClientSecret, TokenUrl};

pub async fn generate_token(
    form: web::Form<AuthForm>,
    data: web::Data<CertServiceState>,
) -> impl Responder {
    let client_id = ClientId::new(form.client_id.clone());
    let client_secret = ClientSecret::new(form.client_secret.clone());
    let auth_url = AuthUrl::new("https://oauth.provider.com/auth").unwrap();
    let token_url = TokenUrl::new("https://oauth.provider.com/token").unwrap();

    let mut client = oauth2::Client::new(client_id, Some(client_secret), auth_url, Some(token_url));
    let token = client.exchange_client_credentials().await.unwrap();

    data.lock().await.update_token(token);
    HttpResponse::Ok().finish()
}

// kms.rs
use actix_web::{web, HttpResponse};
use std::sync::Arc;

pub async fn get_cert(
    params: web::Query<KmsParams>,
    data: web::Data<CertServiceState>,
) -> impl Responder {
    let cert = data.lock().await.get_cert(params.key_id.clone());
    match cert {
        Some(cert) => HttpResponse::Ok().body(cert),
        None => HttpResponse::NotFound().finish(),
    }
}

// cert_service.rs
use actix_web::{web, HttpResponse};
use std::sync::Arc;
use tokio::sync::Mutex;

pub struct CertServiceState {
    token: Option<AccessTokenResponse>,
    kms_url: String,
}

impl CertServiceState {
    pub fn new() -> Self {
        let kms_url = env::var("KMS_URL").unwrap_or_else(|_| "http://localhost:8081".to_string());
        CertServiceState { token: None, kms_url }
    }

    pub async fn update_token(&mut self, token: AccessTokenResponse) {
        self.token = Some(token);
    }

    pub async fn get_cert(&self, key_id: String) -> Option<String> {
        let client = reqwest::Client::new();
        let res = client.get(&format!("{}/cert", self.kms_url))
            .header("Authorization", format!("Bearer {}", self.token.as_ref().unwrap().access_token()))
            .query(&[("key_id", key_id)])
            .send()
            .await
            .map_err(|e| eprintln!("Failed to fetch certificate from KMS: {:?}", e))?;

        if res.status().is_success() {
            res.text().await.ok()
        } else {
            None
        }
    }
}

