<?php

require 'vendor/autoload.php';

use League\OAuth2\Client\Provider\AbstractProvider;
use League\OAuth2\Client\Token\AccessToken;

class AuthenticationSystem {
    private $cache;
    private $provider;
    private $logger;

    public function __construct(AbstractProvider $provider, CacheInterface $cache, LoggerInterface $logger) {
        $this->provider = $provider;
        $this->cache = $cache;
        $this->logger = $logger;
    }

    public function authenticateUser($code) {
        try {
            // Get access token from provider
            $token = $this->provider->getAccessToken('authorization_code', [
                'code' => $code,
            ]);

            // Store tokens in cache
            $cacheKey = 'access_token:' . $token->getToken();
            $this->cache->set($cacheKey, $token->getToken(), 3600); // Token expires in 1 hour

            return $token;
        } catch (\Exception $e) {
            $this->logger->error('Authentication failed: ' . $e->getMessage());
            throw new \RuntimeException('Failed to authenticate user');
        }
    }

    public function revokeAccessToken($accessToken) {
        try {
            // Revoke access token from provider
            $response = $this->provider->revokeToken($accessToken);

            // Delete token from cache
            $cacheKey = 'access_token:' . $accessToken;
            $this->cache->delete($cacheKey);

            return true;
        } catch (\Exception $e) {
            $this->logger->error('Failed to revoke access token: ' . $e->getMessage());
            throw new \RuntimeException('Failed to revoke access token');
        }
    }

    public function getUserInfo(AccessToken $accessToken) {
        try {
            // Get user info from provider
            return $this->provider->getResourceOwner($accessToken);
        } catch (\Exception $e) {
            $this->logger->error('Failed to get user info: ' . $e->getMessage());
            throw new \RuntimeException('Failed to get user info');
        }
    }

    public function rateLimit($userId, $maxRequests, $interval) {
        // Implement rate limiting logic using cache
        $cacheKey = 'rate_limit:' . $userId;
        if ($this->cache->has($cacheKey)) {
            $count = (int)$this->cache->get($cacheKey);
            if ($count >= $maxRequests) {
                throw new \RuntimeException('Rate limit exceeded');
            }
            $this->cache->set($cacheKey, $count + 1, $interval);
        } else {
            $this->cache->set($cacheKey, 1, $interval);
        }
    }
}

// Usage
$provider = new League\OAuth2\Client\Provider\Google([
    'clientId' => getenv('GOOGLE_CLIENT_ID'),
    'clientSecret' => getenv('GOOGLE_CLIENT_SECRET'),
    'redirectUri' => getenv('REDIRECT_URI'),
]);

$cache = new RedisCache();
$logger = new Monolog\Logger('auth_system');

