import threading
import json
from collections import defaultdict
from queue import Queue
import time

class DynamicFileSequenceManager:
    def __init__(self, log_service):
        self.log_service = log_service
        self.configurations = {}
        self.factory_functions = defaultdict(list)
        self.file_locks = {}
        self.job_queue = Queue()

    def parse_and_sort_file(self, file_path, log_id):
        with self.get_file_lock(file_path):
            try:
                with open(file_path, 'r') as file:
                    lines = [line.strip() for line in file]
                lines.sort()
                sequence_number = int(lines[-1].split('-')[-1])
                return sequence_number
            except Exception as e:
                self.log_service.error(log_id, f"Error parsing file: {e}")
                raise

    def get_file_lock(self, file_path):
        if file_path not in self.file_locks:
            self.file_locks[file_path] = threading.Lock()
        return self.file_locks[file_path]

    def add_factory_function(self, file_type, factory_function):
        with self.factory_functions_lock:
            self.factory_functions[file_type].append(factory_function)

    @property
    def factory_functions_lock(self):
        lock_name = f"factory_functions_lock"
        if lock_name not in self.file_locks:
            self.file_locks[lock_name] = threading.Lock()
        return self.file_locks[lock_name]

    def create_instance_from_id(self, file_type, config_id, json_data):
        factory_functions = self.factory_functions.get(file_type)
        if not factory_functions:
            raise ValueError(f"No factory functions found for file type: {file_type}")

        factory_function = next((func for func in factory_functions if func.config_id == config_id), None)
        if not factory_function:
            raise ValueError(f"Factory function with ID {config_id} not found for file type: {file_type}")

        return factory_function(json_data)

    def process_job(self):
        while True:
            try:
                job = self.job_queue.get()
                job()
                self.job_queue.task_done()
            except Exception as e:
                self.log_service.error(job.log_id, f"Error processing job: {e}")

    def start_processing_worker(self, log_id):
        worker_thread = threading.Thread(target=self.process_job)
        worker_thread.daemon = True
        worker_thread.start()

class FactoryFunction:
    def __init__(self, config_id, parse_function):
        self.config_id = config_id
        self.parse_function = parse_function

    def __call__(self, json_data):
        return self.parse_function(json_data)

def example_parse_function(json_data):
    # Implement parsing logic here
    pass

# Example usage:
log_service = LogService()  # Assume a class that handles logging
manager = DynamicFileSequenceManager(log_service)
manager.add_factory_function('example_type', FactoryFunction('1', example_parse_function))
manager.start_processing_worker('worker_log_id')
```

