using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private ConcurrentDictionary<string, (int min, int max)> integerRanges = new ConcurrentDictionary<string, (int min, int max)>();
    private ConcurrentDictionary<string, (double min, double max)> floatRanges = new ConcurrentDictionary<string, (double min, double max)>();

    public RandomValueGenerator()
    {
        // Initialize with default ranges
        integerRanges.TryAdd("DefaultIntRange", (0, 100));
        floatRanges.TryAdd("DefaultFloatRange", (0.0, 1.0));
    }

    public int GetRandomInteger(string rangeName)
    {
        if (!integerRanges.TryGetValue(rangeName, out var range))
        {
            throw new ArgumentException("Invalid integer range name.");
        }
        return Random.Shared.Next(range.min, range.max + 1);
    }

    public double GetRandomFloat(string rangeName)
    {
        if (!floatRanges.TryGetValue(rangeName, out var range))
        {
            throw new ArgumentException("Invalid float range name.");
        }
        return Random.Shared.NextDouble() * (range.max - range.min) + range.min;
    }

    public void UpdateRange(string rangeName, int min, int max)
    {
        integerRanges.TryUpdate(rangeName, (min, max), (int.MinValue, int.MaxValue));
    }

    public void UpdateRange(string rangeName, double min, double max)
    {
        floatRanges.TryUpdate(rangeName, (min, max), (double.MinValue, double.MaxValue));
    }
}

public class ConfigService
{
    public static RandomValueGenerator Instance { get; } = new RandomValueGenerator();

    private ConfigService() { }

    public void SetIntegerRange(string rangeName, int min, int max)
    {
        Instance.UpdateRange(rangeName, min, max);
    }

    public void SetFloatRange(string rangeName, double min, double max)
    {
        Instance.UpdateRange(rangeName, min, max);
    }
}
