#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

// Define constants and structures
#define MAX_CONCURRENT_REQUESTS 100
#define BUFFER_SIZE 4096

typedef enum {
    REQUEST_SUCCESS,
    REQUEST_TIMEOUT,
    INVALID_DATA_FORMAT,
    NETWORK_ERROR
} RequestStatus;

typedef struct {
    int id;
    char *url;
    char *buffer[BUFFER_SIZE];
    size_t buffer_size;
    RequestStatus status;
    pthread_mutex_t mutex;
} Request;

typedef struct {
    Request requests[MAX_CONCURRENT_REQUESTS];
    int request_count;
    pthread_cond_t cond;
    pthread_mutex_t lock;
} RequestQueue;

// Function prototypes
void* worker_thread(void *arg);
Request* create_request(int id, char *url);
void enqueue_request(RequestQueue *queue, Request *request);
Request* dequeue_request(RequestQueue *queue);
void process_requests(RequestQueue *queue);

int main() {
    // Initialize library and start processing requests
    pthread_t thread_ids[MAX_CONCURRENT_REQUESTS];
    RequestQueue queue;
    request_queue_init(&queue);

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&thread_ids[i], NULL, worker_thread, &queue);
    }

    // Simulate adding requests
    char *urls[] = {"http://example.com/resource1", "http://example.com/resource2"};
    for (int i = 0; i < 2; i++) {
        enqueue_request(&queue, create_request(i, urls[i]));
    }

    process_requests(&queue);

    // Join worker threads
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    return 0;
}

void* worker_thread(void *arg) {
    RequestQueue *queue = (RequestQueue *)arg;

    while (1) {
        Request *request = dequeue_request(queue);
        if (request == NULL) break;

        // Simulate network request
        CURL *curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, request->url);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, request->buffer);
            CURLcode res = curl_easy_perform(curl);

            if (res != CURLE_OK) {
                request->status = NETWORK_ERROR;
            } else {
                request->status = REQUEST_SUCCESS;
            }

            curl_easy_cleanup(curl);
        } else {
            request->status = NETWORK_ERROR;
        }

        // Update request status
        pthread_mutex_lock(&request->mutex);
        request->buffer_size = strlen(request->buffer[0]);
        pthread_mutex_unlock(&request->mutex);

        // Notify main thread of completion
        pthread_cond_signal(&queue->cond);
    }

    return NULL;
}

Request* create_request(int id, char *url) {
    Request *request = (Request *)malloc(sizeof(Request));
    request->id = id;
    request->url = strdup(url);
    memset(request->buffer, 0, sizeof(char*) * BUFFER_SIZE);
    request->status = REQUEST_SUCCESS;
    pthread_mutex_init(&request->mutex, NULL);

    return request;
}

void enqueue_request(RequestQueue *queue, Request *request) {
    pthread_mutex_lock(&queue->lock);
    queue->requests[queue->request_count++] = *request;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

Request* dequeue_request(RequestQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    while (queue->request_count == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }

    Request request = queue->requests[--queue->request_count];
    pthread_mutex_unlock(&queue->lock);

    return &request;
}

void process_requests(RequestQueue *queue) {
    while (1) {
        Request *request = dequeue_request(queue);
        if (request == NULL) break;

        // Handle request based on status
        switch (request->status) {
            case REQUEST_SUCCESS:
                printf("Request %d successful\n", request->id);
                break;
            case REQUEST_TIMEOUT:
                printf("Request %d timed out\n", request->id);
                break;
            case INVALID_DATA_FORMAT:
                printf("Request %d has invalid data format\n", request->id);
                break;
            case NETWORK_ERROR:
                printf("Request %d encountered a network error\n", request->id);
                break;
        }

        // Free resources
        free(request->url);
        pthread_mutex_destroy(&request->mutex);
    }
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    Request *request = (Request *)userdata;
    char **buffer = request->buffer;

    for (size_t i = 0; i < nmemb; i++) {
        if (request->buffer_size < BUFFER_SIZE - 1) {
            buffer[request->buffer_size++] = ptr[i];
        }
    }

    return size * nmemb;
}
