    if (path_size <= 0) {
        printf("Failed to get path size from API or invalid result.\n");
        return ERROR_INVALID_PATH;
    }

    if (path_size + 1 > max_size) { // +1 for trailing slash
        printf("Path exceeds maximum allowed size.\n");
        return ERROR_PATH_TOO_LONG;
    }

    // Step 3: Buffer Management
    snprintf(buffer, max_size, "%s/", path);
    buffer[max_size - 1] = '\0'; // Ensure null-termination

    return SUCCESS;
