    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    pthread_t threads[100]; // Assuming a maximum of 100 concurrent lines
    size_t thread_index = 0;

    while (1) {
        char line[256];
        if (!fgets(line, sizeof(line), log_file)) {
            break;
        }

        LogEntry entry;
        fetch_metadata(&entry, &cache); // Fetch metadata and populate entry

