            return EXIT_FAILURE;
        }

        if (++thread_index >= sizeof(threads) / sizeof(threads[0])) {
            for (size_t i = 0; i < thread_index; ++i) {
                pthread_join(threads[i], NULL);
            }
            thread_index = 0;
        }
    }

    // Join remaining threads
    for (size_t i = 0; i < thread_index; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}

