#include <openssl/pbkdf2.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define constants for key derivation function
#define PBKDF2_ITERATIONS 100000
#define SALT_LENGTH 32

// Structure to hold encryption context
typedef struct {
    unsigned char derived_key[32];
    pthread_mutex_t mutex;
} EncryptionContext;

// Function prototypes
void generate_salt(unsigned char *salt);
int derive_key(const char *password, unsigned char *derived_key);
int encrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *data, int data_len, unsigned char *encrypted_data);
int decrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *encrypted_data, int encrypted_data_len, unsigned char *decrypted_data);

// Function to generate a random salt
void generate_salt(unsigned char *salt) {
    if (!RAND_bytes(salt, SALT_LENGTH)) {
        fprintf(stderr, "Error generating salt\n");
        exit(EXIT_FAILURE);
    }
}

// Function to derive key using PBKDF2
int derive_key(const char *password, unsigned char *derived_key) {
    generate_salt(derived_key);
    int ret = PKCS5_PBKDF2_HMAC(password, strlen(password), derived_key, SALT_LENGTH, PBKDF2_ITERATIONS, EVP_sha256(), 32, derived_key);
    if (!ret) {
        fprintf(stderr, "Error deriving key\n");
        return -1;
    }
    return 0;
}

// Function to encrypt data
int encrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *data, int data_len, unsigned char *encrypted_data) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return -1;
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len = 0, written = 0;
    if (EVP_EncryptUpdate(ctx, encrypted_data + len, &len, data, data_len) != 1) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    written += len;
    if (EVP_EncryptFinal_ex(ctx, encrypted_data + written, &len) != 1) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    written += len;
    EVP_CIPHER_CTX_free(ctx);
    return written;
}

// Function to decrypt data
int decrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *encrypted_data, int encrypted_data_len, unsigned char *decrypted_data) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return -1;
    }
    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len = 0, written = 0;
    if (EVP_DecryptUpdate(ctx, decrypted_data + len, &len, encrypted_data, encrypted_data_len) != 1) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    written += len;
    if (EVP_DecryptFinal_ex(ctx, decrypted_data + written, &len) != 1) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    written += len;
    EVP_CIPHER_CTX_free(ctx);
    return written;
}

// Main function to demonstrate encryption and decryption
int main() {
    const char *password = "my_secure_password";
    unsigned char key[32], iv[EVP_MAX_BLOCK_LENGTH];
    unsigned char data[] = "This is a secret message";
    unsigned char encrypted_data[sizeof(data) + EVP_CIPHER_block_size(EVP_aes_256_cbc())], decrypted_data[sizeof(data)];

    // Derive key
    if (derive_key(password, key)) {
        fprintf(stderr, "Key derivation failed\n");
        return EXIT_FAILURE;
    }

    // Generate IV
    if (!RAND_bytes(iv, EVP_CIPHER_block_size(EVP_aes_256_cbc()))) {
        fprintf(stderr, "Error generating IV\n");
        return EXIT_FAILURE;
    }

    // Encrypt data
    int encrypted_len = encrypt_data(key, iv, (unsigned char *)data, sizeof(data), encrypted_data);
    if (encrypted_len < 0) {
        fprintf(stderr, "Encryption failed\n");
        return EXIT_FAILURE;
    }

    // Decrypt data
    int decrypted_len = decrypt_data(key, iv, encrypted_data, encrypted_len, decrypted_data);
    if (decrypted_len < 0) {
        fprintf(stderr, "Decryption failed\n");
        return EXIT_FAILURE;
    }

    // Print results
    printf("Original: %s\n", data);
    printf("Decrypted: %.*s\n", decrypted_len, decrypted_data);

    return EXIT_SUCCESS;
}
