// Thread-safe queue for asynchronous processing
template <typename T>
class ThreadSafeQueue {
private:
    std::queue<T> data;
    mutable std::mutex mutex;
    std::condition_variable cond;

public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(mutex);
        data.push(value);
        cond.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mutex);
        while (data.empty()) {
            cond.wait(lock);
        }
        T result = data.front();
        data.pop();
        return result;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex);
        return data.empty();
    }
};

// Worker function for asynchronous processing
void worker(ThreadSafeQueue<LogMetadata>& queue) {
    while (true) {
        LogMetadata metadata = queue.pop();
        if (!validateMetadata(metadata)) {
            std::cerr << "Validation failed: " << metadata.timestamp << ", " << metadata.logLevel << ", " << metadata.sourceIP << std::endl;
        } else {
            persistData(metadata);
        }
    }
}

// Main function
int main() {
    YAML::Node config = YAML::LoadFile("config.yaml");
    int numThreads = config["num_threads"].as<int>();

    ThreadSafeQueue<LogMetadata> queue;

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < numThreads; ++i) {
        workers.emplace_back(worker, std::ref(queue));
    }

    // Simulate log file processing
    for (int i = 0; i < 1000; ++i) {
        std::string filePath = "log_" + std::to_string(i) + ".txt";
        LogMetadata metadata = extractMetadata(filePath);
        queue.push(metadata);
    }

    // Stop worker threads
    for (auto& thread : workers) {
        queue.push(LogMetadata{});  // Push a sentinel value to signal exit
    }
    for (auto& thread : workers) {
        thread.join();
    }

    return 0;
}
