{
    private readonly string _iisPath = @"C:\inetpub\wwwroot";

    public void AddWebsite(string siteName, string physicalPath)
    {
        if (!Directory.Exists(physicalPath))
            throw new DirectoryNotFoundException("Physical path does not exist.");

        if (!File.Exists(Path.Combine(physicalPath, "web.config")))
            throw new FileNotFoundException("Web.config file is missing.");

        using (var serverManager = new ServerManager())
        {
            var existingSites = serverManager.Sites;
            if (existingSites.Any(s => s.Name == siteName))
                throw new InvalidOperationException("Site name already exists.");

            var site = serverManager.Sites.Add(siteName, physicalPath, 80);
            site.ServerAutoStart = true;

            try
            {
                serverManager.CommitChanges();
                StartWebsiteAsync(site);
            }
            catch (Exception ex)
            {
                // Log error and handle gracefully
                Console.WriteLine($"Failed to add website: {ex.Message}");
            }
        }
    }

    private void StartWebsiteAsync(Site site)
    {
        ThreadPool.QueueUserWorkItem(state =>
        {
            try
            {
                site.Start();
                Console.WriteLine("Website started successfully.");
            }
            catch (Exception ex)
            {
                // Log error and handle gracefully
                Console.WriteLine($"Failed to start website: {ex.Message}");
            }
        });
    }

    public void EnsureIISRunning()
    {
        using (var serviceController = new ServiceController("W3SVC"))
        {
            if (serviceController.Status != ServiceControllerStatus.Running)
            {
                try
                {
                    serviceController.Start();
                    serviceController.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(10));
                }
                catch (Exception ex)
                {
                    // Log error and handle gracefully
                    Console.WriteLine($"Failed to start IIS: {ex.Message}");
                }
            }
        }
    }

