#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuth2TokenResponse;

OAuth2TokenResponse* parse_oauth2_response(const char *json_str) {
    OAuth2TokenResponse *response = (OAuth2TokenResponse*)malloc(sizeof(OAuth2TokenResponse));
    if (!response) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    json_object *parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) {
        fprintf(stderr, "Failed to parse JSON string\n");
        free(response);
        return NULL;
    }

    const char *access_token = json_object_get_string(json_object_object_get_ex(parsed_json, "access_token", NULL));
    int expires_in = json_object_get_int(json_object_object_get_ex(parsed_json, "expires_in", NULL));
    const char *token_type = json_object_get_string(json_object_object_get_ex(parsed_json, "token_type", NULL));
    const char *refresh_token = json_object_get_string(json_object_object_get_ex(parsed_json, "refresh_token", NULL));

    if (access_token == NULL || strlen(access_token) == 0 ||
        expires_in <= 0 ||
        token_type == NULL || strcmp(token_type, "Bearer") != 0 ||
        refresh_token != NULL && strlen(refresh_token) == 0) {
        fprintf(stderr, "Invalid OAuth2 response fields\n");
        free(response);
        json_object_put(parsed_json);
        return NULL;
    }

    response->access_token = strdup(access_token);
    response->expires_in = expires_in;
    response->token_type = strdup(token_type);
    response->refresh_token = refresh_token ? strdup(refresh_token) : NULL;

    json_object_put(parsed_json);
    return response;
}

void free_oauth2_response(OAuth2TokenResponse *response) {
    if (response) {
        free(response->access_token);
        free(response->token_type);
        free(response->refresh_token);
        free(response);
    }
}
```

