using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class EncryptionLibrary
{
    private static readonly byte[] _key = Encoding.UTF8.GetBytes("YourSecureKeyHere"); // 24 bytes for TripleDES
    private static readonly byte[] _iv = Encoding.UTF8.GetBytes("IVForTripleDES"); // 8 bytes

    public string DecryptMessage(string base64EncodedMessage)
    {
        try
        {
            using (var decryptor = Aes.Create())
            {
                decryptor.Key = _key;
                decryptor.IV = _iv;
                decryptor.Mode = CipherMode.CBC;
                decryptor.Padding = PaddingMode.PKCS7;

                var bytesToDecrypt = Convert.FromBase64String(base64EncodedMessage);
                using (var ms = new System.IO.MemoryStream(bytesToDecrypt))
                {
                    using (var cs = new CryptoStream(ms, decryptor.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (var sr = new System.IO.StreamReader(cs))
                        {
                            return sr.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Decryption failed: {ex.Message}");
            return null;
        }
    }
}

public class CommandLineTool
{
    private readonly ConcurrentBag<int> _numbers = new ConcurrentBag<int>();
    private int? _largestNumber;

    public void ProcessInput()
    {
        try
        {
            while (true)
            {
                Console.Write("Enter a positive integer (or any non-integer to finish): ");
                var input = Console.ReadLine();
                if (!int.TryParse(input, out int number) || number <= 0)
                {
                    break;
                }
                _numbers.Add(number);
            }

            if (_numbers.TryPeek(out _largestNumber))
            {
                Console.WriteLine($"Largest integer entered: {_largestNumber}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing input: {ex.Message}");
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        var encryptionLibrary = new EncryptionLibrary();
        string base64Message = "your_base64_encoded_message_here";
        string decryptedMessage = encryptionLibrary.DecryptMessage(base64Message);
        Console.WriteLine($"Decrypted Message: {decryptedMessage}");

        var commandLineTool = new CommandLineTool();
        commandLineTool.ProcessInput();
    }
}
