using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashLibrary
{
    private static readonly ConcurrentDictionary<string, Func<byte[], byte[]>> _hashAlgorithms = new ConcurrentDictionary<string, Func<byte[], byte[]>>();
    private static readonly ConcurrentQueue<HashLogEntry> _logQueue = new ConcurrentQueue<HashLogEntry>();
    private static readonly object _lock = new object();

    public HashLibrary()
    {
        InitializeAlgorithms();
        LogConfiguration("HashLibrary initialized.");
    }

    private void InitializeAlgorithms()
    {
        _hashAlgorithms.TryAdd("MD5", data => MD5.Create().ComputeHash(data));
        _hashAlgorithms.TryAdd("SHA1", data => SHA1.Create().ComputeHash(data));
        _hashAlgorithms.TryAdd("SHA256", data => SHA256.Create().ComputeHash(data));
        _hashAlgorithms.TryAdd("SHA512", data => SHA512.Create().ComputeHash(data));
    }

    public byte[] GenerateHash(string algorithmName, string input)
    {
        if (!_hashAlgorithms.ContainsKey(algorithmName))
            throw new ArgumentException("Invalid hash algorithm.");

        byte[] inputBytes = Encoding.UTF8.GetBytes(input);
        byte[] hashBytes = _hashAlgorithms[algorithmName](inputBytes);

        LogHashGeneration(algorithmName, input, true);

        return hashBytes;
    }

    public async Task<byte[]> GenerateBatchHash(string algorithmName, IEnumerable<string> inputs)
    {
        if (!_hashAlgorithms.ContainsKey(algorithmName))
            throw new ArgumentException("Invalid hash algorithm.");

        var tasks = inputs.Select(input => Task.Run(() => _hashAlgorithms[algorithmName](Encoding.UTF8.GetBytes(input))));
        var results = await Task.WhenAll(tasks);

        LogHashGeneration(algorithmName, string.Join(", ", inputs), true);

        return results;
    }

    private void LogHashGeneration(string algorithmName, string input, bool success)
    {
        _logQueue.Enqueue(new HashLogEntry
        {
            Timestamp = DateTime.Now,
            Input = input,
            Algorithm = algorithmName,
            Success = success
        });
    }

    public void FlushLogs()
    {
        while (_logQueue.TryDequeue(out var logEntry))
        {
            // Integrate with external logging system here.
            Console.WriteLine($"Timestamp: {logEntry.Timestamp}, Input: {logEntry.Input}, Algorithm: {logEntry.Algorithm}, Success: {logEntry.Success}");
        }
    }

    public void SetConfiguration(string key, string value)
    {
        // Implement configuration management logic here.
    }
}

public class HashLogEntry
{
    public DateTime Timestamp { get; set; }
    public string Input { get; set; }
    public string Algorithm { get; set; }
    public bool Success { get; set; }
}
