using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class SecureDataLoader
{
    private readonly string _encryptionKey;
    private readonly byte[] _iv;
    private readonly HttpClient _httpClient;

    public SecureDataLoader(string encryptionKey, byte[] iv)
    {
        if (string.IsNullOrEmpty(encryptionKey) || encryptionKey.Length != 32)
            throw new ArgumentException("Encryption key must be a non-empty string of length 32.");

        if (iv == null || iv.Length != 16)
            throw new ArgumentException("IV must be a non-null byte array of length 16.");

        _encryptionKey = encryptionKey;
        _iv = iv;
        _httpClient = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
    }

    public async Task<T> LoadSecureDataAsync<T>(string dataUrl, int maxRetries = 3)
    {
        if (string.IsNullOrEmpty(dataUrl))
            throw new ArgumentException("Data URL must be a non-empty string.");

        for (int attempt = 0; attempt <= maxRetries; attempt++)
        {
            try
            {
                var response = await _httpClient.GetAsync(dataUrl, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();

                var encryptedData = await response.Content.ReadAsByteArrayAsync();
                var decryptedData = Decrypt(encryptedData, _encryptionKey, _iv);
                return JsonConvert.DeserializeObject<T>(decryptedData);
            }
            catch (HttpRequestException)
            {
                if (attempt == maxRetries) throw;
                // Log the error and retry after a short delay
                await Task.Delay(TimeSpan.FromSeconds(1));
            }
        }

        throw new InvalidOperationException("Failed to load secure data after multiple attempts.");
    }

    private byte[] Decrypt(byte[] encryptedData, string key, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = Encoding.UTF8.GetBytes(key);
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var memoryStream = new MemoryStream(encryptedData))
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            using (var plainTextStream = new MemoryStream())
            {
                await cryptoStream.CopyToAsync(plainTextStream);
                return plainTextStream.ToArray();
            }
        }
    }
}
