using System;
using System.Data.SQLite;
using System.IO;
using System.Threading.Tasks;

public class BinaryFileService : IDisposable
{
    private readonly string _databasePath;
    private SQLiteConnection _connection;

    public BinaryFileService(string databasePath)
    {
        _databasePath = databasePath;
        InitializeDatabase();
    }

    private void InitializeDatabase()
    {
        if (!File.Exists(_databasePath))
        {
            File.Create(_databasePath).Close();
        }

        _connection = new SQLiteConnection($"Data Source={_databasePath};Version=3;");
        _connection.Open();

        using (var command = new SQLiteCommand("CREATE TABLE IF NOT EXISTS Data (Id INTEGER PRIMARY KEY, Payload BLOB);", _connection))
        {
            command.ExecuteNonQuery();
        }
    }

    public async Task LoadAndDeserializeAsync(string filePath)
    {
        using var reader = new BinaryReader(File.Open(filePath, FileMode.Open));
        var buffer = await reader.ReadBytesAsync();

        using (var transaction = _connection.BeginTransaction())
        {
            using (var command = new SQLiteCommand(transaction))
            {
                foreach (var chunk in Enumerable.Range(0, buffer.Length / 1024))
                {
                    command.CommandText = "INSERT INTO Data (Payload) VALUES (@Payload)";
                    command.Parameters.AddWithValue("@Payload", buffer.Skip(chunk * 1024).Take(1024));
                    await command.ExecuteNonQueryAsync();
                }
            }

            transaction.Commit();
        }
    }

    public void Dispose()
    {
        _connection?.Close();
        _connection?.Dispose();
    }
}
