import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.Set;
import java.util.logging.Logger;

public class ObjectDeserializer {

    private static final Logger LOGGER = Logger.getLogger(ObjectDeserializer.class.getName());
    private Set<String> whitelist;
    private VersionControlAPI versionControlAPI;

    public ObjectDeserializer(Set<String> whitelist, VersionControlAPI versionControlAPI) {
        this.whitelist = whitelist;
        this.versionControlAPI = versionControlAPI;
    }

    public Object deserialize(byte[] data) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(bis);
            Object obj = ois.readObject();
            if (!whitelist.contains(obj.getClass().getName())) {
                LOGGER.warning("Deprecated class detected: " + obj.getClass().getName());
            }
            if (!versionControlAPI.isVersionCompatible(obj.getClass().getPackage().getImplementationVersion())) {
                throw new IOException("Incompatible version found.");
            }
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.severe("Deserialization failed: " + e.getMessage());
            throw e;
        } finally {
            if (ois != null) {
                ois.close();
            }
        }
    }

    public interface VersionControlAPI {
        boolean isVersionCompatible(String version);
    }
}
