// Import necessary libraries
const express = require('express');
const multer = require('multer');
const cloudinary = require('cloudinary').v2;
const nodemailer = require('nodemailer');
const { createClient } = require('@supabase/supabase-js');

// Initialize app and storage engine
const app = express();
const upload = multer({ dest: 'uploads/' });

// Configure Cloudinary
cloudinary.config({
  cloud_name: 'your_cloud_name',
  api_key: 'your_api_key',
  api_secret: 'your_api_secret'
});

// Configure Supabase client
const supabaseUrl = 'https://your-supabase-url.supabase.co';
const supabaseAnonKey = 'your_supabase_anon_key';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

// Define file type whitelist and size limits
const fileTypeWhitelist = ['image/png', 'image/jpeg'];
const maxSizeLimit = 5 * 1024 * 1024; // 5MB

// Idempotency token generator function
function generateIdempotencyToken() {
  return Math.random().toString(36).substr(2, 9);
}

// Retry mechanism with exponential backoff
async function retryRequest(task, retries = 5) {
  for (let i = 0; i < retries; i++) {
    try {
      return await task();
    } catch (error) {
      if (i === retries - 1) throw error;
      const delay = Math.pow(2, i) * 1000; // Exponential backoff
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}

// Email notification function
async function sendEmail(userEmail, message) {
  const transporter = nodemailer.createTransport({
    service: 'gmail',
    auth: {
      user: 'your_email@example.com',
      pass: 'your_email_password'
    }
  });

  await transporter.sendMail({
    from: '"File Upload Service" <file-upload-service@example.com>',
    to: userEmail,
    subject: message === 'success' ? 'Upload Successful' : 'Upload Failed',
    text: `Your file upload ${message}.`
  });
}

// Define the file upload route
app.post('/upload', upload.single('file'), async (req, res) => {
  const { originalname, mimetype, size } = req.file;
  const { url } = req.body;

  // Validate file type and size
  if (!fileTypeWhitelist.includes(mimetype)) return res.status(400).send('Invalid file type');
  if (size > maxSizeLimit) return res.status(400).send('File too large');

  try {
    // Generate idempotency token
    const idempotencyToken = generateIdempotencyToken();

    // Check for duplicate uploads
    const { data: existingUpload } = await supabase
      .from('uploads')
      .select('*')
      .eq('url', url)
      .eq('idempotency_token', idempotencyToken);

    if (existingUpload.length > 0) return res.status(200).send('Duplicate upload ignored');

    // Retry the file upload to cloud storage
    await retryRequest(async () => {
      const result = await cloudinary.uploader.upload(req.file.path, { folder: 'uploads' });
      console.log(result);
      await supabase.from('uploads').insert([{ url, idempotency_token: idempotencyToken }]);
    });

    // Send successful email notification
    await sendEmail(url.split('@')[1], 'success');

    res.status(200).send('File uploaded successfully');
  } catch (error) {
    console.error(error);
    await sendEmail(url.split('@')[1], 'failure');
    res.status(500).send('Internal server error');
  }
});

// Start the server
app.listen(3000, () => {
  console.log('File upload service is running on port 3000');
});
