const express = require('express');
const crypto = require('crypto');
const childProcess = require('child_process');
const axios = require('axios');

const app = express();
app.use(express.json());

// Configuration management settings
const CONFIG_FILE_PATH = '/path/to/config/file';
const SECRET_MANAGER_URL = 'https://your-secret-manager-url';

// Function to generate a secure password
function generatePassword(length) {
  return crypto.randomBytes(Math.ceil(length / 2))
    .toString('hex')
    .slice(0, length);
}

// Function to encrypt a password using AES-256-GCM
async function encryptPassword(password) {
  const secret = crypto.randomBytes(32); // 256-bit key
  const iv = crypto.randomBytes(16); // Initialization vector
  const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(secret), iv);
  let encrypted = cipher.update(password, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag();
  return { secret, iv, encrypted, authTag };
}

// Function to decrypt a password using AES-256-GCM
async function decryptPassword(encryptedData) {
  const decipher = crypto.createDecipheriv(
    'aes-256-gcm',
    Buffer.from(encryptedData.secret),
    Buffer.from(encryptedData.iv)
  );
  decipher.setAuthTag(Buffer.from(encryptedData.authTag));
  let decrypted = decipher.update(encryptedData.encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

// Endpoint to modify configuration
app.post('/modify-config', async (req, res) => {
  try {
    const { serviceName, newSettings } = req.body;

    // Generate and encrypt a password
    const password = generatePassword(16);
    const encryptedPassword = await encryptPassword(password);

    // Update the configuration file using sed
    childProcess.execSync(
      `sed -i "s/^${serviceName}_PASSWORD=.*/${serviceName}_PASSWORD=${encryptedPassword.encrypted}/" ${CONFIG_FILE_PATH}`
    );

    // Store the password securely in the secret manager
    const response = await axios.post(SECRET_MANAGER_URL, {
      serviceName,
      password: encryptedPassword,
    });

    if (response.status === 200) {
      res.status(200).json({ message: 'Configuration updated and secure', serviceName });
    } else {
      throw new Error('Failed to store secret');
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

