type GraphNode struct {
	ID        int
	Properties map[string]string
}

// GraphEdge represents an edge connecting two vertices with properties.
type GraphEdge struct {
	FromID    int
	ToID      int
	Properties map[string]string
}

// GraphDatabase is a distributed database for storing graph nodes and edges.
type GraphDatabase struct {
	nodes   map[int]GraphNode
	edges   map[int][]GraphEdge
	muNodes sync.Mutex
	muEdges sync.Mutex
}

// NewGraphDatabase creates a new instance of GraphDatabase.
func NewGraphDatabase() *GraphDatabase {
	return &GraphDatabase{
		nodes: make(map[int]GraphNode),
		edges: make(map[int][]GraphEdge),
	}
}

// AddNode adds a new node to the graph with random properties.
func (db *GraphDatabase) AddNode() (int, error) {
	db.muNodes.Lock()
	defer db.muNodes.Unlock()

	id := rand.Intn(100000)
	node := GraphNode{
		ID: id,
		Properties: map[string]string{
			"createdAt": time.Now().Format(time.RFC3339),
			"status":    "active",
		},
	}
	db.nodes[id] = node
	return id, nil
}

// AddEdge adds a new edge between two nodes with random properties.
func (db *GraphDatabase) AddEdge(fromID, toID int) error {
	db.muEdges.Lock()
	defer db.muEdges.Unlock()

	edge := GraphEdge{
		FromID: fromID,
		ToID: toID,
		Properties: map[string]string{
			"createdAt": time.Now().Format(time.RFC3339),
			"type":      "directed",
		},
	}
	db.edges[fromID] = append(db.edges[fromID], edge)
	return nil
}

// GetNode retrieves a node by its ID.
func (db *GraphDatabase) GetNode(id int) (GraphNode, error) {
	db.muNodes.Lock()
	defer db.muNodes.Unlock()

	node, exists := db.nodes[id]
	if !exists {
		return GraphNode{}, errors.New("node not found")
	}
	return node, nil
}

// GetEdges retrieves all edges for a given node ID.
func (db *GraphDatabase) GetEdges(id int) ([]GraphEdge, error) {
	db.muEdges.Lock()
	defer db.muEdges.Unlock()

	edges, exists := db.edges[id]
	if !exists {
		return []GraphEdge{}, errors.New("no edges found for this node")
	}
	return edges, nil
}

// EncryptProperties encrypts a map of properties using AES encryption.
func EncryptProperties(props map[string]string, key []byte) (map[string]string, error) {
	encryptedProps := make(map[string]string)
	for k, v := range props {
		block, err := aes.NewCipher(key)
		if err != nil {
			return nil, err
		}
		ciphertext := make([]byte, aes.BlockSize+len(v))
		iv := ciphertext[:aes.BlockSize]
		if _, err := rand.Read(iv); err != nil {
			return nil, err
		}
		stream := cipher.NewCFBEncrypter(block, iv)
		stream.XORKeyStream(ciphertext[aes.BlockSize:], []byte(v))
		encryptedProps[k] = base64.StdEncoding.EncodeToString(ciphertext)
	}
	return encryptedProps, nil
}

// DecryptProperties decrypts a map of properties using AES decryption.
func DecryptProperties(props map[string]string, key []byte) (map[string]string, error) {
	decryptedProps := make(map[string]string)
	for k, v := range props {
		ciphertext, err := base64.StdEncoding.DecodeString(v)
		if err != nil {
			return nil, err
		}
		block, err := aes.NewCipher(key)
		if err != nil {
			return nil, err
		}
		if len(ciphertext) < aes.BlockSize {
			return nil, errors.New("ciphertext too short")
		}
		iv := ciphertext[:aes.BlockSize]
		ciphertext = ciphertext[aes.BlockSize:]
		stream := cipher.NewCFBDecrypter(block, iv)
		stream.XORKeyStream(ciphertext, ciphertext)
		decryptedProps[k] = string(ciphertext)
	}
	return decryptedProps, nil
}

// StartHTTPServer starts an HTTP server to provide API endpoints.
func (db *GraphDatabase) StartHTTPServer(port int) {
	http.HandleFunc("/add_node", func(w http.ResponseWriter, r *http.Request) {
		id, err := db.AddNode()
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintf(w, "Node added with ID: %d", id)
	})

	http.HandleFunc("/add_edge", func(w http.ResponseWriter, r *http.Request) {
		fromID := rand.Intn(100000)
		toID := rand.Intn(100000)
		err := db.AddEdge(fromID, toID)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintf(w, "Edge added between nodes %d and %d", fromID, toID)
	})

	http.HandleFunc("/get_node", func(w http.ResponseWriter, r *http.Request) {
		id := rand.Intn(100000)
		node, err := db.GetNode(id)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintf(w, "Node: %+v", node)
	})

	http.HandleFunc("/get_edges", func(w http.ResponseWriter, r *http.Request) {
		id := rand.Intn(100000)
		edges, err := db.GetEdges(id)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintf(w, "Edges: %+v", edges)
	})

	fmt.Printf("Starting server on port %d...\n", port)
	err := http.ListenAndServe(fmt.Sprintf(":%d", port), nil)
	if err != nil {
		fmt.Println(err)
	}
}

func main() {
	db := NewGraphDatabase()
	key := []byte("thisisaverysecurekey1234567890")
	go db.StartHTTPServer(8080)

	// Example usage
	id, _ := db.AddNode()
	encryptedProps, _ := EncryptProperties(map[string]string{"name": "Alice"}, key)
	fmt.Printf("Encrypted properties: %+v\n", encryptedProps)

	decryptedProps, _ := DecryptProperties(encryptedProps, key)
	fmt.Printf("Decrypted properties: %+v\n", decryptedProps)
}
