use std::sync::{Arc, Mutex};
use std::env;
use std::collections::HashMap;
use tokio::net::TcpListener;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use bytes::Bytes;

#[derive(Debug)]
enum DirectoryError {
    InvalidName,
    NameTooLong,
    AlreadyExists,
    NotFound,
    PermissionDenied,
    DiskSpaceLow,
    NetworkFailure,
    LoggingFailed,
    ConfigRetrievalFailed,
}

struct DirectoryManager {
    directories: Arc<Mutex<HashMap<String, String>>>,
    logger: Logger,
}

impl DirectoryManager {
    fn new() -> Self {
        let directories = Arc::new(Mutex::new(HashMap::new()));
        let logger = Logger::new();
        DirectoryManager { directories, logger }
    }

    async fn validate_directory_name(&self, name: &str) -> Result<(), DirectoryError> {
        if name.contains(|c| !c.is_alphanumeric() || c == '.' || c == '/') {
            return Err(DirectoryError::InvalidName);
        }
        if name.len() > 256 {
            return Err(DirectoryError::NameTooLong);
        }
        Ok(())
    }

    async fn check_directory_exists(&self, name: &str) -> Result<(), DirectoryError> {
        let directories = self.directories.lock().unwrap();
        if directories.contains_key(name) {
            match env::var("DIR_PATH") {
                Ok(path) => {
                    directories.insert(name.to_string(), path);
                    Ok(())
                },
                Err(_) => Err(DirectoryError::NotFound),
            }
        } else {
            Ok(())
        }
    }

    async fn create_directory(&self, name: &str) -> Result<(), DirectoryError> {
        self.validate_directory_name(name).await?;
        self.check_directory_exists(name).await?;
        let mut directories = self.directories.lock().unwrap();
        directories.insert(name.to_string(), "path/to/directory".to_string());
        self.logger.log(&format!("Directory created: {}", name));
        Ok(())
    }
}

struct Logger {
    log_file: std::fs::File,
}

impl Logger {
    fn new() -> Self {
        let log_file = std::fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open("directory_manager.log")
            .unwrap();
        Logger { log_file }
    }

    fn log(&self, message: &str) {
        use chrono::{Local, Timelike};
        let now = Local::now();
        let timestamp = format!("{}-{:02}-{:02} {:02}:{:02}:{:02}",
                                now.year(),
                                now.month(),
                                now.day(),
                                now.hour(),
                                now.minute(),
                                now.second());
        let log_entry = format!("[{}] {}\n", timestamp, message);
        self.log_file.write_all(log_entry.as_bytes()).unwrap();
    }
}

#[tokio::main]
async fn main() {
    let manager = DirectoryManager::new();
    let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();

    loop {
        let (mut socket, _) = listener.accept().await.unwrap();
        tokio::spawn(async move {
            let mut buffer = [0; 1024];
            match socket.read(&mut buffer).await {
                Ok(n) if n == 0 => return,
                Ok(n) => {
                    let request = String::from_utf8_lossy(&buffer[..n]);
                    match manager.create_directory(&request.trim()).await {
                        Ok(_) => socket.write_all(b"Directory created successfully").await.unwrap(),
                        Err(e) => socket.write_all(format!("Error: {:?}", e).as_bytes()).await.unwrap(),
                    }
                },
                Err(_) => return,
            }
        });
    }
}
