typedef struct {
    int deviceID;
    char status[50];
    time_t lastUpdate;
    // connectionMetrics can be a more complex structure depending on the requirements
} DeviceStatus;

typedef struct {
    DeviceStatus *devices;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DeviceManager;

DeviceManager deviceManager = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initDeviceManager(size_t initialCapacity) {
    deviceManager.capacity = initialCapacity;
    deviceManager.devices = (DeviceStatus*)malloc(initialCapacity * sizeof(DeviceStatus));
}

void freeDeviceManager() {
    free(deviceManager.devices);
    deviceManager.devices = NULL;
    deviceManager.count = 0;
    deviceManager.capacity = 0;
}

void addOrUpdateDevice(int deviceID, const char *status) {
    pthread_mutex_lock(&deviceManager.mutex);
    for (size_t i = 0; i < deviceManager.count; ++i) {
        if (deviceManager.devices[i].deviceID == deviceID) {
            strcpy(deviceManager.devices[i].status, status);
            deviceManager.devices[i].lastUpdate = time(NULL);
            pthread_mutex_unlock(&deviceManager.mutex);
            return;
        }
    }
    if (deviceManager.count >= deviceManager.capacity) {
        deviceManager.capacity *= 2;
        deviceManager.devices = (DeviceStatus*)realloc(deviceManager.devices, deviceManager.capacity * sizeof(DeviceStatus));
    }
    deviceManager.devices[deviceManager.count].deviceID = deviceID;
    strcpy(deviceManager.devices[deviceManager.count].status, status);
    deviceManager.devices[deviceManager.count].lastUpdate = time(NULL);
    ++deviceManager.count;
    pthread_mutex_unlock(&deviceManager.mutex);
}

bool isDeviceActive(int deviceID, time_t gracePeriod) {
    pthread_mutex_lock(&deviceManager.mutex);
    for (size_t i = 0; i < deviceManager.count; ++i) {
        if (deviceManager.devices[i].deviceID == deviceID && difftime(time(NULL), deviceManager.devices[i].lastUpdate) <= gracePeriod) {
            pthread_mutex_unlock(&deviceManager.mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&deviceManager.mutex);
    return false;
}

