// List of loaded algorithms
CryptoAlgorithm **loadedAlgorithms = NULL;
int algorithmCount = 0;

// Mutex for thread-safe access to algorithm list
pthread_mutex_t algorithmListMutex;

// Load cryptographic algorithms from specified directories
void loadAlgorithms(const char *directory) {
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(directory)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
                continue;

            // Construct full path
            char path[256];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

            // Load algorithm (placeholder function)
            CryptoAlgorithm *algo = loadCryptoAlgorithm(path);
            if (algo != NULL) {
                pthread_mutex_lock(&algorithmListMutex);
                loadedAlgorithms = realloc(loadedAlgorithms, (algorithmCount + 1) * sizeof(CryptoAlgorithm *));
                loadedAlgorithms[algorithmCount++] = algo;
                pthread_mutex_unlock(&algorithmListMutex);
            }
        }
        closedir(dir);
    }
}

// Execute a cryptographic algorithm
void executeAlgorithm(const char *name) {
    pthread_mutex_lock(&algorithmListMutex);
    for (int i = 0; i < algorithmCount; i++) {
        if (strcmp(loadedAlgorithms[i]->name, name) == 0) {
            loadedAlgorithms[i]->execute();
            break;
        }
    }
    pthread_mutex_unlock(&algorithmListMutex);
}

// Background worker to fetch updates from external security API
