#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    int deviceID;
    char status[50];
    time_t lastUpdate;
    double connectionMetrics;
} DeviceStatus;

typedef struct {
    pthread_mutex_t lock;
    DeviceStatus* devices;
    size_t capacity;
    size_t size;
} DeviceManager;

void initDeviceManager(DeviceManager* manager, size_t initialCapacity) {
    manager->capacity = initialCapacity;
    manager->size = 0;
    manager->devices = malloc(initialCapacity * sizeof(DeviceStatus));
    pthread_mutex_init(&manager->lock, NULL);
}

void freeDeviceManager(DeviceManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->devices);
}

void addDevice(DeviceManager* manager, DeviceStatus device) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->devices = realloc(manager->devices, manager->capacity * sizeof(DeviceStatus));
    }
    manager->devices[manager->size++] = device;
    pthread_mutex_unlock(&manager->lock);
}

bool validateOAuthToken(const char* tokenResponse) {
    struct json_object* jobj;
    if ((jobj = json_tokener_parse(tokenResponse)) == NULL) return false;

    const char* requiredFields[] = {"access_token", "expires_in", "token_type"};
    size_t numRequiredFields = sizeof(requiredFields) / sizeof(requiredFields[0]);

    for (size_t i = 0; i < numRequiredFields; ++i) {
        struct json_object* value;
        if (json_object_object_get_ex(jobj, requiredFields[i], &value)) {
            if (!strcmp(requiredFields[i], "token_type") && strcmp(json_object_get_string(value), "Bearer")) return false;
            if (!strcmp(requiredFields[i], "expires_in") && !json_object_is_int(value)) return false;
        } else {
            json_object_put(jobj);
            return false;
        }
    }

    if (json_object_object_get_ex(jobj, "refresh_token", NULL)) {
        // Optional field present
    }

    struct json_object* expires_in_obj = json_object_object_get_ex(jobj, "expires_in", NULL);
    int expires_in = json_object_get_int(expires_in_obj);
    if (expires_in <= 0) return false;

    json_object_put(jobj);
    return true;
}

int main() {
    DeviceManager manager;
    initDeviceManager(&manager, 1024);

    // Example usage
    DeviceStatus device = {1, "Active", time(NULL), 1.5};
    addDevice(&manager, device);

    const char* tokenResponse = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    bool isTokenValid = validateOAuthToken(tokenResponse);
    printf("Is OAuth token valid? %s\n", isTokenValid ? "Yes" : "No");

    freeDeviceManager(&manager);
    return 0;
}
```

