#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define DeviceStatus structure
typedef struct {
    int id;
    char* status;
} DeviceStatus;

// Function prototypes
void initializeDeviceManager(int maxDevices);
void updateDeviceStatus(DeviceStatus* device, const char* newStatus);
DeviceStatus* getDeviceStatus(int id);
void freeDeviceManager();

// Global variables for resource management and concurrency
DeviceStatus** devicePool;
int poolSize;
pthread_mutex_t poolMutex;

void initializeDeviceManager(int maxDevices) {
    poolSize = maxDevices;
    devicePool = (DeviceStatus**)malloc(poolSize * sizeof(DeviceStatus*));
    if (!devicePool) {
        fprintf(stderr, "Failed to allocate memory for device pool\n");
        exit(1);
    }
    for (int i = 0; i < poolSize; i++) {
        devicePool[i] = NULL;
    }

    pthread_mutex_init(&poolMutex, NULL);
}

void updateDeviceStatus(DeviceStatus* device, const char* newStatus) {
    pthread_mutex_lock(&poolMutex);
    if (device->status) {
        free(device->status);
    }
    device->status = strdup(newStatus);
    pthread_mutex_unlock(&poolMutex);
}

DeviceStatus* getDeviceStatus(int id) {
    pthread_mutex_lock(&poolMutex);
    DeviceStatus* device = devicePool[id];
    pthread_mutex_unlock(&poolMutex);
    return device;
}

void freeDeviceManager() {
    for (int i = 0; i < poolSize; i++) {
        if (devicePool[i]) {
            free(devicePool[i]->status);
            free(devicePool[i]);
