class MemoryAllocator {
public:
    MemoryAllocator(size_t poolSize) : poolSize(poolSize), allocatorPool(poolSize) {}

    void* allocate() {
        std::lock_guard<std::mutex> lock(mutex);
        if (allocatorPool.empty()) {
            throw std::bad_alloc();
        }
        void* ptr = allocatorPool.back();
        allocatorPool.pop_back();
        return ptr;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex);
        allocatorPool.push_back(ptr);
    }

private:
    size_t poolSize;
    std::vector<void*> allocatorPool;
    std::mutex mutex;
};

