    if (!RAND_bytes(iv, sizeof(iv))) handleErrors();

    const unsigned char *plaintext = (const unsigned char *)"This is a secret message";
    int plaintext_len = strlen((char *)plaintext);

    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    // Encrypt the plaintext
    int len = encrypt(plaintext, plaintext_len, key, iv, ciphertext);
    printf("Encrypted text: ");
    BIO_dump_fp(stdout, (const char *)ciphertext, len);

    // Decrypt the ciphertext
    len = decrypt(ciphertext, len, key, iv, decryptedtext);
    decryptedtext[len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

