from abc import ABC, abstractmethod
import logging
import requests
from Crypto.Cipher import DES3, AES
from Crypto.Util.Padding import pad, unpad

# Interface for encryption algorithms
class EncryptionAlgorithm(ABC):
    @abstractmethod
    def encrypt(self, data: bytes, key: bytes) -> bytes:
        pass

    @abstractmethod
    def decrypt(self, data: bytes, key: bytes) -> bytes:
        pass

# DES3 Encryption Algorithm
class DES3Encryption(EncryptionAlgorithm):
    def encrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = DES3.new(key, DES3.MODE_ECB)
        return cipher.encrypt(pad(data, DES3.block_size))

    def decrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = DES3.new(key, DES3.MODE_ECB)
        return unpad(cipher.decrypt(data), DES3.block_size)

# AES Encryption Algorithm
class AESEncryption(EncryptionAlgorithm):
    def encrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = AES.new(key, AES.MODE_CBC)
        return cipher.iv + cipher.encrypt(pad(data, AES.block_size))

    def decrypt(self, data: bytes, key: bytes) -> bytes:
        iv = data[:AES.block_size]
        cipher = AES.new(key, AES.MODE_CBC, iv=iv)
        return unpad(cipher.decrypt(data[AES.block_size:]), AES.block_size)

# Cryptographic Service
class CryptoService:
    def __init__(self, algorithm: EncryptionAlgorithm):
        self.algorithm = algorithm

    def encrypt(self, data: bytes, key: bytes) -> bytes:
        return self.algorithm.encrypt(data, key)

    def decrypt(self, data: bytes, key: bytes) -> bytes:
        return self.algorithm.decrypt(data, key)

# External Key Management System Integration
class KeyManager:
    def __init__(self):
        self.keys = {}

    def fetch_key(self, user_id: str) -> bytes:
        # Simulate fetching a key from an external system
        if user_id in self.keys:
            return self.keys[user_id]
        else:
            raise Exception("Key not found")

# Identity Provider Integration
class IdentityProvider:
    def __init__(self):
        pass

    def authenticate(self, user_token: str) -> bool:
        # Simulate authentication using an identity provider
        if user_token == "valid_token":
            return True
        else:
            raise Exception("Authentication failed")

# Logging and Error Handling
def setup_logging():
    logging.basicConfig(level=logging.INFO)
    logger = logging.getLogger(__name__)
    return logger

logger = setup_logging()

# Example Usage
if __name__ == "__main__":
    key_manager = KeyManager()
    identity_provider = IdentityProvider()

    # Fetch user key securely
    user_key = key_manager.fetch_key("user123")

    # Authenticate the user
    if identity_provider.authenticate("valid_token"):
        logger.info("User authenticated successfully")

        # Create a CryptoService instance using AES encryption
        crypto_service = CryptoService(AESEncryption())

        # Encrypt sensitive data
        encrypted_data = crypto_service.encrypt(b"Sensitive transaction data", user_key)
        logger.info(f"Encrypted data: {encrypted_data}")

        # Decrypt the data
        decrypted_data = crypto_service.decrypt(encrypted_data, user_key)
        logger.info(f"Decrypted data: {decrypted_data.decode()}")
    else:
        logger.error("User authentication failed")
```

