using System.Threading.Tasks;

public class WeatherService
{
    private readonly Dictionary<string, HttpClient> _apiClients = new Dictionary<string, HttpClient>();
    private readonly Dictionary<string, string> _defaultValues = new Dictionary<string, string>();

    public WeatherService()
    {
        // Initialize API clients for different weather services
        _apiClients.Add("service1", new HttpClient { BaseAddress = new Uri("https://api.service1.com/") });
        _apiClients.Add("service2", new HttpClient { BaseAddress = new Uri("https://api.service2.com/") });

        // Set default values for missing data
        _defaultValues["temperature"] = "N/A";
    }

    public async Task<string> GetWeatherAsync(string city, string service)
    {
        if (!_apiClients.ContainsKey(service))
            throw new ArgumentException("Invalid service");

        try
        {
            var response = await _apiClients[service].GetAsync($"weather/{city}");
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
        catch (HttpRequestException)
        {
            // Fallback to the next available service or return a default value
            return _defaultValues["temperature"];
        }
    }

    public async Task<List<string>> GetHistoricalWeatherAsync(string city, string service, DateTime startDate, DateTime endDate)
    {
        var weatherData = new List<string>();

        if (!_apiClients.ContainsKey(service))
            throw new ArgumentException("Invalid service");

        try
        {
            var response = await _apiClients[service].GetAsync($"weather/{city}/history?start={startDate.ToString("yyyy-MM-dd")}&end={endDate.ToString("yyyy-MM-dd")}");
            response.EnsureSuccessStatusCode();
            weatherData.AddRange(await response.Content.ReadAsAsync<List<string>>());
        }
        catch (HttpRequestException)
        {
            // Fallback to the next available service or return an empty list
        }

        return weatherData;
    }
}

public class CacheService
{
    private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();

    public string Get(string key, DateTime freshnessTime)
    {
        if (_cache.ContainsKey(key) && DateTime.Now < freshnessTime)
            return _cache[key];

        // Fetch data from WeatherService and update cache
        var weatherService = new WeatherService();
        _cache[key] = weatherService.GetWeatherAsync("New York", "service1").Result; // Example city and service
        return _cache[key];
    }
}

public class DashboardController
{
    public async Task<string> GetCityTemperature(string city)
    {
        var cacheService = new CacheService();
        var freshnessTime = DateTime.Now.AddMinutes(10); // Cache for 10 minutes
        var temperature = cacheService.Get($"{city}_temperature", freshnessTime);
        return $"Current Temperature in {city}: {temperature}";
    }

    public async Task<List<string>> GetHistoricalTemperature(string city, DateTime startDate, DateTime endDate)
    {
        var weatherService = new WeatherService();
        return await weatherService.GetHistoricalWeatherAsync(city, "service1", startDate, endDate);
    }
}
