using System.Xml.Linq;

public class XMLProcessingService : IDisposable
{
    private readonly ConcurrentQueue<XDocument> _xmlQueue = new ConcurrentQueue<XDocument>();
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly ILogger _logger;
    private CancellationTokenSource _cancellationTokenSource;

    public XMLProcessingService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cancellationTokenSource = new CancellationTokenSource();
    }

    public void Start()
    {
        Task.Run(ProcessXMLQueue, _cancellationTokenSource.Token);
    }

    public void Stop()
    {
        _cancellationTokenSource.Cancel();
    }

    public async Task EnqueueAsync(XDocument xml)
    {
        if (xml == null) throw new ArgumentNullException(nameof(xml));
        await _xmlQueue.EnqueueAsync(xml);
    }

    private async Task ProcessXMLQueue(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            if (_xmlQueue.TryDequeue(out var xml))
            {
                try
                {
                    await ProcessXML(xml, cancellationToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing XML");
                }
            }
            else
            {
                await Task.Delay(100, cancellationToken); // Avoid busy-waiting
            }
        }
    }

    private async Task ProcessXML(XDocument xml, CancellationToken cancellationToken)
    {
        // Example validation and API calls
        try
        {
            var validationResponse = await _httpClient.GetAsync("https://api.example.com/validate", cancellationToken);
            validationResponse.EnsureSuccessStatusCode();

            var metadataResponse = await _httpClient.GetAsync("https://api.example.com/metadata", cancellationToken);
            metadataResponse.EnsureSuccessStatusCode();

            // Transactional operations
            // ...

            _logger.LogInformation($"Processed XML with ID: {xml.Root.Attribute("id")?.Value}");
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "API request failed");
        }
    }

    public void Dispose()
    {
        Stop();
        _httpClient.Dispose();
    }
}
