package com.resource.management;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

@SpringBootApplication
public class ResourceManagementService {

    private static Map<String, String> resources = new HashMap<>();
    private static int versionCounter = 0;

    public static void main(String[] args) {
        SpringApplication.run(ResourceManagementService.class, args);
    }

    @PutMapping("/resource/{id}")
    public String updateResource(@PathVariable String id, @RequestBody String jsonData, @RequestHeader("X-Version") Integer clientVersion) {
        synchronized (resources) {
            if (!resources.containsKey(id)) {
                return "404 Not Found";
            }
            int currentVersion = resources.get(id).split(";")[1].hashCode();
            if (clientVersion != null && clientVersion != currentVersion) {
                return "409 Conflict";
            }
            String updatedResource = jsonData + ";" + ++versionCounter;
            resources.put(id, updatedResource);
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(updatedResource.getBytes());
                StringBuilder sb = new StringBuilder();
                for (byte b : digest) {
                    sb.append(String.format("%02x", b));
                }
                return sb.toString();
            } catch (NoSuchAlgorithmException e) {
                return "500 Internal Server Error";
            }
        }
    }

    @DeleteMapping("/resource/{id}")
    public String deleteResource(@PathVariable String id, @RequestHeader("X-Version") Integer clientVersion) {
        synchronized (resources) {
            if (!resources.containsKey(id)) {
                return "404 Not Found";
            }
            int currentVersion = resources.get(id).split(";")[1].hashCode();
            if (clientVersion != null && clientVersion != currentVersion) {
                return "409 Conflict";
            }
            String deletedResource = resources.get(id);
            resources.remove(id);
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(deletedResource.getBytes());
                StringBuilder sb = new StringBuilder();
                for (byte b : digest) {
                    sb.append(String.format("%02x", b));
                }
                return sb.toString();
            } catch (NoSuchAlgorithmException e) {
                return "500 Internal Server Error";
            }
        }
    }

    @GetMapping("/resource/{id}")
    public String getResource(@PathVariable String id) {
        synchronized (resources) {
            if (!resources.containsKey(id)) {
                return "404 Not Found";
            }
            return resources.get(id);
        }
    }
}
