const encryptionKey = 'your-256-bit-key-here';

generateFooterSection(apiEndpoints, encryptionKey)
  .then(footerHtml => {
    document.body.innerHTML += footerHtml;
  })
  .catch(error => {
    console.error('Failed to generate footer section:', error);
  });
