function refreshDialogFields(resourceId, url, fieldNames) {
    return new Promise((resolve, reject) => {
        const startTime = performance.now();
        let endRss;

        process.memoryUsage().beforeRefresh = process.memoryUsage().rss;

        function fetchData(fieldName) {
            return $http.get(`${url}/${fieldName}`)
                .then(response => response.data)
                .catch(error => {
                    console.error(`Failed to fetch data for ${fieldName}:`, error);
                    throw error;
                });
        }

        const fieldPromises = fieldNames.map(fetchData);

        Promise.all(fieldPromises)
            .then(data => {
                // Update dialog fields with fetched data
                fieldNames.forEach((fieldName, index) => {
                    updateDialogField(fieldName, data[index]);
                });

                endRss = process.memoryUsage().rss;
                const timeTaken = performance.now() - startTime;
                resolve({
                    timeTaken,
                    rssDifference: endRss - process.memoryUsage().beforeRefresh,
                    success: true,
                    logs: []
                });
            })
            .catch(error => {
                reject({
                    timeTaken: performance.now() - startTime,
                    rssDifference: endRss ? endRss - process.memoryUsage().beforeRefresh : 0,
                    success: false,
                    logs: [error]
                });
            });
    });
}

