// Initialize Express app
const app = express();
app.use(express.json());

// MongoDB connection setup
mongoose.connect('mongodb://localhost:27017/theme_bitmap', { useNewUrlParser: true, useUnifiedTopology: true });

// Redis client setup
const redisClient = redis.createClient();

// Middleware for rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Route for fetching theme bitmap data
app.get('/theme-bitmap', async (req, res) => {
  try {
    const cacheKey = 'theme_bitmap_data';
    let cachedData = await redisClient.get(cacheKey);

    if (cachedData) {
      return res.json(JSON.parse(cachedData));
    }

    // Fetch data from multiple APIs
    const api1Response = await axios.get('https://api1.example.com/theme-bitmap');
    const api2Response = await axios.get('https://api2.example.com/theme-bitmap');

    // Combine and process data
    const combinedData = {
      ...api1Response.data,
      ...api2Response.data
    };

    // Cache the result in Redis
    redisClient.setex(cacheKey, 3600, JSON.stringify(combinedData));

    res.json(combinedData);
  } catch (error) {
    console.error('Error fetching theme bitmap data:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Route for analytics
app.get('/analytics', async (req, res) => {
  try {
    // Fetch and return analytics data from MongoDB
