// Route for sending user notifications
app.post('/send-notification', async (req, res) => {
  try {
    const { message, userId } = req.body;

    // Send notification using a third-party messaging service
    await axios.post('https://messaging-service.example.com/send', { message, userId });

    res.status(200).json({ success: true });
