import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;

public class EventLogProcessor {

    public static void main(String[] args) {
        // Example usage
        Event[] events = {
            new Event(LocalDateTime.of(2023, 1, 1, 10, 0), LocalDateTime.of(2023, 1, 1, 12, 0)),
            new Event(LocalDateTime.of(2023, 1, 1, 13, 0), LocalDateTime.of(2023, 1, 1, 15, 0)),
            // Add more events as needed
        };

        Map<Integer, Integer> disjointPairs = findDisjointEventPairs(events);
        System.out.println("Disjoint Event Pairs: " + disjointPairs);

        // Test cases
        validateFunctionality();
    }

    public static Map<Integer, Integer> findDisjointEventPairs(Event[] events) {
        Arrays.sort(events, Comparator.comparingLong(e -> e.start.toInstant().toEpochMilli()));

        UnionFind uf = new UnionFind(events.length);
        for (int i = 0; i < events.length - 1; i++) {
            if (!events[i].overlaps(events[i + 1])) {
                uf.union(i, i + 1);
            }
        }

        Map<Integer, Integer> disjointPairs = new HashMap<>();
        for (int i = 0; i < events.length; i++) {
            disjointPairs.put(uf.find(i), i);
        }

        return disjointPairs;
    }

    public static void validateFunctionality() {
        // Implement unit tests with various scenarios including edge cases
    }
}

class Event {
    LocalDateTime start;
    LocalDateTime end;

    public Event(LocalDateTime start, LocalDateTime end) {
        this.start = start;
        this.end = end;
    }

    public boolean overlaps(Event other) {
        return !this.end.isBefore(other.start) && !other.end.isBefore(this.start);
    }
}

class UnionFind {
    int[] parent;

    public UnionFind(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX;
        }
    }
}
