use hyper::{Client, Request, Uri};
use hyper_tls::HttpsConnector;
use tokio::sync::{Semaphore, RwLock};
use std::collections::HashMap;

pub struct HttpClient {
    client: Client<HttpsConnector>,
    semaphore: Semaphore,
    rate_limiter: RateLimiter,
}

impl HttpClient {
    pub fn new(max_connections: usize) -> Self {
        let https_connector = HttpsConnector::new();
        let client = Client::builder().build::<_, hyper::Body>(https_connector);
        let semaphore = Semaphore::new(max_connections);
        let rate_limiter = RateLimiter::new();

        HttpClient {
            client,
            semaphore,
            rate_limiter,
        }
    }

    pub async fn get(&self, uri: Uri) -> Result<hyper::Response<hyper::Body>, hyper::Error> {
        self.rate_limiter.acquire().await?;
        let permit = self.semaphore.acquire().await?;
        let response = self.client.get(uri).send().await?;
        drop(permit);
        Ok(response)
    }

    pub async fn post(
        &self,
        uri: Uri,
        body: hyper::Body,
    ) -> Result<hyper::Response<hyper::Body>, hyper::Error> {
        self.rate_limiter.acquire().await?;
        let permit = self.semaphore.acquire().await?;
        let response = self.client.post(uri).body(body).send().await?;
        drop(permit);
        Ok(response)
    }
}

struct RateLimiter {
    last_request_time: std::time::Instant,
    requests_made: u32,
    max_requests_per_second: f64,
}

impl RateLimiter {
    fn new() -> Self {
        RateLimiter {
            last_request_time: std::time::Instant::now(),
            requests_made: 0,
            max_requests_per_second: 1.0, // Adjust based on SLA requirements
        }
    }

    async fn acquire(&self) -> Result<(), hyper::Error> {
        loop {
            let now = std::time::Instant::now();
            if now.duration_since(self.last_request_time).as_secs_f64() > self.max_requests_per_second {
                self.requests_made = 0;
                self.last_request_time = now;
            } else if self.requests_made < self.max_requests_per_second as u32 {
                self.requests_made += 1;
                break;
            }
            tokio::time::sleep(std::time::Duration::from_secs_f64(1.0 / self.max_requests_per_second)).await;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
