    #[tokio::test]
    async fn test_get_request() {
        let client = HttpClient::new(1);
        let uri = "https://api.example.com/data".parse().unwrap();
        match client.get(uri).await {
            Ok(_) => println!("GET request successful"),
            Err(e) => eprintln!("GET request failed: {}", e),
        }
    }

    #[tokio::test]
