class ClinicStatusUpdater {
    private $loop;
    private $dbPool;
    private $redis;
    private $kafkaProducer;
    private $authenticator;
    private $clusterManager;

    public function __construct() {
        $this->loop = LoopFactory::create();
        $this->dbPool = new ConnectionPool();
        $this->redis = new RedisClient('tcp://127.0.0.1:6379');
        $this->kafkaProducer = new KafkaProducer('localhost:9092');
        $this->authenticator = new Authenticator();
        $this->clusterManager = new ClusterManager();
    }

    public function updateClinicStatusAsync(string $clinicId, string $newStatus, string $lastModifiedIp, \DateTime $date, ?string $metadataJson): PromiseInterface {
        return $this->clusterManager->getClusterForClinic($clinicId)
            ->then(function ($db) use ($clinicId, $newStatus, $lastModifiedIp, $date, $metadataJson) {
                return $this->dbPool->getConnection($db)
                    ->query("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?", [$newStatus, $lastModifiedIp, $date->format('Y-m-d H:i:s'), $clinicId]);
            })
            ->then(function () use ($redis, $metadataJson) {
                if ($metadataJson !== null) {
                    $this->redis->set("clinic:{$metadataJson['id']}", json_encode($metadataJson));
                }
            })
            ->then(function () use ($kafkaProducer, $clinicId, $newStatus) {
                $message = [
                    'topic' => 'ClinicStatusUpdate',
                    'value' => json_encode(['clinic_id' => $clinicId, 'status' => $newStatus])
                ];
                return $this->kafkaProducer->produce($message);
            });
    }
}

