#[actix_web::get("/generate-certificate")]
async fn generate_certificate(data: web::Data<AppState>, client_id: web::Query<String>, redirect_uri: web::Query<String>) -> HttpResponse {
    let token = oauth::exchange_token(&client_id, &redirect_uri).await?;
    let certificate = data.kms_client.lock().unwrap().get_certificate(&token).await?;
    Ok(HttpResponse::Ok().body(certificate))
}

#[actix_web::main]
