    let kms_client = Arc::new(Mutex::new(kms_client::KMSClient::new("https://kms.example.com")));
    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(AppState { kms_client: kms_client.clone() }))
            .route("/generate-certificate", web::get().to(generate_certificate))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

