<?php
// Include necessary libraries and initialize services
require_once 'vendor/autoload.php';

use League\OAuth2\Client\Provider\Facebook;
use League\OAuth2\Client\Provider\Google;
use League\OAuth2\Client\Provider\LinkedIn;

$providers = [
    new Facebook(['clientId' => 'your_facebook_client_id', 'clientSecret' => 'your_facebook_client_secret']),
    new Google(['clientId' => 'your_google_client_id', 'clientSecret' => 'your_google_client_secret']),
    new LinkedIn(['clientId' => 'your_linkedin_client_id', 'clientSecret' => 'your_linkedin_client_secret'])
];

// Authenticate user with OAuth provider
function authenticateUser($providerKey, $code) {
    global $providers;

    if (!isset($providers[$providerKey])) {
        throw new Exception("Provider not found");
    }

    $provider = $providers[$providerKey];
    try {
        $token = $provider->getAccessToken('authorization_code', ['code' => $code]);
        // Store token in distributed cache
        Cache::put($token->getToken(), json_encode($token), now()->addHours(1));
        return $token;
    } catch (\Exception $e) {
        throw new Exception("Authentication failed: " . $e->getMessage());
    }
}

// Authorize user based on stored tokens
function authorizeUser($userId, $accessToken) {
    // Validate token and check permissions
    if (!Cache::has($accessToken)) {
        throw new Exception("Token not found or expired");
    }

    $token = json_decode(Cache::get($accessToken), true);
    if ($token['user_id'] != $userId) {
        throw new Exception("Unauthorized access attempt");
    }

    // Check for user permissions
    if (!hasPermission('access_resource')) {
        throw new Exception("Insufficient permissions");
    }

    return true;
}

// Example usage
try {
    $providerKey = 'facebook'; // or 'google', 'linkedin'
    $code = $_GET['code'];
    $token = authenticateUser($providerKey, $code);
    authorizeUser($userId, $token->getToken());
    echo "Access granted";
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

