['```go
package main

import (
	"context"
	"fmt"
	"net/http"
	"time"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
	"github.com/aws/aws-sdk-go/service/s3/s3manager"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"go.uber.org/zap"
)

var logger *zap.Logger

func init() {
	var err error
	logger, err = zap.NewProduction()
	if err != nil {
		panic(err)
	}
	defer logger.Sync()

	sugar := logger.Sugar()
	sugar.Info("Initializing file storage system")
}

func uploadFile(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "Error retrieving file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	validated := validateFile(header)
	if !validated {
		http.Error(w, "Invalid file type or size", http.StatusUnsupportedMediaType)
		return
	}

	sess, _ := session.NewSession(&aws.Config{
		Region: aws.String("us-east-1")},
	)

	uploader := s3manager.NewUploader(sess)
	result, err := uploader.UploadWithContext(ctx, &s3manager.UploadInput{
		Bucket: aws.String("my-bucket"),
		Key:    aws.String(header.Filename),
		Body:   file,
	})
	if err != nil {
		http.Error(w, "Error uploading file", http.StatusInternalServerError)
		return
	}

	logger.Info("File uploaded successfully",
		zap.String("file_name", header.Filename),
		zap.String("upload_location", result.Location))

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "File uploaded: %s\n", result.Location)
}

func validateFile(header *http.Header) bool {
	maxSize := 10 * 1024 * 1024 // 10 MB
	allowedTypes := []string{"image/png", "image/jpeg"}

	fileType := header.Get("Content-Type")
	fileSize, _ := strconv.Atoi(header.Get("Content-Length"))

	return fileSize <= maxSize && slices.Contains(allowedTypes, fileType)
}

func main() {
	r := chi.NewRouter()
	r.Use(middleware.Logger)

	r.Post("/upload", uploadFile)

	http.ListenAndServe(":8080", r)
}
```']

