// Define a transaction struct for data modeling
struct Transaction {
    int id;
    double amount;
    long timestamp;
};

// Asynchronous processing queue for transactions
class TransactionQueue {
private:
    std::queue<std::shared_ptr<Transaction>> transactions;
    std::mutex mtx;
    std::condition_variable cv;
    bool running;

public:
    TransactionQueue() : running(true) {}

    void push(const std::shared_ptr<Transaction>& tx) {
        std::unique_lock<std::mutex> lock(mtx);
        transactions.push(tx);
        cv.notify_one();
    }

    void pop(std::shared_ptr<Transaction>& tx) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !transactions.empty() || !running; });
        if (!running && transactions.empty()) {
            throw std::runtime_error("Queue is empty and stopping");
        }
        tx = transactions.front();
        transactions.pop();
    }

    void stop() {
        running = false;
        cv.notify_all();
    }
};

