import random

class NotificationService:
    def send_sms(self, user_id, message):
        # Simulate SMS sending
        print(f"Sending SMS to {user_id}: {message}")

    def send_email(self, user_id, subject, body):
        # Simulate email sending
        print(f"Sending Email to {user_id}: {subject} - {body}")

class NotificationQueue:
    def __init__(self):
        self.queue = deque()

    async def enqueue(self, notification):
        self.queue.append(notification)

    async def dequeue(self):
        if self.queue:
            return self.queue.popleft()
        else:
            raise IndexError("No notifications in queue")

class NotificationManager:
    def __init__(self):
        self.services = {
            'sms': NotificationService().send_sms,
            'email': NotificationService().send_email
        }

    async def sendNotification(self, user_id, message, channel='sms'):
        service = self.services.get(channel)
        if service:
            await asyncio.to_thread(service, user_id, message)
        else:
            print(f"No notification service available for {channel}")

class LoadBalancer:
    def __init__(self):
        self.notification_managers = [NotificationManager() for _ in range(3)]

    async def route_notification(self, user_id, message, channel='sms'):
        manager = random.choice(self.notification_managers)
        await manager.sendNotification(user_id, message, channel)

# Example usage
async def main():
    lb = LoadBalancer()
    await lb.route_notification('user123', 'Hello!', 'email')

asyncio.run(main())
