namespace NetworkHealthMonitor
{
    public class NetworkHealthMonitor
    {
        private readonly HttpClient _httpClient;
        private readonly string _configApiUrl;
        private List<NetworkService> _networkServices;
        private Dictionary<string, ServiceStatus> _serviceStatuses;
        private Timer _monitoringTimer;

        public NetworkHealthMonitor(string configApiUrl)
        {
            _configApiUrl = configApiUrl;
            _httpClient = new HttpClient();
            _networkServices = new List<NetworkService>();
            _serviceStatuses = new Dictionary<string, ServiceStatus>();

            // Initialize with configuration and services
            LoadConfigurationAsync().Wait();
            StartMonitoring();
        }

        private async Task LoadConfigurationAsync()
        {
            var configResponse = await _httpClient.GetAsync(_configApiUrl);
            if (configResponse.IsSuccessStatusCode)
            {
                var config = await configResponse.Content.ReadAsAsync<NetworkMonitorConfig>();
                _networkServices = config.Services;
                _serviceStatuses = new Dictionary<string, ServiceStatus>(StringComparer.OrdinalIgnoreCase);

                foreach (var service in _networkServices)
                {
                    _serviceStatuses[service.Id] = new ServiceStatus { Status = ServiceHealth.Unknown };
                }
            }
        }

        private void StartMonitoring()
        {
            _monitoringTimer = new Timer(MonitorNetworkServices, null, TimeSpan.Zero, TimeSpan.FromSeconds(1));
        }

        private async void MonitorNetworkServices(object state)
        {
            foreach (var service in _networkServices)
            {
                try
                {
                    var status = await CheckServiceHealthAsync(service);
                    UpdateServiceStatus(service.Id, status);
                }
                catch (Exception ex)
                {
                    // Handle exceptions and update status accordingly
                }
            }
        }

        private async Task<ServiceHealth> CheckServiceHealthAsync(NetworkService service)
        {
            // Implement health check logic here
            // Example: Send a request to the service and parse the response
            var client = new HttpClient();
            HttpResponseMessage response = await client.GetAsync(service.Url);
            if (response.IsSuccessStatusCode)
            {
                return ServiceHealth.Healthy;
            }
            else
            {
                return ServiceHealth.Unhealthy;
            }
        }

        private void UpdateServiceStatus(string serviceId, ServiceHealth status)
        {
            lock (_serviceStatuses)
            {
                _serviceStatuses[serviceId] = new ServiceStatus { Status = status };
            }

            // Trigger alerts or notifications based on the status change
        }
    }

    public class NetworkMonitorConfig
    {
        public List<NetworkService> Services { get; set; }
    }

    public class NetworkService
    {
        public string Id { get; set; }
        public string Url { get; set; }
    }

    public enum ServiceHealth
    {
        Unknown,
        Healthy,
        Unhealthy
    }

    public class ServiceStatus
    {
        public ServiceHealth Status { get; set; }
    }
}
