#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include "json-c/json.h"

typedef struct {
    char *resourceUrl;
    char *cacheDir;
    int version;
} ResourceBundleConfig;

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if(ptr == NULL) {
        /* out of memory! */
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;

    return realsize;
}

char* fetchResource(ResourceBundleConfig *config) {
    CURL *curl_handle;
    CURLcode res;
    MemoryStruct chunk;
    chunk.data = malloc(1);  
    chunk.size = 0;  

    curl_global_init(CURL_GLOBAL_ALL);

    curl_handle = curl_easy_init();
    if(curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, config->resourceUrl);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl_handle);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl_handle);
    }

    curl_global_cleanup();

    return chunk.data;
}

json_object* parseJson(char *data) {
    json_object *parsed_json = NULL;
    json_error_t error;

    parsed_json = json_tokener_parse_ex(&error, data, strlen(data));
    if(parsed_json == NULL) {
        fprintf(stderr, "Error on line %d: %s\n", error.line, error.text);
    }

    return parsed_json;
}

ResourceBundleConfig* initConfig(char *resourceUrl, char *cacheDir, int version) {
    ResourceBundleConfig *config = (ResourceBundleConfig*) malloc(sizeof(ResourceBundleConfig));
    config->resourceUrl = resourceUrl;
    config->cacheDir = cacheDir;
    config->version = version;
    return config;
}

void loadResourceBundle(ResourceBundleConfig *config) {
    char *data = fetchResource(config);
    json_object *json = parseJson(data);

    if(json != NULL) {
        // Process the JSON data
    } else {
        fprintf(stderr, "Failed to parse JSON data.\n");
    }

    free(data);
}

int main() {
    ResourceBundleConfig *config = initConfig("http://example.com/resource.json", "/cache/dir", 1);
    loadResourceBundle(config);

    free(config->resourceUrl);
    free(config->cacheDir);
    free(config);

    return 0;
}
