class LogProcessor {
public:
    LogProcessor(const std::string& db_config) : database(db_config), stop(false) {}

    void addLogSource(std::string source, std::function<void()> extractMetadata) {
        logSources[source] = extractMetadata;
    }

    void startProcessing() {
        for (auto& source : logSources) {
            std::thread([this, source]() {
                while (!stop) {
                    source.second();
                }
            }).detach();
        }
    }

    void stopProcessing() {
        stop = true;
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

