        MD5_Init(&md5);
        MD5_Update(&md5, data.c_str(), data.size());
        MD5_Final(digest, &md5);

        // Convert the checksum to a hex string
        std::stringstream ss;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(digest[i]);
        }

