using log4net;

public class DynamicWebsiteManager
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(DynamicWebsiteManager));
    private static ConcurrentDictionary<string, WebsiteInstance> _websiteInstances = new ConcurrentDictionary<string, WebsiteInstance>();

    public void AddWebsite(string websiteName, string targetDirectory)
    {
        // Prerequisites verification
        if (!Directory.Exists(targetDirectory) || !Directory.CanWrite(targetDirectory))
        {
            Log.Error("Target directory does not exist or is not writable.");
            throw new Exception("Invalid directory path.");
        }

        if (!File.Exists(Path.Combine(targetDirectory, "web.config")) || !IsValidWebConfig(Path.Combine(targetDirectory, "web.config")))
        {
            Log.Error("Invalid web.config file.");
            throw new Exception("Invalid web.config file.");
        }

        // Check for unique website name and domain
        foreach (var instance in _websiteInstances.Values)
        {
            if (instance.Name == websiteName || instance.RootDomain == GetRootDomain(targetDirectory))
            {
                Log.Error("Website name or root domain already exists.");
                throw new Exception("Duplicate website name or root domain.");
            }
        }

        // IIS integration and health monitoring
        EnsureIisServiceRunning();
        if (!IsIisHealthy())
        {
            Log.Fatal("IIS service is not healthy.");
            throw new Exception("IIS service is not healthy.");
        }

        // Create and start website instance
        var websiteInstance = new WebsiteInstance(websiteName, targetDirectory);
        _websiteInstances.TryAdd(websiteName, websiteInstance);
        websiteInstance.Start();

        Log.Info($"Website '{websiteName}' added successfully.");
    }

    private bool IsValidWebConfig(string webConfigPath)
    {
        // Implement validation logic for the web.config file
        return true;
    }

    private string GetRootDomain(string targetDirectory)
    {
        // Extract root domain from web.config or target directory
        return "example.com";
    }

    private void EnsureIisServiceRunning()
    {
        using (var serviceController = new ServiceController("W3SVC"))
        {
            if (serviceController.Status != ServiceControllerStatus.Running)
            {
                serviceController.Start();
                serviceController.WaitForStatus(ServiceControllerStatus.Running);
            }
        }
    }

    private bool IsIisHealthy()
    {
        // Implement health check logic for IIS
        try
        {
            Ping pingSender = new Ping();
            PingOptions options = new PingOptions();

            // Use the default Ttl value which is 128,
            // but change the fragmentation behavior.
            options.DontFragment = true;

            // Create a buffer of 32 bytes of data to be transmitted.
            string data = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
            byte[] buffer;
            int timeout = 120;

            buffer = System.Text.Encoding.ASCII.GetBytes(data);

            PingReply reply = pingSender.Send("www.example.com", timeout, buffer, options);
            return reply.Status == IPStatus.Success;
        }
        catch
        {
            return false;
        }
    }

    public void RemoveWebsite(string websiteName)
    {
        if (!_websiteInstances.TryRemove(websiteName, out var websiteInstance))
        {
            Log.Warn($"Website '{websiteName}' not found.");
            throw new Exception("Website not found.");
        }

        websiteInstance.Stop();
        Log.Info($"Website '{websiteName}' removed successfully.");
    }
}

public class WebsiteInstance
{
    public string Name { get; private set; }
    public string RootDomain { get; private set; }
    public Process IisProcess { get; private set; }

    public WebsiteInstance(string name, string targetDirectory)
    {
        Name = name;
        RootDomain = "example.com"; // Extract from web.config or directory
        IisProcess = null;
    }

    public void Start()
    {
        try
        {
            var startInfo = new ProcessStartInfo
            {
                FileName = "iisreset",
                Arguments = $"/site:{Name} /start",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            IisProcess = Process.Start(startInfo);
            string output = IisProcess.StandardOutput.ReadToEnd();
            string error = IisProcess.StandardError.ReadToEnd();

            if (!string.IsNullOrEmpty(output))
            {
                Log.Info($"IIS reset output: {output}");
            }

            if (!string.IsNullOrEmpty(error))
            {
                Log.Error($"IIS reset error: {error}");
                throw new Exception("Failed to start website.");
            }
        }
        catch (Exception ex)
        {
            Log.Fatal(ex, "Failed to start website.");
            throw;
        }
    }

    public void Stop()
    {
        try
        {
            if (IisProcess != null && !IisProcess.HasExited)
            {
                IisProcess.Kill();
                IisProcess.WaitForExit();
            }
        }
        catch (Exception ex)
        {
            Log.Fatal(ex, "Failed to stop website.");
            throw;
        }
    }
}
