#include <websocketpp/config/asio_no_tls_client.hpp>
#include <websocketpp/client.hpp>
#include <map>
#include <thread>
#include <mutex>

typedef websocketpp::client<websocketpp::config::asio_no_tls_client> client;

class WebSocketLibrary {
public:
    WebSocketLibrary() {}

    void addVendor(const std::string& vendor, const std::string& url) {
        vendors[vendor] = url;
    }

    void start() {
        for (const auto& [vendor, url] : vendors) {
            threads.emplace_back([this, vendor, url]() { connect(vendor, url); });
        }
        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    std::map<std::string, std::string> vendors;
    std::vector<std::thread> threads;

    void connect(const std::string& vendor, const std::string& url) {
        client c;
        c.init_asio();

        client::connection_ptr con = c.get_connection(url);
        c.connect(con);

        try {
            c.wait();
        } catch (const websocketpp::lib::error_code& e) {
            std::cerr << "Connection error: " << e.message() << std::endl;
        }
    }
};
```

This code block provides a basic structure for the WebSocket library. It initializes a client, adds vendors with their respective URLs, and connects to each vendor's WebSocket server in separate threads. This modular approach allows for easy expansion and integration of additional vendors as needed.']

