using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DataProcessingService : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private readonly IDatabaseService _databaseService;
    private bool _disposed = false;

    public DataProcessingService(HttpClient httpClient, ILogger logger, IDatabaseService databaseService)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _databaseService = databaseService ?? throw new ArgumentNullException(nameof(databaseService));
    }

    public async Task ProcessDataAsync(byte[] data, string mimeType)
    {
        try
        {
            if (!IsValidMimeType(mimeType))
            {
                throw new ArgumentException("Invalid MIME type.");
            }

            var encryptedData = EncryptData(data);
            await _databaseService.SaveAsync(encryptedData);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing data.");
            throw;
        }
    }

    private bool IsValidMimeType(string mimeType)
    {
        return new List<string> { "image/jpeg", "application/pdf" }.Contains(mimeType);
    }

    private byte[] EncryptData(byte[] data)
    {
        using (var aes = Aes.Create())
        {
            var key = Encoding.UTF8.GetBytes("YourSecretKey123"); // Replace with secure key generation
            var iv = Encoding.UTF8.GetBytes("YourInitializationVector"); // Replace with secure IV generation

            aes.Key = key;
            aes.IV = iv;

            using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
            {
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        csEncrypt.Write(data, 0, data.Length);
                    }
                    return msEncrypt.ToArray();
                }
            }
        }
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_disposed)
        {
            return;
        }

        if (disposing)
        {
            // Dispose managed resources.
            _httpClient.Dispose();
            _logger.Dispose();
            _databaseService.Dispose();
        }

        // Free unmanaged resources (unmanaged objects) and override a finalizer below.
        _disposed = true;
    }

    public void Dispose()
    {
        // Do not change this code. Put cleanup code in Dispose(bool disposing) above.
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}
```

