        _logger = logger;
        _tokenizationService = tokenizationService;
    }

    public async Task ProcessTransactionAsync(TransactionRequest request)
    {
        try
        {
            var tokenizedCardInfo = await _tokenizationService.TokenizeCard(request.CardInfo);
            var response = await SendPaymentRequest(tokenizedCardInfo, request.Amount);

            if (response.IsSuccessStatusCode)
            {
                _logger.LogInformation("Transaction processed successfully.");
            }
            else
            {
                _logger.LogError("Failed to process transaction. Status code: {StatusCode}", response.StatusCode);
                // Retry logic can be implemented here
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing transaction.");
            // Handle exceptions and retry logic
        }
    }

    private async Task<HttpResponseMessage> SendPaymentRequest(TokenizedCardInfo tokenizedCardInfo, decimal amount)
    {
        var requestUrl = "https://thirdpartygateway.com/api/payments";
        var requestBody = new { cardToken = tokenizedCardInfo.Token, amount };

        var content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(requestBody), System.Text.Encoding.UTF8, "application/json");

        return await _httpClient.PostAsync(requestUrl, content);
    }
