using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public interface IHasher
{
    string HashData(string data);
}

public class MD5Hasher : IHasher
{
    public string HashData(string data)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(data);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}

public class SHA1Hasher : IHasher
{
    public string HashData(string data)
    {
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(data);
            byte[] hashBytes = sha1.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}

public class SHA256Hasher : IHasher
{
    public string HashData(string data)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(data);
            byte[] hashBytes = sha256.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}

public class SHA512Hasher : IHasher
{
    public string HashData(string data)
    {
        using (SHA512 sha512 = SHA512.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(data);
            byte[] hashBytes = sha512.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}

public class HasherFactory
{
    public static IHasher CreateHasher(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "md5":
                return new MD5Hasher();
            case "sha1":
                return new SHA1Hasher();
            case "sha256":
                return new SHA256Hasher();
            case "sha512":
                return new SHA512Hasher();
            default:
                throw new ArgumentException("Unsupported algorithm");
        }
    }
}

public class HashService
{
    private readonly IHasher _hasher;
    private readonly ILogger _logger;

    public HashService(IHasher hasher, ILogger logger)
    {
        _hasher = hasher;
        _logger = logger;
    }

    public string HashData(string data, string algorithm)
    {
        try
        {
            string hash = _hasher.HashData(data);
            _logger.Log($"{DateTime.Now}, Data: {data}, Algorithm: {algorithm}, Outcome: Success");
            return hash;
        }
        catch (Exception ex)
        {
            _logger.Log($"{DateTime.Now}, Data: {data}, Algorithm: {algorithm}, Outcome: Failure, Error: {ex.Message}");
            throw;
        }
    }
}

public interface ILogger
{
    void Log(string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}

// Usage example
class Program
{
    static async Task Main(string[] args)
    {
        ILogger logger = new ConsoleLogger();
        HashService hashService = new HashService(HasherFactory.CreateHasher("SHA256"), logger);

        string data = "Hello, World!";
        string hash = await Task.Run(() => hashService.HashData(data, "SHA256"));
        Console.WriteLine($"Hash: {hash}");
    }
}
