#define MAX_DEVICES 10000

typedef struct {
    long offset;
    int key;
    int value;
} DeviceStatus;

typedef struct {
    DeviceStatus *statuses[MAX_DEVICES];
    int count;
    pthread_mutex_t lock;
} StatusCollection;

typedef struct {
    CURL *curl_handle;
    char *api_key;
} ApiClient;

void init_status_collection(StatusCollection *collection) {
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_device_status(StatusCollection *collection, DeviceStatus *status) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count < MAX_DEVICES) {
        collection->statuses[collection->count++] = status;
    }
    pthread_mutex_unlock(&collection->lock);
}

DeviceStatus* get_device_status(StatusCollection *collection, int index) {
    DeviceStatus *status = NULL;
    pthread_mutex_lock(&collection->lock);
    if (index >= 0 && index < collection->count) {
        status = collection->statuses[index];
    }
    pthread_mutex_unlock(&collection->lock);
    return status;
}

void cleanup_status_collection(StatusCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
}

ApiClient* create_api_client(const char *api_key) {
    ApiClient *client = (ApiClient *)malloc(sizeof(ApiClient));
    client->curl_handle = curl_easy_init();
    client->api_key = strdup(api_key);
    return client;
}

void destroy_api_client(ApiClient *client) {
    if (client->curl_handle) {
        curl_easy_cleanup(client->curl_handle);
    }
    free(client->api_key);
    free(client);
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    // Handle response data
    return size * nmemb;
}

void make_api_call(ApiClient *client, const char *url) {
    CURLcode res;
    curl_easy_setopt(client->curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(client->curl_handle, CURLOPT_HTTPHEADER,
                     curl_slist_append(NULL, "Authorization: Bearer " client->api_key));
    curl_easy_setopt(client->curl_handle, CURLOPT_WRITEFUNCTION, write_callback);
    res = curl_easy_perform(client->curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "API call failed: %s\n", curl_easy_strerror(res));
    }
}

int main() {
    StatusCollection collection;
    init_status_collection(&collection);

    // Example usage
