#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    char *metadata;
} event;

event *events = NULL;
long *offsets = NULL;
int *keys = NULL;
int num_events = 0;
int max_events = 10000;
int metadata_range_min = 0;
int metadata_range_max = 100000;
int logging_level = 1;

pthread_mutex_t events_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t offsets_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t keys_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    if (logging_level > 0) {
        printf("%s\n", message);
    }
}

int initialize_event_logging_system(int initial_events, int metadata_min, int metadata_max, int level) {
    if (initial_events < 1000 || initial_events > 50000) {
        log_message("Error: Invalid number of events requested.");
        return -1;
    }

    metadata_range_min = metadata_min;
    metadata_range_max = metadata_max;
    logging_level = level;

    events = (event *)malloc(initial_events * sizeof(event));
    offsets = (long *)malloc(initial_events * sizeof(long));
    keys = (int *)malloc(initial_events * sizeof(int));

    if (!events || !offsets || !keys) {
        log_message("Error: Memory allocation failed.");
        free(events);
        free(offsets);
        free(keys);
        return -1;
    }

    num_events = initial_events;
    max_events = 50000;

    srand(time(NULL));
    for (int i = 0; i < num_events; i++) {
        events[i].key = rand() % max_events + 1;
        events[i].metadata = (char *)malloc(20 * sizeof(char)); // Example metadata size
        if (!events[i].metadata) {
            log_message("Error: Memory allocation failed for metadata.");
            return -1;
        }
        sprintf(events[i].metadata, "Data %d", i);
    }

    log_message("Event logging system initialized successfully.");
    return 0;
}

void *event_logging_thread(void *arg) {
    int thread_id = *(int *)arg;
    pthread_mutex_lock(&events_mutex);
    if (num_events < max_events) {
        events[num_events].key = rand() % max_events + 1;
        sprintf(events[num_events].metadata, "Data from thread %d", thread_id);
        num_events++;
    }
    pthread_mutex_unlock(&events_mutex);
    return NULL;
}

int main() {
    int initial_events = 5000;
    int metadata_min = 0;
    int metadata_max = 100000;
    int level = 2;

    if (initialize_event_logging_system(initial_events, metadata_min, metadata_max, level) != 0) {
        return -1;
    }

    pthread_t threads[5];
    int thread_ids[5];

    for (int i = 0; i < 5; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, event_logging_thread, &thread_ids[i]) != 0) {
            log_message("Error: Thread creation failed.");
            return -1;
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_events; i++) {
        free(events[i].metadata);
    }

    free(events);
    free(offsets);
    free(keys);

    log_message("Event logging system terminated successfully.");
    return 0;
}
```

