        if (strcmp(config->current_environment, config->sources[i].url) == 0) {
            apply_conditional_logic(config->sources[i].config, config->current_environment);
            break;
        }
    }

    return validate_configuration(merge_configurations((Configuration *)config));
}

int main(int argc, char *argv[]) {
    Configuration config = {0};
    int status_code = CURLE_OK;

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <environment> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    config.current_environment = argv[1];
    snprintf(config.sources[0].url, sizeof(config.sources[0].url), "http://dev.example.com/config.json");
    parse_json_from_url(config.sources[0].url, &config.sources[0].config);
    config.environment_count++;

    snprintf(config.sources[1].url, sizeof(config.sources[1].url), "http://staging.example.com/config.json");
    parse_json_from_url(config.sources[1].url, &config.sources[1].config);
    config.environment_count++;

    status_code = process_configuration(&config);

    if (status_code != 0) {
        log_message(LOG_ERROR, "Configuration processing failed", __FILE__, __LINE__);
        return EXIT_FAILURE;
    }

    // Save configuration to output file
    FILE *output_file = fopen(argv[2], "w");
    json_object_to_file_ext(output_file, config.sources[0].config, JSON_C_TO_FILE_PRETTY);
    fclose(output_file);

    log_message(LOG_INFO, "Configuration processed successfully", __FILE__, __LINE__);

    return EXIT_SUCCESS;
}
