#include <iostream>
#include <string>
#include <vector>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/aes.h>
#include <openssl/gcm.h>

class EncryptionLibrary {
public:
    void encrypt(const std::string& plaintext, std::string& ciphertext) {
        // Implementation of AES-256-GCM encryption
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key.data(), iv.data());
        int len;
        EVP_EncryptUpdate(ctx, nullptr, &len, plaintext.c_str(), plaintext.size());
        ciphertext.resize(len);
        EVP_EncryptFinal_ex(ctx, ciphertext.data(), &len);
        ciphertext.append(reinterpret_cast<char*>(tag.data()), GCM_TAG_LEN);
        EVP_CIPHER_CTX_free(ctx);
    }

    void decrypt(const std::string& ciphertext, std::string& decryptedtext) {
        // Implementation of AES-256-GCM decryption
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key.data(), iv.data());
        int len;
        EVP_DecryptUpdate(ctx, nullptr, &len, ciphertext.c_str(), ciphertext.size() - GCM_TAG_LEN);
        decryptedtext.resize(len);
        EVP_DecryptFinal_ex(ctx, decryptedtext.data(), &len);
        uint8_t tag[GCM_TAG_LEN];
        memcpy(tag, ciphertext.data() + len, GCM_TAG_LEN);
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, GCM_TAG_LEN, tag) <= 0) {
            // Handle decryption failure
        }
        EVP_CIPHER_CTX_free(ctx);
    }

private:
    std::array<uint8_t, AES_KEY_SIZE> key;
    std::array<uint8_t, AES_BLOCK_SIZE> iv;
    std::array<uint8_t, GCM_TAG_LEN> tag = {0};
};

int main() {
    EncryptionLibrary lib;
    std::string plaintext = "Sensitive data";
    std::string ciphertext;
    std::string decryptedtext;

    lib.encrypt(plaintext, ciphertext);
    std::cout << "Ciphertext: " << ciphertext << std::endl;

    lib.decrypt(ciphertext, decryptedtext);
    std::cout << "Decrypted text: " << decryptedtext << std::endl;

    return 0;
}
