#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/err.h>

// Define interface for external data sources
class ExternalDataSource {
public:
    virtual void send(const std::string& data) = 0;
    virtual void receive(std::string& data) = 0;
};

// Define encryption library class
class EncryptionLibrary {
private:
    AES_KEY key;
    GCM128_CONTEXT ctx;
    std::mutex mutex;
    std::condition_variable cv;

public:
    EncryptionLibrary(const std::string& key_material) {
        // Initialize AES key from key material
        AES_set_encrypt_key(reinterpret_cast<const unsigned char*>(key_material.c_str()), 256, &key);
    }

    void encrypt(const std::string& plaintext, std::string& ciphertext, std::vector<unsigned char>& tag) {
        std::lock_guard<std::mutex> lock(mutex);

        // Initialize GCM context
        AES_GCM_setiv(&ctx, reinterpret_cast<const unsigned char*>("initial_iv"), 12);
        AES_GCM_addauth(&ctx, nullptr, 0, nullptr, 0);

        // Encrypt plaintext and generate tag
        ciphertext.resize(plaintext.size());
        int len;
        AES_GCM_encrypt(&ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]), 
                          reinterpret_cast<const unsigned char*>(plaintext.c_str()), 
                          plaintext.size(), &len);
        AES_GCM_finish(&ctx, reinterpret_cast<unsigned char*>(&tag[0]));
    }

    void decrypt(const std::string& ciphertext, std::string& plaintext, const std::vector<unsigned char>& tag) {
        std::lock_guard<std::mutex> lock(mutex);

        // Initialize GCM context
        AES_GCM_setiv(&ctx, reinterpret_cast<const unsigned char*>("initial_iv"), 12);
        AES_GCM_addauth(&ctx, nullptr, 0, nullptr, 0);

        // Decrypt ciphertext and verify tag
        plaintext.resize(ciphertext.size());
        int len;
        if (AES_GCM_decrypt(&ctx, reinterpret_cast<unsigned char*>(&plaintext[0]), 
                             reinterpret_cast<const unsigned char*>(ciphertext.c_str()), 
                             ciphertext.size(), &len) != 1) {
            throw std::runtime_error("Decryption failed");
        }
    }

    void process_data(const std::string& data) {
        std::string encrypted;
        std::vector<unsigned char> tag(16);

        // Encrypt data
        encrypt(data, encrypted, tag);

        // Send encrypted data to external data source
        ExternalDataSource* dataSource = getExternalDataSource();
        if (dataSource) {
            dataSource->send(encrypted);
        }
    }

private:
    ExternalDataSource* getExternalDataSource() {
        // Implement logic to select and return the appropriate external data source
        return nullptr;
    }
};

// Define main function to demonstrate usage
int main() {
    EncryptionLibrary library("secret_key_material_32_bytes");

    std::string plaintext = "Sensitive information";
    std::string ciphertext;
    std::vector<unsigned char> tag;

    // Encrypt plaintext
    library.encrypt(plaintext, ciphertext, tag);

    // Decrypt ciphertext
    std::string decrypted;
    library.decrypt(ciphertext, decrypted, tag);

    std::cout << "Decrypted: " << decrypted << std::endl;

    return 0;
}
