// Class to handle concurrent uploads with prioritization and retry logic
class FileUploadManager {
private:
    std::vector<std::thread> workers;
    std::queue<std::pair<std::string, CloudStorageClient*>> upload_queue;
    std::mutex queue_mutex;
    std::condition_variable queue_cv;
    bool running;

public:
    FileUploadManager(size_t num_workers) : running(true) {
        for (size_t i = 0; i < num_workers; ++i) {
            workers.emplace_back([this]() { worker_thread(); });
        }
    }

    ~FileUploadManager() {
        running = false;
        queue_cv.notify_all();
        for (auto& thread : workers) {
            thread.join();
        }
    }

    void upload(const std::string& file_path, CloudStorageClient* uploader) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        upload_queue.push({file_path, uploader});
        queue_cv.notify_one();
    }

private:
    void worker_thread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            queue_cv.wait(lock, [this]() { return !running || !upload_queue.empty(); });
            if (!running && upload_queue.empty()) {
                break;
            }
            auto file_info = upload_queue.front();
            upload_queue.pop();
            lock.unlock();

            // Simulate uploading
            std::cout << "Uploading " << file_info.first << " using " << typeid(*file_info.second).name() << std::endl;
        }
    }
};

// Example usage
int main() {
    FileUploadManager uploader_manager(4);

    S3Uploader s3_uploader;
    GoogleCloudUploader gcs_uploader;

    uploader_manager.upload("large_file.txt", &s3_uploader);
    uploader_manager.upload("small_file.txt", &gcs_uploader);

    return 0;
}
