typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct MemoryManager {
    Record* records;
    size_t capacity;
    size_t count;
    size_t upper_limit;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* memory_manager_create(size_t initial_capacity, size_t upper_limit) {
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    if (manager == NULL) {
        return NULL;
    }
    manager->records = malloc(initial_capacity * sizeof(Record));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->upper_limit = upper_limit;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void memory_manager_destroy(MemoryManager* manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    free(manager);
}

int memory_manager_add_record(MemoryManager* manager, long offset, int key) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity || manager->count * sizeof(Record) > manager->upper_limit) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->records[i].key == key) {
            pthread_mutex_unlock(&manager->lock);
            return -2;
        }
    }
    Record new_record = {offset, key};
    manager->records[manager->count] = new_record;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int memory_manager_get_record(MemoryManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->records[i].key == key) {
            int result = manager->records[i].offset;
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void memory_manager_log_memory_usage(MemoryManager* manager) {
