void* updateDevice(void* arg) {
    pthread_mutex_lock(&lock);
    // Simulate updating device status
    int deviceID = *(int*)arg;
    if (deviceID >= 0 && deviceID < MAX_DEVICES) {
        devices[deviceID].lastUpdate = time(NULL);
        curl_global_init(CURL_GLOBAL_DEFAULT);
        CURL *curl;
        CURLcode res;
        curl = curl_easy_init();
        if(curl) {
