            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Accept: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* monitorInactiveDevices(void* arg) {
    while(1) {
        pthread_mutex_lock(&lock);
        for(int i = 0; i < deviceCount; i++) {
            time_t currentTime = time(NULL);
            if(differenceInTime(currentTime, devices[i].lastUpdate) > 60) { // Assuming 60 seconds as inactivity threshold
                // Clean up inactive device
                shiftDevices(i);
                deviceCount--;
            }
        }
        pthread_mutex_unlock(&lock);
        sleep(10); // Check every 10 seconds
    }
}

int differenceInTime(time_t t1, time_t t2) {
    return difftime(t1, t2);
}

void shiftDevices(int fromIndex) {
    for(int i = fromIndex; i < deviceCount - 1; i++) {
        devices[i] = devices[i + 1];
    }
}

int main() {
    pthread_mutex_init(&lock, NULL);
