    int i = 0;

    // Extract the base and extension from the filename
    strcpy(base, filename);
    for(i = strlen(filename); i > 0 && filename[i - 1] != '.'; i--);
    strncpy(extension, &filename[i], sizeof(extension) - 1);
    extension[sizeof(extension) - 1] = '\0';

    // Generate a unique sequence of digits based on the length of the base
    char *digits = malloc((strlen(base) + 1) * sizeof(char));
    sprintf(digits, "%d", strlen(base));

    // Append the digits to the extension and replace the original filename
    char newFilename[512];
    snprintf(newFilename, sizeof(newFilename), "%s.%s%s", base, digits, extension);
    free(digits);

    // Rename the file with the new name
    rename(filename, newFilename);
}
