from flask import Flask, request, jsonify
import requests
from functools import wraps
from time import time

app = Flask(__name__)

# Define your routing rules and backend services here
routing_rules = {
    '/api/v1/data': 'https://backend-service.com/api/data',
    '/api/v1/users': 'https://backend-service.com/api/users'
}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header:
            return jsonify({"error": "Authentication required"}), 403
        # Implement your authentication logic here (OAuth 2.0, API keys, mutual TLS)
        return f(*args, **kwargs)
    return decorated

def handle_request(method, url, headers=None, data=None):
    response = requests.request(method, url, headers=headers, json=data)
    if response.status_code == 429:
        # Handle rate limiting
        return jsonify({"error": "Rate limit exceeded"}), 429
    elif response.status_code != 200:
        # Handle other errors gracefully
        return jsonify({"error": "Internal server error"}), 500
    return response.json()

@app.route('/api/v1/data', methods=['GET'])
@require_auth
def get_data():
    url = routing_rules.get(request.path)
    if not url:
        return jsonify({"error": "Endpoint not found"}), 404
    return handle_request('GET', url, headers=request.headers)

@app.route('/api/v1/users', methods=['POST'])
@require_auth
def create_user():
    url = routing_rules.get(request.path)
    if not url:
        return jsonify({"error": "Endpoint not found"}), 404
    return handle_request('POST', url, headers=request.headers, data=request.json)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

