#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define NetworkEventStruct
typedef struct {
    time_t timestamp;
    char eventType[50];
    char metadata[1024];
} NetworkEventStruct;

// Define EventManager
typedef struct {
    NetworkEventStruct **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventManager;

// Initialize EventManager
void event_manager_init(EventManager *manager, size_t initial_capacity) {
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->events = malloc(initial_capacity * sizeof(NetworkEventStruct *));
    if (manager->events == NULL) {
        fprintf(stderr, "Failed to allocate memory for events.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
}

// Free EventManager
void event_manager_free(EventManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Add event to EventManager
void event_manager_add(EventManager *manager, NetworkEventStruct *event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NetworkEventStruct **new_events = realloc(manager->events, new_capacity * sizeof(NetworkEventStruct *));
        if (new_events == NULL) {
            fprintf(stderr, "Failed to reallocate memory for events.\n");
            exit(EXIT_FAILURE);
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }
    manager->events[manager->count++] = event;
    pthread_mutex_unlock(&manager->lock);
}

// Retrieve event from EventManager
NetworkEventStruct *event_manager_get(EventManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);
    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    NetworkEventStruct *event = manager->events[index];
    pthread_mutex_unlock(&manager->lock);
    return event;
}

// Example usage
int main() {
    EventManager manager;
    event_manager_init(&manager, 10);

    // Create and add a new event
    NetworkEventStruct *event = malloc(sizeof(NetworkEventStruct));
    if (event == NULL) {
        fprintf(stderr, "Failed to allocate memory for event.\n");
        exit(EXIT_FAILURE);
    }
    time_t now;
    time(&now);
    snprintf(event->eventType, sizeof(event->eventType), "CONNECT");
    snprintf(event->metadata, sizeof(event->metadata), "Source IP: 192.168.1.1");
    event->timestamp = now;

    event_manager_add(&manager, event);

    // Retrieve and print the event
    NetworkEventStruct *retrieved_event = event_manager_get(&manager, 0);
    if (retrieved_event != NULL) {
        printf("Event Type: %s\n", retrieved_event->eventType);
        printf("Metadata: %s\n", retrieved_event->metadata);
    }

    // Free resources
    free(event);
    event_manager_free(&manager);

    return 0;
}
