#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <functional>
#include <memory>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <zlib.h>

struct DataItem {
    uint64_t id;
    std::string data;
};

class DataManager {
public:
    using HashFunction = std::function<uint64_t(const std::string&)>;

    DataManager(HashFunction hashFunc, size_t initialCapacity = 1024)
        : hashFunc_(hashFunc), storage_(initialCapacity) {}

    void initialize(const std::vector<std::string>& inputStrings) {
        for (const auto& str : inputStrings) {
            addDataItem(str);
        }
    }

    void addDataItem(const std::string& data) {
        uint64_t id = hashFunc_(data);
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = storage_.find(id);
        if (it != storage_.end()) {
            it->second += " " + data;
        } else {
            storage_[id] = data;
        }
    }

    void compressData() {
        for (auto& item : storage_) {
            uint8_t* compressed = nullptr;
            uLongf compressedLen = 0;
            if (compressBound(item.second.size()) > INT_MAX) throw std::runtime_error("Compression buffer too large");
            compressed = new uint8_t[compressBound(item.second.size())];
            compress(&compressed, &compressedLen, reinterpret_cast<const unsigned char*>(item.second.data()), item.second.size());
            item.second.assign(reinterpret_cast<char*>(compressed), compressedLen);
        }
    }

    void decompressData() {
        for (auto& item : storage_) {
            uint8_t* uncompressed = nullptr;
            uLongf uncompressedLen = item.second.size();
            uncompressed = new uint8_t[uncompressedLen];
            uncompress(uncompressed, &uncompressedLen, reinterpret_cast<const unsigned char*>(item.second.data()), item.second.size());
            item.second.assign(reinterpret_cast<char*>(uncompressed), uncompressedLen);
        }
    }

private:
    HashFunction hashFunc_;
    std::unordered_map<uint64_t, std::string> storage_;
    std::mutex mutex_;
};

int main() {
    DataManager manager([](const std::string& s) { return std::hash<std::string>()(s); });
    std::vector<std::string> data = {"apple", "banana", "cherry"};
    manager.initialize(data);
    manager.compressData();
    manager.decompressData();
    for (const auto& item : manager.storage_) {
        std::cout << "ID: " << item.first << ", Data: " << item.second << std::endl;
    }
    return 0;
}
