class FileManager {
public:
    // Add or update file metadata
    void addOrUpdateMetadata(const std::string& filePath, const FileMetadataStruct& metadata);

    // Retrieve file metadata synchronously
    FileMetadataStruct getMetadataSync(const std::string& filePath) const;

    // Retrieve file metadata asynchronously
    void getMetadataAsync(const std::string& filePath, std::function<void(const FileMetadataStruct&)>) const;

private:
    mutable std::mutex mutex_;
    std::unordered_map<std::string, FileMetadataStruct> metadataMap_;

    // Synchronous storage system integration
    bool syncToStorage(const std::string& filePath, const FileMetadataStruct& metadata);

    // Asynchronous storage system integration
    void asyncToStorage(const std::string& filePath, const FileMetadataStruct& metadata, int retryCount = 0);
};

void FileManager::addOrUpdateMetadata(const std::string& filePath, const FileMetadataStruct& metadata) {
    std::lock_guard<std::mutex> lock(mutex_);
    metadataMap_[filePath] = metadata;
    syncToStorage(filePath, metadata);
}

FileMetadataStruct FileManager::getMetadataSync(const std::string& filePath) const {
    std::lock_guard<std::mutex> lock(mutex_);
    if (metadataMap_.find(filePath) != metadataMap_.end()) {
        return metadataMap_.at(filePath);
    } else {
        throw std::runtime_error("File not found");
    }
}

void FileManager::getMetadataAsync(const std::string& filePath, std::function<void(const FileMetadataStruct&)>) const {
    std::lock_guard<std::mutex> lock(mutex_);
    if (metadataMap_.find(filePath) != metadataMap_.end()) {
        // Simulate asynchronous operation
        std::thread([filePath, this]() {
            auto metadata = getMetadataSync(filePath);
            // Notify completion
        }).detach();
    } else {
        throw std::runtime_error("File not found");
    }
}

bool FileManager::syncToStorage(const std::string& filePath, const FileMetadataStruct& metadata) {
    // Implement synchronous storage integration logic here
    return true; // Simulate success
}

void FileManager::asyncToStorage(const std::string& filePath, const FileMetadataStruct& metadata, int retryCount) {
    if (!syncToStorage(filePath, metadata)) {
        if (retryCount < 3) {
            std::this_thread::sleep_for(std::chrono::milliseconds(pow(2, retryCount) * 100));
            asyncToStorage(filePath, metadata, retryCount + 1);
        } else {
            std::cerr << "Warning: Failed to sync metadata after retries" << std::endl;
        }
    }
}

int main() {
    FileManager fileManager;
    FileMetadataStruct newMetadata = {"path/to/file", time(nullptr), "read", 1};
