#define MAX_EVENTS 5000000
#define CACHE_SIZE 10000

typedef struct {
    char id[20];
    time_t timestamp;
    char payload[1024];
    int status;
} Event;

Event event_cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

sqlite3 *db;

void* fetch_metadata(void* arg) {
    CURL *curl;
    CURLcode res;
    char url[1024];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        sprintf(url, "https://api.example.com/metadata?id=%s", (char*)arg);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return NULL;
}

int store_event(Event *event) {
    pthread_mutex_lock(&cache_lock);
    if(cache_count < CACHE_SIZE) {
        event_cache[cache_count++] = *event;
    } else {
        // Handle cache overflow, e.g., evict least recently used item
    }
    pthread_mutex_unlock(&cache_lock);

    // Store in database
    char sql[2048];
    sprintf(sql, "INSERT INTO events (id, timestamp, payload, status) VALUES ('%s', %ld, '%s', %d)",
            event->id, event->timestamp, event->payload, event->status);
    sqlite3_exec(db, sql, 0, 0, NULL);

    return 1;
}

void* process_events(void* arg) {
    Event *event = (Event*)arg;

    // Fetch metadata asynchronously
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, fetch_metadata, event->id);
    pthread_detach(thread_id);

    // Store event locally and persistently
    if(store_event(event)) {
        printf("Event processed successfully: %s\n", event->id);
    } else {
        printf("Failed to process event: %s\n", event->id);
    }

    return NULL;
}

int main() {
    // Initialize database
    sqlite3_open("events.db", &db);

    // Simulate processing multiple events concurrently
    pthread_t threads[MAX_EVENTS];
    Event events[MAX_EVENTS];

    for(int i = 0; i < MAX_EVENTS; i++) {
        snprintf(events[i].id, sizeof(events[i].id), "event%d", i);
        events[i].timestamp = time(NULL);
        snprintf(events[i].payload, sizeof(events[i].payload), "data for event %d", i);
        events[i].status = 0;

        pthread_create(&threads[i], NULL, process_events, &events[i]);
    }

    for(int i = 0; i < MAX_EVENTS; i++) {
        pthread_join(threads[i], NULL);
    }

    sqlite3_close(db);

    return 0;
}
