// Transaction structure
struct Transaction {
    int id;
    double amount;
    std::string source;
};

// Message queue system
class MessageQueue {
private:
    std::queue<Transaction> transactions;
    std::mutex mtx;
    std::condition_variable cond;
    size_t max_size;

public:
    MessageQueue(size_t max_size) : max_size(max_size) {}

    void push(const Transaction& tx) {
        std::unique_lock<std::mutex> lock(mtx);
        cond.wait(lock, [this]{ return transactions.size() < max_size; });
        transactions.push(tx);
        cond.notify_one();
    }

    bool pop(Transaction& tx) {
        std::unique_lock<std::mutex> lock(mtx);
        if (transactions.empty()) {
            return false;
        }
        tx = transactions.front();
        transactions.pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mtx);
        return transactions.size();
    }
};

