class TransactionProcessor {
public:
    void startProcessing() {
        std::thread producer(&TransactionProcessor::produceTransactions, this);
        std::thread consumer(&TransactionProcessor::consumeTransactions, this);

        producer.join();
        consumer.join();
    }

private:
    std::queue<std::vector<int>> transactionQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    bool stopProcessing = false;

    void produceTransactions() {
        while (!stopProcessing) {
            // Simulate receiving transactions from multiple sources
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            std::vector<int> newTransactions = generateNewTransactions();
            std::lock_guard<std::mutex> lock(queueMutex);
            transactionQueue.push(newTransactions);
            queueCondVar.notify_one();
        }
    }

    void consumeTransactions() {
        while (!stopProcessing) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondVar.wait(lock, [this] { return !transactionQueue.empty() || stopProcessing; });
            if (stopProcessing && transactionQueue.empty()) {
                break;
            }
            std::vector<int> transactions = transactionQueue.front();
            transactionQueue.pop();
            lock.unlock();

            // Process the transactions
            processTransactions(transactions);
        }
    }

    std::vector<int> generateNewTransactions() {
        // Simulate generating new transactions
        return {100, 200, 300};
    }

    void processTransactions(const std::vector<int>& transactions) {
        // Simulate processing transactions
        for (int transaction : transactions) {
            std::cout << "Processing transaction: " << transaction << std::endl;
        }
    }
};

int main() {
    TransactionProcessor processor;
    processor.startProcessing();
    return 0;
}
