    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::cout << "LOG: " << message << std::endl;
    }

private:
    std::mutex mutex_;
};

// Log processor class
class LogProcessor {
public:
    LogProcessor(Logger& logger, const std::string& dbConnectionParams)
        : logger_(logger), dbConnectionParams_(dbConnectionParams), running_(true) {
        // Initialize database connection and other resources here
    }

    ~LogProcessor() {
        stop();
        // Clean up database connection and other resources here
    }

    void start() {
        processingThread_ = std::thread(&LogProcessor::processLogs, this);
    }

    void stop() {
        running_.store(false);
        if (processingThread_.joinable()) {
            processingThread_.join();
        }
    }

    void addLogEntry(const std::string& logEntry) {
        {
            std::lock_guard<std::mutex> lock(queueMutex_);
            logQueue_.push(logEntry);
        }
        conditionVariable_.notify_one();
    }

private:
    void processLogs() {
        while (running_.load()) {
            std::string logEntry;
            {
                std::unique_lock<std::mutex> lock(queueMutex_);
                conditionVariable_.wait(lock, [this] { return !logQueue_.empty() || !running_.load(); });
                if (!running_.load()) break;
                logEntry = logQueue_.front();
                logQueue_.pop();
            }

            // Validate and process the log entry here
            logger_.log("Processing log entry: " + logEntry);
            saveToDatabase(logEntry, dbConnectionParams_);
        }
    }

    void saveToDatabase(const std::string& logEntry, const std::string& dbConnectionParams) {
        // Code to save log entry to database
        logger_.log("Saving log entry to database: " + logEntry);
    }

    Logger& logger_;
    std::string dbConnectionParams_;
    std::queue<std::string> logQueue_;
    std::mutex queueMutex_;
    std::condition_variable conditionVariable_;
    std::thread processingThread_;
    std::atomic<bool> running_;
};

// Main function to demonstrate usage
int main() {
    Logger logger;
    LogProcessor processor(logger, "database_connection_params");

    // Simulate adding log entries
    for (int i = 0; i < 10; ++i) {
        std::string logEntry = "Log entry " + std::to_string(i);
        processor.addLogEntry(logEntry);
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }

    // Stop the processor
    processor.stop();

    return 0;
}
