typedef struct HashTable {
    Tenant** buckets;
    size_t size;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(size, sizeof(Tenant*));
    table->size = size;
    return table;
}

void insert_tenant(HashTable* table, char* namespace, void* data) {
    size_t index = hash(namespace) % table->size;
    Tenant* tenant = malloc(sizeof(Tenant));
    tenant->namespace = strdup(namespace);
    tenant->data = data;

    if (table->buckets[index] != NULL) {
        // Handle collision
        Tenant* current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = tenant;
    } else {
        table->buckets[index] = tenant;
    }
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; i++) {
        Tenant* current = table->buckets[i];
        while (current != NULL) {
            Tenant* next = current->next;
            free(current->namespace);
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

