    manager.services.push_back(new AWSStorage());
    manager.services.push_back(new AzureStorage());

    // Add files to the upload queue
    manager.addFileToQueue("file1.txt", "destination1");
    manager.addFileToQueue("file2.txt", "destination2");

    // Start uploading
