#define MAX_DEVICES 10000
#define MAX_DATA_SIZE 1073741824 // 1 GB
#define LATENCY_THRESHOLD 10 // in milliseconds

typedef struct {
    int device_id;
    char *status_data;
} DeviceStatus;

typedef struct {
    DeviceStatus devices[MAX_DEVICES];
    int count;
    pthread_mutex_t mutex;
} DeviceManager;

DeviceManager device_manager;

void* process_device_status(void* arg) {
    DeviceStatus *status = (DeviceStatus *)arg;

    // Process the status update
    printf("Processing status for device %d\n", status->device_id);

    // Release resources
    free(status->status_data);

    pthread_mutex_lock(&device_manager.mutex);
    int i;
    for(i = 0; i < device_manager.count; i++) {
        if(device_manager.devices[i].device_id == status->device_id) {
            device_manager.devices[i] = device_manager.devices[device_manager.count - 1];
            device_manager.count--;
            break;
        }
    }
    pthread_mutex_unlock(&device_manager.mutex);

    return NULL;
}

int main() {
    // Initialize the device manager
    device_manager.count = 0;
    pthread_mutex_init(&device_manager.mutex, NULL);

    // Simulate receiving device status updates
    for(int i = 0; i < MAX_DEVICES; i++) {
        DeviceStatus *status = (DeviceStatus *)malloc(sizeof(DeviceStatus));
        status->device_id = i;
        status->status_data = malloc(MAX_DATA_SIZE);
        pthread_mutex_lock(&device_manager.mutex);
        device_manager.devices[device_manager.count++] = *status;
        pthread_mutex_unlock(&device_manager.mutex);

        // Process the status update in a separate thread
        pthread_t thread;
        pthread_create(&thread, NULL, process_device_status, (void *)status);
        pthread_detach(thread);
    }

    // Clean up and exit
    pthread_mutex_destroy(&device_manager.mutex);
    return 0;
}
