    int capacity;
} EventCollection;

EventCollection* create_event_collection() {
    EventCollection* collection = malloc(sizeof(EventCollection));
    if (collection == NULL) return NULL;
    collection->events = malloc(10 * sizeof(NetworkEventStruct*)); // Initial capacity of 10
    if (collection->events == NULL) {
        free(collection);
        return NULL;
    }
    collection->size = 0;
    collection->capacity = 10;
    return collection;
}

void add_event(EventCollection* collection, NetworkEventStruct* event) {
    if (collection->size >= collection->capacity) {
        collection->capacity *= 2;
        collection->events = realloc(collection->events, collection->capacity * sizeof(NetworkEventStruct*));
        if (collection->events == NULL) return; // Handle memory allocation failure
    }
    collection->events[collection->size++] = event;
}

// Add other functions as needed for managing the event collection

