    NetworkEventStruct* event = malloc(sizeof(NetworkEventStruct));
    if (event == NULL) return -1; // Handle memory allocation failure
    event->timestamp = 1234567890;
    strcpy(event->type, "INFO");
    // Initialize metadata as needed
    add_event(collection, event);

    // Add other operations and cleanup code

    free(event);
    for (int i = 0; i < collection->size; i++) {
        free(collection->events[i]);
    }
    free(collection->events);
