    void addRequest(const std::function<void()> &request, int priority) {
        std::lock_guard<std::mutex> lock(mutex_);
        requests_.push_back(std::make_pair(request, priority));
        cv_.notify_one();
    }

    void run() {
        while (true) {
            std::function<void()> request;
            int priority = 0;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !requests_.empty(); });
                request = requests_.back().first;
                priority = requests_.back().second;
                requests_.pop_back();
            }
            handleRequest(request, priority);
        }
    }

private:
    void handleRequest(const std::function<void()> &request, int priority) {
        // Implement request handling logic here
        // This could involve asynchronous I/O operations, connection pooling, etc.
    }

    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<std::pair<std::function<void()>, int>> requests_;
};

