// CacheEntry struct to hold data and metadata
struct CacheEntry {
    std::string data;
    time_t lastAccessTime;
    size_t accessCount;

    CacheEntry(std::string d) : data(d), lastAccessTime(time(nullptr)), accessCount(1) {}
};

// CacheManager class implementing the cache management service
class CacheManager {
private:
    std::unordered_map<std::string, CacheEntry> cache;
    std::mutex mutex;
    size_t maxSize;

public:
    CacheManager(size_t maxCacheSize) : maxSize(maxCacheSize) {}

    void add(const std::string& key, const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.size() >= maxSize) {
            evictLeastFrequent();
        }
        cache[key] = CacheEntry(data);
    }

    std::optional<CacheEntry> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            it->second.lastAccessTime = time(nullptr);
            it->second.accessCount++;
            return it->second;
        }
        return {};
    }

private:
    void evictLeastFrequent() {
        CacheEntry* leastFrequent = nullptr;
        for (auto& entry : cache) {
            if (!leastFrequent || entry.second.accessCount < leastFrequent->accessCount) {
                leastFrequent = &entry.second;
            }
        }
        if (leastFrequent) {
            cache.erase(leastFrequent);
        }
    }
};

int main() {
    CacheManager cache(1000);

    cache.add("key1", "data1");
    auto entry = cache.get("key1");

    if (entry.has_value()) {
        std::cout << "Data: " << entry.value().data << ", Access Count: " << entry.value().accessCount << std::endl;
    } else {
        std::cout << "Key not found" << std::endl;
    }

    return 0;
}
