typedef struct {
    time_t timestamp;
    char type[32];
    char metadata[256];
} NetworkEventStruct;

NetworkEventStruct events[MAX_EVENTS];
int event_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_event(time_t timestamp, const char* type, const char* metadata) {
    pthread_mutex_lock(&lock);
    if (event_count < MAX_EVENTS) {
        events[event_count].timestamp = timestamp;
        strncpy(events[event_count].type, type, sizeof(events[event_count].type));
        strncpy(events[event_count].metadata, metadata, sizeof(events[event_count].metadata));
        event_count++;
    }
    pthread_mutex_unlock(&lock);
}

NetworkEventStruct* get_event(int index) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < event_count) {
        NetworkEventStruct* event = &events[index];
        pthread_mutex_unlock(&lock);
        return event;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void update_event(int index, time_t timestamp, const char* type, const char* metadata) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < event_count) {
        events[index].timestamp = timestamp;
        strncpy(events[index].type, type, sizeof(events[index].type));
        strncpy(events[index].metadata, metadata, sizeof(events[index].metadata));
    }
    pthread_mutex_unlock(&lock);
}

