public class WeatherDataAggregator
{
    private readonly HttpClient _httpClient;
    private const string ApiBaseUrl = "https://api.weather.com";

    public WeatherDataAggregator(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<Dictionary<string, double>> GetCurrentTemperatureAsync(string[] cities)
    {
        var temperatureData = new Dictionary<string, double>();

        foreach (var city in cities)
        {
            try
            {
                var response = await _httpClient.GetAsync($"{ApiBaseUrl}/current?city={city}");
                response.EnsureSuccessStatusCode();
                var data = await response.Content.ReadAsAsync<WeatherResponse>();
                temperatureData[city] = data.Temperature;
            }
            catch (HttpRequestException)
            {
                // Fallback to default value or use a backup API
                temperatureData[city] = 25.0; // Default temperature in Celsius
            }
        }

        return temperatureData;
    }

    public async Task<Dictionary<string, List<double>>> GetHistoricalTemperatureAsync(string city, int days)
    {
        var historicalData = new Dictionary<string, List<double>>();

        try
        {
            var response = await _httpClient.GetAsync($"{ApiBaseUrl}/historical?city={city}&days={days}");
            response.EnsureSuccessStatusCode();
            var data = await response.Content.ReadAsAsync<HistoricalWeatherResponse>();
            historicalData[city] = data.TemperatureHistory;
        }
        catch (HttpRequestException)
        {
            // Fallback to default values or use a backup API
            historicalData[city] = new List<double> { 20.0, 21.0, 22.0 }; // Default temperatures in Celsius
        }

        return historicalData;
    }
}

public class WeatherResponse
{
    public double Temperature { get; set; }
}

public class HistoricalWeatherResponse
{
    public List<double> TemperatureHistory { get; set; }
