struct UserSession {
    int userId;
    std::string sessionToken;
    time_t lastActivity;
    std::vector<std::string> activeTabs;
    std::unordered_map<std::string, std::string> preferences;
};

class SessionManager {
private:
    std::unordered_map<int, UserSession> sessions;
    std::mutex sessionsMutex;

public:
    void addSession(int userId, const std::string& sessionToken) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        sessions[userId] = {userId, sessionToken, time(nullptr), {}, {}};
    }

    void updateSession(int userId) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        if (sessions.find(userId) != sessions.end()) {
            sessions[userId].lastActivity = time(nullptr);
        }
    }

    bool validateTab(const std::string& url, const std::string& title) {
        return !url.empty() && !title.empty();
    }

    void evictInactiveSessions(time_t threshold) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        auto now = time(nullptr);
        for (auto it = sessions.begin(); it != sessions.end();) {
            if (now - it->second.lastActivity > threshold) {
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
    }

    void logEvent(const std::string& event) {
        // Implement logging logic here
        std::cout << "LOG: " << event << std::endl;
    }
};

int main() {
    SessionManager manager;
    manager.addSession(1, "sessionToken1");
    manager.updateSession(1);
    bool isValid = manager.validateTab("https://example.com", "Example");
    if (!isValid) {
        return 400; // Bad request
    }
    manager.evictInactiveSessions(3600); // Evict sessions inactive for more than an hour
    manager.logEvent("Session updated");
    return 200; // OK
}
