public void batchProcessOrderData(List<String> orderIds, int batchSize, long timeout) {
    ExecutorService executor = Executors.newFixedThreadPool(batchSize);
    Semaphore semaphore = new Semaphore(batchSize);
    CircuitBreaker circuitBreaker = new CircuitBreaker();

    for (String orderId : orderIds) {
        try {
            semaphore.acquire();
            executor.submit(() -> {
                try {
                    if (circuitBreaker.isOpen()) {
                        handleCircuitBreakerError(orderId);
                        return;
                    }

                    processOrder(orderId);
                    updateShipmentStatus(orderId);
                    logTransactionSuccess(orderId);
                } catch (Exception e) {
                    handleTransactionFailure(orderId, e);
                } finally {
                    semaphore.release();
                }
            });
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            break;
        }

        if (executor.getActiveCount() >= batchSize) {
            try {
                executor.shutdown();
                executor.awaitTermination(timeout, TimeUnit.MILLISECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            executor = Executors.newFixedThreadPool(batchSize);
        }
    }

    executor.shutdown();
}
