var app = angular.module('dynamicDialogModule', []);

app.service('DynamicDialogService', function($http, $q) {
    var cache = {};

    this.refreshField = function(resourceId, url) {
        if (cache[resourceId]) {
            return $q.when(cache[resourceId]);
        }

        return $http.get(url + resourceId)
            .then(function(response) {
                cache[resourceId] = response.data;
                return response.data;
            })
            .catch(function(error) {
                // Handle error
                console.error('Error refreshing field:', error);
                throw error;
            });
    };
