['```go
package main

import (
	"context"
	"log"
	"sync"
	"time"

	"github.com/Shopify/sarama"
)

type LogMessage struct {
	Service string
	Message string
}

type Logger struct {
	config   Config
	client   sarama.SyncProducer
	buffer   chan *LogMessage
	wg       sync.WaitGroup
	shutdown chan bool
}

type Config struct {
	Brokers []string
	Topic   string
}

func NewLogger(config Config) (*Logger, error) {
	brokerConfig := sarama.NewConfig()
	brokerConfig.Producer.RequiredAcks = sarama.WaitForAll
	brokerConfig.Producer.Retry.Max = 5

	client, err := sarama.NewSyncProducer(config.Brokers, brokerConfig)
	if err != nil {
		return nil, err
	}

	logger := &Logger{
		config: config,
		client: client,
		buffer: make(chan *LogMessage, 1000),
		shutdown: make(chan bool),
	}

	go logger.startConsuming()

	return logger, nil
}

func (l *Logger) startConsuming() {
	for {
		select {
		case msg := <-l.buffer:
			partition, offset, err := l.client.SendMessage(msg)
			if err != nil {
				log.Printf("Error sending message to Kafka: %v", err)
			} else {
				log.Printf("Message sent to partition %d at offset %d\n", partition, offset)
			}
		case <-l.shutdown:
			l.client.Close()
			return
		}
	}
}

func (l *Logger) Log(service string, message string) {
	l.buffer <- &LogMessage{Service: service, Message: message}
}

func (l *Logger) Shutdown() {
	close(l.shutdown)
	l.wg.Wait()
}

func main() {
	config := Config{
		Brokers: []string{"localhost:9092"},
		Topic:   "logs",
	}

	logger, err := NewLogger(config)
	if err != nil {
		log.Fatalf("Failed to create logger: %v", err)
	}
	defer logger.Shutdown()

	go func() {
		for i := 0; i < 100; i++ {
			logger.Log("service1", "info message")
			time.Sleep(50 * time.Millisecond)
		}
	}()

	<-time.After(2 * time.Second)
	log.Println("Shutting down logger...")
}
