    ~LogManager() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void log(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(entry);
        cv_.notify_one();
    }

private:
    Queue queue_;
    std::vector<ExportFunction> exportFunctions_;
    std::vector<std::thread> workers_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stop_ = false;
    size_t numThreads_ = std::thread::hardware_concurrency();

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !queue_.empty() || stop_; });

            if (stop_ && queue_.empty()) {
                break;
            }

            Queue batch;
            while (!queue_.empty()) {
                batch.push(queue_.front());
                queue_.pop();
            }
            lock.unlock();

            for (const auto& exportFunc : exportFunctions_) {
                exportFunc(batch);
            }
        }
    }

    static void exportToREST(const Queue& batch) {
        // Implement REST API export logic
    }

    static void exportToMessageBroker(const Queue& batch) {
        // Implement message broker export logic
    }

    static void exportToTimeSeriesDB(const Queue& batch) {
        // Implement time-series database export logic
    }
};
