import java.util.concurrent.*;
import java.util.function.Function;
import java.util.stream.IntStream;

public class DataProcessor {
    private final BlockingQueue<DataPoint> queue = new LinkedBlockingQueue<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Function<DataPoint, Void> dataHandler;
    private final int batchSize;

    public DataProcessor(Function<DataPoint, Void> dataHandler, int batchSize) {
        this.dataHandler = dataHandler;
        this.batchSize = batchSize;
    }

    public void processData(DataPoint dataPoint) {
        try {
            queue.put(dataPoint);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void startProcessing() {
        executor.submit(() -> {
            while (true) {
                try {
                    DataBatch batch = new DataBatch(batchSize);
                    int count = IntStream.range(0, batchSize)
                            .mapToObj(i -> queue.poll())
                            .filter(dataPoint -> dataPoint != null)
                            .peek(batch::add)
                            .mapToInt(DataPoint::getId)
                            .sum();

                    if (count > 0) {
                        processBatch(batch);
                    } else {
                        Thread.sleep(100); // Sleep briefly to avoid busy-waiting
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
    }

    private void processBatch(DataBatch batch) {
        try {
            dataHandler.apply(batch);
        } catch (Exception e) {
            handleProcessingError(e, batch);
        }
    }

    private void handleProcessingError(Exception e, DataBatch batch) {
        // Implement retry logic with exponential backoff
        // Log detailed error information for monitoring and debugging
    }

    public void stop() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    static class DataBatch {
        private final DataPoint[] dataPoints;
        private int size;

        public DataBatch(int capacity) {
            this.dataPoints = new DataPoint[capacity];
        }

        public void add(DataPoint dataPoint) {
            if (size < dataPoints.length) {
                dataPoints[size++] = dataPoint;
            } else {
                throw new IllegalStateException("Batch is full");
            }
        }

        public int size() {
            return size;
        }

        // Provide methods to access batch data as needed
    }

    static class DataPoint {
        private final int id;
        private final double value;

        public DataPoint(int id, double value) {
            this.id = id;
            this.value = value;
        }

        public int getId() {
            return id;
        }

        public double getValue() {
            return value;
        }
    }
}
