            'Authorization: Bearer ' . $GLOBALS['apiKey'],
        ];

        $options = [
            'http' => [
                'header'  => implode("\r\n", $headers),
                'method'  => $method,
                'content' => json_encode($data),
            ],
        ];

        $context  = stream_context_create($options);
        $result = file_get_contents($url, false, $context);

        if ($result === FALSE) {
            throw new Exception('API request failed');
        }

        return json_decode($result, true);
    }

    // Perform multi-factor authentication using third-party identity provider
    $authProviderUrl = getenv('AUTH_PROVIDER_URL');

    function authenticateUser($username, $password) {
        $response = callApi($authProviderUrl . '/authenticate', 'POST', [
            'username' => $username,
            'password' => $password,
        ]);

        if ($response['status'] !== 'success') {
            throw new Exception('Authentication failed');
        }

        return $response['token'];
    }

    // Example usage
    $username = 'example_user';
    $password = 'example_password';

    try {
        $token = authenticateUser($username, $password);
        $apiData = callApi($apiUrl . '/data', 'GET', ['Authorization' => 'Bearer ' . $token]);
        print_r($apiData);
    } catch (Exception $e) {
        $log->error('Error: ' . $e->getMessage());
    }
} catch (PDOException $e) {
    $log->error('Database error: ' . $e->getMessage());
}
