    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly ILogger<UserService> _logger;
    private readonly int _timeoutInSeconds;
    private readonly int _maxRetries;
    private const string CacheKey = "UserDataTable";

    public UserService(
        IConfiguration configuration,
        IHttpClientFactory httpClientFactory,
        IMemoryCache cache,
        ILogger<UserService> logger)
    {
        _httpClient = httpClientFactory.CreateClient("ExternalApi");
        _cache = cache;
        _logger = logger;

        var timeoutConfig = configuration.GetValue<int>("TimeoutInSeconds", 10);
        var maxRetriesConfig = configuration.GetValue<int>("MaxRetries", 3);

        _timeoutInSeconds = Math.Max(1, timeoutConfig);
        _maxRetries = Math.Max(0, maxRetriesConfig);
    }

    public async Task<DataTableReader> GetUserDataTableAsync()
    {
        if (_cache.TryGetValue(CacheKey, out DataTable dataTable))
        {
            return new DataTableReader(dataTable);
        }

        var dataTable = await FetchUserDataAsync();
        _cache.Set(CacheKey, dataTable, TimeSpan.FromMinutes(10));

        return new DataTableReader(dataTable);
    }

    private async Task<DataTable> FetchUserDataAsync()
    {
        int retries = 0;
        while (retries <= _maxRetries)
        {
            try
            {
                using var request = new HttpRequestMessage(HttpMethod.Get, "https://api.example.com/users");
                request.Headers.Add("Authorization", "Bearer your_token_here");

                using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead,
                    CancellationToken.None);

                if (response.IsSuccessStatusCode)
                {
                    var json = await response.Content.ReadAsStringAsync();
                    return ConvertJsonToDataTable(json);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching user data");
            }

            retries++;
            if (retries > 1) await Task.Delay(TimeSpan.FromSeconds(_timeoutInSeconds));
        }

        throw new Exception("Failed to fetch user data after multiple retries");
    }

    private static DataTable ConvertJsonToDataTable(string json)
    {
        // Implement JSON to DataTable conversion logic here
        return new DataTable();
    }
}

public class Startup
{
