class ClinicUpdateService {
    private $authApiClient;
    private $auditLogService;
    private $notificationService;
    private $databaseConnection;

    public function __construct($authApiClient, $auditLogService, $notificationService, $databaseConnection) {
        $this->authApiClient = $authApiClient;
        $this->auditLogService = $auditLogService;
        $this->notificationService = $notificationService;
        $this->databaseConnection = $databaseConnection;
    }

    public function updateClinicStatus($clinicId, $status, $lastModifiedIp) {
        // Input validation and sanitization
        if (!is_numeric($clinicId)) {
            throw new InvalidArgumentException("Invalid clinic ID");
        }
        if (empty($status) || !is_string($status)) {
            throw new InvalidArgumentException("Invalid status");
        }
        if (empty($lastModifiedIp) || !filter_var($lastModifiedIp, FILTER_VALIDATE_IP)) {
            throw new InvalidArgumentException("Invalid last modified IP address");
        }

        $transaction = null;
        try {
            // Start transaction
            $this->databaseConnection->beginTransaction();
            $transaction = $this->databaseConnection->getTransaction();

            // Update clinic status in database
            $sql = "UPDATE clinics SET status = :status, last_modified_ip = :lastModifiedIp, last_modified_date = NOW() WHERE id = :clinicId";
            $stmt = $this->databaseConnection->prepare($sql);
            $stmt->execute(['status' => $status, 'lastModifiedIp' => $lastModifiedIp, 'clinicId' => $clinicId]);

            // Log audit trail
            $auditLogEntry = [
                'user_id' => $this->authApiClient->getCurrentUserId(),
                'action' => 'UPDATE_CLINIC_STATUS',
                'target_id' => $clinicId,
                'data' => json_encode(['status' => $status, 'last_modified_ip' => $lastModifiedIp])
            ];
            $this->auditLogService->logEntry($auditLogEntry);

            // Notify interested parties
            $notificationData = [
                'message' => "Clinic ID {$clinicId} status updated to {$status}",
                'recipients' => ['admin@example.com', 'support@example.com']
            ];
            $this->notificationService->sendNotification($notificationData);

            // Commit transaction
            $transaction->commit();
        } catch (\Exception $e) {
            if ($transaction !== null) {
                $transaction->rollback();
            }
            throw $e;
        }
    }
}

// Usage example
