// JsonParser.hpp
#pragma once

#include <json/json.h>
#include <iostream>

namespace json {

template <typename T>
T parseJson(const std::string& jsonString) {
    Json::Value root;
    Json::CharReaderBuilder builder;
    std::unique_ptr<Json::CharReader> reader(builder.newCharReader());
    std::string errs;

    if (!reader->parse(jsonString.c_str(), jsonString.c_str() + jsonString.size(), &root, &errs)) {
        throw std::runtime_error("Failed to parse JSON: " + errs);
    }

    return T::fromJson(root);
}

template <typename T>
void toJson(const T& obj, std::ostream& os) {
    Json::StreamWriterBuilder builder;
    builder["commentStyle"] = "None";
    builder["indentation"] = "   ";
    std::unique_ptr<Json::StreamWriter> writer(builder.newStreamWriter());
    writer->write(obj.toJson(), &os);
}

} // namespace json
