// DynamicSpatialIndexManager.cpp
#include "DynamicSpatialIndexManager.hpp"
#include <thread>

void dsim::DynamicSpatialIndexManager::workerThread() {
    while (true) {
        std::function<void()> task;
        {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this]{ return !tasks_.empty(); });
            task = std::move(tasks_.front());
            tasks_.pop();
        }
        task();
    }
}

void dsim::DynamicSpatialIndexManager::addEntry(const SpatialIndexEntry& entry) {
    {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push([this, &entry] { root->insert(entry); });
    }
    cv_.notify_one();
}

void dsim::DynamicSpatialIndexManager::removeEntry(const SpatialIndexEntry& entry) {
    {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push([this, &entry] { root->remove(entry); });
    }
    cv_.notify_one();
}

std::vector<SpatialIndexEntry> dsim::DynamicSpatialIndexManager::queryRange(double minX, double minY, double minZ, double maxX, double maxY, double maxZ) {
    std::vector<SpatialIndexEntry> results;
    {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push([this, &minX, &minY, &minZ, &maxX, &maxY, &maxZ, &results] { 
            root->queryRange(minX, minY, minZ, maxX, maxY, maxZ, results); 
        });
    }
    cv_.notify_one();
    // Wait for the task to complete
    return results;
}

// OctreeNode and SpatialIndexEntry implementation details are omitted for brevity.
