    void retryTransaction(uint8_t transaction) {
        std::lock_guard<std::mutex> lock(mutex_);
        retryQueue_.push(transaction);
        cv_.notify_one();
    }

    bool handleRetries() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !retryQueue_.empty(); });
            uint8_t transaction = retryQueue_.front();
            retryQueue_.pop();
            lock.unlock();

            if (!processTransaction(transaction)) {
                logError("Failed to process transaction after retry");
                retryTransaction(transaction);
            } else {
                return true;
            }
        }
    }

    void startRetryThread() {
        retryThread_ = std::thread(&TransactionProcessor::handleRetries, this);
    }

    void stopRetryThread() {
        if (retryThread_.joinable()) {
            retryThread_.join();
        }
    }

    void logError(const std::string& error) {
        // Logging logic here
        std::cerr << "Error: " << error << std::endl;
    }

private:
