package main

import (
    "fmt"
    "sync"
    "time"
)

type Event struct {
    ID        string
    Publisher string
    Data      map[string]interface{}
}

type EventLogQueue struct {
    queue []Event
    mutex sync.Mutex
}

func (ql *EventLogQueue) Enqueue(event Event) {
    ql.mutex.Lock()
    defer ql.mutex.Unlock()
    ql.queue = append(ql.queue, event)
}

func (ql *EventLogQueue) Dequeue() (Event, bool) {
    ql.mutex.Lock()
    defer ql.mutex.Unlock()
    if len(ql.queue) == 0 {
        return Event{}, false
    }
    event := ql.queue[0]
    ql.queue = ql.queue[1:]
    return event, true
}

type ExternalAPIClient struct{}

func (eac *ExternalAPIClient) SendEvent(event Event) error {
    // Simulate sending event to external API
    time.Sleep(100 * time.Millisecond)
    return nil
}

type EventLogSystem struct {
    queue      EventLogQueue
    workers    int
    client     *ExternalAPIClient
    workerPool chan func()
}

func NewEventLogSystem(workers int) *EventLogSystem {
    es := &EventLogSystem{
        queue:      EventLogQueue{},
        workers:    workers,
        client:     &ExternalAPIClient{},
        workerPool: make(chan func(), workers),
    }
    for i := 0; i < workers; i++ {
        go func() {
            for work := range es.workerPool {
                work()
            }
        }()
    }
    return es
}

func (es *EventLogSystem) LogEvent(event Event) {
    go func() {
        es.queue.Enqueue(event)
        es.workerPool <- func() {
            es.processQueue()
        }
    }()
}

func (es *EventLogSystem) processQueue() {
    for {
        event, ok := es.queue.Dequeue()
        if !ok {
            break
        }
        err := es.client.SendEvent(event)
        if err != nil {
            // Implement adaptive retry policy
        } else {
            fmt.Printf("Event %s logged successfully\n", event.ID)
        }
    }
}

func main() {
    es := NewEventLogSystem(10)
    for i := 0; i < 1000; i++ {
        event := Event{
            ID:        fmt.Sprintf("event-%d", i),
            Publisher: "publisher-1",
            Data:      map[string]interface{}{"message": fmt.Sprintf("Message %d", i)},
        }
        es.LogEvent(event)
    }
}
