using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public class ResourceUsageMonitor
{
    private readonly List<(string ServiceName, Action CriticalProcess)> _services;
    private readonly Dictionary<string, long> _resourceLimits;
    private readonly Dictionary<string, DateTime> _lastReportTimes;
    private Timer _reportTimer;

    public ResourceUsageMonitor(Dictionary<string, long> resourceLimits)
    {
        _services = new List<(string ServiceName, Action CriticalProcess)>();
        _resourceLimits = resourceLimits;
        _lastReportTimes = new Dictionary<string, DateTime>();

        // Initialize the report timer
        _reportTimer = new Timer(GenerateReports, null, TimeSpan.Zero, TimeSpan.FromSeconds(30));
    }

    public void AddService(string serviceName, Action criticalProcess)
    {
        if (!_services.Any(s => s.ServiceName == serviceName))
        {
            _services.Add((serviceName, criticalProcess));
        }
    }

    public void StartMonitoring()
    {
        foreach (var service in _services)
        {
            Task.Run(() => MonitorService(service.ServiceName, service.CriticalProcess));
        }
    }

    private async Task MonitorService(string serviceName, Action criticalProcess)
    {
        try
        {
            while (true)
            {
                Process process = Process.GetCurrentProcess();
                long cpuUsage = process.TotalProcessorTime.Ticks;
                long memoryUsage = process.WorkingSet64;

                if (_resourceLimits.ContainsKey(serviceName))
                {
                    if (cpuUsage > _resourceLimits[serviceName] * 2) // Example threshold
                    {
                        Console.WriteLine($"CPU usage spike detected for {serviceName}");
                    }

                    if (memoryUsage > _resourceLimits[serviceName] * 1.5) // Example threshold
                    {
                        Console.WriteLine($"Memory usage spike detected for {serviceName}");
                    }
                }

                await Task.Delay(1000); // Delay between checks
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error monitoring service {serviceName}: {ex.Message}");
        }
    }

    private void GenerateReports(object state)
    {
        foreach (var service in _services)
        {
            if (!_lastReportTimes.ContainsKey(service.ServiceName) || 
                DateTime.Now - _lastReportTimes[service.ServiceName] > TimeSpan.FromSeconds(60))
            {
                // Log or send report for resource usage
                Console.WriteLine($"Generating report for {service.ServiceName}");
                _lastReportTimes[service.ServiceName] = DateTime.Now;
            }
        }
    }

    public void StopMonitoring()
    {
        _reportTimer.Change(Timeout.Infinite, 0);
