#include <queue>
#include <functional>
#include <atomic>

class BatchProcessor {
public:
    using Data = std::string;
    using ProcessFunction = std::function<void(const Data&)>;

    class TaskQueue {
    public:
        void addTask(const Data& data) {
            std::unique_lock<std::mutex> lock(mutex_);
            tasks_.push(data);
            condition_.notify_one();
        }

        bool getTask(Data& task) {
            std::unique_lock<std::mutex> lock(mutex_);
            if (tasks_.empty()) return false;
            task = std::move(tasks_.front());
            tasks_.pop();
            return true;
        }

    private:
        std::queue<Data> tasks_;
        std::mutex mutex_;
        std::condition_variable condition_;
    };

    BatchProcessor(int numWorkers) : stop_(false), workers_(numWorkers) {
        for (int i = 0; i < numWorkers; ++i) {
            workers_.emplace_back([this]() {
                while (true) {
                    Data task;
                    if (!taskQueue_.getTask(task)) break;
                    processFunction_(task);
                }
            });
        }
    }

    ~BatchProcessor() {
        stop_ = true;
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    void setProcessFunction(ProcessFunction func) {
        processFunction_ = std::move(func);
    }

    void addData(const Data& data) {
        taskQueue_.addTask(data);
    }

private:
    TaskQueue taskQueue_;
    ProcessFunction processFunction_;
    std::vector<std::thread> workers_;
    std::atomic<bool> stop_;
};
