using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicWebsiteManager
{
    private readonly HttpClient _configClient;
    private readonly ConcurrentDictionary<string, WebsiteConfig> _websiteConfigs = new ConcurrentDictionary<string, WebsiteConfig>();
    private readonly ConcurrentBag<IWebsiteService> _websiteServices = new ConcurrentBag<IWebsiteService>();

    public DynamicWebsiteManager()
    {
        _configClient = new HttpClient();
    }

    public async Task InitializeAsync(string configUrl)
    {
        while (true)
        {
            try
            {
                var response = await _configClient.GetAsync(configUrl);
                if (response.IsSuccessStatusCode)
                {
                    var configs = await response.Content.ReadAsAsync<WebsiteConfig[]>(new System.Text.Json.JsonSerializerOptions { PropertyNameCaseInsensitive = true });
                    foreach (var config in configs.Where(c => !_websiteConfigs.ContainsKey(c.Id)))
                    {
                        _websiteConfigs.TryAdd(config.Id, config);
                        _websiteServices.Add(new WebsiteService(_configClient, config));
                    }
                }
            }
            catch
            {
                // Log error and retry after a delay
            }

            await Task.Delay(60000); // Retry every minute
        }
    }

    public async Task StartIisAsync()
    {
        // Code to start IIS service if not running
    }

    public async Task<bool> CheckHealthAsync()
    {
        return _websiteServices.All(service => service.IsHealthy());
    }

    public async Task ScaleAsync(double loadFactor)
    {
        var targetCount = (int)(loadFactor * _websiteConfigs.Count);
        while (_websiteServices.Count < targetCount)
        {
            if (_websiteConfigs.Any())
            {
                var config = _websiteConfigs.First();
                _websiteConfigs.TryRemove(config.Key, out _);
                _websiteServices.Add(new WebsiteService(_configClient, config));
            }
            else
            {
                await Task.Delay(1000); // Wait for new configs
            }
        }
    }

    public async Task CleanupAsync()
    {
        foreach (var service in _websiteServices)
        {
            await service.CleanupAsync();
        }
    }
}

public class WebsiteConfig
{
    public string Id { get; set; }
    public string Url { get; set; }
    // Other properties
}

public interface IWebsiteService : IDisposable
{
    bool IsHealthy();
    Task CleanupAsync();
}

