using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashingLibrary
{
    private string _algorithm;
    private ILogger _logger;

    public HashingLibrary(string algorithm, ILogger logger)
    {
        _algorithm = algorithm;
        _logger = logger;
    }

    public string GenerateHash(object data)
    {
        byte[] hashBytes;
        using (var hasher = GetHashAlgorithm(_algorithm))
        {
            hashBytes = hasher.ComputeHash(GetDataBytes(data));
        }
        var hashValue = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        LogHashGenerationEvent(data, _algorithm, true);
        return hashValue;
    }

    private HashAlgorithm GetHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToLower())
        {
            case "md5": return MD5.Create();
            case "sha1": return SHA1.Create();
            case "sha256": return SHA256.Create();
            case "sha512": return SHA512.Create();
            case "blake2s": return new Blake2B(256);
            case "keccak": return Keccak.Create(256);
            default: throw new ArgumentException("Unsupported hashing algorithm");
        }
    }

    private byte[] GetDataBytes(object data)
    {
        switch (data)
        {
            case string str: return Encoding.UTF8.GetBytes(str);
            case byte[] bytes: return bytes;
            // Add more cases for other data types as needed
            default: throw new ArgumentException("Unsupported data type");
        }
    }

    private void LogHashGenerationEvent(object input, string algorithm, bool success)
    {
        var logEntry = new LogEntry
        {
            Timestamp = DateTime.UtcNow,
            InputData = input.ToString(),
            Algorithm = algorithm,
            Success = success
        };
        _logger.Log(logEntry);
    }
}

public interface ILogger
{
    void Log(LogEntry entry);
}

public class FileLogger : ILogger
{
    public void Log(LogEntry entry)
    {
        var logLine = $"{entry.Timestamp}|{entry.InputData}|{entry.Algorithm}|{(entry.Success ? "Success" : "Failure")}";
        File.AppendAllText("log.txt", logLine + Environment.NewLine);
    }
}

public class LogEntry
{
    public DateTime Timestamp { get; set; }
    public string InputData { get; set; }
    public string Algorithm { get; set; }
    public bool Success { get; set; }
}
```

