use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use tokio::sync::Mutex;
use tokio::task;

#[derive(Clone)]
struct DistributedDirectoryManager {
    config: Arc<Mutex<HashMap<String, String>>>,
    environment: Arc<Mutex<HashMap<String, String>>>,
    log_service: LogService,
}

impl DistributedDirectoryManager {
    fn new(config: HashMap<String, String>, environment: HashMap<String, String>) -> Self {
        DistributedDirectoryManager {
            config: Arc::new(Mutex::new(config)),
            environment: Arc::new(Mutex::new(environment)),
            log_service: LogService::new(),
        }
    }

    async fn create_directory(&self, path: &str) {
        let mut config = self.config.lock().await;
        let mut environment = self.environment.lock().await;

        // Simulate directory creation
        if !config.contains_key(path) {
            config.insert(path.to_string(), "created".to_string());
            environment.insert(format!("{}:variable", path), "value".to_string());
            self.log_service.log_event(&format!("Directory created at {}", path));
        } else {
            self.log_service.log_event(&format!("Attempted to create existing directory at {}", path));
        }
    }

    async fn rename_directory(&self, old_path: &str, new_path: &str) {
        let mut config = self.config.lock().await;
        let mut environment = self.environment.lock().await;

        // Simulate directory renaming
        if let Some(value) = config.remove(old_path) {
            config.insert(new_path.to_string(), value);
            environment.retain(|k, v| !k.starts_with(old_path));
            environment.insert(format!("{}:variable", new_path), "value".to_string());
            self.log_service.log_event(&format!("Directory renamed from {} to {}", old_path, new_path));
        } else {
            self.log_service.log_event(&format!("Attempted to rename non-existent directory at {}", old_path));
        }
    }

    async fn delete_directory(&self, path: &str) {
        let mut config = self.config.lock().await;
        let mut environment = self.environment.lock().await;

        // Simulate directory deletion
        if config.remove(path).is_some() {
            environment.retain(|k, v| !k.starts_with(path));
            self.log_service.log_event(&format!("Directory deleted at {}", path));
        } else {
            self.log_service.log_event(&format!("Attempted to delete non-existent directory at {}", path));
        }
    }

    async fn update_environment_variable(&self, path: &str, variable_name: &str, value: &str) {
        let mut environment = self.environment.lock().await;

        // Simulate updating environment variable
        if let Some(ref mut entry) = environment.get_mut(&format!("{}:variable", path)) {
            *entry = value.to_string();
            self.log_service.log_event(&format!("Environment variable updated at {} for {}", path, variable_name));
        } else {
            self.log_service.log_event(&format!("Attempted to update non-existent environment variable at {}", path));
        }
    }

    async fn get_directory_info(&self, path: &str) -> Option<&String> {
        let config = self.config.lock().await;
        config.get(path)
    }
}

struct LogService {
    log_storage: Arc<Mutex<Vec<String>>>,
}

impl LogService {
    fn new() -> Self {
        LogService {
            log_storage: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn log_event(&self, event: &str) {
        let mut logs = self.log_storage.lock().unwrap();
        logs.push(event.to_string());
    }
}

#[tokio::main]
async fn main() {
    let config = HashMap::from([("region".to_string(), "us-east-1".to_string())]);
    let environment = HashMap::new();

    let manager = DistributedDirectoryManager::new(config, environment);

    let mut tasks = Vec::new();
    for _ in 0..10 {
        tasks.push(task::spawn(async move {
            manager.create_directory("/data/newdir").await;
            manager.rename_directory("/data/olddir", "/data/newdir").await;
            manager.delete_directory("/data/newdir").await;
            manager.update_environment_variable("/data/dir", "variable_name", "new_value").await;
        }));
    }

    for task in tasks {
        task.await.unwrap();
    }
}
