# Define a modular Python library structure

from abc import ABC, abstractmethod
import json

class DataConnector(ABC):
    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def fetch_data(self):
        pass

class RelationalDBConnector(DataConnector):
    def connect(self):
        print("Connecting to relational database...")

    def fetch_data(self):
        return "Data from relational database"

class NoSQLStoreConnector(DataConnector):
    def connect(self):
        print("Connecting to NoSQL store...")

    def fetch_data(self):
        return "Data from NoSQL store"

class MessageBrokerConnector(DataConnector):
    def connect(self):
        print("Connecting to message broker...")

    def fetch_data(self):
        return "Data from message broker"

class HTTPAPIConnector(DataConnector):
    def connect(self):
        print("Connecting to HTTP API...")

    def fetch_data(self):
        return "Data from HTTP API"

class StreamProcessingEngine:
    def process_stream(self, data):
        # Implement stream processing logic here
        pass

class BatchProcessor:
    def process_batch(self, data):
        # Implement batch processing logic here
        pass

class MixedModeManager:
    def __init__(self, engine, processor):
        self.engine = engine
        self.processor = processor

    def handle_data(self, data, mode='stream'):
        if mode == 'stream':
            self.engine.process_stream(data)
        elif mode == 'batch':
            self.processor.process_batch(data)

# Example usage
connectors = {
    "relational_db": RelationalDBConnector(),
    "nosql_store": NoSQLStoreConnector(),
    "message_broker": MessageBrokerConnector(),
    "http_api": HTTPAPIConnector()
}

engine = StreamProcessingEngine()
processor = BatchProcessor()
manager = MixedModeManager(engine, processor)

for connector_name, connector in connectors.items():
    connector.connect()
    data = connector.fetch_data()
    manager.handle_data(data)
