// Include necessary headers
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/des.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

// Define constants
#define MAX_RECORDS 1000
#define KEY_RANGE_MIN 100
#define KEY_RANGE_MAX 999

// Record structure
typedef struct {
    long offset;
    int key;
} Record;

// Global variables
Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize records with unique keys
void init_records() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key;
        do {
            key = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
        } while (find_record_by_key(key) != -1);
        records[i].offset = i * sizeof(Record);
        records[i].key = key;
    }
    record_count = MAX_RECORDS;
    pthread_mutex_unlock(&mutex);
}

// Function to find a record by key
int find_record_by_key(int key) {
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            return i;
        }
    }
    return -1;
}

// Function to encrypt data using DES
void des_encrypt(unsigned char *data, unsigned char *key, int length) {
    DES_key_schedule ks;
    DES_set_odd_parity((DES_cblock *)key);
    DES_set_key_unchecked((DES_cblock *)key, &ks);
    for (int i = 0; i < length; i += 8) {
        DES_encrypt1((DES_cblock *)(data + i), (DES_cblock *)(data + i), ks, DES_ENCRYPT);
    }
}

// Function to decrypt data using DES
void des_decrypt(unsigned char *data, unsigned char *key, int length) {
    DES_key_schedule ks;
    DES_set_odd_parity((DES_cblock *)key);
    DES_set_key_unchecked((DES_cblock *)key, &ks);
    for (int i = 0; i < length; i += 8) {
        DES_encrypt1((DES_cblock *)(data + i), (DES_cblock *)(data + i), ks, DES_DECRYPT);
    }
}

// Function to encrypt data using AES
void aes_encrypt(unsigned char *data, unsigned char *key, int length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, (unsigned char *)"0123456789abcdef");
    EVP_EncryptUpdate(ctx, data, &length, data, length);
    EVP_EncryptFinal_ex(ctx, data + length, &length);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using AES
void aes_decrypt(unsigned char *data, unsigned char *key, int length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, (unsigned char *)"0123456789abcdef");
    EVP_DecryptUpdate(ctx, data, &length, data, length);
    EVP_DecryptFinal_ex(ctx, data + length, &length);
    EVP_CIPHER_CTX_free(ctx);
}

// Function to handle API requests
void handle_api_request(int client_socket) {
    // Parse request and extract parameters
    char buffer[1024];
    read(client_socket, buffer, sizeof(buffer));
    char *method = strtok(buffer, " ");
    char *endpoint = strtok(NULL, " ");
    char *params = strtok(NULL, "\n");

    // Process request based on method and endpoint
    if (strcmp(method, "POST") == 0 && strcmp(endpoint, "/encrypt") == 0) {
        // Extract data and key from params
        unsigned char data[1024];
        unsigned char key[32];
        sscanf(params, "%s %s", (char *)data, (char *)key);

        // Encrypt data using DES or AES
        if (strcmp(key, "des") == 0) {
            des_encrypt(data, key, strlen((char *)data));
        } else if (strcmp(key, "aes") == 0) {
            aes_encrypt(data, key, strlen((char *)data));
        }

        // Send encrypted data back to client
        write(client_socket, data, strlen((char *)data));
    } else if (strcmp(method, "POST") == 0 && strcmp(endpoint, "/decrypt") == 0) {
        // Extract data and key from params
        unsigned char data[1024];
        unsigned char key[32];
        sscanf(params, "%s %s", (char *)data, (char *)key);

        // Decrypt data using DES or AES
        if (strcmp(key, "des") == 0) {
            des_decrypt(data, key, strlen((char *)data));
        } else if (strcmp(key, "aes") == 0) {
            aes_decrypt(data, key, strlen((char *)data));
        }

        // Send decrypted data back to client
        write(client_socket, data, strlen((char *)data));
    }

    // Close client socket
    close(client_socket);
}

// Function to start server and handle incoming requests
void start_server() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    bind(server_socket, (struct sockaddr *)&address, sizeof(address));
    listen(server_socket, 5);
    printf("Server started on port 8080\n");

    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        pthread_t thread;
        pthread_create(&thread, NULL, handle_api_request, (void *)client_socket);
        pthread_detach(thread);
    }

    close(server_socket);
}

// Main function
int main() {
    init_records();
    start_server();
    return 0;
}
