                Queue<DataPoint> queue = dataQueues.get(deviceId);
                if (!queue.isEmpty()) {
                    DataPoint[] batch = new DataPoint[Math.min(queue.size(), BATCH_SIZE)];
                    queue.drainTo(batch, BATCH_SIZE);

                    processBatch(batch, deviceId);
                }
            }

            // Adjust number of active threads based on load
            int currentThreads = activeThreads.get();
            if (currentThreads < MAX_THREADS && dataQueues.values().stream().anyMatch(q -> q.size() > BATCH_SIZE / 2)) {
                startNewThread();
            } else if (currentThreads > MIN_THREADS && dataQueues.values().stream().allMatch(q -> q.size() <= BATCH_SIZE / 4)) {
                stopThread();
            }

            try {
                Thread.sleep(SLEEP_INTERVAL);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void processBatch(DataPoint[] batch, String deviceId) {
        // Process data batch
        for (DataPoint dataPoint : batch) {
            validateAndTransform(dataPoint);
            exportData(dataPoint);
        }

        activeThreads.decrementAndGet();
    }

    private void validateAndTransform(DataPoint dataPoint) {
        // Validate and transform data point
    }

    private void exportData(DataPoint dataPoint) {
        // Export data to external systems with error handling and retries
    }

    private void startNewThread() {
        new Thread(this::startProcessing).start();
        activeThreads.incrementAndGet();
    }

    private void stopThread() {
        // Implement strategy to gracefully stop threads
    }
}
```

