import os
from Crypto.Cipher import DES, AES, ChaCha20
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
from cachetools import TTLCache, cached

class CryptographicService:
    def __init__(self, key_size=32):
        self.key = os.urandom(key_size)
        self.caches = {
            'des': TTLCache(maxsize=100, ttl=300),
            'aes': TTLCache(maxsize=100, ttl=300),
            'chacha20': TTLCache(maxsize=100, ttl=300)
        }

    @cached(cache=lambda self: self.caches['des'])
    def encrypt_des(self, plaintext):
        des = DES.new(self.key, DES.MODE_ECB)
        return des.encrypt(pad(plaintext.encode(), DES.block_size))

    @cached(cache=lambda self: self.caches['aes'])
    def encrypt_aes(self, plaintext, mode=DES.MODE_ECB):
        aes = AES.new(self.key, mode)
        if mode in [AES.MODE_CBC, AES.MODE_CFB]:
            iv = os.urandom(AES.block_size)
            return iv + aes.encrypt(pad(plaintext.encode(), AES.block_size))
        else:
            return aes.encrypt(pad(plaintext.encode(), AES.block_size))

    @cached(cache=lambda self: self.caches['chacha20'])
    def encrypt_chacha20(self, plaintext):
        chacha = ChaCha20.new(key=self.key)
        nonce = os.urandom(16)
        return nonce + chacha.encrypt(plaintext.encode())

    def decrypt_des(self, ciphertext):
        des = DES.new(self.key, DES.MODE_ECB)
        return unpad(des.decrypt(ciphertext), DES.block_size).decode()

    def decrypt_aes(self, ciphertext, mode=DES.MODE_ECB):
        aes = AES.new(self.key, mode)
        if mode in [AES.MODE_CBC, AES.MODE_CFB]:
            iv = ciphertext[:AES.block_size]
            ciphertext = ciphertext[AES.block_size:]
        return unpad(aes.decrypt(ciphertext), AES.block_size).decode()

    def decrypt_chacha20(self, ciphertext):
        chacha = ChaCha20.new(key=self.key)
        nonce = ciphertext[:16]
        ciphertext = ciphertext[16:]
        return chacha.decrypt(ciphertext).decode()

# Usage
service = CryptographicService()
encrypted_des = service.encrypt_des("Hello DES")
decrypted_des = service.decrypt_des(encrypted_des)

encrypted_aes_ecb = service.encrypt_aes("Hello AES ECB", AES.MODE_ECB)
decrypted_aes_ecb = service.decrypt_aes(encrypted_aes_ecb, AES.MODE_ECB)

encrypted_chacha20 = service.encrypt_chacha20("Hello ChaCha20")
decrypted_chacha20 = service.decrypt_chacha20(encrypted_chacha20)
```

