#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->records = (Record*)malloc(initial_capacity * sizeof(Record));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

bool add_record(MemoryManager *manager, long offset, int key) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        pthread_mutex_unlock(&manager->lock);
        return false; // Memory limit exceeded
    }
    manager->records[manager->size].offset = offset;
    manager->records[manager->size].key = key;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return true;
}

void destroy_memory_manager(MemoryManager *manager) {
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
