#include "FileMetadataStruct.h"
#include <vector>
#include <memory>
#include <mutex>

class IMetadataStorage;
class IExternalSystem;

class MetadataManager {
public:
    void addMetadata(const FileMetadataStruct& metadata);
    void updateMetadata(const FileMetadataStruct& metadata);
    FileMetadataStruct getMetadata(const std::string& filePath) const;

private:
    std::unordered_map<std::string, FileMetadataStruct> metadataMap;
    mutable std::mutex mutex;
    std::vector<IMetadataStorage*> storageSystems;
    IExternalSystem* externalSystem;
};

// MetadataManager.cpp
#include "MetadataManager.h"
#include <iostream>
#include <stdexcept>

void MetadataManager::addMetadata(const FileMetadataStruct& metadata) {
    std::lock_guard<std::mutex> lock(mutex);
    metadataMap[metadata.filePath] = metadata;

    for (auto storage : storageSystems) {
        storage->store(metadata);
    }

    externalSystem->syncMetadata(metadata);
}

void MetadataManager::updateMetadata(const FileMetadataStruct& metadata) {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = metadataMap.find(metadata.filePath);
    if (it != metadataMap.end()) {
        it->second = metadata;

        for (auto storage : storageSystems) {
            storage->store(it->second);
        }

        externalSystem->syncMetadata(it->second);
    } else {
        throw std::runtime_error("Metadata not found");
    }
}

FileMetadataStruct MetadataManager::getMetadata(const std::string& filePath) const {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = metadataMap.find(filePath);
    if (it != metadataMap.end()) {
        return it->second;
    } else {
        throw std::runtime_error("Metadata not found");
    }
}

// MetadataStorage.h
#pragma once

class IMetadataStorage {
public:
    virtual void store(const FileMetadataStruct& metadata) = 0;
};

// ExternalSystem.h
#pragma once

class IExternalSystem {
public:
    virtual void syncMetadata(const FileMetadataStruct& metadata) = 0;
};
