import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

@SpringBootApplication
@RestController
public class ResourceManagementService {

    private Jedis jedis = new Jedis("localhost");

    @PutMapping("/update")
    public String updateResource(@RequestBody String jsonData) {
        try {
            // Validate and process JSON data
            String md5Hash = generateMd5(jsonData);
            // Store in Redis atomically
            jedis.set(md5Hash, jsonData);
            return md5Hash;
        } catch (Exception e) {
            handleException(e);
            return null;
        }
    }

    @DeleteMapping("/create")
    public String createResource() {
        try {
            // Create resource with default values
            String defaultValues = "{\"key\":\"default\"}";
            String md5Hash = generateMd5(defaultValues);
            // Store in Redis atomically
            jedis.set(md5Hash, defaultValues);
            return md5Hash;
        } catch (Exception e) {
            handleException(e);
            return null;
        }
    }

    private String generateMd5(String data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(data.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void handleException(Exception e) {
        // Log the exception using external logging service
        // Retry mechanism for transient issues
        // Informative error responses to clients
    }

    public static void main(String[] args) {
        SpringApplication.run(ResourceManagementService.class, args);
    }
}
