#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <cstdint>
#include <openssl/sha.h>
#include "redis-plus-plus/include/redis++.h"

class DataItem {
public:
    uint64_t id;
    std::string data;

    DataItem(uint64_t id, std::string data) : id(id), data(data) {}
};

class DataManager {
private:
    redis::client dbClient;
    std::unordered_map<uint64_t, DataItem*> itemMap;

public:
    DataManager(const std::string& redisUrl) : dbClient(redisUrl) {}

    ~DataManager() {
        for (auto& item : itemMap) {
            delete item.second;
        }
    }

    void initialize(const std::vector<std::string>& inputStrings) {
        for (const auto& str : inputStrings) {
            uint64_t id = hashString(str);
            if (itemMap.find(id) != itemMap.end()) {
                mergeItems(itemMap[id], str);
            } else {
                DataItem* newItem = new DataItem(id, str);
                itemMap[id] = newItem;
                saveToDB(*newItem);
            }
        }
    }

    void update(const std::string& inputString) {
        uint64_t id = hashString(inputString);
        if (itemMap.find(id) != itemMap.end()) {
            mergeItems(itemMap[id], inputString);
            saveToDB(*itemMap[id]);
        } else {
            DataItem* newItem = new DataItem(id, inputString);
            itemMap[id] = newItem;
            saveToDB(*newItem);
        }
    }

private:
    uint64_t hashString(const std::string& str) {
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256((unsigned char*)str.c_str(), str.length(), (unsigned char*)&digest);
        return *reinterpret_cast<uint64_t*>(digest);
    }

    void mergeItems(DataItem* item, const std::string& newData) {
        item->data += newData;
    }

    void saveToDB(const DataItem& item) {
        try {
            dbClient.set(item.id, item.data);
        } catch (const redis::exception& e) {
            std::cerr << "Error saving to DB: " << e.what() << std::endl;
        }
    }
};

int main() {
    std::vector<std::string> inputStrings = {"example1", "example2", "example3"};
    DataManager manager("tcp://localhost:6379");
    manager.initialize(inputStrings);
    manager.update("example1");
    return 0;
}
```']

