import java.io.BufferedReader;
import java.io.File;
import java.io.InputStreamReader;

public class CommandExecutor {

    public static void main(String[] args) {
        String command = "your_command_here";
        File directory = new File("your_directory_here");

        try {
            executeCommand(command, directory);
        } catch (Exception e) {
            System.err.println("Error executing command: " + e.getMessage());
        }
    }

    public static void executeCommand(String command, File directory) throws Exception {
        // Delete file if it exists
        File fileToDelete = new File(directory, "file_to_delete.txt");
        if (fileToDelete.exists()) {
            fileToDelete.delete();
        }

        Process process = Runtime.getRuntime().exec(command, null, directory);

        BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String s;
        System.out.println("Standard Output:");
        while ((s = stdInput.readLine()) != null) {
            System.out.println(s);
        }

        System.err.println("Standard Error:");
        while ((s = stdError.readLine()) != null) {
            System.err.println(s);
        }

        int exitCode = process.waitFor();
        System.out.println("Exit Code: " + exitCode);
    }
}
