const fs = require('fs');
const path = require('path');
const chokidar = require('chokidar');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);

async function loadConfig(filePath) {
  try {
    const data = await readFileAsync(filePath, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    console.error(`Failed to read config file ${filePath}:`, error);
    throw error;
  }
}

function mergeConfigs(baseConfig, updateConfig) {
  return { ...baseConfig, ...updateConfig };
}

async function saveConfig(config, outputFilePath) {
  try {
    const data = JSON.stringify(config, null, 2);
    await writeFileAsync(outputFilePath, data);
    console.log(`Config saved to ${outputFilePath}`);
  } catch (error) {
    console.error(`Failed to write config file ${outputFilePath}:`, error);
    throw error;
  }
}

async function watchConfigFiles(baseFilePath, updateFilePath, outputFilePath) {
  const baseConfig = await loadConfig(baseFilePath);
  let currentConfig = { ...baseConfig };

  chokidar.watch(updateFilePath).on('change', async () => {
    try {
      const updateConfig = await loadConfig(updateFilePath);
      const newConfig = mergeConfigs(currentConfig, updateConfig);
      await saveConfig(newConfig, outputFilePath);
      currentConfig = newConfig;
      console.log('Configuration updated and saved.');
    } catch (error) {
      console.error('Error during config update:', error);
    }
  });
}

// Example usage
const baseFilePath = path.join(__dirname, 'config_base.json');
const updateFilePath = path.join(__dirname, 'config_update.json');
const outputFilePath = path.join(__dirname, 'config_final.json');

watchConfigFiles(baseFilePath, updateFilePath, outputFilePath);
```

