#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct MemoryManager {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager *mm = (MemoryManager*) malloc(sizeof(MemoryManager));
    mm->records = (Record*) malloc(initial_capacity * sizeof(Record));
    mm->capacity = initial_capacity;
    mm->size = 0;
    pthread_mutex_init(&mm->lock, NULL);
    return mm;
}

void destroy_memory_manager(MemoryManager *mm) {
    free(mm->records);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

int add_record(MemoryManager *mm, Record record) {
    pthread_mutex_lock(&mm->lock);
    if (mm->size >= mm->capacity) {
        // Double the capacity and reallocate memory
        mm->capacity *= 2;
        mm->records = (Record*) realloc(mm->records, mm->capacity * sizeof(Record));
        if (!mm->records) {
            pthread_mutex_unlock(&mm->lock);
            return -1; // Memory allocation failed
        }
    }
    mm->records[mm->size++] = record;
    pthread_mutex_unlock(&mm->lock);
    return 0;
}

