    long offset;
    int key;
} Record;

// Memory management structure
typedef struct {
    Record records[MAX_RECORDS];
    int size;
    pthread_mutex_t lock;
    size_t memory_usage;
    size_t max_memory_limit;
} MemoryManager;

// Function to initialize the memory manager
void init_memory_manager(MemoryManager *mm, size_t max_memory_limit) {
    mm->size = 0;
    mm->max_memory_limit = max_memory_limit;
    pthread_mutex_init(&mm->lock, NULL);
    mm->memory_usage = 0;
}

// Function to allocate memory for a new record
int allocate_record(MemoryManager *mm, long offset, int key) {
    pthread_mutex_lock(&mm->lock);
    if (mm->size >= MAX_RECORDS || mm->memory_usage + sizeof(Record) > mm->max_memory_limit) {
        pthread_mutex_unlock(&mm->lock);
        return -1; // Out of memory
    }
    Record new_record = {offset, key};
    memcpy(&mm->records[mm->size], &new_record, sizeof(Record));
    mm->size++;
    mm->memory_usage += sizeof(Record);
    pthread_mutex_unlock(&mm->lock);
    return 0;
}

// Function to retrieve a record by index
int get_record(MemoryManager *mm, int index, Record *result) {
    pthread_mutex_lock(&mm->lock);
    if (index < 0 || index >= mm->size) {
        pthread_mutex_unlock(&mm->lock);
        return -1; // Invalid index
    }
    memcpy(result, &mm->records[index], sizeof(Record));
    pthread_mutex_unlock(&mm->lock);
    return 0;
