// MemoryManager.h
#ifndef MEMORY_MANAGER_H
#define MEMORY_MANAGER_H

#include <unordered_map>
#include <string>
#include <mutex>

class MemoryManager {
public:
    static MemoryManager& getInstance() {
        static MemoryManager instance;
        return instance;
    }

    void setMaxMemorySize(size_t size) { maxMemorySize = size; }
    bool allocateRecord(const std::string& key, int value);
    bool deallocateRecord(const std::string& key);
    int getRecordValue(const std::string& key);

private:
    MemoryManager() {}
    ~MemoryManager() {}

    static MemoryManager instance;
    std::unordered_map<std::string, int> records;
    size_t maxMemorySize = 0;
    size_t currentMemoryUsage = 0;
    std::mutex mutex;
};

#endif // MEMORY_MANAGER_H

// MemoryManager.cpp
#include "MemoryManager.h"

MemoryManager& MemoryManager::instance = MemoryManager();

bool MemoryManager::allocateRecord(const std::string& key, int value) {
    std::lock_guard<std::mutex> lock(mutex);
    if (records.find(key) != records.end()) return false;
    if (currentMemoryUsage + sizeof(int) > maxMemorySize) return false;
    records[key] = value;
    currentMemoryUsage += sizeof(int);
    return true;
}

bool MemoryManager::deallocateRecord(const std::string& key) {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = records.find(key);
    if (it == records.end()) return false;
    currentMemoryUsage -= sizeof(int);
    records.erase(it);
    return true;
}

int MemoryManager::getRecordValue(const std::string& key) {
    std::lock_guard<std::mutex> lock(mutex);
    auto it = records.find(key);
    if (it == records.end()) throw std::runtime_error("Key not found");
    return it->second;
}

// forward_list_utils.h
#ifndef FORWARD_LIST_UTILS_H
#define FORWARD_LIST_UTILS_H

#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert);

#endif // FORWARD_LIST_UTILS_H

// forward_list_utils.cpp
#include "forward_list_utils.h"

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto it = list.begin();
    for (; it != list.end(); ++it) {
        if (*it == target) break;
    }
    if (it != list.end()) {
        list.insert_after(it, toInsert);
    } else {
        list.push_back(toInsert);
    }
}
