// MemoryManager.cs
using System;
using System.Collections.Generic;

public class MemoryManager
{
    private static readonly Lazy<MemoryManager> lazyInstance = new Lazy<MemoryManager>(() => new MemoryManager());
    public static MemoryManager Instance => lazyInstance.Value;

    private Dictionary<string, int> records;
    private long maxMemorySize;
    private long currentMemoryUsage;

    private MemoryManager()
    {
        records = new Dictionary<string, int>();
        maxMemorySize = 0;
        currentMemoryUsage = 0;
    }

    public void SetMaxMemorySize(long size)
    {
        maxMemorySize = size;
    }

    public bool AllocateRecord(string key, int value)
    {
        lock (records)
        {
            if (records.ContainsKey(key)) return false;
            if (currentMemoryUsage + sizeof(int) > maxMemorySize) return false;
            records[key] = value;
            currentMemoryUsage += sizeof(int);
            return true;
        }
    }

    public bool DeallocateRecord(string key)
    {
        lock (records)
        {
            if (!records.ContainsKey(key)) return false;
            currentMemoryUsage -= sizeof(int);
            records.Remove(key);
            return true;
        }
    }

    public int GetRecordValue(string key)
    {
        lock (records)
        {
            if (!records.ContainsKey(key)) throw new Exception("Key not found");
            return records[key];
        }
    }
}

// ForwardListUtils.cs
using System.Collections.Generic;

public static class ForwardListUtils
{
    public static void InsertAfterFirstOccurrence(ForwardList<string> list, string target, string toInsert)
    {
        var it = list.Begin;
        for (; it != null; it = it.Next)
        {
            if (it.Value == target) break;
        }
        if (it != null)
        {
            list.InsertAfter(it, toInsert);
        }
        else
        {
            list.Add(toInsert);
        }
    }
}
