# Import necessary libraries
import logging
from abc import ABC, abstractmethod
import threading
import time
import requests

# Define an abstract base class for logging backends
class LoggingBackend(ABC):
    @abstractmethod
    def log(self, message):
        pass

# Implement concrete logging backend for AWS CloudWatch
class CloudWatchBackend(LoggingBackend):
    def log(self, message):
        # Simulate logging to AWS CloudWatch
        print(f"Logging to CloudWatch: {message}")

# Implement concrete logging backend for Google Stackdriver
class StackdriverBackend(LoggingBackend):
    def log(self, message):
        # Simulate logging to Google Stackdriver
        print(f"Logging to Stackdriver: {message}")

# Define a logger manager class
class LoggerManager:
    _instance = None
    _lock = threading.Lock()
    backends = {}

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = cls()
        return cls._instance

    def __init__(self):
        self.load_backends()

    def load_backends(self):
        # Simulate loading supported logging backends
        services = os.getenv("SUPPORTED_SERVICES", "cloudwatch,stackdriver").split(",")
        for service in services:
            if service == "cloudwatch":
                self.backends[service] = CloudWatchBackend()
            elif service == "stackdriver":
                self.backends[service] = StackdriverBackend()

    def log(self, message):
        # Log to all configured backends
        for backend in self.backends.values():
            backend.log(message)

# Example usage
logger_manager = LoggerManager.get_instance()
logger_manager.log("This is a test log message.")
