// Define a LogProcessor class that can be dynamically configured
class LogProcessor {
public:
    void setMetadataFields(const std::vector<std::string>& fields) {
        metadata_fields = fields;
    }

    void processLogEntry(const LogEntry& entry) {
        // Validate and extract metadata
        for (const auto& field : metadata_fields) {
            if (entry.message.find(field) == std::string::npos) {
                throw std::runtime_error("Missing metadata field: " + field);
            }
        }

        // Log the entry
        logger.log(entry);
    }

private:
    Logger logger;
    std::vector<std::string> metadata_fields;
};

int main() {
    // Example usage
    LogProcessor processor;
    processor.setMetadataFields({"timestamp", "source"});

    LogEntry entry = {"2023-10-05T14:30:00Z", "app-server-1", "INFO: Service started"};
    processor.processLogEntry(entry);

    return 0;
}
