// Define a UnionFind class for disjoint set operations
public class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public boolean areDisjoint(int x, int y) {
        return find(x) != find(y);
    }
}

// Define a DisjointPairsCounter class to compute disjoint pairs
@Service
public class DisjointPairsCounter {
    @Autowired
    private UnionFind unionFind;

    public int countDisjointPairs(int[] array) {
        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!unionFind.areDisjoint(array[i], array[j])) {
                    unionFind.union(array[i], array[j]);
                }
            }
        }
        return unionFind.parent.length - unionFind.rank.length;
    }
}

// Define a DisjointPairsController class to handle disjoint pairs computation
@RestController
@RequestMapping("/disjoint-pairs")
public class DisjointPairsController {
    @Autowired
    private DisjointPairsCounter counter;

    @PostMapping
    public ResponseEntity<Integer> countDisjointPairs(@RequestBody int[] array) {
        try {
            long startTime = System.currentTimeMillis();
            int result = counter.countDisjointPairs(array);
            long endTime = System.currentTimeMillis();
            System.out.println("Execution time: " + (endTime - startTime) + " ms");
            return new ResponseEntity<>(result, HttpStatus.OK);
        } catch (Exception e) {
            return new ResponseEntity<>("Error counting disjoint pairs", HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }
}
