#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 10000
#define MAX_KEY_RANGE 1000

typedef struct {
    long offset;
    int key;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
int key_range = MAX_KEY_RANGE;

void initialize_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->offset = -1;
        records[i]->key = rand() % key_range;
    }
}

void free_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }
}

int find_key(int target_key) {
    for (int i = 0; i < record_count; i++) {
        if (records[i]->key == target_key && records[i]->offset != -1) {
            return i;
        }
    }
    return -1;
}

void set_record(long offset, int key) {
    int index = find_key(key);
    if (index == -1 || record_count >= MAX_RECORDS) {
        fprintf(stderr, "Record not found or memory limit exceeded\n");
        return;
    }
    records[index]->offset = offset;
}

long get_offset(int key) {
    int index = find_key(key);
    if (index == -1) {
        fprintf(stderr, "Key not found\n");
        return -1;
    }
    return records[index]->offset;
}

int add_record(long offset, int key) {
    if (record_count >= MAX_RECORDS) {
        fprintf(stderr, "Memory limit exceeded\n");
        return -1;
    }
    set_record(offset, key);
    record_count++;
    return 0;
}

int remove_record(int key) {
    int index = find_key(key);
    if (index == -1) {
        fprintf(stderr, "Key not found\n");
        return -1;
    }
    records[index]->offset = -1;
    record_count--;
    return 0;
}

int is_record_empty(int key) {
    int index = find_key(key);
    return index != -1 && records[index]->offset == -1;
}

void print_records() {
    printf("Records:\n");
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i] && records[i]->offset != -1) {
            printf("%d: %ld\n", records[i]->key, records[i]->offset);
        }
    }
}

int main() {
    initialize_records();
    add_record(123456789, 1001);
    print_records();
    remove_record(1001);
    print_records();
    free_records();
    return 0;
}
