public class DistributedLoggingFramework {

    private ConcurrentHashMap<String, LogQueue> logQueues = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();
    private ExternalLogAggregationService els;

    public void initialize(ExternalLogAggregationService els) {
        this.els = els;
    }

    public void log(String sourceId, String message, LogLevel level, LogContext context) {
        LogEntry entry = new LogEntry(sourceId, message, level, context);
        LogQueue queue = logQueues.computeIfAbsent(sourceId, k -> new LogQueue());
        queue.add(entry);

        // Asynchronously send logs to ELS
        executorService.submit(() -> {
            while (!queue.isEmpty()) {
                try {
                    els.send(queue.poll());
                } catch (Exception e) {
                    handleLogFailure(e, entry);
                }
            }
        });
    }

    private void handleLogFailure(Exception e, LogEntry entry) {
        if (els.isAvailable() && !isTransientFailure(e)) {
            log(entry.sourceId, "Failed to send log: " + e.getMessage(), LogLevel.ERROR, null);
        } else {
            // Retry logic or fallback mechanism
            executorService.schedule(() -> handleLogFailure(e, entry), 1, TimeUnit.SECONDS);
        }
    }

    private boolean isTransientFailure(Exception e) {
        // Implement logic to determine if the failure is transient
        return false;
    }

    public void setLogLevel(String sourceId, LogLevel level) {
        LogQueue queue = logQueues.get(sourceId);
        if (queue != null) {
            queue.setLogLevel(level);
        }
    }

    public void updateContext(String sourceId, LogContext context) {
        LogQueue queue = logQueues.get(sourceId);
        if (queue != null) {
            queue.updateContext(context);
        }
