// Define the Device struct to represent network devices
#[derive(Clone, Debug)]
struct Device {
    ip: String,
    port: u16,
    status: String,
    last_activity: std::time::SystemTime,
}

impl Device {
    // Constructor to create a new device with initial values
    fn new(ip: &str, port: u16) -> Result<Self, &'static str> {
        if Self::is_valid_ip(ip) && (1..=65535).contains(&port) {
            Ok(Device {
                ip: ip.to_string(),
                port,
                status: "Online".to_string(),
                last_activity: std::time::SystemTime::now(),
            })
        } else {
            Err("Invalid IP address or port number")
        }
    }

    // Method to check if the IP address is valid
    fn is_valid_ip(ip: &str) -> bool {
        ip.parse::<std::net::IpAddr>().is_ok()
    }
}

// Define a trait for network monitoring operations
trait NetworkMonitor {
    fn add_device(&self, device: Device) -> Result<(), &'static str>;
    fn update_device(&self, device_id: usize, status: &str) -> Result<(), &'static str>;
    fn remove_device(&self, device_id: usize) -> Result<(), &'static str>;
    fn get_device_status(&self, device_id: usize) -> Option<String>;
}

// Implement the NetworkMonitor trait for a basic in-memory data structure
struct InMemoryMonitor {
    devices: Vec<Device>,
}

impl NetworkMonitor for InMemoryMonitor {
    fn add_device(&mut self, device: Device) -> Result<(), &'static str> {
        self.devices.push(device);
        Ok(())
    }

    fn update_device(&mut self, device_id: usize, status: &str) -> Result<(), &'static str> {
        if let Some(device) = self.devices.get_mut(device_id) {
            device.status = status.to_string();
            device.last_activity = std::time::SystemTime::now();
            Ok(())
        } else {
            Err("Device not found")
        }
    }

    fn remove_device(&mut self, device_id: usize) -> Result<(), &'static str> {
        if device_id < self.devices.len() {
            self.devices.remove(device_id);
            Ok(())
        } else {
            Err("Device not found")
        }
    }

    fn get_device_status(&self, device_id: usize) -> Option<String> {
        self.devices.get(device_id).map(|d| d.status.clone())
    }
}

