#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <openssl/aes.h>
#include <openssl/rand.h>

class EncryptionLibrary {
public:
    EncryptionLibrary(size_t buffer_size, size_t max_buffer_size)
        : buffer_size_(buffer_size), max_buffer_size_(max_buffer_size),
          running_(true), processing_active_(false) {}

    void start() {
        producer_thread_ = std::thread(&EncryptionLibrary::producer, this);
        consumer_thread_ = std::thread(&EncryptionLibrary::consumer, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        producer_thread_.join();
        consumer_thread_.join();
    }

private:
    void producer() {
        while (running_) {
            // Simulate data production
            std::vector<uint8_t> data(buffer_size_, 0);
            if (!RAND_bytes(data.data(), buffer_size_)) {
                std::cerr << "Error generating random data" << std::endl;
                continue;
            }

            {
                std::unique_lock<std::mutex> lock(mutex_);
                while (buffer_.size() >= max_buffer_size_) {
                    condition_.wait(lock);
                }
                buffer_.push(data);
            }
            condition_.notify_all();
        }
    }

    void consumer() {
        while (running_ || !buffer_.empty()) {
            std::vector<uint8_t> data;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                while (buffer_.empty()) {
                    if (!running_) break;
                    condition_.wait(lock);
                }
                if (buffer_.empty()) continue;
                data = buffer_.front();
                buffer_.pop();
            }

            // Simulate encryption
            std::vector<uint8_t> encrypted_data(data.size() + AES_BLOCK_SIZE, 0);
            AES_KEY key;
            AES_set_encrypt_key(reinterpret_cast<const unsigned char*>(key_material_.data()), 256, &key);
            for (size_t i = 0; i < data.size(); i += AES_BLOCK_SIZE) {
                AES_cbc_encrypt(data.data() + i, encrypted_data.data() + i, AES_BLOCK_SIZE, &key, iv_.data(), AES_ENCRYPT);
            }

            // Simulate processing
            std::this_thread::sleep_for(std::chrono::milliseconds(10));

            {
                std::unique_lock<std::mutex> lock(mutex_);
                processed_data_.push(encrypted_data);
            }
            condition_.notify_all();
        }
    }

    size_t buffer_size_;
    size_t max_buffer_size_;
    bool running_;
    bool processing_active_;
    std::thread producer_thread_;
    std::thread consumer_thread_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::vector<uint8_t>> buffer_;
    std::queue<std::vector<uint8_t>> processed_data_;
    std::vector<uint8_t> key_material_{/* 32 bytes of key material */};
    std::array<unsigned char, AES_BLOCK_SIZE> iv_{/* Initialization vector */};
};

int main() {
    EncryptionLibrary library(1024, 8 * 1024);
    library.start();

    // Simulate a shutdown after some time
    std::this_thread::sleep_for(std::chrono::seconds(5));
    library.stop();

    return 0;
}
```

