int validate_struct(PasswordStruct* pwd, ConnectionStruct* conn, CallbackFunc cb) {
    if (pwd == NULL || pwd->password == NULL || pwd->password[0] == '\0') {
        return -1; // Password is empty or NULL
    }
    if (conn != NULL && conn->title != NULL && strlen(conn->title) > 0) {
        return -2; // Connection has a title set
    }
    if (cb == NULL) {
        return -3; // Callback function is NULL
    }
    return 0; // Success
}

int main() {
    PasswordStruct pwd = { "securepassword" };
    ConnectionStruct conn = { "default" };
    CallbackFunc cb = &printf;

    int result = validate_struct(&pwd, &conn, cb);
    if (result == 0) {
        printf("Validation successful.\n");
    } else {
        printf("Validation failed with error code: %d\n", result);
    }

    return 0;
}
