// Create services
const eventService = new EventService();
const dataProcessingService = new DataProcessingService();
const alertingService = new AlertingService();
const rateLimitingService = new RateLimitingService();

// Define controllers for handling requests
class SensorDataController {
  async receiveSensorData(req, res) {
    const sensorData = req.body;
    await eventService.emitEvent(sensorData);
    res.status(200).send('Data received');
  }
}

class AlertController {
  async getAlerts(req, res) {
    const alerts = await alertingService.getLatestAlerts();
    res.json(alerts);
  }
}

// Define services for processing and handling data
class EventService {
  constructor() {
    this.client = new kafka.KafkaClient({ kafkaHost: 'kafka-broker' });
  }

  async emitEvent(data) {
    const producer = new kafka.Producer(this.client);
    producer.on('ready', () => {
      producer.send([{ topic: 'sensor_data', messages: JSON.stringify(data) }]);
    });
  }
}

class DataProcessingService {
  constructor() {
    this.redisClient = redis.createClient();
    this.dbClient = mysql.createPool({
      host: 'mysql-db',
      user: 'user',
      password: 'password',
      database: 'data'
    });
  }

  async processSensorData(data) {
    await this.redisClient.set(data.deviceId, JSON.stringify(data));
    await this.dbClient.execute('INSERT INTO sensor_data SET ?', data);
  }
}

class AlertingService {
  constructor() {
    // Load alert rules from a configuration file or database
    this.alertRules = require('./alert-rules.json');
  }

  async getLatestAlerts() {
    const alerts = [];
    for (const rule of this.alertRules) {
      // Fetch data from Redis or database based on rule
      const data = await this.redisClient.get(rule.deviceId);
      if (this.isAlertTriggered(data, rule)) {
        alerts.push({ deviceId: rule.deviceId, alertMessage: rule.message });
      }
    }
    return alerts;
  }

  isAlertTriggered(data, rule) {
    // Implement logic to determine if an alert should be triggered
    const value = JSON.parse(data)[rule.field];
    return value > rule.threshold;
  }
}

class RateLimitingService {
  constructor() {
    this.rateLimiter = new RateLimiter();
  }

  async checkRateLimit(userId, limit) {
    // Implement rate limiting logic using Redis or similar mechanism
    const currentCount = await this.redisClient.incr('rate_limit_' + userId);
    if (currentCount == 1) {
      this.redisClient.expire('rate_limit_' + userId, 60); // Set expiration time
    }
    return currentCount <= limit;
  }
}

// Create Express app and define routes
const app = express();
app.use(express.json());

const sensorDataController = new SensorDataController();
app.post('/sensor-data', rateLimitingService.checkRateLimit('user_id', 10), sensorDataController.receiveSensorData);

const alertController = new AlertController();
app.get('/alerts', alertController.getAlerts);

// Start the server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
