    {
        _httpClient = httpClient;
    }

    public async Task<WeatherData> GetCurrentWeatherAsync(string city, string apiKey)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://api.weather.com/current?city={city}&apiKey={apiKey}");
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsAsync<WeatherData>();
            }
            else
            {
                throw new Exception("Failed to retrieve weather data");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error retrieving current weather for {city}: {ex.Message}");
            // Fallback mechanism: Return default values or cached data
            return new WeatherData { Temperature = 20, Humidity = 50 };
        }
    }

    public async Task<WeatherHistory> GetHistoricalWeatherAsync(string city, string apiKey, DateTime startDate, DateTime endDate)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://api.weather.com/historical?city={city}&apiKey={apiKey}&startDate={startDate.ToString("yyyy-MM-dd")}&endDate={endDate.ToString("yyyy-MM-dd")}");
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsAsync<WeatherHistory>();
            }
            else
            {
                throw new Exception("Failed to retrieve historical weather data");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error retrieving historical weather for {city}: {ex.Message}");
            // Fallback mechanism: Return default values or cached data
            return new WeatherHistory();
        }
    }
