    private readonly ICacheService _cacheService;
    private readonly ILogger _logger;

    public XmlProcessor(HttpClient httpClient, ICacheService cacheService, ILogger logger)
    {
        _httpClient = httpClient;
        _cacheService = cacheService;
        _logger = logger;
    }

    public async Task ProcessDocumentAsync(string xmlContent, string apiUrl)
    {
        try
        {
            // Parse the XML content
            var xmlDoc = XDocument.Parse(xmlContent);

            // Validate against cached schema or fetch from API if not available
            var schemaKey = "xmlSchemaVersion1.0"; // Example schema key
            var xmlSchema = await _cacheService.GetOrFetchAsync(schemaKey, async () =>
            {
                var response = await _httpClient.GetAsync(apiUrl + "/schema");
                return await response.Content.ReadAsStringAsync();
            });

            xmlDoc.Validate(new System.Xml.Schema.XmlReaderSettings { Schemas = new System.Xml.Schema.XmlSchemaSet() { Add(System.Xml.Schema.XmlSchema.ReadText(System.IO.StreamWriter.Create(xmlSchema))) } }, null);

            // Extract business-relevant information
            var businessData = xmlDoc.Descendants("BusinessData")
                .Select(x => new
                {
                    Id = (string)x.Attribute("Id"),
                    Value = (string)x.Value
                })
                .ToList();

            // Fetch metadata from external API
            var metadataResponse = await _httpClient.GetAsync(apiUrl + "/metadata");
            var metadata = await metadataResponse.Content.ReadAsStringAsync();
            var metadataDict = JsonConvert.DeserializeObject<Dictionary<string, object>>(metadata);

            // Cache frequently accessed data
            foreach (var data in businessData)
            {
                _cacheService.Set(data.Id, data.Value);
            }

            // Log processed information
            _logger.LogInformation("Processed document with business data: {BusinessData}", string.Join(", ", businessData));
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing document");
        }
    }
}
