    private static final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private static final int MAX_RETRIES = 3;
    private static final int RETRY_DELAY = 1000; // in milliseconds

    public MoSTState loadStateObject(String configServiceUrl) {
