            if (!isValidFile(file)) {
                return null;
            }

            MoSTState state = cache.get(filePath);
            if (state != null) {
                return state;
            }

            state = deserialize(file);
            cache.putIfAbsent(filePath, state);
            startCacheInvalidationTimer(filePath);

            return state;
        } catch (Exception e) {
            logError("Failed to load state object", e);
            return null;
        }
    }

