    private boolean isValidFile(File file) {
        try {
            long fileSize = file.length();
            if (fileSize < 0 || fileSize > MAX_FILE_SIZE) {
                return false;
            }

            long lastModified = file.lastModified();
            if (System.currentTimeMillis() - lastModified > MAX_TIMESTAMP_DIFF) {
                return false;
            }

            byte[] hash = calculateHash(file);
            // Verify hash against expected value
            return true;
        } catch (IOException e) {
            logError("Failed to validate file", e);
            return false;
        }
    }

    private byte[] calculateHash(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return digest.digest();
    }

    private MoSTState deserialize(File file) throws IOException, ClassNotFoundException {
