// RealTimeMarketDataAggregator.java
package com.example.realtime.marketdata;

import io.grpc.Server;
import io.grpc.ServerBuilder;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class RealTimeMarketDataAggregator {

    public static void main(String[] args) {
        SpringApplication.run(RealTimeMarketDataAggregator.class, args);
    }

    @Bean
    public Server grpcServer() throws Exception {
        return ServerBuilder.forPort(50051)
                .addService(new MarketDataService())
                .build()
                .start();
    }
}

// MarketDataService.java
package com.example.realtime.marketdata;

import io.grpc.stub.StreamObserver;
import marketdata.MarketDataOuterClass;

public class MarketDataService extends MarketDataGrpc.MarketDataBaseImplBase {

    @Override
    public void getRealTimeData(Empty request, StreamObserver<MarketDataOuterClass.MarketData> responseObserver) {
        // Simulate fetching real-time data from various sources
        for (int i = 0; i < 100; i++) {
            MarketDataOuterClass.MarketData marketData = MarketDataOuterClass.MarketData.newBuilder()
                    .setTimestamp(System.currentTimeMillis())
                    .setTicker("AAPL")
                    .setPrice(150.75)
                    .setVolume(1000 + i)
                    .build();
            responseObserver.onNext(marketData);
        }
        responseObserver.onCompleted();
    }
}

// application.properties
server.port=8080

# Add other configurations as needed
