import asyncio
from abc import ABC, abstractmethod
from collections import deque
from concurrent.futures import ThreadPoolExecutor
import logging
import queue

class Transaction:
    def __init__(self, id, amount, source):
        self.id = id
        self.amount = amount
        self.source = source

class MarketDataAPI(ABC):
    @abstractmethod
    async def get_real_time_data(self, symbol: str) -> dict:
        pass

class ComplianceEngine(ABC):
    @abstractmethod
    async def validate_transaction(self, transaction: Transaction) -> bool:
        pass

class Database(ABC):
    @abstractmethod
    async def store_transaction(self, transaction: Transaction) -> None:
        pass

class BatchTransactionProcessor:
    def __init__(self, market_data_api: MarketDataAPI, compliance_engine: ComplianceEngine, database: Database, max_workers=10, cache_size=1000):
        self.market_data_api = market_data_api
        self.compliance_engine = compliance_engine
        self.database = database
        self.executor = ThreadPoolExecutor(max_workers=max_workers)
        self.transaction_queue = queue.Queue()
        self.cache = deque(maxlen=cache_size)
        self.error_count = 0

    async def process_transaction(self, transaction: Transaction):
        try:
            real_time_data = await self.fetch_real_time_data(transaction.source)
            if not self.compliance_engine.validate_transaction(transaction):
                logging.warning(f"Transaction {transaction.id} failed compliance check.")
                return False
            await self.database.store_transaction(transaction)
            return True
        except Exception as e:
            logging.error(f"Error processing transaction {transaction.id}: {e}")
            self.error_count += 1
            return False

    async def fetch_real_time_data(self, symbol: str):
        if symbol in self.cache:
            return self.cache[symbol]
        else:
            data = await self.market_data_api.get_real_time_data(symbol)
            self.cache.append((symbol, data))
            return data

    async def handle_batch(self, batch: list[Transaction]):
        tasks = [self.process_transaction(tx) for tx in batch]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        for result in results:
            if isinstance(result, Exception):
                logging.error(f"Unhandled exception during processing: {result}")

    async def monitor_performance(self):
        while True:
            # Implement performance monitoring logic here
            await asyncio.sleep(60)

    def start_processing(self):
        loop = asyncio.get_event_loop()
        loop.create_task(self.monitor_performance())
        try:
            while True:
                batch = [self.transaction_queue.get() for _ in range(10)]  # Adjust batch size as needed
                loop.run_until_complete(self.handle_batch(batch))
        except KeyboardInterrupt:
            pass

# Example usage
class MockMarketDataAPI(MarketDataAPI):
    async def get_real_time_data(self, symbol: str) -> dict:
        return {"price": 150.75}

class MockComplianceEngine(ComplianceEngine):
    async def validate_transaction(self, transaction: Transaction) -> bool:
        return True

class MockDatabase(Database):
    async def store_transaction(self, transaction: Transaction) -> None:
        print(f"Transaction {transaction.id} stored")

if __name__ == "__main__":
    market_data_api = MockMarketDataAPI()
    compliance_engine = MockComplianceEngine()
    database = MockDatabase()
    processor = BatchTransactionProcessor(market_data_api, compliance_engine, database)
    processor.start_processing()
