# Import necessary libraries
import os
from flask import Flask, request, jsonify
from redis import Redis
from rq import Queue, Worker, get_current_job
from rq.decorators import job

app = Flask(__name__)
redis_conn = Redis(host='localhost', port=6379)
queue = Queue(connection=redis_conn)

# Define a function to process logs
@job(queue)
def process_log(log_entry):
    # Simulate log processing logic here
    print(f"Processing log entry: {log_entry}")

# Route to receive and enqueue logs
@app.route('/log', methods=['POST'])
def receive_log():
    log_entry = request.json.get('log')
    if not log_entry:
        return jsonify({"error": "Log entry is missing"}), 400

    # Enqueue the log processing task
    job_id = process_log.delay(log_entry)

    return jsonify({"job_id": str(job_id)}), 202

# Route to get status of a log processing job
@app.route('/log/<job_id>', methods=['GET'])
def get_job_status(job_id):
    try:
        job = Queue(connection=redis_conn).fetch_job(job_id)
        if job.is_finished:
            return jsonify({"status": "Completed", "result": job.result}), 200
        elif job.is_failed:
            return jsonify({"status": "Failed", "error": job.exc_info}), 500
        else:
            return jsonify({"status": "Pending"}), 202
    except Exception as e:
        return jsonify({"error": str(e)}), 404

# Start the Flask application
if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

