let moduleCache = {};

// Load a module asynchronously with caching and retry mechanism
async function loadModule(moduleName, retries = 3) {
  if (moduleCache[moduleName]) return moduleCache[moduleName];

  for (let i = 0; i < retries; i++) {
    try {
      const modulePath = path.resolve(__dirname, 'modules', `${moduleName}.js`);
      const module = await ModuleLoader.load(modulePath);
      moduleCache[moduleName] = module;
      return module;
    } catch (error) {
      if (i === retries - 1) throw error;
      // Retry after a short delay
      await new Promise(resolve => setTimeout(resolve, 500));
    }
  }
}

