import asyncio
from dataclasses import dataclass
from typing import List

@dataclass
class Transaction:
    product_id: str
    quantity: int
    timestamp: float

class InventoryService:
    def __init__(self):
        self.inventory = {}

    async def process_transaction(self, transaction: Transaction):
        if transaction.product_id in self.inventory:
            self.inventory[transaction.product_id] -= transaction.quantity
            if self.inventory[transaction.product_id] < 0:
                raise ValueError("Insufficient stock")
        else:
            raise KeyError("Product not found")

class Warehouse:
    def __init__(self, location: str):
        self.location = location
        self.service = InventoryService()

    async def handle_transaction(self, transaction: Transaction):
        try:
            await self.service.process_transaction(transaction)
        except (ValueError, KeyError) as e:
            print(f"Failed to process transaction at {self.location}: {e}")

class ECommercePlatform:
    def __init__(self, warehouses: List[Warehouse]):
        self.warehouses = warehouses

    async def dispatch_transaction(self, transaction: Transaction):
        tasks = [warehouse.handle_transaction(transaction) for warehouse in self.warehouses]
        await asyncio.gather(*tasks)

# Example usage
warehouses = [
    Warehouse("New York"),
    Warehouse("London"),
    Warehouse("Tokyo")
]

platform = ECommercePlatform(warehouses)
transaction = Transaction("P123", 5, time.time())
await platform.dispatch_transaction(transaction)
