import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class RemoteChannelManager {
    private ServerSocketChannel serverChannel;
    private Selector selector;
    private int maxConnections;
    private ConnectionPool connectionPool;

    public RemoteChannelManager(int port, int maxConnections) throws IOException {
        this.maxConnections = maxConnections;
        this.selector = Selector.open();
        this.serverChannel = ServerSocketChannel.open();
        this.serverChannel.configureBlocking(false);
        serverChannel.socket().bind(new InetSocketAddress(port));
        serverChannel.register(selector, SelectionKey.OP_ACCEPT);

        this.connectionPool = new ConnectionPool(maxConnections);

        // Initialize connection pool
        for (int i = 0; i < maxConnections; i++) {
            SocketChannel channel = SocketChannel.open();
            channel.configureBlocking(false);
            connectionPool.add(channel);
        }
    }

    public void start() throws IOException {
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> iter = selectedKeys.iterator();
            while (iter.hasNext()) {
                SelectionKey key = iter.next();

                if (!key.isValid()) {
                    continue;
                }

                if (key.isAcceptable()) {
                    accept(key);
                } else if (key.isReadable()) {
                    read(key);
                } else if (key.isWritable()) {
                    write(key);
                }

                iter.remove();
            }
        }
    }

    private void accept(SelectionKey key) throws IOException {
        ServerSocketChannel serverChannel = (ServerSocketChannel) key.channel();
        SocketChannel channel = serverChannel.accept();
        channel.configureBlocking(false);

        if (connectionPool.isAvailable()) {
            connectionPool.add(channel);
            channel.register(selector, SelectionKey.OP_READ);
        } else {
