        return null;
    }

    public void close() throws IOException {
        selector.close();
        serverChannel.close();
        connectionPool.close();
    }

    private static class ConnectionPool {
        private int maxSize;
        private SocketChannel[] pool;
        private int availableCount;

        public ConnectionPool(int maxSize) {
            this.maxSize = maxSize;
            this.pool = new SocketChannel[maxSize];
            this.availableCount = maxSize;
        }

        public boolean isAvailable() {
            return availableCount > 0;
        }

        public void add(SocketChannel channel) {
            pool[--availableCount] = channel;
        }

        public SocketChannel get() throws InterruptedException {
