            for (int i = 0; i < maxSize; i++) {
                if (pool[i] == channel) {
                    index = i;
                    break;
                }
            }
            if (index != -1) {
                availableCount++;
                pool[index] = null;
            } else {
                // Handle unexpected state
            }
        }

        public void close() throws IOException {
            for (SocketChannel channel : pool) {
                if (channel != null) {
                    channel.close();
                }
            }
        }
    }
}
