typedef struct {
    char token[128];
    time_t expiration;
} SecureToken;

SecureToken token_cache[CACHE_SIZE];

int add_token_to_cache(const char *user_id, const char *token, time_t expiration) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (token_cache[i].expiration == 0) {
            strcpy(token_cache[i].token, token);
            token_cache[i].expiration = expiration;
            return 1;
        }
    }
    return 0;
}

SecureToken *get_token_from_cache(const char *user_id) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(token_cache[i].token, user_id) == 0 && token_cache[i].expiration > time(NULL)) {
            return &token_cache[i];
        }
    }
    return NULL;
}

void remove_token_from_cache(const char *user_id) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(token_cache[i].token, user_id) == 0) {
            token_cache[i].expiration = 0;
            break;
        }
    }
}

