func NewJWTService(config Config) (*JWTService, error) {
	jwtService := &JWTService{
		logLevel: config.LogLevel,
		client:   resty.New(),
	}

	for _, caConfig := range config.CAs {
		ca, err := NewCA(caConfig)
		if err != nil {
			return nil, err
		}
		jwtService.cas = append(jwtService.cas, ca)
	}

	jwtService.cache = NewLRUCache(config.CacheSize)

	return jwtService, nil
}

type CA struct {
