		size:  size,
		cache: make(map[string]interface{}),
	}
	return lru
}

func (l *LRUCache) Get(key string) (interface{}, bool) {
	if val, exists := l.cache[key]; exists {
		return val, true
	}
	return nil, false
}

func (l *LRUCache) Set(key string, value interface{}) {
	if len(l.cache) >= l.size {
		l.evict()
	}
	l.cache[key] = value
}

