// Define transaction structure
typedef struct {
    int user_id;
    double value;
    time_t timestamp;
} Transaction;

// Define metrics structure
typedef struct {
    double max_weighted_sum[1000]; // Assuming max 1000 users
    int total_valid_transactions;
    double average_transaction_value;
} Metrics;

// Global variables
Metrics metrics = {0};
pthread_mutex_t metrics_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to filter transactions
int is_valid_transaction(Transaction *tx) {
    time_t current_time = time(NULL);
    return difftime(current_time, tx->timestamp) <= 300 && // Age check (5 minutes)
           metrics.max_weighted_sum[tx->user_id] < 200; // Frequency and Weighted Sum check
}

// Function to process transactions
void *process_transaction(void *arg) {
    Transaction *tx = (Transaction *)arg;
    if (is_valid_transaction(tx)) {
        pthread_mutex_lock(&metrics_mutex);
        metrics.max_weighted_sum[tx->user_id] += tx->value;
        metrics.total_valid_transactions++;
        metrics.average_transaction_value = (double)metrics.total_valid_transactions / metrics.total_valid_transactions;
        pthread_mutex_unlock(&metrics_mutex);

        // Persist to database and notify
        persist_to_database(tx);
        if (tx->value > CONFIGURABLE_THRESHOLD) {
            notify_monitoring_service(tx);
        }
    }
    free(tx); // Clean up transaction memory
    return NULL;
}

