    int thread_count = 0;

    while (1) {
        // Simulate receiving a new transaction
        Transaction *tx = (Transaction *)malloc(sizeof(Transaction));
        tx->user_id = rand() % 1000;
        tx->value = rand() % 1000 / 10.0;
        tx->timestamp = time(NULL);

        if (pthread_create(&threads[thread_count], NULL, process_transaction, (void *)tx) != 0) {
            perror("Failed to create thread");
            break;
        }
        thread_count++;

        // Join threads if necessary
        if (thread_count >= 1000) {
            for (int i = 0; i < thread_count; i++) {
                pthread_join(threads[i], NULL);
            }
            thread_count = 0;
        }

        // Simulate sleep to mimic real-time streaming
        usleep(1000);
    }

    return 0;
}
