class LogProcessor {
public:
    using DataStream = std::string;
    using ProcessingStage = std::function<void(const DataStream&)>;

    void addProcessingStage(ProcessingStage stage) {
        stages.push_back(stage);
    }

    void processLogData(const DataStream& data) {
        for (auto& stage : stages) {
            stage(data);
        }
    }

private:
    std::vector<ProcessingStage> stages;
};

class KafkaSource {
public:
    using DataCallback = std::function<void(const LogProcessor::DataStream&)>;

    void subscribe(DataCallback callback) {
        callback_ = callback;
    }

    void startConsuming() {
        running.store(true);
        consumeThread = std::thread([this]() {
            while (running.load()) {
                // Simulate Kafka messages
                auto message = "Log message";
                if (callback_) {
                    callback_(message);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        });
    }

    void stopConsuming() {
        running.store(false);
        if (consumeThread.joinable()) {
            consumeThread.join();
        }
    }

private:
    std::thread consumeThread;
    std::atomic<bool> running{false};
    DataCallback callback_;
};

class HTTPSource {
public:
    using DataCallback = std::function<void(const LogProcessor::DataStream&)>;

    void setURL(const std::string& url) {
        this->url = url;
    }

    void startConsuming() {
        running.store(true);
        consumeThread = std::thread([this]() {
            while (running.load()) {
                // Simulate HTTP requests
                auto message = "Log message from HTTP";
                if (callback_) {
                    callback_(message);
                }
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });
    }

    void stopConsuming() {
        running.store(false);
        if (consumeThread.joinable()) {
            consumeThread.join();
        }
    }

private:
    std::thread consumeThread;
    std::atomic<bool> running{false};
    std::string url;
};

class TCPSource {
public:
    using DataCallback = std::function<void(const LogProcessor::DataStream&)>;

    void startConsuming(int port) {
        running.store(true);
        consumeThread = std::thread([this, port]() {
            while (running.load()) {
                // Simulate TCP connections
                auto message = "Log message from TCP";
                if (callback_) {
                    callback_(message);
                }
                std::this_thread::sleep_for(std::chrono::seconds(2));
            }
        });
    }

    void stopConsuming() {
        running.store(false);
        if (consumeThread.joinable()) {
            consumeThread.join();
        }
    }

private:
    std::thread consumeThread;
    std::atomic<bool> running{false};
};

int main() {
    LogProcessor processor;

    KafkaSource kafkaSource;
    kafkaSource.subscribe([&processor](const LogProcessor::DataStream& data) {
        processor.processLogData(data);
    });
    kafkaSource.startConsuming();

    HTTPSource httpSource;
    httpSource.setURL("http://example.com/logs");
    httpSource.subscribe([&processor](const LogProcessor::DataStream& data) {
        processor.processLogData(data);
    });
    httpSource.startConsuming();

    TCPSource tcpSource;
    tcpSource.startConsuming(12345);
    tcpSource.subscribe([&processor](const LogProcessor::DataStream& data) {
        processor.processLogData(data);
    });

    // Simulate running for a while
    std::this_thread::sleep_for(std::chrono::minutes(5));

    kafkaSource.stopConsuming();
    httpSource.stopConsuming();
    tcpSource.stopConsuming();

    return 0;
}
