#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>

class RealTimeDataAggregator {
public:
    RealTimeDataAggregator(size_t numThreads) : stop(false), workerCount(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                for (;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~RealTimeDataAggregator() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.emplace([task]() { (*task)(); });
        }
        condition.notify_one();
        return res;
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
    size_t workerCount;
};

// Example usage
int main() {
    RealTimeDataAggregator aggregator(4);

    auto result = aggregator.enqueue([](int a, int b) -> int { return a + b; }, 3, 5);
    std::cout << "Result: " << result.get() << std::endl;

    return 0;
}
```

This code defines a `RealTimeDataAggregator` class that uses a thread pool to manage concurrent task execution. The class provides methods for enqueuing tasks and retrieving their results asynchronously. This example demonstrates how to use the `enqueue` method to add a simple addition task to the thread pool and wait for its completion.

This implementation is a basic starting point and can be extended with additional features such as error handling, resource management, and more sophisticated task scheduling mechanisms to support real-time data aggregation and processing in an enterprise environment.']

