// Define data structures for metrics and logs
struct Metric {
    std::string name;
    double value;
};

struct LogLine {
    std::string source;
    std::vector<Metric> metrics;
};

// Thread-safe queue for log lines
class ThreadSafeQueue {
private:
    std::queue<LogLine> queue;
    mutable std::mutex mutex;
    std::condition_variable condition;

public:
    void push(const LogLine& item) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(item);
        condition.notify_one();
    }

    bool try_pop(LogLine& item) {
        std::unique_lock<std::mutex> lock(mutex);
        if (queue.empty()) {
            return false;
        }
        item = queue.front();
        queue.pop();
        return true;
    }

    void wait_and_pop(LogLine& item) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this]{ return !queue.empty(); });
        item = queue.front();
        queue.pop();
    }
};

// Worker thread function
void worker(ThreadSafeQueue& queue, int id) {
    while (true) {
        LogLine line;
        if (queue.try_pop(line)) {
            // Process the log line here
            std::cout << "Worker " << id << " processing log from " << line.source << std::endl;
        } else {
            break;
        }
    }
}

// Main function
int main() {
    ThreadSafeQueue queue;

    // Start worker threads
    const int num_workers = 4;
    std::vector<std::thread> workers(num_workers);
    for (int i = 0; i < num_workers; ++i) {
        workers[i] = std::thread(worker, std::ref(queue), i + 1);
    }

    // Simulate log ingestion
    for (int i = 0; i < 10; ++i) {
        LogLine line;
        line.source = "Source" + std::to_string(i % num_workers + 1);
        line.metrics.push_back({"Metric1", static_cast<double>(i)});
        queue.push(line);
    }

    // Wait for worker threads to finish
    for (auto& w : workers) {
        w.join();

    return 0;
}
