    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void processFile(String inputFile, String outputFile) {
        executorService.submit(() -> {
            try {
                // Simulate file conversion
                convertFile(inputFile, outputFile);
            } catch (Exception e) {
                handleConversionError(e, inputFile, outputFile);
            }
        });
    }

    private void convertFile(String inputFile, String outputFile) throws Exception {
        // Placeholder for actual file conversion logic
        System.out.println("Converting " + inputFile + " to " + outputFile);
        // Simulate a 5-second delay
        Thread.sleep(5000);
    }

    private void handleConversionError(Exception e, String inputFile, String outputFile) {
        int retryCount = 0;
        final int maxRetries = 3;
        long delay = 1000; // Initial delay in milliseconds

        while (retryCount < maxRetries) {
            try {
                convertFile(inputFile, outputFile);
                break;
            } catch (Exception ex) {
                retryCount++;
                if (retryCount >= maxRetries) {
                    System.err.println("Failed to convert " + inputFile + " after " + maxRetries + " attempts");
                    throw new RuntimeException(e);
                }
                try {
                    Thread.sleep(delay);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                delay *= 2; // Exponential backoff
            }
        }
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        FileConversionApplication app = new FileConversionApplication();

        // Simulate processing multiple files
        for (int i = 0; i < 20; i++) {
            String inputFile = "file" + i + ".txt";
            String outputFile = "converted_" + i + ".pdf";
            app.processFile(inputFile, outputFile);
        }

        try {
            app.shutdown();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
```

