// Singleton class for managing the payment processing system
class PaymentProcessingSystem {
private:
    static PaymentProcessingSystem* instance;
    PaymentVerificationService verifier;
    TransactionLog logger;
    PaymentGateway gateway;

    std::queue<std::string> transactionQueue;
    std::condition_variable cv;
    std::mutex queueMutex;
    std::atomic<bool> stopProcessing{false};

    PaymentProcessingSystem() {}

public:
    static PaymentProcessingSystem* getInstance() {
        if (instance == nullptr) {
            instance = new PaymentProcessingSystem();
        }
        return instance;
    }

    void enqueueTransaction(const std::string& transactionId) {
        std::lock_guard<std::mutex> lock(queueMutex);
        transactionQueue.push(transactionId);
        cv.notify_one();
    }

    void processTransactions() {
        while (!stopProcessing) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !transactionQueue.empty() || stopProcessing; });

            if (stopProcessing && transactionQueue.empty()) {
                break;
            }

            std::string transactionId = transactionQueue.front();
            transactionQueue.pop();

            lock.unlock();

            processPaymentTransaction(transactionId);
        }
    }

    void stop() {
        stopProcessing.store(true);
        cv.notify_all();
    }

private:
    void processPaymentTransaction(const std::string& transactionId) {
        // Cardholder Verification
        if (verifier.validateCard("1234-5678-9012-3456")) {
            // Transaction Logging
            logger.logTransaction(transactionId, "Card verification successful");

            // API Integration
            if (gateway.processPayment(transactionId, 100.0)) {
                logger.logTransaction(transactionId, "Payment processed successfully");
            } else {
                logger.logTransaction(transactionId, "Payment processing failed");
            }
        } else {
            logger.logTransaction(transactionId, "Card verification failed");
        }
    }
};

// Global instance for thread-safe access
PaymentProcessingSystem* PaymentProcessingSystem::instance = nullptr;

int main() {
    // Create multiple threads to simulate concurrent transaction processing
    std::vector<std::thread> workers;
    for (int i = 0; i < 5; ++i) {
        workers.emplace_back(&PaymentProcessingSystem::getInstance()->processTransactions);
    }

    // Enqueue some transactions
    PaymentProcessingSystem::getInstance()->enqueueTransaction("TXN12345");
    PaymentProcessingSystem::getInstance()->enqueueTransaction("TXN67890");

    // Wait for a while to simulate processing time
    std::this_thread::sleep_for(std::chrono::seconds(10));

    // Stop the processing system
    PaymentProcessingSystem::getInstance()->stop();

    // Join all worker threads
    for (auto& t : workers) {
        t.join();
    }

    return 0;
}
