using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class CreditCardService : ICreditCardService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<CreditCardService> _logger;
    private readonly ConcurrentDictionary<string, AuthenticationToken> _authTokens;

    public CreditCardService(HttpClient httpClient, ILogger<CreditCardService> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
        _authTokens = new ConcurrentDictionary<string, AuthenticationToken>();
    }

    public async Task<TransactionResponse> ProcessCreditCardAsync(CreditCardRequest request, string authenticationMethod, string transactionType)
    {
        var authToken = await GetAuthenticationToken(authenticationMethod, transactionType);
        _httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", authToken.Token);

        try
        {
            var response = await _httpClient.PostAsJsonAsync("/api/transaction/process", request);
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsAsync<TransactionResponse>();
            }
            else
            {
                _logger.LogError($"Transaction failed with status code: {response.StatusCode}");
                throw new InvalidOperationException("Failed to process transaction");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while processing the transaction.");
            throw;
        }
    }

    private async Task<AuthenticationToken> GetAuthenticationToken(string authenticationMethod, string transactionType)
    {
        if (!_authTokens.TryGetValue($"{authenticationMethod}_{transactionType}", out var token))
        {
            // Logic to fetch and cache the appropriate authentication token
            token = await FetchAuthTokenFromApi(authenticationMethod, transactionType);
            _authTokens.TryAdd($"{authenticationMethod}_{transactionType}", token);
        }
        return token;
    }

    private async Task<AuthenticationToken> FetchAuthTokenFromApi(string authenticationMethod, string transactionType)
    {
        // Simulated API call to fetch an authentication token
        await Task.Delay(100); // Simulate network delay
        var authToken = new AuthenticationToken { Token = "fake_token", ExpiresAt = DateTime.UtcNow.AddMinutes(5) };
        return authToken;
    }
}

public class CreditCardRequest
{
    public string CardNumber { get; set; }
    public decimal Amount { get; set; }
    // Other properties as needed
}

public class TransactionResponse
{
    public bool Success { get; set; }
    public string Message { get; set; }
    // Other properties as needed
}

public class AuthenticationToken
{
    public string Token { get; set; }
    public DateTime ExpiresAt { get; set; }
}
