using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

namespace HashLibrary
{
    public class HashGenerator
    {
        private readonly ILogger<HashGenerator> _logger;
        private readonly string _hashAlgorithm;

        public HashGenerator(ILogger<HashGenerator> logger, string hashAlgorithm)
        {
            _logger = logger;
            _hashAlgorithm = hashAlgorithm;
        }

        public string GenerateHash(string input)
        {
            byte[] data = Encoding.UTF8.GetBytes(input);
            using (var algorithm = CreateHashAlgorithm(_hashAlgorithm))
            {
                var result = algorithm.ComputeHash(data);
                return BitConverter.ToString(result).Replace("-", "").ToLower();
            }
        }

        private HashAlgorithm CreateHashAlgorithm(string algorithmName)
        {
            switch (algorithmName.ToLower())
            {
                case "md5":
                    return MD5.Create();
                case "sha1":
                    return SHA1.Create();
                case "sha256":
                    return SHA256.Create();
                case "sha512":
                    return SHA512.Create();
                case "blake2":
                    return Blake2b.Create();
                case "keccak":
                    return new Keccak(256);
                default:
                    throw new ArgumentException("Unsupported hash algorithm");
            }
        }

        public void LogHashGenerationEvent(string inputData, string algorithmType, bool success)
        {
            _logger.LogInformation("Hash generation event - Input: {InputData}, Algorithm: {AlgorithmType}, Success: {Success}", inputData, algorithmType, success);
        }
    }

    public class Program
    {
        public static void Main()
        {
            var loggerFactory = LoggerFactory.Create(builder =>
            {
                builder.AddConsole();
            });

            using (var logger = loggerFactory.CreateLogger<Program>())
            {
                var hashGenerator = new HashGenerator(logger, "SHA256");
                string input = "Hello, world!";
                string hash = hashGenerator.GenerateHash(input);
                hashGenerator.LogHashGenerationEvent(input, "SHA256", true);

                logger.LogInformation("Generated hash: {Hash}", hash);
            }
        }
    }
}
```

