import Microsoft.AspNetCore.Identity;
using System.Security.Cryptography;
using System.Text;

public class UserValidator : IUserValidator<ApplicationUser>
{
    private readonly IdentityOptions _optionsAccessor;
    private readonly SignInManager<ApplicationUser> _signInManager;

    public UserValidator(IdentityOptions optionsAccessor, SignInManager<ApplicationUser> signInManager)
    {
        _optionsAccessor = optionsAccessor;
        _signInManager = signInManager;
    }

    public async Task<IdentityResult> ValidateAsync(UserManager<ApplicationUser> manager, ApplicationUser user)
    {
        var result = new IdentityResult();

        if (user.PasswordHash == null)
        {
            result.Errors.Add(new IdentityError { Code = "PasswordMissing", Description = "You must set a password." });
        }

        // Check password length
        if (_optionsAccessor.User.Requirements.Password.RequiredLength > 0 &&
            user.Password.Length < _optionsAccessor.User.Requirements.Password.RequiredLength)
        {
            result.Errors.Add(new IdentityError { Code = "PasswordTooShort", Description = $"Passwords must be at least {_optionsAccessor.User.Requirements.Password.RequiredLength} characters." });
        }

        // Check password complexity
        if (_optionsAccessor.User.Requirements.Password.RequireDigit ||
            _optionsAccessor.User.Requirements.Password.RequireLowercase ||
            _optionsAccessor.User.Requirements.Password.RequireNonLetterOrDigit ||
            _optionsAccessor.User.Requirements.Password.RequireUppercase)
        {
            var hasDigit = user.Password.Any(char.IsDigit);
            var hasLowercase = user.Password.Any(char.IsLower);
            var hasNonLetterOrDigit = user.Password.Any(c => !char.IsLetterOrDigit(c));
            var hasUppercase = user.Password.Any(char.IsUpper);

            if (!_optionsAccessor.User.Requirements.Password.RequireDigit || !hasDigit)
                result.Errors.Add(new IdentityError { Code = "PasswordRequiresDigit", Description = $"Passwords must contain at least one digit." });

            if (!_optionsAccessor.User.Requirements.Password.RequireLowercase || !hasLowercase)
                result.Errors.Add(new IdentityError { Code = "PasswordRequiresLowercase", Description = $"Passwords must contain at least one lowercase letter." });

            if (!_optionsAccessor.User.Requirements.Password.RequireNonLetterOrDigit || !hasNonLetterOrDigit)
                result.Errors.Add(new IdentityError { Code = "PasswordRequiresNonLetterOrDigit", Description = $"Passwords must contain at least one non-letter or digit character." });

            if (!_optionsAccessor.User.Requirements.Password.RequireUppercase || !hasUppercase)
                result.Errors.Add(new IdentityError { Code = "PasswordRequiresUppercase", Description = $"Passwords must contain at least one uppercase letter." });
        }

        // Check user lockout
        var isLockedOut = await _signInManager.IsUserLockoutEnabledAsync(user);
        if (isLockedOut)
        {
            result.Errors.Add(new IdentityError { Code = "UserIsLockedOut", Description = "This account has been locked out." });
        }

        return result;
    }
}
