use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use std::time::{Duration, Instant};
use rand::Rng;

mod payment_gateway {
    use super::*;

    pub async fn process_payment(amount: f64) -> bool {
        // Simulate payment processing with rate limiting
        let delay = Duration::from_secs_f32(rand::thread_rng().gen_range(0.1..=0.5));
        tokio::time::sleep(delay).await;
        true
    }
}

mod cache {
    use super::*;
    use tokio::sync::Mutex;

    pub struct RedisCache {
        store: RwLock<HashMap<String, String>>,
    }

    impl RedisCache {
        pub fn new() -> Self {
            RedisCache {
                store: RwLock::new(HashMap::new()),
            }
        }

        pub async fn get(&self, key: &str) -> Option<String> {
            let store = self.store.read().await;
            store.get(key).cloned()
        }

        pub async fn set(&self, key: String, value: String) {
            let mut store = self.store.write().await;
            store.insert(key, value);
        }
    }
}

mod transaction_service {
    use super::*;

    pub struct TransactionService {
        cache: RedisCache,
    }

    impl TransactionService {
        pub fn new() -> Self {
            TransactionService {
                cache: RedisCache::new(),
            }
        }

        pub async fn process_transaction(&self, amount: f64) -> bool {
            if let Some(cached_result) = self.cache.get("transaction_result").await {
                return cached_result.parse::<bool>().unwrap();
            }

            let result = payment_gateway::process_payment(amount).await;
            self.cache.set("transaction_result".to_string(), result.to_string()).await;
            result
        }
    }
}

#[tokio::main]
async fn main() {
    let (tx, mut rx) = mpsc::channel(100);
    let transaction_service = TransactionService::new();

    for _ in 0..5000 {
        let tx = tx.clone();
        let transaction_service = transaction_service.clone();
        tokio::spawn(async move {
            if let Err(_) = tx.send(transaction_service.process_transaction(10.0).await).await {
                eprintln!("Failed to send message");
            }
        });
    }

    while let Some(result) = rx.recv().await {
        println!("Transaction result: {}", result);
    }
}
```

