#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_ATTEMPTS 5

typedef struct {
    void* data;
    size_t size;
} Buffer;

Buffer create_buffer(size_t size) {
    Buffer buffer;
    buffer.data = malloc(size);
    if (buffer.data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    buffer.size = size;
    return buffer;
}

void destroy_buffer(Buffer* buffer) {
    free(buffer->data);
    buffer->data = NULL;
    buffer->size = 0;
}

Buffer copy_buffer(Buffer* src, size_t num_bytes) {
    if (num_bytes > src->size) {
        fprintf(stderr, "Attempted to copy more bytes than available\n");
        exit(1);
    }
    Buffer dest = create_buffer(num_bytes);
    memcpy(dest.data, src->data, num_bytes);
    return dest;
}

// Mock function for fetching data from a key-value store
int fetch_data_from_store(const char* key, void** data, size_t* size) {
    // Simulate successful and unsuccessful attempts
    static int attempt = 0;
    if (attempt++ < MAX_ATTEMPTS - 1) {
        return -1; // Simulate failure
    }
    *data = malloc(1024); // Allocate memory for data
    if (*data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    strcpy(*data, "Sample Data");
    *size = strlen(*data);
    return 0;
}

// Asynchronous fetchData function with exponential backoff and retry strategy
void* fetch_data(void* args) {
    const char* key = (const char*)args;
    void* data = NULL;
    size_t size = 0;
    int attempts = 0;
    while (fetch_data_from_store(key, &data, &size) != 0 && attempts < MAX_ATTEMPTS) {
        usleep(1 << attempts); // Exponential backoff
        attempts++;
    }
    if (attempts == MAX_ATTEMPTS) {
        fprintf(stderr, "Failed to fetch data after %d attempts\n", MAX_ATTEMPTS);
        return NULL;
    }
    Buffer buffer = copy_buffer((Buffer*)data, size);
    free(data); // Free allocated memory
    return (void*)buffer.data;
}

int main() {
    const char* key = "example_key";
    pthread_t thread;
    if (pthread_create(&thread, NULL, fetch_data, (void*)key) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(1);
    }
    pthread_join(thread, NULL);

    return 0;
}
