#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTS 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t count;
    size_t allocated;
    size_t max_allocated;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->count = 0;
    mp->allocated = initial_size;
    mp->max_allocated = initial_size;
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_struct(MemoryPool *mp) {
    if (mp->count == mp->allocated) {
        size_t new_size = mp->max_allocated * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(mp->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            return NULL; // Handle allocation failure
        }
        mp->pool = new_pool;
        mp->allocated = new_size;
        mp->max_allocated = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = &mp->pool[mp->count];
    mp->count++;
    return ptr;
}

void free_struct(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *ptr) {
    if (ptr >= mp->pool && ptr < &mp->pool[mp->count]) {
        memmove(ptr, ptr + 1, (mp->count - (ptr - mp->pool) - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        mp->count--;
    }
}

void processNfapiCrcIndications(MemoryPool *mp, int N) {
    srand(time(NULL)); // Initialize random seed
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *indication = allocate_struct(mp);
        if (!indication) {
            // Handle allocation failure
            continue;
        }
        indication->RX_UE_INFORMATION_TAG = rand();
        indication->RNTI = rand();
        indication->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG
    }
}

int main() {
    MemoryPool *mp = create_memory_pool(100); // Initial pool size of 100 structures
    processNfapiCrcIndications(mp, 500); // Process up to 500 indications
    destroy_memory_pool(mp);
    return 0;
}
