#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCTURES 1000000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* memory_pool = NULL;
size_t pool_size = 0;
size_t pool_capacity = 0;

void initialize_memory_pool(size_t capacity) {
    if (capacity > MAX_STRUCTURES) {
        fprintf(stderr, "Memory pool capacity exceeds maximum limit.\n");
        exit(EXIT_FAILURE);
    }
    pool_capacity = capacity;
    memory_pool = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool.\n");
        exit(EXIT_FAILURE);
    }
}

void* get_memory_from_pool() {
    if (pool_size >= pool_capacity) {
        fprintf(stderr, "Memory pool is full.\n");
        return NULL;
    }
    return &memory_pool[pool_size++];
}

NFAPI_CRC_INDICATION_PDU_T* populateCrcIndications(size_t N) {
    initialize_memory_pool(N);
    NFAPI_CRC_INDICATION_PDU_T* results = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!results) {
        fprintf(stderr, "Failed to allocate memory for results.\n");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_memory_from_pool();
        if (!pdu) {
            fprintf(stderr, "Failed to allocate memory from pool.\n");
            free(results);
            return NULL;
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        pdu->RNTI = rand() % UINT32_MAX;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Random flag
        results[i] = *pdu;
    }

    return results;
}

void cleanup_memory_pool() {
    free(memory_pool);
    memory_pool = NULL;
    pool_size = 0;
    pool_capacity = 0;
}

void cleanup_results(NFAPI_CRC_INDICATION_PDU_T* results, size_t N) {
    free(results);
}

int main() {
    size_t N = 1000;
    NFAPI_CRC_INDICATION_PDU_T* indications = populateCrcIndications(N);
    if (indications) {
        // Process the indications
        cleanup_results(indications, N);
    }
    cleanup_memory_pool();
    return 0;
}
