    size_t plaintext_len = strlen((const char*)plaintext);
    unsigned char ciphertext[128];
    size_t ciphertext_len = sizeof(ciphertext);

    if (perform_encryption(crypto_service, plaintext, plaintext_len, ciphertext, &ciphertext_len, CRYPTO_AES) != 0) {
        log_error("Failed to encrypt transaction data");
        destroy_crypto_service(crypto_service);
        return EXIT_FAILURE;
    }

    unsigned char decrypted_text[128];
    size_t decrypted_text_len = sizeof(decrypted_text);

    if (perform_decryption(crypto_service, ciphertext, ciphertext_len, decrypted_text, &decrypted_text_len, CRYPTO_AES) != 0) {
        log_error("Failed to decrypt transaction data");
        destroy_crypto_service(crypto_service);
        return EXIT_FAILURE;
    }

    printf("Decrypted text: %.*s\n", (int)decrypted_text_len, decrypted_text);

    handle_transaction(crypto_service, plaintext, plaintext_len);

    destroy_crypto_service(crypto_service);
    return EXIT_SUCCESS;
}
