// payment_service.rs
mod payment_gateway_one;
mod payment_gateway_two;

use std::sync::{Arc, Mutex};
use tokio::task;

struct PaymentService {
    gateway_one: payment_gateway_one::PaymentGatewayOne,
    gateway_two: payment_gateway_two::PaymentGatewayTwo,
}

impl PaymentService {
    fn new() -> Self {
        PaymentService {
            gateway_one: payment_gateway_one::PaymentGatewayOne::new(),
            gateway_two: payment_gateway_two::PaymentGatewayTwo::new(),
        }
    }

    async fn process_payment(&self, request: &PaymentRequest) -> Result<PaymentResponse, PaymentError> {
        let validator = self.gateway_one.validate(request).await?;
        if !validator.is_valid() {
            return Err(PaymentError::InvalidTransaction);
        }

        let mut cache = cache_manager::CacheManager::new();
        let cached_data = cache.get(request.transaction_id).await?;

        match cached_data {
            Some(data) => Ok(PaymentResponse { data }),
            None => {
                let data = self.gateway_two.fetch_data(request).await?;
                cache.set(request.transaction_id, data.clone()).await?;
                Ok(PaymentResponse { data })
            }
        }
    }
}

#[derive(Debug)]
enum PaymentError {
    InvalidTransaction,
    GatewayError,
    CacheError,
}

