// cache_manager.rs
mod lru_cache;
mod lfu_cache;

use std::sync::{Arc, Mutex};
use tokio::task;

struct CacheManager {
    lru_cache: Arc<Mutex<lru_cache::LRUCache>>,
    lfu_cache: Arc<Mutex<lfu_cache::LFUCache>>,
}

impl CacheManager {
    fn new() -> Self {
        CacheManager {
            lru_cache: Arc::new(Mutex::new(lru_cache::LRUCache::new())),
            lfu_cache: Arc::new(Mutex::new(lfu_cache::LFUCache::new())),
        }
    }

    async fn get(&self, key: &str) -> Result<Option<Vec<u8>>, CacheError> {
        let mut lru = self.lru_cache.lock().unwrap();
        if let Some(data) = lru.get(key) {
            return Ok(Some(data.clone()));
        }

        let mut lfu = self.lfu_cache.lock().unwrap();
        if let Some(data) = lfu.get(key) {
            return Ok(Some(data.clone()));
        }

        Err(CacheError::KeyNotFound)
    }

    async fn set(&self, key: &str, data: Vec<u8>) -> Result<(), CacheError> {
        self.lru_cache.lock().unwrap().set(key, data.clone());
        self.lfu_cache.lock().unwrap().set(key, data);
        Ok(())
    }
}

#[derive(Debug)]
enum CacheError {
    KeyNotFound,
}
