// lru_cache.rs
use std::collections::{HashMap, VecDeque};

struct LRUCache {
    capacity: usize,
    cache: HashMap<String, (Vec<u8>, usize)>,
    order: VecDeque<String>,
}

impl LRUCache {
    fn new() -> Self {
        LRUCache {
            capacity: 10000,
            cache: HashMap::new(),
            order: VecDeque::new(),
        }
    }

    fn get(&mut self, key: &str) -> Option<Vec<u8>> {
        if let Some((data, index)) = self.cache.get(key).cloned() {
            self.order.remove(index);
            self.order.push_back(key.to_string());
            return Some(data);
        }
        None
    }

    fn set(&mut self, key: &str, data: Vec<u8>) {
        if let Some(index) = self.order.iter().position(|k| k == key) {
            self.order.remove(index);
        }
        if self.cache.len() >= self.capacity {
            if let Some(key_to_remove) = self.order.pop_front() {
                self.cache.remove(&key_to_remove);
            }
        }
        self.cache.insert(key.to_string(), (data, self.order.len()));
        self.order.push_back(key.to_string());
    }
}
