```rust
// lfu_cache.rs
use std::collections::{HashMap, BinaryHeap};
use std::cmp::Reverse;

struct CacheItem {
    key: String,
    frequency: u32,
}

struct LFUCache {
    capacity: usize,
    cache: HashMap<String, (Vec<u8>, Reverse<CacheItem>)>,
    heap: BinaryHeap<Reverse<CacheItem>>,
}

impl LFUCache {
    fn new() -> Self {
        LFUCache {
            capacity: 10000,
            cache: HashMap::new(),
            heap: BinaryHeap::new(),
        }
    }

    fn get(&mut self, key: &str) -> Option<Vec<u8>> {
        if let Some((data, item)) = self.cache.get(key).cloned() {
            self.heap.retain(|i| i.key != key);
            item.frequency += 1;
            self.heap.push(Reverse(item));
            return Some(data);
        }
        None
    }

    fn set(&mut self, key: &str, data: Vec<u8>) {
        if let Some(index) = self.heap.iter().position(|i| i.key == key) {
            self.heap.remove(index);
        }
        if self.cache.len() >= self.capacity {
            if let Some(item) = self.heap.pop() {
                self.cache.remove(&item.key);
            }
        }
        let item = CacheItem {
            key: key.to_string(),
            frequency: 1,
        };
        self.cache.insert(key.to_string(), (data, Reverse(item)));
        self.heap.push(Reverse(CacheItem {
            key: key.to_string(),
            frequency: 1,
        }));
    }
}
