// Custom memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void* blocks;
    size_t free_index;
} MemoryPool;

// Initialize the memory pool
void initMemoryPool(MemoryPool* pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    memset(pool->blocks, 0, block_size * num_blocks);
    pool->free_index = 0;
}

// Allocate memory from the pool
void* allocateFromPool(MemoryPool* pool) {
    if (pool->free_index < pool->num_blocks) {
        void* block = (char*)pool->blocks + (pool->free_index * pool->block_size);
        pool->free_index++;
        return block;
    }
    return NULL; // Pool is full
}

// Free memory back to the pool
void freeToPool(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->blocks) / pool->block_size;
    if (index < pool->free_index) {
        memset(block, 0, pool->block_size);
        pool->free_index = index;
    }
