#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t next_index;
    pthread_mutex_t mutex;
} CrcIndicationPool;

void initCrcIndicationPool(CrcIndicationPool *pool, size_t pool_size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pool->pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = pool_size;
    pool->next_index = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

void *getCrcIndicationFromPool(CrcIndicationPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->next_index >= pool->pool_size) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *indication = &pool->pool[pool->next_index++];
    pthread_mutex_unlock(&pool->mutex);
    return indication;
}

void freeCrcIndicationPool(CrcIndicationPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    pool->next_index = 0;
    pthread_mutex_unlock(&pool->mutex);
    free(pool->pool);
