    NFAPI_CRC_INDICATION_PDU_T* blocks;
    size_t blockSize;
    size_t totalBlocks;
    size_t usedBlocks;
    size_t nextBlock;
} MemoryPool;

MemoryPool memoryPool = {NULL, 0, 0, 0, 0};

void initMemoryPool(size_t blockSize) {
    if (memoryPool.blocks != NULL) free(memoryPool.blocks);
    memoryPool.blockSize = blockSize;
    memoryPool.totalBlocks = MAX_STRUCTURES / blockSize + (MAX_STRUCTURES % blockSize ? 1 : 0);
    memoryPool.blocks = (NFAPI_CRC_INDICATION_PDU_T*)malloc(memoryPool.totalBlocks * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (memoryPool.blocks == NULL) {
        // Handle memory allocation failure
        exit(1);
    }
    memoryPool.usedBlocks = 0;
    memoryPool.nextBlock = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocateBlock() {
    if (memoryPool.nextBlock >= memoryPool.totalBlocks) {
        // Memory pool exhausted or need to resize
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* block = &memoryPool.blocks[memoryPool.nextBlock++];
    block->RX_UE_INFORMATION_TAG = generateRandomRxUeInfoTag(); // Implement this function
    block->RNTI = generateValidRnti(); // Implement this function
    block->CRC_INDICATION_REL8_TAG = (rand() % 2) == 0; // Randomly set CRC flag
    return block;
}

void freeMemoryPool() {
    if (memoryPool.blocks != NULL) {
        free(memoryPool.blocks);
        memoryPool.blocks = NULL;
        memoryPool.blockSize = 0;
        memoryPool.totalBlocks = 0;
        memoryPool.usedBlocks = 0;
        memoryPool.nextBlock = 0;
    }
}

void processNfapiCrcIndications(size_t N) {
