    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* block = allocateBlock();
        if (block == NULL) {
            // Handle allocation failure
            break;
        }
        // Process the allocated block
    }
    freeMemoryPool();
}
