#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <memory>
#include <atomic>

class DataProcessor {
public:
    struct SensorData {
        std::chrono::system_clock::time_point timestamp;
        double temperature;
        double humidity;
        double pressure;
    };

    DataProcessor(std::size_t poolSize, std::size_t batchSize)
        : memoryPool(poolSize), batchSize(batchSize) {}

    void startProcessing() {
        workerThread = std::thread(&DataProcessor::processData, this);
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopFlag = true;
        }
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    void addData(const SensorData& data) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            dataQueue.push(data);
        }
        condition.notify_one();
    }

private:
    std::vector<SensorData*> memoryPool;
    std::queue<SensorData*> freeList;
    std::queue<SensorData*> dataList;
    std::thread workerThread;
    std::mutex mutex;
    std::condition_variable condition;
    std::atomic<bool> stopFlag{false};
    std::size_t batchSize;

    void processData() {
        while (!stopFlag) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !dataQueue.empty() || stopFlag; });

            if (stopFlag && dataQueue.empty()) {
                break;
            }

            for (std::size_t i = 0; i < batchSize && !dataQueue.empty(); ++i) {
                dataList.push(dataQueue.front());
                dataQueue.pop();
            }
        }

        while (!dataList.empty()) {
            processDataBatch(dataList);
            std::swap(dataList, freeList);
        }
    }

    void processDataBatch(std::queue<SensorData*>& batch) {
        // Process the batch of data here
        for (SensorData* data : batch) {
            // Example processing: Print temperature
            std::cout << "Timestamp: " << data->timestamp.time_since_epoch().count()
                      << ", Temperature: " << data->temperature << std::endl;
            freeList.push(data);
        }
    }

    SensorData* allocateMemory() {
        if (freeList.empty()) {
            return new SensorData();
        } else {
            auto data = freeList.front();
            freeList.pop();
            return data;
        }
    }

    void deallocateMemory(SensorData* data) {
        freeList.push(data);
    }
};
