#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct {
    pthread_mutex_t lock;
    LinkedListNode* head;
} SafeLinkedList;

SafeLinkedList* create_safe_linked_list() {
    SafeLinkedList* list = (SafeLinkedList*)malloc(sizeof(SafeLinkedList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void safe_insert_node(SafeLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void safe_free_linked_list(SafeLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    LinkedListNode* current = list->head;
    while (current) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
