import io.quarkus.arc.DefaultBean;
import io.smallrye.mutiny.Uni;

@DefaultBean
public class TradingMicroservice {

    private final MarketDataClient marketDataClient;
    private final OrderPlacementClient orderPlacementClient;
    private final RiskAssessmentService riskAssessmentService;
    private final Cache<String, MarketData> dataCache;
    private final ConnectionPool connectionPool;
    private final Logger logger;

    public TradingMicroservice(MarketDataClient marketDataClient,
                                 OrderPlacementClient orderPlacementClient,
                                 RiskAssessmentService riskAssessmentService,
                                 Cache<String, MarketData> dataCache,
                                 ConnectionPool connectionPool,
                                 Logger logger) {
        this.marketDataClient = marketDataClient;
        this.orderPlacementClient = orderPlacementClient;
        this.riskAssessmentService = riskAssessmentService;
        this.dataCache = dataCache;
        this.connectionPool = connectionPool;
        this.logger = logger;
    }

    public Uni<Void> processTradingSignals() {
        return marketDataClient.fetchMarketData()
                .onItem().transformToUni(marketData -> {
                    if (riskAssessmentService.isSafe(marketData)) {
                        dataCache.put(marketData.getSymbol(), marketData);
                        connectionPool.getConnection().ifPresent(conn -> {
                            orderPlacementClient.placeOrder(marketData, conn)
                                    .onItem().transformToUni(orderResponse -> {
                                        logger.info("Order placed: " + orderResponse.getId());
                                        return Uni.createFrom().nullObject();
                                    });
                        });
                    } else {
                        logger.warn("Risk assessment failed for symbol: " + marketData.getSymbol());
                        return Uni.createFrom().nullObject();
                    }
                })
                .onFailure(Exception.class).recoverWithItem(() -> {
                    logger.error("Failed to process trading signals", new RuntimeException("System unavailable"));
                    return Uni.createFrom().nullObject();
                });
    }

}
```

