#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct NFAPI_CRC_INDICATION_PDU {
    int RNTI;
    char RX_UE_INFORMATION_TAG[10];
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode *next;
} LinkedListNode;

// Global head of the linked list
LinkedListNode* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new NFAPI_CRC_INDICATION_PDU_T structure with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T* create_new_pdu(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) return NULL;

    new_pdu->RNTI = RNTI;
    snprintf(new_pdu->RX_UE_INFORMATION_TAG, 10, "RX_UE_%d", RNTI);
    snprintf(new_pdu->CRC_INDICATION_REL8_TAG, 10, "CRC_%d", RNTI);
    new_pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_pdu->next = NULL;

    return new_pdu;
}

// Function to add a new node to the linked list
void add_node(int RNTI) {
    pthread_mutex_lock(&lock);
    LinkedListNode *new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->data = *create_new_pdu(RNTI);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);
}

// Function to free the linked list
void free_list() {
    pthread_mutex_lock(&lock);
    LinkedListNode *current = head;
    while (current != NULL) {
        LinkedListNode *temp = current;
        current = current->next;
        free(temp->data.RX_UE_INFORMATION_TAG);
        free(temp->data.CRC_INDICATION_REL8_TAG);
        free(temp);
    }
    head = NULL;
    pthread_mutex_unlock(&lock);
}

// Example usage
int main() {
    srand(time(NULL)); // Seed for random number generation

    add_node(101);
    add_node(102);

    return 0;
}
