class ResourceMonitoring {
public:
    static ResourceMonitoring& getInstance() {
        static std::call_once(initFlag, &ResourceMonitoring::initSingleton);
        return *instance;
    }

    void collect_metrics() {
        // Periodically gather metrics
        while (running.load()) {
            // Gather CPU, memory, disk I/O, and network I/O statistics for each pod
            // ...
            std::this_thread::sleep_for(std::chrono::seconds(10));
        }
    }

    void startMonitoring() {
        running.store(true);
        monitorThread = std::thread(&ResourceMonitoring::collect_metrics, this);
    }

    void stopMonitoring() {
        running.store(false);
        if (monitorThread.joinable()) {
            monitorThread.join();
        }
    }

private:
    ResourceMonitoring() {}
    ~ResourceMonitoring() {}

    static void initSingleton() {
        instance = new ResourceMonitoring();
    }

    static std::atomic<bool> running;
    static std::thread monitorThread;
    static ResourceMonitoring* instance;
    static std::call_once initFlag;
};

std::atomic<bool> ResourceMonitoring::running(false);
std::thread ResourceMonitoring::monitorThread;
ResourceMonitoring* ResourceMonitoring::instance = nullptr;
std::call_once ResourceMonitoring::initFlag;

int main() {
    ResourceMonitoring& monitor = ResourceMonitoring::getInstance();
    monitor.startMonitoring();

    // Simulate application running
    std::this_thread::sleep_for(std::chrono::minutes(5));

    monitor.stopMonitoring();
    return 0;
}
