#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_UE 10000
#define MIN_RNTI 1
#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_unique_tag(int *used_tags, int max_tag) {
    static pthread_mutex_t tag_mutex = PTHREAD_MUTEX_INITIALIZER;
    int tag;

    while (1) {
        pthread_mutex_lock(&tag_mutex);
        do {
            tag = rand() % max_tag + 1;
        } while (used_tags[tag]);
        used_tags[tag] = 1;
        pthread_mutex_unlock(&tag_mutex);

        if (tag != 0)
            break;
    }

    return tag;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(int N, int *errors) {
    static pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications;
    int *used_tags;
    int i;

    if (N < 1 || N > MAX_UE) {
        *errors = -1; // Invalid number of UEs
        return NULL;
    }

    crc_indications = malloc(N * sizeof(*crc_indications));
    if (!crc_indications) {
        *errors = -2; // Memory allocation failed
        return NULL;
    }

    used_tags = calloc(MAX_RNTI + 1, sizeof(int));
    if (!used_tags) {
        free(crc_indications);
        *errors = -3; // Memory allocation failed
        return NULL;
    }

    for (i = 0; i < N; ++i) {
        crc_indications[i].RX_UE_INFORMATION_TAG = generate_unique_tag(used_tags, MAX_RNTI);
        if (!crc_indications[i].RX_UE_INFORMATION_TAG) {
            *errors = -4; // Unique tag generation failed
            free(crc_indications);
            free(used_tags);
            return NULL;
        }

        crc_indications[i].RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand();
    }

    free(used_tags);
    *errors = 0; // Success
    return crc_indications;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *crc_indications, int N) {
    if (crc_indications) {
        free(crc_indications);
    }
}
