        pthread_mutex_destroy(&ctx->lock);
        PQfinish(ctx->db_conn);
        free(ctx);
    }
}

int insert_pdu_to_db(DBContext *ctx, NFAPI_CRC_INDICATION_PDU_T *pdu) {
