    PGresult *res = PQexecParams(ctx->db_conn,
                                  "INSERT INTO napi_crc_indication (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG, timestamp) VALUES ($1, $2, $3, $4, $5)",
