        fprintf(stderr, "Error inserting PDU: %s\n", PQerrorMessage(ctx->db_conn));
        PQclear(res);
        pthread_mutex_unlock(&ctx->lock);
        return -1;
    }
    PQclear(res);
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

int generate_and_persist_pdus(DBContext *ctx, size_t N) {
