#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <libpq-fe.h>

#define N 100 // Maximum number of concurrent operations

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

PGconn *pool[N]; // Connection pool
pthread_t threads[N]; // Thread pool

void* process_pdu(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T pdu = *(NFAPI_CRC_INDICATION_PDU_T*)arg;

    // Simulate database write operation
    for (int i = 0; i < N; i++) {
        PGconn *conn = pool[i % N];
        if (PQstatus(conn) != CONNECTION_OK) {
            printf("Connection to database failed: %s", PQerrorMessage(conn));
            continue;
        }

        char query[128];
        snprintf(query, sizeof(query), "INSERT INTO napi_crc_indication VALUES (%d, %d, %d, %d)",
                 pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG, pdu.CRCFLAG);

        PGresult *res = PQexec(conn, query);
        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            printf("INSERT failed: %s", PQerrorMessage(conn));
            PQclear(res);
            continue;
        }

        PQclear(res);
    }

    return NULL;
}

void initialize_pool(int pool_size) {
    for (int i = 0; i < pool_size; i++) {
        char conn_str[256];
        snprintf(conn_str, sizeof(conn_str), "host=localhost user=postgres password=secret dbname=napi_db");
        pool[i] = PQconnectdb(conn_str);
        if (PQstatus(pool[i]) != CONNECTION_OK) {
            printf("Connection to database failed: %s", PQerrorMessage(pool[i]));
            exit(1);
        }
    }
}

int main() {
    int num_indications = 10000; // Number of PDUs to process
    NFAPI_CRC_INDICATION_PDU_T puds[num_indications];

    initialize_pool(N);

    for (int i = 0; i < num_indications; i++) {
        puds[i].RX_UE_INFORMATION_TAG = rand() % 100;
        puds[i].RNTI = rand() % 1000;
        puds[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        puds[i].CRCFLAG = rand() % 2;

        if (i % N == 0) {
            for (int j = 0; j < N; j++) {
                pthread_create(&threads[j], NULL, process_pdu, &puds[i + j]);
            }

            for (int j = 0; j < N; j++) {
                pthread_join(threads[j], NULL);
            }
        }
    }

    for (int i = 0; i < N; i++) {
        PQfinish(pool[i]);
    }

    return 0;
}
