#define MAX_UEs 10000
#define MAX_CRC_INDICATIONS 100000

typedef struct {
    uint16_t RNTI;
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *allocate_crc_indications(int N, int *error_code) {
    if (N < 1 || N > MAX_UEs) {
        *error_code = -1; // Invalid number of UEs
        return NULL;
    }

    uint32_t total_crc_indications = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_crc_indications > MAX_CRC_INDICATIONS) {
        *error_code = -2; // Exceeds system-defined limit
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(total_crc_indications);
    if (!crc_indications) {
        *error_code = -3; // Memory allocation failed
        return NULL;
    }

    // Initialize CRC indications with unique identifiers and random CRCFLAG
    for (int i = 0; i < N; i++) {
        crc_indications[i].RNTI = i + 1;
        crc_indications[i].RX_UE_INFORMATION_TAG = i * 1000 + i;
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % UINT32_MAX;
    }

    *error_code = 0; // Success
    return crc_indications;
}

int main() {
    int error_code;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = allocate_crc_indications(10, &error_code);
    if (crc_indications) {
        printf("CRC indications allocated successfully.\n");
        free(crc_indications);
    } else {
        printf("Error: %d\n", error_code);
    }
    return 0;
}
