#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <atomic>
#include <memory>
#include <future>

class NetworkEventProcessor {
public:
    NetworkEventProcessor(size_t numThreads) : stop(false), workerCount(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&NetworkEventProcessor::workerThread, this);
        }
    }

    ~NetworkEventProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        queueCondition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void processEvent(const Event& event) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            events.push(event);
        }
        queueCondition.notify_one();
    }

private:
    struct Event {};

    void workerThread() {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                queueCondition.wait(lock, [this] { return stop || !events.empty(); });
                if (stop && events.empty()) {
                    break;
                }
                event = events.front();
                events.pop();
            }
            processEvent(event); // Process the event
        }
    }

    std::atomic<bool> stop;
    size_t workerCount;
    std::vector<std::thread> workers;
    std::queue<Event> events;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
};

int main() {
    NetworkEventProcessor processor(300);
    // Simulate event processing
    for (size_t i = 0; i < 45000; ++i) {
        Event event;
        processor.processEvent(event);
    }
    return 0;
}
