// Include necessary headers
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a network event
typedef struct Event {
    time_t timestamp;
    char type[32];
    char source_ip[16];
    char* payload;
    size_t payload_size;
} Event;

// Define a non-blocking queue structure
typedef struct QueueNode {
    Event event;
    struct QueueNode* next;
} QueueNode;

typedef struct NonBlockingQueue {
    QueueNode* head;
    QueueNode* tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NonBlockingQueue;

// Function to initialize the non-blocking queue
void init_queue(NonBlockingQueue* queue) {
    queue->head = NULL;
    queue->tail = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

// Function to enqueue an event into the queue
void enqueue_event(NonBlockingQueue* queue, Event* event) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    if (!new_node) {
        // Handle memory allocation failure
        return;
    }
    memcpy(&new_node->event, event, sizeof(Event));
    new_node->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Function to dequeue an event from the queue
int dequeue_event(NonBlockingQueue* queue, Event* event) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->head == NULL) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    QueueNode* old_head = queue->head;
    memcpy(event, &old_head->event, sizeof(Event));
    queue->head = old_head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    pthread_mutex_unlock(&queue->mutex);
    free(old_head);
    return 0; // Success
}

// Function to destroy the non-blocking queue
void destroy_queue(NonBlockingQueue* queue) {
    QueueNode* current = queue->head;
    while (current) {
        QueueNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
}

// Example usage
int main() {
    NonBlockingQueue event_queue;
    init_queue(&event_queue);

    Event new_event;
    new_event.timestamp = time(NULL);
    strncpy(new_event.type, "LOGIN", sizeof(new_event.type));
    strncpy(new_event.source_ip, "192.168.1.1", sizeof(new_event.source_ip));
    new_event.payload_size = strlen("User logged in successfully");
    new_event.payload = (char*)malloc(new_event.payload_size + 1);
    strcpy(new_event.payload, "User logged in successfully");

    enqueue_event(&event_queue, &new_event);

    Event retrieved_event;
    if (!dequeue_event(&event_queue, &retrieved_event)) {
        printf("Retrieved event: Type=%s, IP=%s, Payload=%s\n",
               retrieved_event.type, retrieved_event.source_ip, retrieved_event.payload);
    }

    free(new_event.payload);
    destroy_queue(&event_queue);

    return 0;
}
