#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the event structure
typedef struct {
    time_t timestamp;
    char type[50];
    char source_ip[16];
    char payload[1024];
} Event;

// Define a node for the linked list
typedef struct Node {
    Event event;
    struct Node *next;
} Node;

// Define the queue structure
typedef struct Queue {
    Node *front;
    Node *rear;
    int size;
} Queue;

// Initialize the queue
void init_queue(Queue *q) {
    q->front = q->rear = NULL;
    q->size = 0;
}

// Check if the queue is empty
int is_empty(Queue *q) {
    return q->front == NULL;
}

// Enqueue an event into the queue
void enqueue(Queue *q, Event event) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = NULL;

    if (is_empty(q)) {
        q->front = q->rear = new_node;
    } else {
        q->rear->next = new_node;
        q->rear = new_node;
    }
    q->size++;
}

// Dequeue an event from the queue
Event dequeue(Queue *q) {
    if (is_empty(q)) {
        printf("Queue is empty!\n");
        Event empty_event = {0};
        return empty_event;
    }

    Node *temp = q->front;
    Event event = temp->event;

    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    q->size--;
    return event;
}

// Get the size of the queue
int get_size(Queue *q) {
    return q->size;
}

// Thread function for processing events
void *process_events(void *arg) {
    Queue *q = (Queue *)arg;

    while (1) {
        Event event = dequeue(q);
        if (!is_empty(q)) {
            // Process the event here
            printf("Processing event with timestamp: %ld\n", event.timestamp);
        } else {
            break;
        }
    }

    pthread_exit(NULL);
}

int main() {
    Queue q;
    init_queue(&q);

    // Simulate adding events to the queue
    Event e1 = {time(NULL), "LOGIN", "192.168.1.1", "User logged in"};
    enqueue(&q, e1);

    Event e2 = {time(NULL) + 50, "LOGOUT", "192.168.1.1", "User logged out"};
    enqueue(&q, e2);

    // Create a thread to process events
    pthread_t tid;
    pthread_create(&tid, NULL, process_events, &q);
    pthread_join(tid, NULL);

    return 0;
}
