app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Function to insert event into the database
async function insertEvent(event) {
  try {
    const client = await pool.connect();
    await client.query('INSERT INTO events (data) VALUES ($1)', [event]);
    client.release();
  } catch (err) {
    console.error(err.stack);
  }
}

// Function to fetch events from the database
async function fetchEvents(limit, offset) {
  try {
    const client = await pool.connect();
    const res = await client.query('SELECT * FROM events LIMIT $1 OFFSET $2', [limit, offset]);
    client.release();
    return res.rows;
  } catch (err) {
    console.error(err.stack);
    throw err;
  }
}

// Function to delete event from the database
async function deleteEvent(id) {
  try {
    const client = await pool.connect();
    await client.query('DELETE FROM events WHERE id = $1', [id]);
    client.release();
  } catch (err) {
    console.error(err.stack);
  }
}

// Route to receive and store events from multiple sources
app.post('/events', async (req, res) => {
  const event = req.body;
  await insertEvent(event);
  res.send('Event received');
});

// Route to retrieve events from the database
app.get('/events', async (req, res) => {
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;
  try {
    const events = await fetchEvents(limit, offset);
    res.json(events);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Route to delete an event from the database
app.delete('/events/:id', async (req, res) => {
  const id = req.params.id;
  await deleteEvent(id);
  res.send('Event deleted');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
