  for await (const chunk of stream) {
    if (!this.paused) {
      try {
        const event = JSON.parse(chunk.toString());
        // Process the event
        console.log('Processing event:', event);
      } catch (err) {
        console.error('Error processing event:', err);
      }
    }
  }
};

StreamProcessor.prototype.pause = () => {
  this.paused = true;
};

StreamProcessor.prototype.resume = () => {
  this.paused = false;
};

// Usage example
const stream = require('stream').Readable();
const processor = new StreamProcessor();

processor.processStream(stream);

// Pause and resume events processing
setTimeout(() => processor.pause(), 5000);
setTimeout(() => processor.resume(), 10000);
