#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

// Define constants and structures
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB per log file
#define RETRY_ATTEMPTS 3

typedef struct {
    char tenant_id[64];
    FILE* log_file;
} TenantLog;

typedef struct {
    pthread_mutex_t lock;
    TenantLog tenants[10000]; // Assuming up to 10,000 tenants
} LogManager;

// Function prototypes
void initializeLogManager(LogManager* manager);
void finalizeLogManager(LogManager* manager);
int logConditionalMessage(LogManager* manager, const char* tenant_id, int conditionMet, ...);

// Implementation of the LogManager functions

void initializeLogManager(LogManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < 10000; ++i) {
        manager->tenants[i].log_file = NULL;
    }
}

void finalizeLogManager(LogManager* manager) {
    for (int i = 0; i < 10000; ++i) {
        if (manager->tenants[i].log_file != NULL) {
            fclose(manager->tenants[i].log_file);
        }
    }
    pthread_mutex_destroy(&manager->lock);
}

int logConditionalMessage(LogManager* manager, const char* tenant_id, int conditionMet, ...) {
    pthread_mutex_lock(&manager->lock);
    TenantLog* tenant = NULL;
    for (int i = 0; i < 10000; ++i) {
        if (strcmp(manager->tenants[i].tenant_id, tenant_id) == 0) {
            tenant = &manager->tenants[i];
            break;
        }
    }

    if (tenant == NULL || tenant->log_file == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Tenant not found or log file not initialized
    }

    time_t now = time(NULL);
    struct tm* tm_info = localtime(&now);
    if (tm_info->tm_hour < 9 || tm_info->tm_hour >= 17) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Not within business hours
    }

    if (!conditionMet) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Condition not met
    }

    va_list args;
    char buffer[MAX_LOG_SIZE];
    va_start(args, conditionMet);
    int result = vsnprintf(buffer, sizeof(buffer), tenant_id, args);
    va_end(args);

    if (result < 0) {
        pthread_mutex_unlock(&manager->lock);
        return -4; // Error in formatting message
    }

    fprintf(tenant->log_file, "%s\n", buffer);
    fflush(tenant->log_file);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Example usage
int main() {
    LogManager manager;
    initializeLogManager(&manager);

    // Initialize log files for tenants
    TenantLog* tenant1 = &manager.tenants[0];
    strcpy(tenant1->tenant_id, "Tenant1");
    tenant1->log_file = fopen("Tenant1.log", "a");

    TenantLog* tenant2 = &manager.tenants[1];
    strcpy(tenant2->tenant_id, "Tenant2");
    tenant2->log_file = fopen("Tenant2.log", "a");

    // Log messages conditionally
    logConditionalMessage(&manager, "Tenant1", 1, "This is a conditional message for Tenant1");
    logConditionalMessage(&manager, "Tenant2", 0, "This message should not be logged");

    finalizeLogManager(&manager);
    return 0;
}
```

This code provides the basic structure for the `LogManager` library component. It includes functions to initialize and finalize the manager, as well as an asynchronous function to log conditional messages based on specific conditions. The implementation ensures thread safety using mutexes and handles basic error checking. Further enhancements are required for full functionality, including network integration, structured logging, and more detailed resource management.']

