// JavaScript function to recursively traverse a DOM tree and return elements that match a given selector
function findElementsBySelector(element, selector, testFunction) {
    let result = [];

    // Check if the current element matches the selector and test function
    if (element.matches(selector) && testFunction(element)) {
        result.push(element);
    }

    // Recursively search through child nodes
    element.children.forEach(child => {
        result = result.concat(findElementsBySelector(child, selector, testFunction));
    });

    return result;
}

