using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using PaymentGatewayClient;

[ApiController]
[Route("api/[controller]")]
public class CreditCardController : ControllerBase
{
    private readonly IThirdPartyPaymentGateway _paymentGateway;
    private readonly IDistributedCache _cache;

    public CreditCardController(IThirdPartyPaymentGateway paymentGateway, IDistributedCache cache)
    {
        _paymentGateway = paymentGateway ?? throw new ArgumentNullException(nameof(paymentGateway));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    [HttpPost("process")]
    public async Task<IActionResult> ProcessTransaction([FromBody] CreditCardTransaction transaction)
    {
        if (transaction == null) return BadRequest();

        try
        {
            var authMethod = DetermineAuthenticationMethod(transaction);
            await AuthenticateGateway(authMethod);

            var result = await _paymentGateway.ProcessTransaction(transaction);
            if (result.IsSuccess)
            {
                await CacheResult(result.TransactionId, result.ResponseData);
                return Ok(result);
            }

            return StatusCode(502, "Payment gateway failed to process transaction");
        }
        catch (Exception ex)
        {
            // Log exception and handle gracefully
            return StatusCode(500, "Internal server error");
        }
    }

    private AuthenticationMethod DetermineAuthenticationMethod(CreditCardTransaction transaction)
    {
        if (transaction.IsCritical)
        {
            return AuthenticationMethod.MultiFactor;
        }
        else if (User.HasRole("Admin"))
        {
            return AuthenticationMethod.OAuth2;
        }
        else
        {
            return AuthenticationMethod.ApiKey;
        }
    }

    private async Task AuthenticateGateway(AuthenticationMethod method)
    {
        switch (method)
        {
            case AuthenticationMethod.MultiFactor:
                await _paymentGateway.AuthenticateMultiFactor();
                break;
            case AuthenticationMethod.OAuth2:
                var token = await _paymentGateway.GetOAuth2Token(User);
                _paymentGateway.SetAuthenticationToken(token);
                break;
            case AuthenticationMethod.ApiKey:
                var apiKey = await _paymentGateway.GetApiKey();
                _paymentGateway.SetAuthenticationToken(apiKey);
                break;
        }
    }

    private async Task CacheResult(string transactionId, string responseData)
    {
        await _cache.SetStringAsync(transactionId, responseData, new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
        });
    }
}

public class CreditCardTransaction
{
    public string TransactionId { get; set; }
    public decimal Amount { get; set; }
    public string CardNumber { get; set; }
    public bool IsCritical { get; set; }
}

public enum AuthenticationMethod
{
    MultiFactor,
    OAuth2,
    ApiKey
}
