#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <chrono>

class StreamProcessingEngine {
public:
    void start() {
        for (size_t i = 0; i < numThreads_; ++i) {
            threads_.emplace_back([this]() { worker(); });
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    template<typename Source, typename Format>
    void processStream(Source& source, Format format) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.emplace(source, format);
        cv_.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this]() { return stop_ || !queue_.empty(); });
            if (stop_) break;
            auto task = queue_.front();
            queue_.pop();
            lock.unlock();

            process(task.source, task.format);
        }
    }

    void process(Source& source, Format format) {
        // Implement data processing logic here
    }

    struct Task {
        Source source;
        Format format;
    };

    std::vector<std::thread> threads_;
    std::queue<Task> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stop_ = false;
    size_t numThreads_ = std::thread::hardware_concurrency();
};

int main() {
    StreamProcessingEngine engine;
    engine.start();

    // Example usage
