#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MD5_DIGEST_LENGTH 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 4096;
    snprintf(pdu->CRC_INDICATION_REL8_TAG, sizeof(pdu->CRC_INDICATION_REL8_TAG), "CRC%d", rand() % 10);
    pdu->CRCFLAG = rand() % 2;
}

void* compute_md5_hash(void *arg) {
    char *file_path = (char *)arg;
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    unsigned char buffer[1024];
    MD5_CTX md5;
    MD5_Init(&md5);

    while (size_t bytes_read = fread(buffer, 1, sizeof(buffer), file)) {
        MD5_Update(&md5, buffer, bytes_read);
    }

    fclose(file);

    unsigned char hash_value[MD5_DIGEST_LENGTH];
    MD5_Final(hash_value, &md5);

    printf("MD5 hash of %s: ", file_path);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", hash_value[i]);
    }
    printf("\n");

    return NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdus[10];
    for (int i = 0; i < 10; i++) {
        generate_crc_indication_pdu(&pdus[i]);
        // Process PDUs as needed
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, compute_md5_hash, "example.txt") != 0) {
        perror("Error creating thread");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
```

