#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/bio.h>
#include <openssl/jwt.h>
#include <redis/redis++.h>

class JWTManager {
public:
    JWTManager(const std::string& publicKeyPath, const std::string& privateKeyPath)
        : redisClient("127.0.0.1", 6379), publicKey(publicKeyPath), privateKey(privateKeyPath) {}

    std::string generateToken(const std::string& userId, int ttl = 3600) {
        // Generate JWT
        return jwt::create(jwt::algorithm::RS256(privateKey), jwt::header(), jwt::payload({{"sub", userId}, {"exp", time(nullptr) + ttl}}));
    }

    bool validateToken(const std::string& token) {
        try {
            // Validate JWT
            auto decoded = jwt::decode(token);
            return decoded.verify(jwt::algorithm::RS256(publicKey));
        } catch (const jwt::invalid_token_exception& e) {
            std::cerr << "Invalid token: " << e.what() << std::endl;
            return false;
        }
    }

private:
    redis::client redisClient;
    std::string publicKey;
    std::string privateKey;
};

class TokenCache {
public:
    void setToken(const std::string& userId, const std::string& token) {
        // Store token in Redis with expiration
        redisClient.set(userId, token);
        redisClient.expire(userId, 3600); // TTL of 1 hour
    }

    std::optional<std::string> getToken(const std::string& userId) {
        // Retrieve token from Redis
        return redisClient.get(userId);
    }

private:
    redis::client redisClient;
};

class TokenService {
public:
    TokenService(JWTManager jwtManager, TokenCache tokenCache)
        : jwtManager(jwtManager), tokenCache(tokenCache) {}

    std::string authenticateUser(const std::string& userId) {
        // Generate and cache JWT
        std::string token = jwtManager.generateToken(userId);
        tokenCache.setToken(userId, token);
        return token;
    }

    bool verifyToken(const std::string& token) {
        // Validate JWT and retrieve user ID from cache
        if (jwtManager.validateToken(token)) {
            auto userId = getUserIdFromToken(token);
            return tokenCache.getToken(userId).has_value();
        }
        return false;
    }

private:
    JWTManager jwtManager;
    TokenCache tokenCache;

    std::string getUserIdFromToken(const std::string& token) {
        // Extract user ID from JWT payload
        auto decoded = jwt::decode(token);
        return decoded.get_payload()["sub"].as_string();
    }
};

int main() {
    JWTManager jwtManager("public.pem", "private.pem");
    TokenCache tokenCache;
    TokenService tokenService(jwtManager, tokenCache);

    // Example usage
    std::string userId = "user123";
    std::string token = tokenService.authenticateUser(userId);
    if (tokenService.verifyToken(token)) {
        std::cout << "Authentication successful!" << std::endl;
    } else {
        std::cout << "Authentication failed!" << std::endl;
    }

    return 0;
}
