// Main class for the cloud-native file metadata updater
class FileMetadataUpdater {
private:
    CloudStorage storage;
    HTTPClient httpClient;
    ContentDetectionService contentService;
    Logger logger;

    std::mutex queueMutex;
    std::condition_variable condition;
    std::queue<std::pair<std::string, std::map<std::string, std::string>>> updateQueue;
    bool stopProcessing = false;

public:
    void addUpdateTask(const std::string& file_id, const std::map<std::string, std::string>& metadata) {
        std::lock_guard<std::mutex> lock(queueMutex);
        updateQueue.push({file_id, metadata});
        condition.notify_one();
    }

    void processUpdates() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this] { return !updateQueue.empty() || stopProcessing; });
            if (stopProcessing && updateQueue.empty()) {
                break;
            }
            auto task = updateQueue.front();
            updateQueue.pop();
            lock.unlock();

            try {
                processUpdateTask(task.first, task.second);
            } catch (const std::exception& e) {
                logger.log("Error processing update: " + std::string(e.what()));
            }
        }
    }

private:
    void processUpdateTask(const std::string& file_id, const std::map<std::string, std::string>& metadata) {
        try {
            if (!storage.authenticate("api_key", "secret_key")) {
                throw std::runtime_error("Authentication failed");
            }

            storage.handleRateLimiting();

            auto contentMetadata = httpClient.getContentMetadata(file_id);
            auto analysisMetadata = contentService.isAvailable() ? contentService.analyzeContent(file_id) : fallbackAnalysis(file_id);

            std::map<std::string, std::string> updatedMetadata = combineMetadata(metadata, contentMetadata, analysisMetadata);
            storage.updateMetadata(file_id, updatedMetadata);
        } catch (const std::exception& e) {
            logger.log("Error processing update: " + std::string(e.what()));
        }
    }

    std::map<std::string, std::string> fallbackAnalysis(const std::string& file_id) {
        // Implement a robust fallback mechanism combining heuristic methods, user preferences, and policy rules
        return {{"language", "Unknown"}, {"category", "unknown"}};
    }

    std::map<std::string, std::string> combineMetadata(const std::map<std::string, std::string>& metadata1,
                                                        const std::map<std::string, std::string>& metadata2,
                                                        const std::map<std::string, std::string>& metadata3) {
        // Combine metadata from different sources
        std::map<std::string, std::string> combinedMetadata;
        for (const auto& pair : metadata1) {
            combinedMetadata[pair.first] = pair.second;
        }
        for (const auto& pair : metadata2) {
            combinedMetadata[pair.first] = pair.second;
        }
        for (const auto& pair : metadata3) {
            combinedMetadata[pair.first] = pair.second;
        }
        return combinedMetadata;
    }
};

int main() {
    FileMetadataUpdater updater;

    std::thread processingThread(&FileMetadataUpdater::processUpdates, &updater);

    updater.addUpdateTask("file123", {{"size", "1MB"}, {"owner", "user1"}});

    processingThread.join();

    return 0;
}
```

