#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <fstream>

// Define the SensorData structure to hold data from individual sensors
struct SensorData {
    std::string nodeId;
    double temperature;
    double humidity;
    // Add more sensor data fields as needed
};

// Define a class for managing the network of IoT sensors
class IoTNetworkManager {
private:
    std::vector<SensorData> sensorDataQueue;
    std::mutex queueMutex;
    std::condition_variable dataReady;
    bool running;

public:
    IoTNetworkManager() : running(true) {}

    // Function to start collecting data from sensors (simulated)
    void collectData() {
        while (running) {
            // Simulate sensor data collection
            SensorData newData = { "Node1", 23.5, 45.0 };
            std::lock_guard<std::mutex> lock(queueMutex);
            sensorDataQueue.push_back(newData);
            dataReady.notify_one();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

    // Function to process and analyze collected data
    void processData() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataReady.wait(lock, [this] { return !sensorDataQueue.empty(); });
            SensorData data = sensorDataQueue.front();
            sensorDataQueue.pop_front();
            lock.unlock();

            // Perform data analysis and trigger alerts if necessary
            analyzeAndAlert(data);
        }
    }

    // Function to analyze data and trigger alerts
    void analyzeAndAlert(const SensorData& data) {
        if (data.temperature > 40.0 || data.humidity < 25.0) {
            std::cout << "Warning: High temperature or low humidity detected on Node " << data.nodeId << std::endl;
        }
    }

    // Function to stop the network manager
    void stop() {
        running = false;
        dataReady.notify_all();
    }
};

// Main function to demonstrate the application
int main() {
    IoTNetworkManager manager;

    // Start data collection and processing threads
    std::thread collector(&IoTNetworkManager::collectData, &manager);
    std::thread processor(&IoTNetworkManager::processData, &manager);

    // Simulate running for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));

    manager.stop();
    collector.join();
    processor.join();

    return 0;
}
```

