['```javascript
function traverseDOM(element, selector, testFunction) {
  let result = [];

  function visit(node) {
    if (testFunction(node)) {
      result.push(node);
    }
    node.childNodes.forEach(child => visit(child));
  }

  visit(element);
  return result.filter(el => el.matches(selector));
}
