# Import necessary libraries
import logging
from abc import ABC, abstractmethod
from typing import List, Dict, Any

class LoggerBackend(ABC):
    @abstractmethod
    def log(self, message: str) -> None:
        pass

class AWSLogger(LoggerBackend):
    def log(self, message: str) -> None:
        # Implement AWS CloudWatch logging logic here
        print(f"Logging to AWS: {message}")

class GoogleStackdriverLogger(LoggerBackend):
    def log(self, message: str) -> None:
        # Implement Google Stackdriver logging logic here
        print(f"Logging to Google Stackdriver: {message}")

class SplunkLogger(LoggerBackend):
    def log(self, message: str) -> None:
        # Implement Splunk logging logic here
        print(f"Logging to Splunk: {message}")

class LoggerManager:
    _backends: Dict[str, LoggerBackend] = {}

    @staticmethod
    def get_backends() -> List[LoggerBackend]:
        if not LoggerManager._backends:
            backends_config = os.getenv('LOGGING_BACKENDS', 'AWS,GoogleStackdriver,Splunk').split(',')
            for backend in backends_config:
                if backend == 'AWS':
                    LoggerManager._backends['AWS'] = AWSLogger()
                elif backend == 'GoogleStackdriver':
                    LoggerManager._backends['GoogleStackdriver'] = GoogleStackdriverLogger()
                elif backend == 'Splunk':
                    LoggerManager._backends['Splunk'] = SplunkLogger()
        return list(LoggerManager._backends.values())

class LogEntry:
    def __init__(self, message: str, level: str):
        self.message = message
        self.level = level

class LoggingFramework:
    def __init__(self, mode: str = 'synchronous'):
        self.mode = mode
        self.backends = LoggerManager.get_backends()

    def log(self, entry: LogEntry) -> None:
        if self.mode == 'synchronous':
            for backend in self.backends:
                backend.log(entry.message)
        elif self.mode == 'asynchronous':
            # Implement asynchronous logging logic here
            pass

# Example usage
if __name__ == "__main__":
    framework = LoggingFramework(mode='asynchronous')
    entry = LogEntry("This is a test log message", "INFO")
    framework.log(entry)
```

Note: This code provides a basic structure for a modular, scalable logging framework in Python. It includes abstract base class `LoggerBackend` for different logging services, concrete implementations for AWS CloudWatch, Google Stackdriver, and Splunk, a `LoggerManager` to dynamically load supported backends based on environmental variables, and a `LoggingFramework` to handle both synchronous and asynchronous log delivery modes. The actual implementation of each backend's logging logic is left as an exercise for the developer.']

