["```javascript
// server.js (Node.js backend using Express)
const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const redis = require('redis');
const app = express();
const port = process.env.PORT || 3001;

app.use(bodyParser.json());
const client = redis.createClient();

client.on('error', (err) => {
  console.log('Redis Error: ' + err);
});

// Route to handle RESTful API requests
app.get('/api/data', async (req, res) => {
  try {
    const response = await axios.get('https://api.example.com/data');
    const data = response.data;

    // Store data in Redis cache
    client.setex('data_key', 3600, JSON.stringify(data)); // Cache for 1 hour

    res.json(data);
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Error fetching data' });
  }
});

// Route to handle Webhooks
app.post('/webhook', async (req, res) => {
  const webhookData = req.body;

  // Process and store webhook data in Redis cache
  client.setex('webhook_data_key', 3600, JSON.stringify(webhookData));

  res.status(200).send();
});

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});
