typedef struct {
    pthread_mutex_t lock;
    NetworkEventStruct **events;
    size_t count;
    size_t capacity;
} EventManager;

EventManager *event_manager_init() {
    EventManager *manager = malloc(sizeof(EventManager));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;
    return manager;
}

void event_manager_add_event(EventManager *manager, NetworkEventStruct *event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        manager->events = realloc(manager->events, new_capacity * sizeof(NetworkEventStruct *));
        manager->capacity = new_capacity;
    }
    manager->events[manager->count++] = event;
    pthread_mutex_unlock(&manager->lock);
}

void event_manager_free(EventManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->events[i]);
    }
    free(manager->events);
    free(manager);
    pthread_mutex_unlock(&manager->lock);
}

void process_events(EventManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        NetworkEventStruct *event = manager->events[i];
        // Process each event
        printf("Timestamp: %ld, Event Type: %s\n", event->timestamp, event->eventType);
