#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/time.h>
#include <string.h>

#define MAX_PDUS 1024
#define DEFAULT_PDUS 32

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int in_use;
} PduEntry;

typedef struct {
    PduEntry pdus[MAX_PDUS];
    sem_t available_sem;
    pthread_mutex_t mutex;
    int max_pdus;
    int default_pdus;
} PduManager;

PduManager* create_pdu_manager(int max_pdus, int default_pdus) {
    PduManager* manager = (PduManager*)malloc(sizeof(PduManager));
    if (!manager) {
        perror("Memory allocation failed");
        return NULL;
    }
    memset(manager, 0, sizeof(PduManager));
    manager->max_pdus = max_pdus ? : MAX_PDUS;
    manager->default_pdus = default_pdus ? : DEFAULT_PDUS;
    sem_init(&manager->available_sem, 0, manager->max_pdus);
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(PduManager* manager) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (sem_wait(&manager->available_sem) == 0) {
        pthread_mutex_lock(&manager->mutex);
        for (int i = 0; i < manager->max_pdus; i++) {
            if (!manager->pdus[i].in_use) {
                manager->pdus[i].in_use = 1;
                pdu = &manager->pdus[i].pdu;
                break;
            }
        }
        pthread_mutex_unlock(&manager->mutex);
    }
    return pdu;
}

void free_pdu(PduManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pthread_mutex_lock(&manager->mutex);
        for (int i = 0; i < manager->max_pdus; i++) {
            if (&manager->pdus[i].pdu == pdu) {
                manager->pdus[i].in_use = 0;
                sem_post(&manager->available_sem);
                break;
            }
        }
        pthread_mutex_unlock(&manager->mutex);
    }
}

void destroy_pdu_manager(PduManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        sem_destroy(&manager->available_sem);
        free(manager);
    }
}
