        : event_id(eid), timestamp(ts), payload(pl), metadata(md) {}
};

class MessageBroker {
public:
    void start() {
        // Start ZMQ context and publisher
        zmq::context_t ctx(1);
        publisher = std::make_unique<zmq::socket_t>(ctx, ZMQ_PUB);
        publisher->bind("tcp://*:5556");

        // Start worker threads
        for (size_t i = 0; i < num_workers; ++i) {
            workers.emplace_back([this]() { worker_thread(i); });
        }
    }

    void stop() {
        running = false;
        for (auto& w : workers) {
            w.join();
        }
        publisher->close();
    }

    void ingest_message(const Message& msg) {
        std::lock_guard<std::mutex> lock(mutex);
        message_queue.push(msg);
        cond.notify_one();
    }

private:
    std::unique_ptr<zmq::socket_t> publisher;
    std::vector<std::thread> workers;
    size_t num_workers = 4; // Number of worker threads
    bool running = true;
    std::mutex mutex;
    std::condition_variable cond;
    std::queue<Message> message_queue;

    void worker_thread(size_t id) {
        while (running) {
            std::unique_lock<std::mutex> lock(mutex);
            cond.wait(lock, [this] { return !message_queue.empty() || !running; });
            if (!running) break;

            Message msg = message_queue.front();
            message_queue.pop();

            // Process and publish message
            process_message(msg);
        }
    }

    void process_message(const Message& msg) {
        std::string serialized_msg = serialize_message(msg);
        publisher->send(zmq::buffer(serialized_msg), zmq::send_flags::none);
    }

    std::string serialize_message(const Message& msg) {
        Json::Value json;
        json["event_id"] = msg.event_id;
        json["timestamp"] = msg.timestamp;
        json["payload"] = msg.payload;
        json["metadata"] = msg.metadata;

        Json::StreamWriterBuilder wbuilder;
        return Json::writeString(wbuilder, json);
    }
};

int main() {
    MessageBroker broker;
    broker.start();

    // Simulate message ingestion
    for (size_t i = 0; i < 10; ++i) {
        Message msg("event_" + std::to_string(i), "timestamp", "payload", "metadata");
        broker.ingest_message(msg);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    broker.stop();

    return 0;
}
```

This code provides a basic framework for a message broker using ZeroMQ and JSON for message serialization. It includes thread-safe message ingestion, processing, and publishing mechanisms. The `Message` class represents the structure of each message, and the `MessageBroker` class manages the overall system, including worker threads for concurrent processing and a publisher for distributing messages to subscribers.']

