PduEntry pdus[MAX_PDUS];
int next_pdu_index = 0;
pthread_mutex_t pdus_lock;
pthread_cond_t pdus_full;

void init_pdu_manager() {
    for (int i = 0; i < MAX_PDUS; i++) {
        pthread_mutex_init(&pdus[i].lock, NULL);
    }
    pthread_mutex_init(&pdus_lock, NULL);
    pthread_cond_init(&pdus_full, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&pdus_lock);
    while (next_pdu_index == MAX_PDUS) {
        pthread_cond_wait(&pdus_full, &pdus_lock);
    }

    PduEntry* entry = &pdus[next_pdu_index];
    next_pdu_index++;
    pthread_mutex_unlock(&pdus_lock);

    return &entry->pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (int i = 0; i < MAX_PDUS; i++) {
        if (&pdus[i].pdu == pdu) {
            pthread_mutex_lock(&pdus_lock);
            pthread_mutex_lock(&entry->lock);
            next_pdu_index = i;
            pthread_cond_signal(&pdus_full);
            pthread_mutex_unlock(&entry->lock);
            pthread_mutex_unlock(&pdus_lock);
            break;
        }
    }
}

