struct NFAPI_CRC_INDICATION_PDU_T {
    // PDU fields go here
};

class NFAPIModule {
public:
    NFAPIModule(size_t initialCapacity, size_t maxPDUs)
        : capacity(initialCapacity), maxPDUs(maxPDUs), buffer(new NFAPI_CRC_INDICATION_PDU_T[initialCapacity]) {}

    ~NFAPIModule() {
        delete[] buffer;
    }

    void push(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return size < capacity; });
        buffer[size++] = pdu;
        lock.unlock();
        cv.notify_one();
    }

    bool try_pop(NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mutex);
        if (size == 0) {
            return false;
        }
        pdu = buffer[--size];
        return true;
    }

    size_t size() const {
        return size;
    }

private:
    size_t capacity;
    size_t maxPDUs;
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t size = 0;
    std::mutex mutex;
    std::condition_variable cv;
};

class NFAPIMultiThreadedManager {
public:
    NFAPIMultiThreadedManager(size_t initialCapacity, size_t maxPDUs)
        : nfapiModule(initialCapacity, maxPDUs), workerThreads(1) {}

    void start() {
        for (size_t i = 0; i < workerThreads; ++i) {
            workers.emplace_back(&NFAPIMultiThreadedManager::workerLoop, this);
        }
    }

    void stop() {
        running.store(false);
        cv.notify_all();
        for (auto& thread : workers) {
            thread.join();
        }
    }

    void push(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        nfapiModule.push(pdu);
    }

private:
    void workerLoop() {
        while (running.load()) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            if (nfapiModule.try_pop(pdu)) {
                processPDU(pdu);
            }
        }
    }

    void processPDU(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Process PDU logic here
        std::cout << "Processing PDU" << std::endl;
    }

    NFAPIModule nfapiModule;
    std::vector<std::thread> workers;
    std::atomic<bool> running{true};
    std::condition_variable cv;
};

int main() {
    size_t initialCapacity = 1024;
    size_t maxPDUs = 2048;

    NFAPIMultiThreadedManager manager(initialCapacity, maxPDUs);
    manager.start();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    manager.push(pdu);

    manager.stop();
    return 0;
}
