#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>

class EncryptionLibrary {
public:
    static std::string encrypt(const std::string& plaintext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return "";

        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()))) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        std::string ciphertext;
        ciphertext.resize(plaintext.size() + EVP_CIPHER_block_size(EVP_aes_256_gcm()));
        int len;
        if (1 != EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]), &len, reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.size())) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }
        ciphertext.resize(len);

        uint64_t tag_len = 16;
        ciphertext.resize(ciphertext.size() + static_cast<size_t>(tag_len));

        if (1 != EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&ciphertext[ciphertext.size() - tag_len]), &len)) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        EVP_CIPHER_CTX_free(ctx);
        return ciphertext;
    }

    static std::string decrypt(const std::string& ciphertext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return "";

        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()))) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        std::string plaintext;
        plaintext.resize(ciphertext.size() - 16); // Subtract tag length

        int len;
        if (1 != EVP_DecryptUpdate(ctx, reinterpret_cast<unsigned char*>(&plaintext[0]), &len, reinterpret_cast<const unsigned char*>(ciphertext.c_str()), ciphertext.size() - 16)) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }
        plaintext.resize(len);

        uint64_t tag_len = 16;
        if (1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, tag_len, const_cast<unsigned char*>(&ciphertext[ciphertext.size() - tag_len]))) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        int ret;
        if (1 != EVP_DecryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&plaintext[len]), &ret)) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }
        len += ret;

        plaintext.resize(len);
        EVP_CIPHER_CTX_free(ctx);
        return plaintext;
    }

    static std::string generateKey(size_t length = 32) {
        std::string key(length, '\0');
        if (!RAND_bytes(reinterpret_cast<unsigned char*>(key.data()), length)) {
            throw std::runtime_error("Failed to generate random key");
        }
        return key;
    }

    static std::string generateIV() {
        std::string iv(16, '\0');
        if (!RAND_bytes(reinterpret_cast<unsigned char*>(iv.data()), 16)) {
            throw std::runtime_error("Failed to generate IV");
        }
        return iv;
    }
};
