}

void compute_file_hash(const char *file_path, unsigned char hash[MD5_DIGEST_LENGTH]) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) != 0) {
        perror("Failed to get file stats");
        fclose(file);
        return;
    }

    FileHandle handle = {file, 4096, (char*) malloc(4096)};
    unsigned char chunk[4096];
    size_t bytes_read;

    while ((bytes_read = fread(chunk, 1, 4096, file)) > 0) {
        MD5_Update(&context, chunk, bytes_read);
    }

    fclose(file);
    free(handle.buffer);
}

