function traverseDOM(node, selector, predicate) {
    let matches = [];
    if (predicate(node)) {
        if (node.matches(selector)) {
            matches.push(node);
        }
    }
    for (let child of node.children) {
        matches = matches.concat(traverseDOM(child, selector, predicate));
    }
    return matches;
}

