#include <map>

class NetworkStatisticsCollector {
public:
    NetworkStatisticsCollector(size_t numThreads = std::thread::hardware_concurrency())
        : running(true), numThreads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return !running || !tasks.empty(); });
                        if (!running && tasks.empty()) {
                            return;
                        }
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~NetworkStatisticsCollector() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            running = false;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    template <typename T>
    void collect(const std::string& source, const T& metric) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            tasks.emplace([this, source, metric] {
                processMetric(source, metric);
            });
        }
        condition.notify_one();
    }

private:
    void processMetric(const std::string& source, const auto& metric) {
        // Process the metric here
        std::cout << "Processing metric from " << source << ": " << metric << std::endl;
    }

    bool running;
    size_t numThreads;
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
};

int main() {
    NetworkStatisticsCollector collector(4);

    // Example usage
    collector.collect("source1", 10.5);
    collector.collect("source2", 20.3);

    return 0;
}
