  loadPrimitive(primitiveName) {
    if (!this.loadedPrimitives[primitiveName]) {
      try {
        // Dynamically load primitive
        const module = require(`./primitives/${primitiveName}`);
        this.loadedPrimitives[primitiveName] = new module();
      } catch (error) {
