        {
            std::unique_lock<std::mutex> lock(mutex);
            stop_flag = true;
        }
        condition.notify_all();
        for (auto& thread : workers) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void logEvent(const Event& event) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            event_queue.push(event);
        }
        condition.notify_one();
    }

private:
    struct Event {
        // Define the structure of an event
    };

    KafkaClient* kafka_client;
    MQTTClient* mqtt_client;
    RESTClient* rest_client;

    std::vector<std::thread> workers;
    std::queue<Event> event_queue;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop_flag = false;
    int num_threads;

    void workerThread() {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !event_queue.empty() || stop_flag; });
                if (stop_flag && event_queue.empty()) {
                    break;
                }
                event = event_queue.front();
                event_queue.pop();
            }

            // Process the event using Kafka, MQTT, and RESTful clients
            kafka_client->send(event);
            mqtt_client->publish(event);
            rest_client->post(event);
        }
    }
};
