#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int key;
    long offset;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) {
        return NULL;
    }
    collection->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        // Free any resources associated with records if necessary
    }
    free(collection->records);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

bool insert_record(RecordCollection *collection, int key, long offset, int value) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        Record *new_records = (Record*)realloc(collection->records, collection->capacity * 2 * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return false;
        }
        collection->records = new_records;
        collection->capacity *= 2;
    }
    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    collection->records[collection->size].value = value;
    ++collection->size;
    pthread_mutex_unlock(&collection->lock);
    return true;
}

bool update_record(RecordCollection *collection, int key, long offset, int new_value) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key && collection->records[i].offset == offset) {
            collection->records[i].value = new_value;
            pthread_mutex_unlock(&collection->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return false;
}

bool delete_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key && collection->records[i].offset == offset) {
            while (i + 1 < collection->size) {
                collection->records[i] = collection->records[i + 1];
                ++i;
            }
            --collection->size;
            pthread_mutex_unlock(&collection->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return false;
}

Record* find_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key && collection->records[i].offset == offset) {
            Record *record_copy = (Record*)malloc(sizeof(Record));
            if (!record_copy) {
                pthread_mutex_unlock(&collection->lock);
                return NULL;
            }
            *record_copy = collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return record_copy;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}
