#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_RECORDS 1000
#define DEFAULT_CACHE_SIZE 500

typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int size;
    pthread_mutex_t lock;
    int cache_size;
} DataStore;

DataStore data_store;

void init_data_store() {
    memset(&data_store, 0, sizeof(data_store));
    pthread_mutex_init(&data_store.lock, NULL);
}

int add_record(int key, long offset, int value) {
    pthread_mutex_lock(&data_store.lock);
    if (data_store.size >= MAX_RECORDS) {
        pthread_mutex_unlock(&data_store.lock);
        return -1; // Error: Data store is full
    }
    data_store.records[data_store.size].key = key;
    data_store.records[data_store.size].offset = offset;
    data_store.records[data_store.size].value = value;
    data_store.size++;
    pthread_mutex_unlock(&data_store.lock);
    return 0; // Success
}

int get_record(int key, int *value) {
    pthread_mutex_lock(&data_store.lock);
    for (int i = 0; i < data_store.size; i++) {
        if (data_store.records[i].key == key) {
            *value = data_store.records[i].value;
            pthread_mutex_unlock(&data_store.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&data_store.lock);
    return -1; // Error: Record not found
}

int update_record(int key, int new_value) {
    pthread_mutex_lock(&data_store.lock);
    for (int i = 0; i < data_store.size; i++) {
        if (data_store.records[i].key == key) {
            data_store.records[i].value = new_value;
            pthread_mutex_unlock(&data_store.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&data_store.lock);
    return -1; // Error: Record not found
}

int delete_record(int key) {
    pthread_mutex_lock(&data_store.lock);
    for (int i = 0; i < data_store.size; i++) {
        if (data_store.records[i].key == key) {
            for (int j = i; j < data_store.size - 1; j++) {
                data_store.records[j] = data_store.records[j + 1];
            }
            data_store.size--;
            pthread_mutex_unlock(&data_store.lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&data_store.lock);
    return -1; // Error: Record not found
}

void* thread_function(void* arg) {
    int key = *(int*)arg;
    int value;
    if (get_record(key, &value) == 0) {
        printf("Record with key %d has value %d\n", key, value);
    } else {
        printf("Failed to get record with key %d\n", key);
    }
    return NULL;
}

int main() {
    init_data_store();
    add_record(1, 100, 50);
    add_record(2, 200, 75);

    int keys[] = {1, 2, 3};
    pthread_t threads[3];
    for (int i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, thread_function, &keys[i]);
    }

    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

