using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DecryptionLibrary
{
    private readonly ConcurrentDictionary<string, string> _messageCache = new();
    private readonly HttpClient _httpClient;
    private readonly List<TripleDES> _decryptionKeys;
    private int _concurrencyLevel = 4; // Default concurrency level

    public DecryptionLibrary(List<byte[]> keys)
    {
        _decryptionKeys = keys.Select(key => TripleDES.Create()).ToList();
        foreach (var key in _decryptionKeys)
        {
            key.Key = key.IV = key.Key;
        }
        _httpClient = new HttpClient();
    }

    public void SetConcurrencyLevel(int level)
    {
        _concurrencyLevel = Math.Max(1, level);
    }

    public async Task<string> DecryptMessageAsync(string encryptedBase64, CancellationToken cancellationToken = default)
    {
        if (_messageCache.TryGetValue(encryptedBase64, out var decryptedMessage))
        {
            return decryptedMessage;
        }

        try
        {
            using (var memoryStream = new MemoryStream(Convert.FromBase64String(encryptedBase64)))
            {
                var decryptor = _decryptionKeys.OrderBy(key => Guid.NewGuid()).First().CreateDecryptor();
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                using (var reader = new StreamReader(cryptoStream))
                {
                    decryptedMessage = await reader.ReadToEndAsync(cancellationToken);
                }
            }

            _messageCache.TryAdd(encryptedBase64, decryptedMessage);
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            LogError(encryptedBase64, ex);
            throw; // Rethrow for caller to handle
        }
    }

    public async IAsyncEnumerable<string> FetchAndDecryptMessagesAsync(string dataSourceUrl, CancellationToken cancellationToken = default)
    {
        using var response = await _httpClient.GetAsync(dataSourceUrl, HttpCompletionOption.ResponseHeadersRead, cancellationToken);
        response.EnsureSuccessStatusCode();

        var messages = await response.Content.ReadAsAsync<IEnumerable<string>>(cancellationToken);

        var tasks = messages.Select(async message =>
        {
            try
            {
                return await DecryptMessageAsync(message, cancellationToken);
            }
            catch (Exception ex)
            {
                LogError(message, ex);
                return null;
            }
        }).ToList();

        foreach (var task in tasks)
        {
            var decryptedMessage = await task;
            if (decryptedMessage != null)
            {
                yield return decryptedMessage;
            }
        }
    }

    private void LogError(string message, Exception ex)
    {
        Console.WriteLine($"{DateTime.UtcNow}: Message ID: {message.Substring(0, Math.Min(message.Length, 10))}, Error: {ex.Message}");
    }
}

public class Program
{
    public static async Task Main()
    {
        var keys = Enumerable.Range(0, 5).Select(_ => Guid.NewGuid().ToByteArray()).ToList();
        var library = new DecryptionLibrary(keys);
        library.SetConcurrencyLevel(8);

        var messages = await library.FetchAndDecryptMessagesAsync("https://example.com/encrypted-messages", CancellationToken.None);
        foreach (var message in messages)
        {
            Console.WriteLine(message);
        }
    }
}
