public class WeatherService {

    private final ExternalWeatherApi externalWeatherApi;
    private final CityCache cityCache;
    private final ConfigurationService configService;
    private ScheduledExecutorService scheduler;

    public WeatherService(ExternalWeatherApi api, CityCache cache, ConfigurationService config) {
        this.externalWeatherApi = api;
        this.cityCache = cache;
        this.configService = config;
    }

    public void start() {
        scheduler = Executors.newScheduledThreadPool(1);
        long updateInterval = configService.getUpdateInterval();
        scheduler.scheduleAtFixedRate(this::fetchAndCacheWeather, 0, updateInterval, TimeUnit.SECONDS);
    }

    private void fetchAndCacheWeather() {
        try {
            for (String city : configService.getActiveCities()) {
                String weatherData = externalWeatherApi.fetchWeather(city);
                WeatherModel model = new WeatherModel(weatherData);
                cityCache.put(city, model);
            }
        } catch (Exception e) {
            handleFetchError(e);
        }
    }

    private void handleFetchError(Exception e) {
        // Log error and notify administrators
    }

    public void addCity(String city) {
        configService.addActiveCity(city);
    }

    public void removeCity(String city) {
        configService.removeActiveCity(city);
        cityCache.invalidate(city);
    }

    public WeatherModel getWeatherForCity(String city) {
        return cityCache.get(city);
    }

    public void clearCache() {
        cityCache.clear();
    }

    public void clearCityCache(String city) {
        cityCache.invalidate(city);
    }

    public void stop() {
        scheduler.shutdownNow();
    }
}
