    void start() {
        running.store(true);
        for (auto& [_, service] : services) {
            std::thread([this, &service]() { collect_metrics(service); }).detach();
        }
    }

    void stop() {
        running.store(false);
        for (auto& [_, cv] : condition_variables) {
            cv.notify_all();
        }
    }

private:
    NetworkMetrics() {}

    struct Service {
        std::string name;
        // External API or service details
    };

    std::unordered_map<std::string, Service> services;
    std::unordered_map<std::string, std::condition_variable> condition_variables;
    std::atomic<bool> running{false};

    void collect_metrics(Service& service) {
        while (running.load()) {
            // Collect metrics using high-resolution timer and rolling window approach
            auto start = std::chrono::high_resolution_clock::now();
            // Simulate metric collection
            // ...
            auto end = std::chrono::high_resolution_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

            // Handle errors and edge cases
            try {
                // Process collected metrics
                // ...
            } catch (const std::exception& e) {
                std::cerr << "Error collecting metrics for service " << service.name << ": " << e.what() << std::endl;
            }

            if (duration < std::chrono::milliseconds(10)) {
                std::this_thread::sleep_for(std::chrono::milliseconds(10) - duration);
