class NFAPIManager {
public:
    NFAPIManager(size_t maxPdus, size_t M)
        : maxPdus_(maxPdus), M_(M), isRunning_(true) {
        for (size_t i = 0; i < maxPdus_; ++i) {
            pdus_.emplace_back(std::make_shared<NFAPI_CRC_INDICATION_PDU_T>());
        }
        startThreads();
    }

    ~NFAPIManager() {
        stop();
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void processPdu(std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T> pdu) {
        std::unique_lock<std::mutex> lock(mutex_);
        pdusQueue_.push(pdu);
        cv_.notify_one();
    }

private:
    size_t maxPdus_;
    size_t M_;
    bool isRunning_;
    std::queue<std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> pdusQueue_;
    std::vector<std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> pdus_;
    std::vector<std::thread> threads_;
    std::mutex mutex_;
    std::condition_variable cv_;

    void startThreads() {
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            threads_.emplace_back(&NFAPIManager::worker, this);
        }
    }

    void stop() {
        isRunning_ = false;
        cv_.notify_all();
    }

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !pdusQueue_.empty() || !isRunning_; });
            if (!isRunning_) break;

            auto pdu = pdusQueue_.front();
            pdusQueue_.pop();

            lock.unlock();
            processPduInternal(pdu);
        }
    }

    void processPduInternal(std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T> pdu) {
        // Process PDU here, including encryption/decryption and other operations
