['```rust
use tokio::sync::RwLock;
use std::collections::{HashMap, HashSet};
use std::hash::{Hash, Hasher};
use sha2::{Sha256, Digest};

#[derive(Clone)]
struct CacheKey<K> {
    key: K,
}

impl<K> CacheKey<K>
where
    K: Eq + Hash + Clone,
{
    fn new(key: K) -> Self {
        CacheKey { key }
    }

    fn hash(&self) -> u64 {
        let mut hasher = Sha256::new();
        hasher.update(self.key);
        let result = hasher.finalize();
        u64::from_le_bytes(result[0..8].try_into().unwrap())
    }
}

struct Node<K, V> {
    id: usize,
    data: HashMap<CacheKey<K>, V>,
}

impl<K, V> Node<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    fn new(id: usize) -> Self {
        Node {
            id,
            data: HashMap::new(),
        }
    }

    async fn get(&self, key: CacheKey<K>) -> Option<V> {
        self.data.get(&key).cloned()
    }

    async fn set(&mut self, key: CacheKey<K>, value: V) {
        self.data.insert(key, value);
    }

    async fn invalidate(&mut self, key: CacheKey<K>) {
        self.data.remove(&key);
    }
}

struct DistributedCache<K, V> {
    nodes: Vec<Node<K, V>>,
    ring: HashMap<u64, usize>,
}

impl<K, V> DistributedCache<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    fn new(nodes: Vec<Node<K, V>>) -> Self {
        let mut ring = HashMap::new();
        for (i, node) in nodes.iter().enumerate() {
            for key in node.data.keys() {
                let hash = key.hash();
                ring.insert(hash, i);
            }
        }
        DistributedCache { nodes, ring }
    }

    async fn get(&self, key: CacheKey<K>) -> Option<V> {
        if let Some(node_id) = self.ring.get(&key.hash()) {
            self.nodes[*node_id].get(key.clone()).await
        } else {
            None
        }
    }

    async fn set(&mut self, key: CacheKey<K>, value: V) {
        if let Some(node_id) = self.ring.get_mut(&key.hash()) {
            self.nodes[*node_id].set(key.clone(), value).await;
        }
    }

    async fn invalidate(&mut self, key: CacheKey<K>) {
        if let Some(node_id) = self.ring.get_mut(&key.hash()) {
            self.nodes[*node_id].invalidate(key.clone()).await;
        }
    }
}

#[tokio::main]
async fn main() {
    // Example usage
    let mut nodes = vec![
        Node::new(0),
        Node::new(1),
        Node::new(2),
    ];

    // Populate nodes with some data
    nodes[0].set(CacheKey::new("key1"), "value1").await;
    nodes[1].set(CacheKey::new("key2"), "value2").await;
    nodes[2].set(CacheKey::new("key3"), "value3").await;

    let cache = DistributedCache::new(nodes);

    // Get data from the cache
    if let Some(value) = cache.get(CacheKey::new("key1")).await {
        println!("Value: {}", value);
    }

    // Set new data in the cache
    cache.set(CacheKey::new("key4"), "value4").await;

    // Invalidate some data
    cache.invalidate(CacheKey::new("key2")).await;
}
```

This code provides a basic structure for a distributed caching system using Tokio for asynchronous operations. It includes a `CacheKey` to hash keys, a `Node` to store and manage data, and a `DistributedCache` to distribute data across nodes using consistent hashing. The example usage at the end demonstrates how to interact with the cache.

Note that this code is simplified and does not include all the features and considerations mentioned in your requirements, such as authentication, authorization, RESTful API, comprehensive logging, and optimizations for scalability.']

