class LogProcessor {
public:
    LogProcessor(int numLines, std::string outputFormat)
        : numLines(numLines), outputFormat(outputFormat), stop(false) {}

    void start(const std::vector<std::string>& filePaths) {
        for (const auto& path : filePaths) {
            workers.emplace_back(&LogProcessor::processFile, this, path);
        }
        for (auto& worker : workers) {
            worker.join();
        }
    }

private:
    int numLines;
    std::string outputFormat;
    bool stop;
    std::vector<std::thread> workers;

    void processFile(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filePath << std::endl;
            return;
        }

        // Read and process log lines asynchronously
        while (true) {
            std::string line;
            std::getline(file, line);
            if (stop || file.eof() && file.fail()) break;

            // Process the log line here
            std::cout << "Processing: " << line << std::endl;

            // Handle external requests using HTTPClientLib
            HTTPClientLib client;
            client.setURL("http://example.com/api/endpoint");
            client.setHeader("Content-Type", "application/json");
            client.setRequestMethod(HTTPClientLib::HTTP_POST);
            client.setData("{\"logLine\":\"" + line + "\"}");
            HTTPResponse response = client.sendRequest();
            if (response.getStatusCode() != 200) {
                std::cerr << "Failed to send request: " << response.getErrorMessage() << std::endl;
            }
        }

        file.close();
    }
};

