use actix actor::{Actor, Context};
use actix_web::{web, App, HttpServer, Responder};
use futures::stream::StreamExt;
use tokio::sync::mpsc;
use tokio_postgres::NoTls;

struct DataProcessor {
    db_client: tokio_postgres::Client,
    message_queue_url: String,
}

impl Actor for DataProcessor {
    type Context = Context<Self>;

    fn started(&mut self, ctx: &mut Self::Context) {
        // Connect to database and subscribe to API stream
        let (tx, mut rx) = mpsc::channel(32);
        tokio::spawn(async move {
            let (client, connection) =
                tokio_postgres::connect("host=localhost user=postgres password=secret dbname=test", NoTls)
                    .await.unwrap();
            ctx.spawn(DataProcessor { db_client: client, message_queue_url: "".to_string() })
                .start();

            // Simulate API stream
            let api_stream = async_stream::stream! {
                for i in 0..1_000_000_000 {
                    yield i;
                }
            };

            // Process API data
            while let Some(data) = api_stream.next().await {
                tx.send(data).unwrap();
            }
        });
    }

    fn stopping(&mut self, _ctx: &mut Self::Context) -> Running {
        Running::Stop
    }
}

#[actix_web::main]
