    this.refreshFields = function(resourceId, url, fields) {
      var refreshInterval = 1000; // 1 second
      var intervalPromise;

      this.startRefresh = function() {
        intervalPromise = $timeout(function() {
          ResourceService.fetchData(resourceId, url)
            .then(function(data) {
              angular.forEach(fields, function(field) {
                field.value = data[field.key];
              });
              this.startRefresh();
            }.bind(this))
            .catch(function(error) {
              console.error('Error fetching data:', error);
              this.stopRefresh();
            }.bind(this));
        }, refreshInterval);
      };

      this.stopRefresh = function() {
        $timeout.cancel(intervalPromise);
      };
    };
  }])
  .controller('DialogController', ['DialogService', function(DialogService) {
    var vm = this;
    vm.fields = [
      { key: 'name', value: '' },
      { key: 'email', value: '' }
    ];

