const { ModuleManager } = require('./module-manager');

const app = express();
const moduleManager = new ModuleManager();

app.use(bodyParser.json());

app.post('/modules', async (req, res) => {
  const { module } = req.body;
  try {
    await moduleManager.loadModule(module);
    res.status(201).send({ message: 'Module loaded successfully' });
  } catch (error) {
    res.status(500).send({ error: 'Failed to load module', details: error.message });
  }
});

app.get('/modules', async (req, res) => {
  try {
    const modules = await moduleManager.getLoadedModules();
    res.status(200).json(modules);
  } catch (error) {
    res.status(500).send({ error: 'Failed to retrieve modules', details: error.message });
  }
});

app.put('/modules/:id', async (req, res) => {
  const { id } = req.params;
  const { module } = req.body;
  try {
    await moduleManager.updateModule(id, module);
    res.status(200).send({ message: 'Module updated successfully' });
  } catch (error) {
    res.status(500).send({ error: 'Failed to update module', details: error.message });
  }
});

app.delete('/modules/:id', async (req, res) => {
  const { id } = req.params;
  try {
    await moduleManager.unloadModule(id);
    res.status(200).send({ message: 'Module unloaded successfully' });
  } catch (error) {
    res.status(500).send({ error: 'Failed to unload module', details: error.message });
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
