// Define a template class for dynamic collections of records
template <typename KeyType, typename ValueType>
class DynamicRecordCollection {
private:
    struct Record {
        KeyType key;
        long offset;
        ValueType value;
    };

    std::unordered_map<KeyType, Record> records;
    std::mutex mutex;

public:
    // Constructor with initial capacity
    DynamicRecordCollection(size_t initialCapacity) : records(initialCapacity) {}

    // Function to insert a record with validation checks
    bool insert(KeyType key, long offset, ValueType value) {
        std::lock_guard<std::mutex> lock(mutex);
        if (records.find(key) != records.end()) return false; // Key already exists
        records[key] = {key, offset, value};
        return true;
    }

    // Function to update a record with validation checks
    bool update(KeyType key, long newOffset, ValueType newValue) {
        std::lock_guard<std::mutex> lock(mutex);
        if (records.find(key) == records.end()) return false; // Key does not exist
        records[key].offset = newOffset;
        records[key].value = newValue;
        return true;
    }

    // Function to delete a record with validation checks
    bool erase(KeyType key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (records.find(key) == records.end()) return false; // Key does not exist
        records.erase(key);
        return true;
    }

    // Function to retrieve a value by key and offset
    ValueType getValueByKeyAndOffset(KeyType key, long offset) {
        std::lock_guard<std::mutex> lock(mutex);
        if (records.find(key) == records.end()) throw std::runtime_error("Key not found");
        if (records[key].offset != offset) throw std::runtime_error("Invalid offset");
        return records[key].value;
    }
};
```

