use reqwest::{Client, Certificate, Identity};
use std::time::Duration;
use tracing::{info, error};

// Define a trait for the API client
trait HttpClient {
    fn get(&self, url: &str) -> Result<String>;
    fn post(&self, url: &str, body: String) -> Result<String>;
}

// Implement the HttpClient trait for a custom HTTP client
struct CustomHttpClient {
    client: Client,
}

impl CustomHttpClient {
    // Create a new instance of CustomHttpClient with optional certificate validation and customizable timeouts
    fn new(validate_cert: bool, timeout: Duration) -> Self {
        let mut builder = Client::builder().timeout(timeout);

        if validate_cert {
            // Load the CA certificates from file (e.g., "path/to/cacert.pem")
            let cert = Certificate::from_pem(include_bytes!("path/to/cacert.pem")).unwrap();
            builder = builder.add_root_certificate(cert);
        } else {
            builder = builder.dangerously_disable_hostname_verification().disable_http2();
        }

        Self {
            client: builder.build().unwrap(),
        }
    }

    // Retry logic for transient failures
    async fn retry_request<F>(&self, url: &str, body: Option<String>, max_retries: u32) -> Result<String>
    where
        F: FnOnce(&Client, &str, Option<&String>) -> reqwest::Result<reqwest::Response>,
    {
        for attempt in 0..max_retries + 1 {
            match (attempt, body.as_ref()) {
                (_, None) => {
                    info!("Attempting GET request to {}", url);
                    let response = self.client.get(url).send().await?;
                    if response.status().is_success() {
                        return response.text().await.map_err(|e| e.into());
                    }
                }
                (0, Some(body)) => {
                    info!("Attempting POST request to {} with body {:?}", url, body);
                    let response = self.client.post(url).body(body.clone()).send().await?;
                    if response.status().is_success() {
                        return response.text().await.map_err(|e| e.into());
                    }
                }
                (retry_count, Some(body)) => {
                    info!("Retrying POST request to {} with body {:?} (attempt {}/{})", url, body, retry_count + 1, max_retries);
                    let response = self.client.post(url).body(body.clone()).send().await?;
                    if response.status().is_success() {
                        return response.text().await.map_err(|e| e.into());
                    }
                }
            }

            // Implement exponential backoff strategy
            tokio::time::sleep(Duration::from_millis(2_u32.pow(attempt))).await;
        }

        error!("Max retries reached for request to {}", url);
        Err(reqwest::Error::new(reqwest::ErrorKind::TimedOut, "Request timed out"))
    }
}

// Implement the HttpClient trait for CustomHttpClient
impl HttpClient for CustomHttpClient {
    fn get(&self, url: &str) -> Result<String> {
        self.retry_request(url, None, 3).await
    }

    fn post(&self, url: &str, body: String) -> Result<String> {
        self.retry_request(url, Some(body), 3).await
    }
}
