from flask import Flask, request, jsonify
from functools import wraps
import requests
from ratelimiter import RateLimiter
import redis
import time

app = Flask(__name__)
cache = redis.Redis(host='localhost', port=6379, db=0)
rate_limiter = RateLimiter(max_calls=100, period=60)

def cache_key(*args):
    return "weather_data:" + ":".join(str(a) for a in args)

@app.route('/weather', methods=['GET'])
@rate_limiter
def fetch_weather_data():
    lat = request.args.get('lat')
    lon = request.args.get('lon')
    time_range = request.args.get('time_range')
    granularity = request.args.get('granularity')
    unit_system = request.args.get('unit_system')

    cache_key_value = cache_key(lat, lon, time_range, granularity, unit_system)
    data = cache.get(cache_key_value)

    if data:
        return jsonify(data.decode('utf-8'))

    try:
        response = requests.get(f'https://api.weather.com/forecast?lat={lat}&lon={lon}&time_range={time_range}&granularity={granularity}&unit_system={unit_system}', timeout=5)
        response.raise_for_status()
        data = response.json()

        cache.setex(cache_key_value, 3600, json.dumps(data))
        return jsonify(data)

    except requests.exceptions.RequestException as e:
        # Fallback mechanism can be implemented here
        return jsonify({'error': 'Service Unavailable'}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
