    value: f64,
}

struct NetworkMetricsAggregator {
    config_manager: ConfigManager,
    data_processing_framework: DataProcessingFramework,
}

impl NetworkMetricsAggregator {
    fn new() -> Self {
        Self {
            config_manager: ConfigManager::new(),
            data_processing_framework: DataProcessingFramework::new(),
        }
    }

    async fn process_metrics(&self) -> Result<Vec<Metric>, reqwest::Error> {
        let metrics = self.config_manager.fetch_metrics().await?;
        let processed_data = self.data_processing_framework.process(metrics).await?;
        Ok(processed_data)
    }
}

struct ConfigManager {
    client: reqwest::Client,
    base_url: String,
}

impl ConfigManager {
    fn new() -> Self {
        Self {
            client: reqwest::Client::new(),
            base_url: "https://api.example.com".to_string(),
        }
    }

    async fn fetch_metrics(&self) -> Result<Vec<Metric>, reqwest::Error> {
        let response = self.client.get(format!("{}/metrics", self.base_url)).send().await?;
        if response.status().is_success() {
            Ok(response.json::<Vec<Metric>>().await?)
        } else {
            Err(reqwest::Error::from_status(response.status()))
        }
    }
}

struct DataProcessingFramework {
    tasks: Arc<Mutex<VecDeque<task::JoinHandle<Metric>>>>,
}

impl DataProcessingFramework {
    fn new() -> Self {
        Self {
            tasks: Arc::new(Mutex::new(VecDeque::new())),
        }
    }

    async fn process(&self, metrics: Vec<Metric>) -> Result<Vec<Metric>, reqwest::Error> {
        let mut results = Vec::new();
        for metric in metrics {
            let task = task::spawn(async move {
                // Simulate data processing
                Metric {
                    name: metric.name,
                    value: metric.value * 1.1, // Example transformation
                }
            });
            self.tasks.lock().unwrap().push_back(task);
        }

        while !self.tasks.lock().unwrap().is_empty() {
            if let Some(task) = self.tasks.lock().unwrap().pop_front() {
                results.push(task.await?);
            }
        }

        Ok(results)
    }
}

