    CacheManager cacheManager;
    EncryptionModule encryptionModule;
    ErrorHandlingFramework errorHandler;
    HardwareAcceleration hardwareAccel;
    StorageAdapter storageAdapter;
    MonitoringSystem monitoring;

    std::thread workerThread;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    std::queue<std::pair<std::string, std::vector<std::byte>>> dataQueue;
    bool running = false;
};

// DynamicMetricsAggregator.cpp
#include "DynamicMetricsAggregator.h"

void DataCollector::collectData(const std::string& source, const std::vector<std::byte>& data) {
