    // Implementation details
}

MonitoringSystem::monitorResources() {
    // Implementation details
}

void DynamicMetricsAggregator::start() {
    running = true;
    workerThread = std::thread([this]() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataCondition.wait(lock, [this] { return !dataQueue.empty() || !running; });
            if (!running && dataQueue.empty()) break;

            auto data = dataQueue.front();
            dataQueue.pop();

            lock.unlock();
            collector.collectData(data.first, data.second);
            processData(data.second);
        }
    });
}

void DynamicMetricsAggregator::stop() {
    running = false;
    dataCondition.notify_all();
    if (workerThread.joinable()) workerThread.join();
}

void DynamicMetricsAggregator::addData(const std::string& source, const std::vector<std::byte>& data) {
    std::lock_guard<std::mutex> lock(queueMutex);
    dataQueue.push({source, data});
    dataCondition.notify_one();
}

void DynamicMetricsAggregator::configureEncryption(EncryptionMode mode) {
    encryptionModule.configure(mode);
}
