// DynamicSpatialIndexManager.h
#pragma once

#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>

class DynamicSpatialIndexManager {
public:
    void insertEntry(const std::string& entry);
    void updateEntry(const std::string& oldEntry, const std::string& newEntry);
    void deleteEntry(const std::string& entry);
    bool searchEntry(const std::string& entry);

private:
    std::vector<std::string> entries;
    std::mutex mutex_;
    std::condition_variable cv_;
};

// DynamicSpatialIndexManager.cpp
#include "DynamicSpatialIndexManager.h"

void DynamicSpatialIndexManager::insertEntry(const std::string& entry) {
    std::unique_lock<std::mutex> lock(mutex_);
    entries.push_back(entry);
    cv_.notify_all();
}

void DynamicSpatialIndexManager::updateEntry(const std::string& oldEntry, const std::string& newEntry) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = std::find(entries.begin(), entries.end(), oldEntry);
    if (it != entries.end()) {
        *it = newEntry;
    }
    cv_.notify_all();
}

void DynamicSpatialIndexManager::deleteEntry(const std::string& entry) {
    std::unique_lock<std::mutex> lock(mutex_);
    entries.erase(std::remove(entries.begin(), entries.end(), entry), entries.end());
    cv_.notify_all();
}

bool DynamicSpatialIndexManager::searchEntry(const std::string& entry) {
    std::unique_lock<std::mutex> lock(mutex_);
