// EventLoggingSystem.java

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.HashMap;
import java.util.Map;

public class EventLoggingSystem {
    private final ExecutorService workerPool;
    private final Map<String, LinkedBlockingQueue<Event>> queues;
    private final Map<String, APIHandler> apiHandlers;

    public EventLoggingSystem(int numWorkers) {
        this.workerPool = Executors.newFixedThreadPool(numWorkers);
        this.queues = new HashMap<>();
        this.apiHandlers = new HashMap<>();

        // Initialize event queues
        for (String eventType : EventTypes.getAllEventTypes()) {
            queues.put(eventType, new LinkedBlockingQueue<>());
        }

        // Initialize API handlers with adaptive retry policies
        for (APIConfig config : APIConfigs.getAllAPIConfigs()) {
            apiHandlers.put(config.getAPIName(), new APIHandler(config));
        }
    }

    public void logEvent(Event event) {
        String eventType = event.getType();
        LinkedBlockingQueue<Event> queue = queues.get(eventType);
        if (queue != null) {
            try {
                queue.put(event);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public void processEvents() {
        workerPool.submit(() -> {
            for (LinkedBlockingQueue<Event> queue : queues.values()) {
                while (!Thread.currentThread().isInterrupted()) {
                    try {
                        Event event = queue.take();
                        String eventType = event.getType();
                        APIHandler handler = apiHandlers.get(eventType);
                        if (handler != null) {
                            handler.processEvent(event);
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        });
    }

    public void scaleWorkers(int newSize) {
        workerPool.shutdownNow();
        this.workerPool = Executors.newFixedThreadPool(newSize);
        processEvents();
    }

    // Other methods for handling cache, security, machine learning models, and alerting system
}

