// CloudStorageManager to manage storage operations across providers
public class CloudStorageManager {
    private Map<String, CloudStorage> storageProviders;
    private CacheManager cacheManager;
    private DataTransferProtocol dataTransferProtocol;

    public CloudStorageManager() {
        this.storageProviders = new HashMap<>();
        this.cacheManager = new CacheManager();
        this.dataTransferProtocol = new DataTransferProtocol();
    }

    public void addProvider(String providerName, CloudStorage provider) {
        storageProviders.put(providerName, provider);
    }

    public void uploadFile(String filePath, String providerName) {
        if (cacheManager.retrieveCache(filePath) != null) {
            // Use cached data
        } else {
            CloudStorage provider = storageProviders.get(providerName);
            provider.upload(filePath);
            cacheManager.cacheData(filePath, provider.listObjects());
        }
    }

    public void downloadFile(String objectKey, String destinationPath, String providerName) {
        if (cacheManager.retrieveCache(objectKey) != null) {
            // Use cached data
        } else {
            CloudStorage provider = storageProviders.get(providerName);
            provider.download(objectKey, destinationPath);
            cacheManager.cacheData(objectKey, provider.listObjects());
        }
    }

    public void deleteFile(String objectKey, String providerName) {
        CloudStorage provider = storageProviders.get(providerName);
        provider.delete(objectKey);
        cacheManager.cacheData(objectKey, null); // Invalidate cache
    }

    public List<String> listFiles(String providerName) {
        CloudStorage provider = storageProviders.get(providerName);
        return provider.listObjects();
    }
}

// RESTful API for programmatic interaction
@RestController
public class CloudStorageController {
    @Autowired
    private CloudStorageManager cloudStorageManager;

    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("filePath") String filePath, @RequestParam("providerName") String providerName) {
        cloudStorageManager.uploadFile(filePath, providerName);
        return ResponseEntity.ok("File uploaded successfully");
    }

    @GetMapping("/download")
    public ResponseEntity<Resource> downloadFile(@RequestParam("objectKey") String objectKey, @RequestParam("destinationPath") String destinationPath, @RequestParam("providerName") String providerName) {
        cloudStorageManager.downloadFile(objectKey, destinationPath, providerName);
        // Return file as Resource
        return ResponseEntity.ok().body(null);
    }

    @DeleteMapping("/delete")
    public ResponseEntity<String> deleteFile(@RequestParam("objectKey") String objectKey, @RequestParam("providerName") String providerName) {
        cloudStorageManager.deleteFile(objectKey, providerName);
        return ResponseEntity.ok("File deleted successfully");
    }
}
