use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use std::time::Duration;
use serde_json::Value;

#[derive(Clone)]
struct PaymentGateway {
    name: String,
    max_requests_per_second: u32,
}

async fn process_request(
    request: Value,
    payment_gateways: Vec<PaymentGateway>,
) -> Result<(), String> {
    // Simulate processing with rate limiting and retry logic
    let gateway = payment_gateways.iter().find(|g| g.name == "Example");
    if let Some(gateway) = gateway {
        if !rate_limit::check(gateway.max_requests_per_second, Duration::from_secs(1)) {
            return Err("Rate limit exceeded".to_string());
        }
        // Simulate external call with retry logic
        match retry::call(|| validate_payment(request.clone())) {
            Ok(_) => Ok(()),
            Err(_) => Err("Payment validation failed".to_string()),
        }
    } else {
        Err("Gateway not found".to_string())
    }
}

async fn handle_connection(mut stream: TcpStream) {
    let mut reader = tokio::io::BufReader::new(&stream);
    let mut buffer = String::new();
    loop {
        match reader.read_line(&mut buffer).await {
            Ok(0) => break,
            Ok(_) => {
                if let Some(request) = parse_request(&buffer) {
                    if let Err(e) = process_request(request, payment_gateways.clone()).await {
                        println!("Request failed: {}", e);
                    }
                    buffer.clear();
                }
            },
            Err(e) => {
                eprintln!("Error reading from stream: {:?}", e);
                break;
            },
        }
    }
}

#[tokio::main]
async fn main() {
    let payment_gateways = vec![
        PaymentGateway {
            name: "Example".to_string(),
            max_requests_per_second: 20,
        },
        // Add more gateways as needed
    ];

    let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();
    println!("Listening on {}", listener.local_addr().unwrap());

    loop {
        match listener.accept().await {
            Ok((stream, addr)) => {
                tokio::spawn(async move {
                    handle_connection(stream).await;
                });
            },
            Err(e) => {
                eprintln!("Error accepting connection: {:?}", e);
            },
        }
    }
}
```

