      this.loadPrimitive(algorithm);
    }

    const startTime = Date.now();
    const result = await this.cryptoPrimitives[algorithm].process(transactionData);
    const endTime = Date.now();

    this.metrics.throughput++;
    this.metrics.latency += (endTime - startTime);

    return result;
  }

