using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

public class WebApiService : IHostedService
{
    private readonly ILogger<WebApiService> _logger;
    private readonly string _serverUrl;
    private readonly int[] _portRange;
    private int? _selectedPort;

    public WebApiService(ILogger<WebApiService> logger, IConfiguration configuration)
    {
        _logger = logger;
        _serverUrl = configuration["ServerUrl"];
        _portRange = Array.ConvertAll(configuration["PortRange"].Split(','), int.Parse);
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        for (int port = _portRange[0]; port <= _portRange[1]; port++)
        {
            if (!await IsPortInUse(_serverUrl, port))
            {
                _selectedPort = port;
                await LaunchWebApiEndpoint();
                return;
            }
        }

        _logger.LogError("No available ports in the specified range.");
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        // Cleanup code here
    }

    private async Task<bool> IsPortInUse(string serverUrl, int port)
    {
        using (var client = new HttpClient())
        {
            try
            {
                var response = await client.GetAsync($"http://{serverUrl}:{port}/health");
                return response.IsSuccessStatusCode;
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Failed to check port availability.");
                return true;
            }
        }
    }

    private async Task LaunchWebApiEndpoint()
    {
        var builder = WebApplication.CreateBuilder(new WebApplicationOptions
        {
            ContentRootPath = Directory.GetCurrentDirectory(),
            EnvironmentName = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production"
        });

        builder.Services.AddControllers();
        builder.Services.AddEndpointsApiExplorer();

        var app = builder.Build();

        if (app.Environment.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.MapControllers();

        await app.ListenAsync(new System.Net.IPAddress(0), _selectedPort.Value);

        _logger.LogInformation($"Web API endpoint launched on port {_selectedPort}");
    }
}
