pthread_mutex_t dbMutex = PTHREAD_MUTEX_INITIALIZER;
sqlite3 *dbConnection = NULL;

void* generateAndPersistNfapiPdus(void* arg) {
    int n = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_STRUCTS];

    for (int i = 0; i < n; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        pdus[i].RNTI = rand() % 16384;
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 'A' : 'B';
        pdus[i].CRCFLAG = rand();
    }

    pthread_mutex_lock(&dbMutex);
    for (int i = 0; i < n; i += BATCH_SIZE) {
        int batchSize = (i + BATCH_SIZE > n) ? (n - i) : BATCH_SIZE;

        char sql[1024 * batchSize];
        snprintf(sql, sizeof(sql), "INSERT INTO nfapi_pdu_table (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES ");

        for (int j = 0; j < batchSize; j++) {
            if (j > 0) snprintf(sql + strlen(sql), sizeof(sql) - strlen(sql), ", ");
            snprintf(sql + strlen(sql), sizeof(sql) - strlen(sql), "(%d, %d, '%c', %d)",
                     pdus[i + j].RX_UE_INFORMATION_TAG,
                     pdus[i + j].RNTI,
                     pdus[i + j].CRC_INDICATION_REL8_TAG,
                     pdus[i + j].CRCFLAG);
        }

        sqlite3_stmt *stmt;
        int rc = sqlite3_prepare_v2(dbConnection, sql, -1, &stmt, NULL);
        if (rc != SQLITE_OK) {
            // Handle error
        } else {
            while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
                // Process result
            }
            sqlite3_finalize(stmt);
        }
    }
    pthread_mutex_unlock(&dbMutex);

    return NULL;
}

int main() {
    int N = 1000000;
    pthread_t thread;

    if (sqlite3_open("nfapi.db", &dbConnection) != SQLITE_OK) {
        // Handle error
    }

    pthread_create(&thread, NULL, generateAndPersistNfapiPdus, (void*)&N);
    pthread_join(thread, NULL);

    sqlite3_close(dbConnection);

    return 0;
}
