#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_RETRIES 3
#define RETRY_DELAY_BASE_MS 100

typedef struct {
    char *client_id;
    char *client_secret;
} Config;

typedef struct {
    pthread_mutex_t lock;
    Config config;
} TokenValidationService;

void load_config(TokenValidationService *service) {
    // Implement secure configuration reload mechanism
}

int validate_token(const char *token, const Config *config) {
    CURL *curl;
    CURLcode res;
    int retries = 0;
    int status_code = -1;

    while (retries < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_URL, "https://api.tokenverify.com/validate");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, token);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_USERPWD, (const char *)config->client_id ":" config->client_secret);

            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                sleep(RETRY_DELAY_BASE_MS * pow(2, retries) / 1000); // Exponential backoff
                retries++;
            } else {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                status_code = (int)response_code;
                break;
            }
        }
        curl_global_cleanup();
    }

    return status_code == 200 ? 1 : 0; // Return 1 for valid token, 0 otherwise
}

void *token_validation_thread(void *arg) {
    TokenValidationService *service = (TokenValidationService *)arg;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        pthread_mutex_lock(&service->lock);
        load_config(service); // Reload config if necessary
        pthread_mutex_unlock(&service->lock);

        int is_valid = validate_token(buffer, &service->config);
        printf("Token %s: %d\n", buffer, is_valid);
    }
    return NULL;
}

int main() {
    TokenValidationService service;
    pthread_t thread;

    pthread_mutex_init(&service.lock, NULL);
    load_config(&service);

    if (pthread_create(&thread, NULL, token_validation_thread, &service) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);

    pthread_mutex_destroy(&service.lock);

    return 0;
}
