import java.util.Arrays;

public class DisjointPairsChecker {
    private int[] parent;
    private int[] rank;

    public DisjointPairsChecker(int size) {
        this.parent = new int[size];
        this.rank = new int[size];
        initialize(size);
    }

    private void initialize(int n) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public boolean areDisjoint(int x, int y) {
        long startTime = System.currentTimeMillis();
        return find(x) != find(y);
    }

    public static void main(String[] args) {
        DisjointPairsChecker checker = new DisjointPairsChecker(10);
        checker.union(0, 1);
        checker.union(2, 3);

        int[][] pairs = {
            {0, 2}, {1, 3}, {4, 5}
        };

        for (int[] pair : pairs) {
            long startTime = System.currentTimeMillis();
            boolean result = checker.areDisjoint(pair[0], pair[1]);
            long endTime = System.currentTimeMillis();
            System.out.println("Pair (" + pair[0] + ", " + pair[1] + ") is disjoint: " + result);
            System.out.println("Time taken: " + (endTime - startTime) + " ms");
        }
    }
}
