    {
        _hashFunctions = new Dictionary<HashAlgorithmType, Func<string, HashAlgorithm>>
        {
            { HashAlgorithmType.MD5, MD5.Create },
            { HashAlgorithmType.SHA1, SHA1.Create },
            { HashAlgorithmType.SHA256, SHA256.Create },
            { HashAlgorithmType.SHA512, SHA512.Create },
            { HashAlgorithmType.BLAKE2, () => new Blake2b() }, // Assuming a custom implementation of Blake2b
            { HashAlgorithmType.Keccak, () => new Keccak() } // Assuming a custom implementation of Keccak
        };
    }

    public string ComputeHash(string data, HashAlgorithmType algorithm)
    {
        using (var hashAlgorithm = _hashFunctions[algorithm](data))
        {
            var hashBytes = hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(data));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public byte[] ComputeHash(byte[] data, HashAlgorithmType algorithm)
    {
        using (var hashAlgorithm = _hashFunctions[algorithm](data))
