['```java
import java.security.Key;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.apache.log4j.Logger;

public class CryptoService {
    private static final Logger logger = Logger.getLogger(CryptoService.class);

    public String encrypt(String data, String key, String algorithm, int mode) throws Exception {
        Key secretKey = new SecretKeySpec(key.getBytes(), algorithm);
        Cipher cipher = Cipher.getInstance(algorithm + "/" + getMode(mode));
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        byte[] encryptedBytes = cipher.doFinal(data.getBytes());
        return bytesToHex(encryptedBytes);
    }

    public String decrypt(String encryptedData, String key, String algorithm, int mode) throws Exception {
        Key secretKey = new SecretKeySpec(key.getBytes(), algorithm);
        Cipher cipher = Cipher.getInstance(algorithm + "/" + getMode(mode));
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] decryptedBytes = cipher.doFinal(hexToBytes(encryptedData));
        return new String(decryptedBytes);
    }

    private String getMode(int mode) {
        switch (mode) {
            case 1: return "ECB";
            case 2: return "EDE";
            case 3: return "EDE3";
            case 4: return "CFB";
            default: throw new IllegalArgumentException("Invalid mode");
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }

    private byte[] hexToBytes(String hex) {
        int len = hex.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                                 + Character.digit(hex.charAt(i+1), 16));
        }
        return data;
    }

    public static void main(String[] args) {
        CryptoService service = new CryptoService();
        try {
            String key = "0123456789abcdef";
            String data = "SensitiveData";
            String encrypted = service.encrypt(data, key, "AES", 2);
            logger.info("Encrypted: " + encrypted);

            String decrypted = service.decrypt(encrypted, key, "AES", 2);
            logger.info("Decrypted: " + decrypted);
        } catch (Exception e) {
            logger.error("CryptoService Error", e);
        }
    }
}
