#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <redis.h>

typedef enum {
    ACTIVE,
    INACTIVE
} ConnectionState;

typedef struct {
    char UEIdentifier[20];
    char RANNodeIdentifier[20];
    ConnectionState state;
} SessionStatus;

typedef struct {
    SessionStatus session;
    time_t lastUpdated;
} CachedSession;

CachedSession* sessions = NULL;
int sessionCount = 0;
pthread_mutex_t sessionsMutex = PTHREAD_MUTEX_INITIALIZER;
redisContext *redisContext = NULL;

void initRedis() {
    redisContext = redisConnect("127.0.0.1", 6379);
    if (redisContext == NULL || redisContext->err) {
        printf("Connection error: %s\n", redisContext->errstr);
        exit(EXIT_FAILURE);
    }
}

void cleanupRedis() {
    redisFree(redisContext);
}

void* fetchSessionFromAPI(void* args) {
    // Simulate fetching session from API
    char *ueIdentifier = (char*)args;
    char response[1024];
    sprintf(response, "{\"UEIdentifier\":\"%s\",\"RANNodeIdentifier\":\"NodeA\",\"ConnectionState\":\"ACTIVE\"}", ueIdentifier);

    // Parse response and update cache
    CachedSession cachedSession;
    strcpy(cachedSession.session.UEIdentifier, "session1");
    strcpy(cachedSession.session.RANNodeIdentifier, "NodeA");
    cachedSession.session.state = ACTIVE;
    cachedSession.lastUpdated = time(NULL);

    pthread_mutex_lock(&sessionsMutex);
    sessions = realloc(sessions, (sessionCount + 1) * sizeof(CachedSession));
    memcpy(&sessions[sessionCount], &cachedSession, sizeof(CachedSession));
    sessionCount++;
    pthread_mutex_unlock(&sessionsMutex);

    return NULL;
}

void updateSession(char* ueIdentifier, ConnectionState newState) {
    pthread_mutex_lock(&sessionsMutex);
    for (int i = 0; i < sessionCount; i++) {
        if (strcmp(sessions[i].session.UEIdentifier, ueIdentifier) == 0) {
            sessions[i].session.state = newState;
            sessions[i].lastUpdated = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&sessionsMutex);

    // Update in Redis
    redisCommand(redisContext, "SET %s {\"UEIdentifier\":\"%s\",\"RANNodeIdentifier\":\"NodeA\",\"ConnectionState\":\"%d\"}",
                 ueIdentifier, ueIdentifier, newState);
}

CachedSession* getSession(char* ueIdentifier) {
    pthread_mutex_lock(&sessionsMutex);
    for (int i = 0; i < sessionCount; i++) {
        if (strcmp(sessions[i].session.UEIdentifier, ueIdentifier) == 0) {
            CachedSession* result = malloc(sizeof(CachedSession));
            memcpy(result, &sessions[i], sizeof(CachedSession));
            pthread_mutex_unlock(&sessionsMutex);
            return result;
        }
    }
    pthread_mutex_unlock(&sessionsMutex);

    // Fetch from Redis
    redisReply *reply = (redisReply *)redisCommand(redisContext, "GET %s", ueIdentifier);
    if (reply && reply->type == REDIS_REPLY_STRING) {
        CachedSession* cachedSession = malloc(sizeof(CachedSession));
        sscanf(reply->str, "{\"UEIdentifier\":\"%[^\\\"],\"RANNodeIdentifier\":\"%[^\\\"],\"ConnectionState\":\"%d\"}",
               cachedSession->session.UEIdentifier, cachedSession->session.RANNodeIdentifier, &cachedSession->session.state);
        freeReplyObject(reply);
        return cachedSession;
    }

    freeReplyObject(reply);
    return NULL;
}

int main() {
    initRedis();

    // Simulate fetching and updating sessions
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, fetchSessionFromAPI, (void*)"session1");
    pthread_create(&thread2, NULL, updateSession, (void*)"session1", INACTIVE);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    // Simulate retrieving a session
    CachedSession* session = getSession("session1");
    if (session != NULL) {
        printf("Session found: UEIdentifier=%s, RANNodeIdentifier=%s, ConnectionState=%d\n",
               session->session.UEIdentifier, session->session.RANNodeIdentifier, session->session.state);
        free(session);
    }

    cleanupRedis();
    return 0;
}
