using System;
using System.Net.Http;
using System.Threading.Tasks;
using Polly;
using Polly.CircuitBreaker;

public class PageSectionUpdateMicroservice
{
    private readonly HttpClient _httpClient;
    private readonly AsyncCircuitBreakerPolicy _circuitBreakerPolicy;

    public PageSectionUpdateMicroservice(HttpClient httpClient, int failureThreshold, TimeSpan durationOfBreak)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _circuitBreakerPolicy = Policy
            .Handle<HttpRequestException>()
            .CircuitBreakerAsync(failureThreshold, durationOfBreak);
    }

    public async Task UpdatePageSection(string url, string data)
    {
        await _circuitBreakerPolicy.ExecuteAsync(async () =>
        {
            var content = new StringContent(data, System.Text.Encoding.UTF8, "application/json");
            var response = await _httpClient.PostAsync(url, content);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to update page section. Status code: {response.StatusCode}");
            }
        });
    }
}
