// microservice.js

const express = require('express');
const axios = require('axios');
const redis = require('redis');
const kafka = require('kafka-node');

const app = express();
const client = redis.createClient();
const producer = new kafka.Producer(new kafka.KafkaClient());

app.use(express.json());

// Event Store
async function persistEvent(event) {
    await client.set(event.id, JSON.stringify(event));
}

// Queue
function enqueue(event) {
    producer.send([{ topic: 'events', messages: JSON.stringify(event) }], (err, data) => {
        if (err) throw err;
    });
}

// Event Processing
app.post('/event', async (req, res) => {
    const event = req.body;

    try {
        await persistEvent(event);
        enqueue(event);
        res.status(201).send('Event received and processed');
    } catch (error) {
        console.error(error);
        res.status(500).send('Error processing event');
    }
});

// Event Retrieval
app.get('/event/:id', async (req, res) => {
    const eventId = req.params.id;

    try {
        const event = await client.get(eventId);
        if (!event) return res.status(404).send('Event not found');

        res.json(JSON.parse(event));
    } catch (error) {
        console.error(error);
        res.status(500).send('Error retrieving event');
    }
});

// Event Deletion
app.delete('/event/:id', async (req, res) => {
    const eventId = req.params.id;

    try {
        await client.del(eventId);
        res.send('Event deleted');
    } catch (error) {
        console.error(error);
        res.status(500).send('Error deleting event');
    }
});

// Start the microservice
app.listen(3000, () => {
    console.log('Microservice is running on port 3000');
});
```

This code sets up a basic microservice using Express.js to handle HTTP requests. It uses Redis for event storage and Kafka for asynchronous messaging. The service can persist events, enqueue them for processing, retrieve events by ID, and delete events. Error handling is included, and the microservice logs errors to the console."]

