#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct PDU {
    // Define PDU structure here
} PDU;

typedef struct ListNode {
    PDU* pdu;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    ListNode* head;
    pthread_mutex_t mutex;
    sem_t semaphore;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    sem_init(&list->semaphore, 0, 1);
}

void addPDU(DynamicList* list, PDU* pdu) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    newNode->pdu = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    newNode->next = list->head;
    list->head = newNode;
    sem_post(&list->semaphore);
    pthread_mutex_unlock(&list->mutex);
}

PDU* retrievePDU(DynamicList* list) {
    ListNode* node;
    PDU* pdu;

    if (sem_wait(&list->semaphore) == -1) {
        return NULL; // Handle error
    }

    pthread_mutex_lock(&list->mutex);
    node = list->head;
    if (node != NULL) {
        list->head = node->next;
        pdu = node->pdu;
        free(node);
    } else {
        sem_post(&list->semaphore);
        return NULL;
    }
    pthread_mutex_unlock(&list->mutex);

    return pdu;
}

void removePDU(DynamicList* list, PDU* pdu) {
    ListNode* current = list->head;
    ListNode* previous = NULL;

    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        if (current->pdu == pdu) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            sem_post(&list->semaphore);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        previous = current;
        current = current->next;
    }
    sem_post(&list->semaphore);
    pthread_mutex_unlock(&list->mutex);
}

void destroyDynamicList(DynamicList* list) {
    ListNode* current = list->head;
    ListNode* next;

    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    sem_destroy(&list->semaphore);
}
