typedef struct {
    pthread_mutex_t lock;
    LTE_PDU *pdu_list[10000];
    int size;
} Dynamic_List;

Dynamic_List *create_dynamic_list() {
    Dynamic_List *list = (Dynamic_List *)malloc(sizeof(Dynamic_List));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

void destroy_dynamic_list(Dynamic_List *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        free(list->pdu_list[i]);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(Dynamic_List *list, LTE_PDU *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= 10000) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List full
    }
    list->pdu_list[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

LTE_PDU *get_pdu(Dynamic_List *list, int index) {
    pthread_mutex_lock(&list->lock);
    if (index < 0 || index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Invalid index
    }
    LTE_PDU *pdu = list->pdu_list[index];
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

int remove_pdu(Dynamic_List *list, int index) {
    pthread_mutex_lock(&list->lock);
    if (index < 0 || index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid index
    }
    free(list->pdu_list[index]);
    for (int i = index; i < list->size - 1; i++) {
        list->pdu_list[i] = list->pdu_list[i + 1];
    }
    list->size--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

