#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>

// Define the structure for an LTE MAC Protocol Data Unit (PDU)
typedef struct {
    long offset;
    int key;
} LteMacPdu;

// Define the structure for a record consisting of an offset and a key
typedef struct {
    long offset;
    int key;
} Record;

// Define a node in the dynamic list
typedef struct Node {
    LteMacPdu pdu;
    Record record;
    struct Node* next;
} Node;

// Define the dynamic list structure
typedef struct DynamicList {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

// Initialize the dynamic list
DynamicList* initDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a PDU and record to the dynamic list
void addPduAndRecord(DynamicList* list, LteMacPdu pdu, Record record) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->pdu = pdu;
    newNode->record = record;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

// Retrieve a record by key from the dynamic list
Record* getRecordByKey(DynamicList* list, int key) {
    Node* temp = list->head;
    while (temp != NULL) {
        if (temp->record.key == key) {
            return &temp->record;
        }
        temp = temp->next;
    }
    return NULL;
}

// Remove a record by key from the dynamic list
void removeRecordByKey(DynamicList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Node* temp = list->head;
    Node* prev = NULL;

    while (temp != NULL && temp->record.key != key) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);
    pthread_mutex_unlock(&list->lock);
}

// Free the memory allocated for the dynamic list
void freeDynamicList(DynamicList* list) {
    Node* temp = list->head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    DynamicList* list = initDynamicList();

    LteMacPdu pdu = {12345, 6789};
    Record record = {12345, 6789};

    addPduAndRecord(list, pdu, record);

    Record* retrievedRecord = getRecordByKey(list, 6789);
    if (retrievedRecord != NULL) {
        printf("Retrieved offset: %ld, key: %d\n", retrievedRecord->offset, retrievedRecord->key);
    }

    removeRecordByKey(list, 6789);

    freeDynamicList(list);

    return 0;
}
```

This code snippet provides a basic implementation of a dynamic list for LTE MAC Protocol Data Units (PDUs) and records. It includes functions to add PDU and record pairs to the list, retrieve records by key, remove records by key, and free the memory allocated for the list. The implementation uses a mutex for thread safety to ensure concurrent access to the list is handled correctly.']

