#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_PDUS 10000

typedef struct PDU {
    void* data;
    size_t length;
} PDU;

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct List {
    PDU pdus[MAX_PDUS];
    Record records[MAX_PDUS];
    size_t pdu_count;
    size_t record_count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} List;

List* list_create() {
    List* list = malloc(sizeof(List));
    if (list == NULL) {
        return NULL;
    }
    memset(list, 0, sizeof(List));
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void list_destroy(List* list) {
    if (list != NULL) {
        pthread_mutex_lock(&list->lock);
        pthread_mutex_unlock(&list->lock);
        pthread_cond_destroy(&list->cond);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int list_add_pdu(List* list, void* data, size_t length) {
    if (list == NULL || data == NULL || length == 0) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    if (list->pdu_count >= MAX_PDUS) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }
    list->pdus[list->pdu_count].data = data;
    list->pdus[list->pdu_count].length = length;
    list->pdu_count++;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_add_record(List* list, long offset, int key) {
    if (list == NULL || offset < 0 || key < 0) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    if (list->record_count >= MAX_PDUS) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }
    list->records[list->record_count].offset = offset;
    list->records[list->record_count].key = key;
    list->record_count++;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_get_pdu(List* list, void** data, size_t* length) {
    if (list == NULL || data == NULL || length == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    while (list->pdu_count == 0) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    *data = list->pdus[list->pdu_count - 1].data;
    *length = list->pdus[list->pdu_count - 1].length;
    list->pdu_count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_get_record(List* list, long* offset, int* key) {
    if (list == NULL || offset == NULL || key == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    while (list->record_count == 0) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    *offset = list->records[list->record_count - 1].offset;
    *key = list->records[list->record_count - 1].key;
    list->record_count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_remove_pdu(List* list, void** data, size_t* length) {
    if (list == NULL || data == NULL || length == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    while (list->pdu_count == 0) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    *data = list->pdus[list->pdu_count - 1].data;
    *length = list->pdus[list->pdu_count - 1].length;
    list->pdu_count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_remove_record(List* list, long* offset, int* key) {
    if (list == NULL || offset == NULL || key == NULL) {
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    while (list->record_count == 0) {
        pthread_cond_wait(&list->cond, &list->lock);
    }
    *offset = list->records[list->record_count - 1].offset;
    *key = list->records[list->record_count - 1].key;
    list->record_count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}
