    public MessageProcessor(string redisConnectionString, string[] encryptionKeyNames)
    {
        _httpClient = new HttpClient();
        _redisDatabase = ConnectionMultiplexer.Connect(redisConnectionString).GetDatabase();
        _encryptionKeys = new ConcurrentDictionary<string, byte[]>(StringComparer.Ordinal);
        _logger = new Logger();

