    public async Task ProcessMessagesAsync(string cloudStorageUrl, string encryptionKeyName)
    {
        while (true)
        {
            try
            {
                var message = await FetchNextMessageAsync(cloudStorageUrl);
                if (message == null) break;

                var decryptedMessage = DecryptMessage(message, _encryptionKeys[encryptionKeyName]);
                CacheDecryptedMessage(decryptedMessage);
                ProcessDecryptedMessage(decryptedMessage);
