        var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var ms = new MemoryStream(encryptedBytes))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                return cs.ToArray();
            }
        }
    }

    private void CacheDecryptedMessage(byte[] decryptedMessage)
    {
        // Implement caching logic with a dynamic eviction policy
        var messageHash = BitConverter.ToString(decryptedMessage).Replace("-", "").ToLowerInvariant();
        _redisDatabase.StringSet(messageHash, decryptedMessage);
    }

    private void ProcessDecryptedMessage(byte[] decryptedMessage)
    {
        // Implement logic to process the decrypted message
        // For example, parsing and processing data
    }

    public void Dispose()
    {
        _httpClient.Dispose();
        _logger.Dispose();
    }
}

public class Logger : IDisposable
{
    private readonly TextWriter _logWriter;

    public Logger(string logFilePath = "app.log")
    {
        _logWriter = new StreamWriter(logFilePath, true);
    }

    public void LogError(Exception ex, string message)
    {
        var logEntry = $"{DateTime.UtcNow.ToString("o")}: {message} - Error: {ex.Message}";
        lock (_logWriter)
        {
            _logWriter.WriteLine(logEntry);
        }
    }

    public void Dispose()
    {
        _logWriter.Dispose();
    }
}
