// C code for a modular library that dynamically manages memory allocation

#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (manager == NULL) return NULL;

    manager->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    if (manager != NULL) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

bool allocate_record(MemoryManager* manager, long offset, int key) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    manager->records[manager->count].offset = offset;
    manager->records[manager->count].key = key;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return true;
}

// Additional functions for managing memory, handling concurrency,
// and integrating with legacy systems would be implemented here.
