#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicMemoryManager;

DynamicMemoryManager* create_memory_manager(size_t initial_capacity) {
    DynamicMemoryManager* manager = (DynamicMemoryManager*)malloc(sizeof(DynamicMemoryManager));
    if (manager == NULL) return NULL;
    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_memory_manager(DynamicMemoryManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->records);
    free(manager);
}

int add_record(DynamicMemoryManager* manager, Record record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        Record* new_records = (Record*)realloc(manager->records, manager->capacity * sizeof(Record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->records = new_records;
    }
    manager->records[manager->size++] = record;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Additional functions for memory management, concurrency control, and SLA compliance can be implemented here
