package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/go-resty/resty/v2"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/tools/clientcmd"
)

type CommunicationManager struct {
	client    *resty.Client
	kubeClient kubernetes.Interface
	configPath string
}

func NewCommunicationManager(configPath string) (*CommunicationManager, error) {
	c := resty.New()
	kubeConfig, err := clientcmd.BuildConfigFromFlags("", configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to build kubeconfig: %w", err)
	}
	kubeClientset, err := kubernetes.NewForConfig(kubeConfig)
	if err != nil {
		return nil, fmt.Errorf("failed to create kube clientset: %w", err)
	}

	return &CommunicationManager{
		client:    c,
		kubeClient: kubeClientset,
		configPath: configPath,
	}, nil
}

func (cm *CommunicationManager) StartWebhookServer(ctx context.Context, port int) error {
	mux := http.NewServeMux()
	mux.HandleFunc("/webhook", cm.handleWebhook)

	server := &http.Server{
		Addr:    fmt.Sprintf(":%d", port),
		Handler: mux,
	}

	go func() {
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Could not start server: %v\n", err)
		}
	}()

	<-ctx.Done()

	return server.Shutdown(ctx)
}

func (cm *CommunicationManager) handleWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	var data map[string]interface{}
	if err := cm.client.R().SetBody(r.Body).Decode(&data); err != nil {
		http.Error(w, "Failed to decode JSON", http.StatusBadRequest)
		return
	}

	rxUEInfoTag, ok := data["RX_UE_INFORMATION_TAG"].(string)
	if !ok || rxUEInfoTag == "" {
		http.Error(w, "Invalid RX_UE_INFORMATION_TAG", http.StatusBadRequest)
		return
	}

	RNTI, ok := data["RNTI"].(int64)
	if !ok || RNTI <= 0 {
		http.Error(w, "Invalid RNTI", http.StatusBadRequest)
		return
	}

	// Process the webhook data
	go cm.processData(rxUEInfoTag, RNTI)

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Webhook received")
}

