} DeviceManager;

DeviceManager* create_device_manager(int initial_capacity, int memory_limit, int unique_range_start, int unique_range_end) {
    DeviceManager *manager = (DeviceManager*)malloc(sizeof(DeviceManager));
    manager->devices = (DeviceStatus*)calloc(initial_capacity, sizeof(DeviceStatus));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->memoryLimit = memory_limit;
    manager->uniqueRangeStart = unique_range_start;
    manager->uniqueRangeEnd = unique_range_end;
    return manager;
}

void destroy_device_manager(DeviceManager *manager) {
    free(manager->devices);
    free(manager);
}

int add_device(DeviceManager *manager, int deviceID, char *status, int connectionMetrics) {
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->devices = (DeviceStatus*)realloc(manager->devices, manager->capacity * sizeof(DeviceStatus));
    }
    DeviceStatus *device = &manager->devices[manager->count++];
    device->deviceID = deviceID;
    strncpy(device->status, status, 49);
    device->lastUpdate = time(NULL);
    device->connectionMetrics = connectionMetrics;
    return 0;
