@RestController
@RequestMapping("/api/userdata")
public class UserDataController {

    @Autowired
    private UserApiClient userApiClient;

    @Autowired
    private CacheManager cacheManager;

    @GetMapping("/{email}")
    public ResponseEntity<UserData> getUserData(@PathVariable String email) {
        // Check if data is already cached
        String cacheKey = "userData:" + email;
        UserData cachedUserData = (UserData) cacheManager.get(cacheKey);

        if (cachedUserData != null) {
            return ResponseEntity.ok(cachedUserData);
        } else {
            try {
                // Fetch user data from external API
                UserData userData = userApiClient.fetchUserData(email);

                // Cache the fetched data
                cacheManager.put(cacheKey, userData);

                return ResponseEntity.ok(userData);
            } catch (ApiException e) {
                if (e.getStatusCode() == HttpStatus.UNAUTHORIZED) {
                    return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(null);
                } else {
                    return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(null);
                }
            } catch (IOException | JsonProcessingException e) {
                return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(null);
            }
        }
    }

    // Add more endpoints and methods as needed
}

@Service
public class UserApiClient {

    private final RestTemplate restTemplate;

    public UserApiClient(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
    }

    public UserData fetchUserData(String email) throws ApiException, IOException, JsonProcessingException {
        String url = "https://api.example.com/users?email=" + email;
        HttpHeaders headers = new HttpHeaders();
        headers.set("Authorization", "Bearer " + getToken());
        HttpEntity<String> requestEntity = new HttpEntity<>(headers);

        ResponseEntity<UserData> response = restTemplate.exchange(url, HttpMethod.GET, requestEntity, UserData.class);

        if (response.getStatusCode() == HttpStatus.OK) {
            return response.getBody();
        } else if (response.getStatusCode() == HttpStatus.UNAUTHORIZED) {
            throw new ApiException("Unauthorized", HttpStatus.UNAUTHORIZED);
        } else {
            throw new IOException("API error");
        }
    }

    private String getToken() {
        // Implement token retrieval logic
        return "your_token_here";
    }
}

