import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class BatchProcessingEngine {

    private ExecutorService executorService;

    public BatchProcessingEngine(int threadPoolSize) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void processBatch(List<DataRecord> dataRecords) {
        for (DataRecord record : dataRecords) {
            executorService.submit(() -> {
                try {
                    validateAndTransform(record);
                    storeInDatabase(record);
                } catch (Exception e) {
                    handleProcessingError(e, record);
                }
            });
        }
    }

    private void validateAndTransform(DataRecord record) throws ValidationException, TransformationException {
        if (!record.isValid()) {
            throw new ValidationException("Invalid data record");
        }
        record.transform();
    }

    private void storeInDatabase(DataRecord record) throws StorageException {
        // Code to store data in database
    }

    private void handleProcessingError(Exception e, DataRecord record) {
        logError(e);
        retryFailedRecord(record);
        notifySupport(e);
    }

    private void logError(Exception e) {
        // Code to log error details
    }

    private void retryFailedRecord(DataRecord record) {
        executorService.submit(() -> {
            try {
                storeInDatabase(record);
            } catch (Exception re) {
                handleProcessingError(re, record);
            }
        });
    }

    private void notifySupport(Exception e) {
        // Code to notify support team
    }
}
