// Define a class to manage input data and delegate processing to AI models
class ImageProcessor {
public:
    void addTask(const std::string& data, IAIModel* model) {
        std::lock_guard<std::mutex> lock(mutex_);
        tasks_.push({data, model});
        condition_.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !tasks_.empty(); });
            auto task = tasks_.front();
            tasks_.pop();
            lock.unlock();

            task.second->recognize(task.first);
        }
    }

