import asyncio
from hashlib import sha256
from io import BytesIO
from typing import Callable, Dict, Optional

class FileHasher:
    def __init__(self):
        self.cache = {}

    async def hash_file(self, file_path: str, offset: int, chunk_size: int = 1024 * 1024) -> bytes:
        if file_path in self.cache:
            return self.cache[file_path]

        try:
            with open(file_path, 'rb') as f:
                f.seek(offset)
                hasher = sha256()
                while chunk := f.read(chunk_size):
                    hasher.update(chunk)
            hash_value = hasher.digest()
            self.cache[file_path] = hash_value
            return hash_value
        except Exception as e:
            print(f"Error hashing file: {e}")
            raise

class CloudStorageClient:
    async def download_file(self, bucket_name: str, file_key: str, offset: int, length: Optional[int]) -> bytes:
        # Implement downloading from AWS S3, Google Cloud Storage, or Azure Blob Storage
        pass

class FileProcessor:
    def __init__(self, storage_client: CloudStorageClient):
        self.storage_client = storage_client
        self.file_hasher = FileHasher()

    async def process_file(self, cloud_provider: str, bucket_name: str, file_key: str, offset: int) -> bytes:
        try:
            downloaded_data = await self.storage_client.download_file(bucket_name, file_key, offset)
            return await self.file_hasher.hash_file(BytesIO(downloaded_data), 0)
        except Exception as e:
            print(f"Error processing file on {cloud_provider}: {e}")
            raise

class Service:
    def __init__(self, storage_clients: Dict[str, CloudStorageClient]):
        self.storage_clients = storage_clients
        self.file_processor = FileProcessor(storage_client=CloudStorageClient())

    async def hash_large_file(self, cloud_provider: str, bucket_name: str, file_key: str, offset: int) -> bytes:
        return await self.file_processor.process_file(cloud_provider, bucket_name, file_key, offset)

# Usage
async def main():
    storage_clients = {
        'aws': CloudStorageClient(),
        'google': CloudStorageClient(),
        'azure': CloudStorageClient()
    }
    service = Service(storage_clients)
    result = await service.hash_large_file('aws', 'bucket-name', 'file-key', 0)
    print(result)

asyncio.run(main())
```

