// Define DeviceStatus structure
typedef struct {
    int deviceID;
    char status[20];
    time_t lastUpdate;
    // Add connectionMetrics here
} DeviceStatus;

// Define a node for the linked list
typedef struct Node {
    DeviceStatus data;
    struct Node* next;
} Node;

// Define a linked list for managing DeviceStatus
typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

// Initialize the linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new device to the linked list
void addDevice(LinkedList* list, DeviceStatus device) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }
    newNode->data = device;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Remove an inactive device from the linked list
void removeInactiveDevice(LinkedList* list, time_t currentTime, time_t inactivityThreshold) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (currentTime - current->data.lastUpdate > inactivityThreshold) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            current = previous->next;
        } else {
            previous = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Example usage
int main() {
    LinkedList deviceList;
    initLinkedList(&deviceList);

    DeviceStatus device1 = {1, "Online", time(NULL), /* Add connectionMetrics */};
    addDevice(&deviceList, device1);

    // Simulate removing an inactive device after 60 seconds of inactivity
    removeInactiveDevice(&deviceList, time(NULL) + 60, 59);

    return 0;
}
```

