namespace network {

class NetworkMetrics {
public:
    static NetworkMetrics& get_instance() {
        static NetworkMetrics instance;
        return instance;
    }

    void collect_metrics() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            if (services_.empty()) {
                condition_.wait(lock, [this] { return !services_.empty(); });
            }
            for (auto& service : services_) {
                auto metric = fetch_metric(service);
                record_metric(metric);
            }
            lock.unlock();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

    void add_service(const std::string& service_name) {
        std::lock_guard<std::mutex> lock(mutex_);
        services_.push_back(service_name);
        condition_.notify_one();
    }

    void remove_service(const std::string& service_name) {
        std::lock_guard<std::mutex> lock(mutex_);
        services_.erase(std::remove(services_.begin(), services_.end(), service_name), services_.end());
    }

    ~NetworkMetrics() {
        running_ = false;
        condition_.notify_all();
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    NetworkMetrics()
        : running_(true),
          max_buffer_size_(1000),
