// Function to securely encrypt and decrypt data
int encryptData(const unsigned char* plaintext, int plaintextLen, const unsigned char* key,
                const unsigned char* iv, unsigned char** ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error creating context
        return -1;
    }
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        // Handle encryption initialization failure
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    // Allocate memory for ciphertext
    *ciphertext = (unsigned char*)malloc(plaintextLen + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    if (*ciphertext == NULL) {
        // Handle memory allocation failure
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len, ciphertextLen;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintextLen)) {
        // Handle encryption update failure
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertextLen = len;
    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        // Handle encryption finalization failure
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertextLen += len;
    *valueSize = ciphertextLen;
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

int decryptData(const unsigned char* ciphertext, int ciphertextLen, const unsigned char* key,
                const unsigned char* iv, unsigned char** plaintext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error creating context
        return -1;
    }
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        // Handle decryption initialization failure
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *plaintext = (unsigned char*)malloc(ciphertextLen + 1);
    if (*plaintext == NULL) {
        // Handle memory allocation failure
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int len, plaintextLen;
    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertextLen)) {
        // Handle decryption update failure
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintextLen = len;
    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) {
        // Handle decryption finalization failure
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext[len] = '\0';
    *valueSize = len;
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

