// Define configuration parameters
#define MAX_RETRY_INTERVAL 60 // seconds
#define CONGESTION_THRESHOLD 100 // number of messages

typedef struct {
    FILE* logFile;
    int retryAttempts;
    time_t lastRetryTime;
    int messageCount;
    pthread_mutex_t mutex;
} LogManager;

LogManager logManager = {NULL, 3, 0, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize the LogManager
void initLogManager(const char* fileName) {
    if (logManager.logFile != NULL) return; // Avoid re-initialization

    logManager.logFile = fopen(fileName, "a");
    if (logManager.logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&logManager.mutex, NULL);
}

// Function to format and log a message
void logConditionalMessage(int dbConnectionActive, int conditionMet) {
    time_t now = time(NULL);
    struct tm* tmInfo = localtime(&now);
    int hour = tmInfo->tm_hour;

    if (dbConnectionActive && 9 <= hour && hour < 17 && conditionMet) {
        pthread_mutex_lock(&logManager.mutex);
        if (logManager.logFile == NULL) {
            // Asynchronous logging to external service
            for (int i = 0; i < logManager.retryAttempts; i++) {
                sleep(1); // Simulate retry delay
                logManager.logFile = fopen("async_log.txt", "a");
                if (logManager.logFile != NULL) break;
            }
        }

        if (logManager.logFile != NULL) {
            char buffer[256];
            snprintf(buffer, sizeof(buffer), "%s: Message logged\n", ctime(&now));
            fwrite(buffer, 1, strlen(buffer), logManager.logFile);
            fflush(logManager.logFile);

            // Update congestion status
            if (++logManager.messageCount > CONGESTION_THRESHOLD) {
                time_t currentTime = time(NULL);
                if (difftime(currentTime, logManager.lastRetryTime) >= 3600) {
                    logManager.retryAttempts--;
                    logManager.lastRetryTime = currentTime;
                }
            }

            // Simulate file size check
            fseek(logManager.logFile, 0, SEEK_END);
            off_t fileSize = ftell(logManager.logFile);
            if (fileSize > 1024 * 1024) { // Example: 1MB threshold
                logManager.retryAttempts--;
            }
        }

        pthread_mutex_unlock(&logManager.mutex);
    }
}

// Function to close the LogManager
void closeLogManager() {
    if (logManager.logFile != NULL) {
        fclose(logManager.logFile);
        logManager.logFile = NULL;
    }

    pthread_mutex_destroy(&logManager.mutex);
}
