        pdusMap = new ConcurrentHashMap<>();
        recordsMap = new ConcurrentHashMap<>();
    }

    // Thread-safe methods for adding, retrieving, and removing PDUs and records
    public void addPDU(long offset, PDU pdu) {
        pdusMap.put(offset, pdu);
    }

    public PDU getPDU(long offset) {
        return pdusMap.get(offset);
    }

    public boolean removePDU(long offset) {
        return pdusMap.remove(offset) != null;
    }

