import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.Comparator;
import java.util.PriorityQueue;

public class EventProcessor {
    private UnionFind unionFind;
    private PriorityQueue<Event> eventQueue;
    private long startTime;
    private long endTime;
    private int disjointPairsCount;

    public EventProcessor(int size) {
        this.unionFind = new UnionFind(size);
        this.eventQueue = new PriorityQueue<>(Comparator.comparingLong(Event::getTimestamp));
        this.startTime = System.currentTimeMillis();
    }

    public void processEvent(Event event) {
        if (!event.isValid()) {
            return;
        }
        ZonedDateTime startZoned = event.getStart().atZone(ZoneId.systemDefault());
        ZonedDateTime endZoned = event.getEnd().atZone(ZoneId.systemDefault());

        // Adjust for time zone and daylight saving transitions
        long startTimeMillis = startZoned.toInstant().toEpochMilli();
        long endTimeMillis = endZoned.toInstant().toEpochMilli();

        int startId = unionFind.find((int) (startTimeMillis / 1000L));
        int endId = unionFind.find((int) (endTimeMillis / 1000L));

        if (startId != endId) {
            unionFind.union(startId, endId);
            disjointPairsCount++;
        }
    }

    public long getTotalDisjointPairs() {
        return disjointPairsCount;
    }

    public long getProcessingTime() {
        endTime = System.currentTimeMillis();
        return endTime - startTime;
    }
}

class Event {
    private LocalDateTime start;
    private LocalDateTime end;

    public Event(LocalDateTime start, LocalDateTime end) {
        this.start = start;
        this.end = end;
    }

    public LocalDateTime getStart() {
        return start;
    }

    public LocalDateTime getEnd() {
        return end;
    }

    public boolean isValid() {
        return start != null && end != null && start.isBefore(end);
    }

    public long getTimestamp() {
        return start.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
    }
}

class UnionFind {
    private int[] parent;

    public UnionFind(int size) {
        this.parent = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    }
}
