#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_NFS_API_CRC_INDICATION_PDU 1024

typedef struct {
    // Define the structure fields as per NFAPI specifications
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *queue;
    int front, rear;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} CRC_Queue_T;

CRC_Queue_T* create_crc_queue(int capacity) {
    CRC_Queue_T *q = (CRC_Queue_T*)malloc(sizeof(CRC_Queue_T));
    q->queue = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->front = q->rear = -1;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void destroy_crc_queue(CRC_Queue_T *q) {
    free(q->queue);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    free(q);
}

int enqueue(CRC_Queue_T *q, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&q->lock);
    while (q->size == q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    if (q->front == -1)
        q->front = 0;
    q->rear = (q->rear + 1) % q->capacity;
    q->queue[q->rear] = item;
    q->size++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
    return 1;
}

int dequeue(CRC_Queue_T *q, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&q->lock);
    while (q->size == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    *item = q->queue[q->front];
    if (q->front == q->rear)
        q->front = q->rear = -1;
    else
        q->front = (q->front + 1) % q->capacity;
    q->size--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return 1;
}

void* crc_processing_thread(void *arg) {
    CRC_Queue_T *q = (CRC_Queue_T*)arg;
    NFAPI_CRC_INDICATION_PDU_T item;
    while (1) {
        dequeue(q, &item);
        // Process the item
        printf("Processing item\n");
    }
    return NULL;
}

int main() {
    int num_threads = 4;
