#include <pthread.h>

typedef struct {
    // Define the structure fields as per NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_free(DynamicArray *array) {
    free(array->data);
    free(array);
}

int dynamic_array_push(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T dynamic_array_pop(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    if (array->size == 0) {
        pthread_mutex_unlock(&array->lock);
        NFAPI_CRC_INDICATION_PDU_T empty_item = {0};
        return empty_item; // Return an empty item on underflow
    }
    NFAPI_CRC_INDICATION_PDU_T item = array->data[--array->size];
    pthread_mutex_unlock(&array->lock);
    return item;
}
