        static Logger instance;
        return instance;
    }

    void log(const std::string& message, const std::string& source) {
        auto now = std::chrono::system_clock::now();
        std::time_t time = std::chrono::system_clock::to_time_t(now);
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push({message, source, now});
        cond_.notify_one();
    }

private:
    Logger() {}
    ~Logger() {}

    struct LogEntry {
        std::string message;
        std::string source;
        std::chrono::system_clock::time_point timestamp;
    };

    std::queue<LogEntry> queue_;
    std::mutex mutex_;
    std::condition_variable cond_;

    friend class LogWriter;
};

class LogWriter {
public:
    void write(const Logger::LogEntry& entry) {
        // Implement logic to write log entries to various sinks
        std::cout << "Writing log: " << entry.message << " from source: " << entry.source << std::endl;
    }
};

void worker(LogWriter& writer, std::queue<Logger::LogEntry>& queue) {
    while (true) {
        std::unique_lock<std::mutex> lock(queue.mutex_);
        queue.cond_.wait(lock, [&queue] { return !queue.empty(); });
        Logger::LogEntry entry = queue.front();
        queue.pop();
        lock.unlock();

        writer.write(entry);
    }
}

int main() {
    Logger& logger = Logger::getInstance();
    LogWriter writer;

    std::vector<std::thread> threads;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back(worker, std::ref(writer), std::ref(logger.queue_));
    }

    // Simulate log generation
    for (int i = 0; i < 1000000; ++i) {
        logger.log("Log entry " + std::to_string(i), "Source " + std::to_string(i % 10));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
