package main

import (
    "context"
    "log"
    "net/http"
    "sync"
    "time"

    "github.com/go-chi/chi/v5"
    "github.com/go-chi/cors"
    "go.etcd.io/bbolt"
    "golang.org/x/exp/slices"
    github.com/google/gopacket/layers"
)

type DynamicSessionManager struct {
    db            *bbolt.DB
    cache         map[string]string
    messageBroker MessageBroker
    mu            sync.Mutex
}

func NewDynamicSessionManager(dbPath string, broker MessageBroker) (*DynamicSessionManager, error) {
    db, err := bbolt.Open(dbPath, 0666, nil)
    if err != nil {
        return nil, err
    }
    return &DynamicSessionManager{
        db:            db,
        cache:         make(map[string]string),
        messageBroker: broker,
    }, nil
}

func (sm *DynamicSessionManager) CreateSession(ctx context.Context, userID string) error {
    sm.mu.Lock()
    defer sm.mu.Unlock()

    // Logic to create a new session
    err := sm.db.Update(func(tx *bbolt.Tx) error {
        b, err := tx.CreateBucketIfNotExists([]byte("sessions"))
        if err != nil {
            return err
        }
        key := []byte(userID)
        if b.Get(key) != nil {
            return errors.New("session already exists")
        }
        b.Put(key, []byte("active"))
        sm.cache[userID] = "active"
        return sm.messageBroker.Publish(ctx, userID, "created")
    })
    return err
}

func (sm *DynamicSessionManager) UpdateSession(ctx context.Context, userID string) error {
    sm.mu.Lock()
    defer sm.mu.Unlock()

    // Logic to update an existing session
    err := sm.db.Update(func(tx *bbolt.Tx) error {
        b := tx.Bucket([]byte("sessions"))
        if b.Get([]byte(userID)) == nil {
            return errors.New("session not found")
        }
        b.Put([]byte(userID), []byte("active"))
        sm.cache[userID] = "active"
        return sm.messageBroker.Publish(ctx, userID, "updated")
    })
    return err
}

func (sm *DynamicSessionManager) DeleteSession(ctx context.Context, userID string) error {
    sm.mu.Lock()
    defer sm.mu.Unlock()

    // Logic to delete a session
    err := sm.db.Update(func(tx *bbolt.Tx) error {
        b := tx.Bucket([]byte("sessions"))
        if b.Get([]byte(userID)) == nil {
            return errors.New("session not found")
        }
        b.Delete([]byte(userID))
        delete(sm.cache, userID)
        return sm.messageBroker.Publish(ctx, userID, "deleted")
    })
    return err
}

func (sm *DynamicSessionManager) GetSession(ctx context.Context, userID string) (string, error) {
    sm.mu.Lock()
    defer sm.mu.Unlock()

    // Logic to get session status
    if value := sm.cache[userID]; value != "" {
        return value, nil
    }
    return "", errors.New("session not found")
}

func (sm *DynamicSessionManager) StartHTTPServer(port int) error {
    r := chi.NewRouter()
    r.Use(cors.Handler(cors.Options{
        AllowedOrigins: []string{"*"},
        AllowMethods:   []string{"GET", "POST", "PUT", "DELETE", "OPTIONS"},
        AllowHeaders:   []string{"Accept", "Authorization", "Content-Type", "Origin"},
        ExposeHeaders:  []string{"Link"},
    }))
    r.Post("/sessions", sm.handleCreateSession)
    r.Put("/sessions/{userID}", sm.handleUpdateSession)
    r.Delete("/sessions/{userID}", sm.handleDeleteSession)

    log.Printf("Starting HTTP server on port %d\n", port)
    return http.ListenAndServe(fmt.Sprintf(":%d", port), r)
}

func (sm *DynamicSessionManager) handleCreateSession(w http.ResponseWriter, r *http.Request) {
    userID := chi.URLParam(r, "userID")
    if err := sm.CreateSession(r.Context(), userID); err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }
    w.WriteHeader(http.StatusCreated)
}

func (sm *DynamicSessionManager) handleUpdateSession(w http.ResponseWriter, r *http.Request) {
    userID := chi.URLParam(r, "userID")
    if err := sm.UpdateSession(r.Context(), userID); err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }
    w.WriteHeader(http.StatusOK)
}

func (sm *DynamicSessionManager) handleDeleteSession(w http.ResponseWriter, r *http.Request) {
    userID := chi.URLParam(r, "userID")
    if err := sm.DeleteSession(r.Context(), userID); err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }
    w.WriteHeader(http.StatusNoContent)
}

type MessageBroker interface {
    Publish(ctx context.Context, userID string, eventType string) error
    Subscribe(userID string, handler func(eventType string)) error
}

func main() {
    dbPath := "sessions.db"
    broker := NewRedisMessageBroker()
    sm, err := NewDynamicSessionManager(dbPath, broker)
    if err != nil {
        log.Fatalf("Failed to create session manager: %v", err)
    }
    if err := sm.StartHTTPServer(8080); err != nil {
        log.Fatalf("Failed to start HTTP server: %v", err)
    }
}
