#include <stdint.h>

#define MAX_STRUCTS 1000000

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool[MAX_STRUCTS];
int pool_index = 0;

void* allocateMemory() {
    if (pool_index >= MAX_STRUCTS) {
        printf("Memory allocation failed: Pool limit reached.\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    pool[pool_index++] = ptr;
    return ptr;
}

void freeMemory(void *ptr) {
    for (int i = 0; i < pool_index; i++) {
        if (pool[i] == ptr) {
            pool[i] = NULL;
            free(ptr);
            return;
        }
    }
    printf("Attempted to free memory that was not in the pool.\n");
}

void processNfapiCrcIndications(uint16_t RNTI, uint8_t CRCFLAG) {
    // Input validation
    if (RNTI > 65535 || (CRCFLAG != 0 && CRCFLAG != 1)) {
        printf("Invalid input parameters.\n");
        return;
    }

    void *ptr = allocateMemory();
    if (ptr == NULL) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)ptr;
    data->RNTI = RNTI;
    data->CRCFLAG = CRCFLAG;

    // Process the data
    // ...

    freeMemory(ptr);
}

int main() {
    processNfapiCrcIndications(100, 1);
    return 0;
}
```

