#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <string>
#include <memory>

class DynamicLogAndGraphManager {
public:
    DynamicLogAndGraphManager() {}

    void handleLogAndGraphEvents(const std::string& logEntry, const std::string& graphData) {
        // Lock the queue for thread-safe operations
        std::lock_guard<std::mutex> lock(logQueueMutex);
        logQueue.push(logEntry);
        graphQueue.push(graphData);
        logCond.notify_one();
        graphCond.notify_one();
    }

    void startMonitoring() {
        logThread = std::thread(&DynamicLogAndGraphManager::monitorLogs, this);
        graphThread = std::thread(&DynamicLogAndGraphManager::monitorGraphs, this);
    }

    void stopMonitoring() {
        runMonitor = false;
        logCond.notify_all();
        graphCond.notify_all();
        if (logThread.joinable()) logThread.join();
        if (graphThread.joinable()) graphThread.join();
    }

private:
    std::queue<std::string> logQueue;
    std::queue<std::string> graphQueue;
    std::mutex logQueueMutex;
    std::mutex graphQueueMutex;
    std::condition_variable logCond;
    std::condition_variable graphCond;
    bool runMonitor = true;

    void monitorLogs() {
        while (runMonitor) {
            std::unique_lock<std::mutex> lock(logQueueMutex);
            logCond.wait(lock, [this] { return !logQueue.empty() || !runMonitor; });
            if (!runMonitor) break;
            std::string logEntry = logQueue.front();
            logQueue.pop();
            lock.unlock();

            // Process log entry
            processLogEntry(logEntry);
        }
    }

    void monitorGraphs() {
        while (runMonitor) {
            std::unique_lock<std::mutex> lock(graphQueueMutex);
            graphCond.wait(lock, [this] { return !graphQueue.empty() || !runMonitor; });
            if (!runMonitor) break;
            std::string graphData = graphQueue.front();
            graphQueue.pop();
            lock.unlock();

            // Process graph data
            processGraphData(graphData);
        }
    }

    void processLogEntry(const std::string& logEntry) {
        // Implement log processing logic here
    }

    void processGraphData(const std::string& graphData) {
        // Implement graph data processing logic here
    }
};

int main() {
    DynamicLogAndGraphManager manager;
    manager.startMonitoring();

    // Simulate incoming log entries and graph data
    for (int i = 0; i < 10; ++i) {
        manager.handleLogAndGraphEvents("Log entry " + std::to_string(i), "Graph data " + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }

    manager.stopMonitoring();
    return 0;
}
```

