const express = require('express');
const bodyParser = require('body-parser');
const { Pool } = require('pg');
const axios = require('axios');

const app = express();
app.use(bodyParser.json());

const dbConfig = {
  host: 'db_host',
  port: 'db_port',
  database: 'db_name',
  user: 'db_user',
  password: 'db_password'
};

const pool = new Pool(dbConfig);

app.put('/api/resources/:id', async (req, res) => {
  const { id } = req.params;
  const { data } = req.body;

  try {
    // Fetch latest version from database
    const existingResource = await pool.query('SELECT * FROM resources WHERE id = $1 FOR UPDATE', [id]);
    if (!existingResource.rows.length) return res.status(404).json({ error: 'Resource not found' });

    const { version } = existingResource.rows[0];
    data.version = version + 1;

    // Update resource with new version
    await pool.query('UPDATE resources SET data = $1, version = $2 WHERE id = $3 AND version = $4', [data, data.version, id, version]);

    res.status(200).json({ message: 'Resource updated successfully' });
  } catch (error) {
    if (error.code === 'P2002') return res.status(409).json({ error: 'Conflict detected. Please try again later.' });
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.delete('/api/resources/:id', async (req, res) => {
  const { id } = req.params;

  try {
    // Fetch resource to ensure it exists
    const existingResource = await pool.query('SELECT * FROM resources WHERE id = $1 FOR UPDATE', [id]);
    if (!existingResource.rows.length) return res.status(404).json({ error: 'Resource not found' });

    // Delete resource
    await pool.query('DELETE FROM resources WHERE id = $1', [id]);

    res.status(200).json({ message: 'Resource deleted successfully' });
  } catch (error) {
