const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const { Queue } = require('queue');

const app = express();
app.use(bodyParser.json());

// Define regular expressions for book title extraction
const titleRegex = /(?:Book|Novel)\s*:\s*(.*)/i;

// Initialize a queue to manage document processing concurrently
const processQueue = new Queue({
  concurrency: 10,
  timeout: 60000,
  bufferLimit: Infinity
});

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Endpoint to process document
app.post('/process', async (req, res) => {
  const documents = req.body.documents;

  if (!Array.isArray(documents)) {
    return res.status(400).json({ error: 'Invalid input format' });
  }

  for (const doc of documents) {
    await processQueue.push(async () => {
      try {
        const titles = extractBookTitles(doc);
        for (const title of titles) {
          await validateAndCategorizeTitle(title, res);
        }
      } catch (error) {
        console.error('Error processing document:', error);
        res.status(500).json({ error: 'Internal server error' });
      }
    });
  }

  res.json({ message: 'Processing started' });
});

// Function to extract book titles using regular expressions
function extractBookTitles(document) {
  const matches = document.match(titleRegex);
  return matches ? matches.slice(1) : [];
}

// Function to validate and categorize book title
async function validateAndCategorizeTitle(title, res) {
  try {
    const genreResponse = await axios.get('https://api.example.com/genre', { params: { title } });
    if (genreResponse.data.genre) {
      // Categorize the title based on genre
      console.log(`Book "${title}" categorized as ${genreResponse.data.genre}`);
    }
  } catch (error) {
    // Retry logic with exponential backoff
    const retries = [200, 500, 1000, 3000];
    for (const delay of retries) {
      await new Promise(resolve => setTimeout(resolve, delay));
      try {
        const genreResponse = await axios.get('https://api.example.com/genre', { params: { title } });
        if (genreResponse.data.genre) {
          // Categorize the title based on genre
          console.log(`Book "${title}" categorized as ${genreResponse.data.genre}`);
          return;
        }
      } catch (error) {
        continue; // Retry next delay
      }
    }
    console.error('Failed to validate genre after retries');
  }
}

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
