// This is a simplified example of a real-time collaborative document editor using WebSockets and Merkle trees.
// It does not include all the features and considerations mentioned but provides a starting point.

const WebSocket = require('ws');
const crypto = require('crypto');

class DocumentEditor {
  constructor(documentId) {
    this.documentId = documentId;
    this.clients = new Map();
    this.documentVersion = {};
    this.merkleTree = new MerkleTree();
  }

  addClient(clientId, socket) {
    this.clients.set(clientId, socket);
    socket.on('message', (data) => this.handleMessage(data));
    socket.on('close', () => this.removeClient(clientId));
  }

  removeClient(clientId) {
    this.clients.delete(clientId);
  }

  handleMessage(message) {
    // Parse the message and apply changes to the document
    const { action, data } = JSON.parse(message);
    if (action === 'edit') {
      this.applyEdit(data);
    }
  }

  applyEdit(editData) {
    // Apply the edit to the document
    this.documentVersion[editData.id] = editData.content;
    this.merkleTree.update(this.documentVersion);
    this.broadcastUpdates();
  }

  broadcastUpdates() {
    const updates = this.merkleTree.getUpdates();
    for (const [clientId, socket] of this.clients) {
      socket.send(JSON.stringify({ action: 'update', data: updates }));
    }
  }

  static async getDocumentData(documentId) {
    // Fetch document data from a legacy system or third-party API
    return await fetch(`https://api.example.com/documents/${documentId}`).then(response => response.json());
  }

  static async updateDocumentData(documentId, newData) {
    // Update document data in the legacy system or third-party API
    return await fetch(`https://api.example.com/documents/${documentId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newData)
    }).then(response => response.json());
  }
}

class MerkleTree {
  constructor() {
    this.nodes = [];
  }

  update(data) {
    // Update the Merkle tree with new data
  }

  getUpdates() {
    // Return the updates to be broadcasted to clients
    return {};
  }
}

// Example usage:
const documentId = '12345';
const editor = new DocumentEditor(documentId);

// Simulate adding clients and receiving messages
editor.addClient('client1', { send: (message) => console.log(message) });
editor.applyEdit({ id: 'paragraph1', content: 'Updated content' });

// Fetch initial document data from an external system
DocumentEditor.getDocumentData(documentId).then(data => {
  editor.documentVersion = data;
  editor.merkleTree.update(editor.documentVersion);
});
