['```rust
use reqwest::{Client, Error};
use tokio::sync::Semaphore;
use std::time::{Duration, Instant};

const MAX_CONCURRENT_REQUESTS: usize = 100;

struct HttpClient {
    client: Client,
    semaphore: Semaphore,
}

impl HttpClient {
    fn new() -> Self {
        HttpClient {
            client: Client::new(),
            semaphore: Semaphore::new(MAX_CONCURRENT_REQUESTS),
        }
    }

    async fn get(&self, url: &str) -> Result<String, Error> {
        let permit = self.semaphore.acquire().await?;
        let response = self.client.get(url).send().await?.text().await?;
        drop(permit);
        Ok(response)
    }

    async fn post(&self, url: &str, body: String) -> Result<String, Error> {
        let permit = self.semaphore.acquire().await?;
        let response = self.client.post(url).body(body).send().await?.text().await?;
        drop(permit);
        Ok(response)
    }

    async fn put(&self, url: &str, body: String) -> Result<String, Error> {
        let permit = self.semaphore.acquire().await?;
        let response = self.client.put(url).body(body).send().await?.text().await?;
        drop(permit);
        Ok(response)
    }

    async fn delete(&self, url: &str) -> Result<String, Error> {
        let permit = self.semaphore.acquire().await?;
        let response = self.client.delete(url).send().await?.text().await?;
        drop(permit);
        Ok(response)
    }
}

#[tokio::main]
async fn main() {
    let http_client = HttpClient::new();
    match http_client.get("https://api.example.com/data").await {
        Ok(data) => println!("Data: {}", data),
        Err(e) => eprintln!("Error: {}", e),
    }
}
