package com.example.cloudstorage;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

public class CloudStorageManager {
    private ExecutorService executorService;
    private CircuitBreaker circuitBreaker;

    public CloudStorageManager() {
        this.executorService = Executors.newFixedThreadPool(10);
        this.circuitBreaker = new CircuitBreaker();
    }

    public void uploadFile(String provider, String filePath) {
        if (circuitBreaker.isOpen()) {
            throw new RuntimeException("Circuit breaker is open");
        }
        executorService.submit(() -> {
            try {
                // Simulate file upload
                Thread.sleep(100);
                System.out.println("File uploaded to " + provider);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Upload interrupted");
            }
        });
    }

    public void downloadFile(String provider, String filePath) {
        if (circuitBreaker.isOpen()) {
            throw new RuntimeException("Circuit breaker is open");
        }
        executorService.submit(() -> {
            try {
                // Simulate file download
                Thread.sleep(100);
                System.out.println("File downloaded from " + provider);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Download interrupted");
            }
        });
    }

    public void handleCircuitBreaker() {
        circuitBreaker.monitor(() -> executorService.isTerminated());
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
        }
    }
}

class CircuitBreaker {
    private final AtomicBoolean open = new AtomicBoolean(false);

    public boolean isOpen() {
        return open.get();
    }

    public void monitor(Runnable task) {
        try {
            task.run();
        } catch (Exception e) {
            open.set(true);
        }
    }
}
```

