// Worker class for processing log data
class LogProcessor {
public:
    void process(const std::string& logData, TSDBClient& db) {
        // Simulate extracting numerical data and computing rolling average
        static double sum = 0.0;
        static int count = 0;
        double value = std::stod(logData.substr(10)); // Example: Extract numeric part from log
        sum += value;
        count++;
        double average = sum / count;
        db.insert("rolling_average", average);
    }
};

// Thread pool class to manage worker threads
class ThreadPool {
public:
    ThreadPool(size_t size) : stop(false), numThreads(size) {
        for (size_t i = 0; i < size; ++i)
            workers.emplace_back([this] {
                for (;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty())
                            return;
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
    }

    template<class F, class... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            if (stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");
            tasks.emplace([f, args...] { f(args...); });
        }
        condition.notify_one();
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers)
            worker.join();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
    size_t numThreads;
};

int main() {
    KafkaConsumer kafka;
    S3Reader s3;
    TSDBClient db;
    LogProcessor processor;

    ThreadPool pool(4);

    // Simulate consuming logs from multiple sources
    std::thread consumerThread([&]() {
        while (true) {
            std::string logData = kafka.poll();
            pool.enqueue([processor, &db, logData]() { processor.process(logData, db); });
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    consumerThread.join();

    return 0;
}
