void logEmail(const std::string& email, const std::string& message) {
    // Simulated logging to a file or console
    static std::mutex logMutex;
    std::lock_guard<std::mutex> lock(logMutex);
    std::cout << "Log: " << email << " - " << message << std::endl;
}

void sendEmail(const std::string& recipient, const std::string& subject, const std::string& body) {
    if (!validateEmail(recipient)) {
        logEmail(recipient, "Invalid email address");
        return;
    }

    // Simulated API call to an external service
    bool success = false;
    for (int i = 0; i < 3 && !success; ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 1000));
        success = true; // Simulate successful delivery
    }

    if (success) {
        logEmail(recipient, "Email sent successfully");
    } else {
        logEmail(recipient, "Failed to send email after retries");
    }
}

