#include <openssl/pem.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <stdio.h>

int convert_oauth_to_pem(const char *private_key_path, const char *certificate_path, const char *output_pem_path) {
    FILE *private_key_file = fopen(private_key_path, "r");
    if (!private_key_file) {
        perror("Failed to open private key file");
        return 1;
    }

    FILE *certificate_file = fopen(certificate_path, "r");
    if (!certificate_file) {
        fclose(private_key_file);
        perror("Failed to open certificate file");
        return 1;
    }

    RSA *rsa = PEM_read_RSA_PUBKEY(private_key_file, NULL, NULL, NULL);
    if (!rsa) {
        fclose(private_key_file);
        fclose(certificate_file);
        ERR_print_errors_fp(stderr);
        return 1;
    }

    X509 *cert = PEM_read_X509(certificate_file, NULL, NULL, NULL);
    if (!cert) {
        RSA_free(rsa);
        fclose(private_key_file);
        fclose(certificate_file);
        ERR_print_errors_fp(stderr);
        return 1;
    }

    FILE *output_pem = fopen(output_pem_path, "w");
    if (!output_pem) {
        X509_free(cert);
        RSA_free(rsa);
        fclose(private_key_file);
        fclose(certificate_file);
        perror("Failed to open output PEM file");
        return 1;
    }

    if (PEM_write_RSAPrivateKey(output_pem, rsa, NULL, NULL, 0, NULL, NULL) != 1) {
        X509_free(cert);
        RSA_free(rsa);
        fclose(private_key_file);
        fclose(certificate_file);
        fclose(output_pem);
        ERR_print_errors_fp(stderr);
        return 1;
    }

    if (PEM_write_X509(output_pem, cert) != 1) {
        X509_free(cert);
        RSA_free(rsa);
        fclose(private_key_file);
        fclose(certificate_file);
        fclose(output_pem);
        ERR_print_errors_fp(stderr);
        return 1;
    }

    X509_free(cert);
    RSA_free(rsa);
    fclose(private_key_file);
    fclose(certificate_file);
    fclose(output_pem);

    printf("PEM file created successfully at %s\n", output_pem_path);
    return 0;
}
```

This function reads a private key and certificate from specified paths, converts them into RSA and X509 structures respectively, and then writes these structures to an output PEM file. The function handles file operations and OpenSSL-specific errors, ensuring that resources are freed properly in case of any failures.']

