// TCPConnectionManager.h
#pragma once

#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

struct TCP_CONNECTION_RECORD_T {
    std::string ipAddress;
    int port;
    std::string encryptionKey;
};

class TCPConnectionManager {
public:
    void addConnection(const TCP_CONNECTION_RECORD_T& connection);
    void removeConnection(int connectionId);
    void start();
    void stop();

private:
    void workerThread();
    void handleConnection(const TCP_CONNECTION_RECORD_T& connection);

    std::vector<TCP_CONNECTION_RECORD_T> connections;
    std::mutex connectionsMutex;
    std::condition_variable cv;
    bool running = false;
};

// TCPConnectionManager.cpp
#include "TCPConnectionManager.h"
#include <openssl/evp.h>
#include <openssl/rand.h>

void TCPConnectionManager::addConnection(const TCP_CONNECTION_RECORD_T& connection) {
    std::lock_guard<std::mutex> lock(connectionsMutex);
    connections.push_back(connection);
}

void TCPConnectionManager::removeConnection(int connectionId) {
    std::lock_guard<std::mutex> lock(connectionsMutex);
    connections.erase(connections.begin() + connectionId);
}

void TCPConnectionManager::start() {
    running = true;
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        std::thread(&TCPConnectionManager::workerThread, this).detach();
    }
}

void TCPConnectionManager::stop() {
    {
        std::lock_guard<std::mutex> lock(connectionsMutex);
        running = false;
    }
    cv.notify_all();
}

void TCPConnectionManager::workerThread() {
    while (true) {
        std::unique_lock<std::mutex> lock(connectionsMutex);
        cv.wait(lock, [this]{ return !connections.empty() || !running; });

        if (!running && connections.empty()) break;

        auto connection = connections.back();
        connections.pop_back();
        lock.unlock();

        handleConnection(connection);
    }
}

void TCPConnectionManager::handleConnection(const TCP_CONNECTION_RECORD_T& connection) {
