#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NetworkEventLogEntry {
    time_t timestamp;
    char eventType[128];
    double metrics;
} NetworkEventLogEntry;

typedef struct ListNode {
    NetworkEventLogEntry entry;
    struct ListNode* next;
} ListNode;

typedef struct ThreadSafeList {
    pthread_mutex_t lock;
    ListNode* head;
    size_t count;
} ThreadSafeList;

ThreadSafeList* createThreadSafeList() {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    if (list == NULL) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroyThreadSafeList(ThreadSafeList* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addEntryToThreadSafeList(ThreadSafeList* list, NetworkEventLogEntry entry) {
    pthread_mutex_lock(&list->lock);
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    newNode->entry = entry;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int getEntryFromThreadSafeList(ThreadSafeList* list, NetworkEventLogEntry** entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count == 0) {
        pthread_mutex_unlock(&list->lock);
        *entry = NULL;
        return -1;
    }
    ListNode* node = list->head;
    *entry = &node->entry;
    list->head = node->next;
    free(node);
    list->count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Implement other necessary functions for external logging service integration, error handling, and performance optimizations.

// Document the trade-offs made and provide unit tests.
```

