using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MD5HashLibrary
{
    private static readonly ConcurrentDictionary<string, string> hashCache = new();
    private const int MinLength = 1;
    private const int MaxLength = 100;

    public string GenerateMD5Hash(string input)
    {
        if (!IsValidInput(input))
        {
            throw new ArgumentException("Invalid input. Input must be alphanumeric and within the specified length range.");
        }

        if (hashCache.TryGetValue(input, out var cachedHash))
        {
            return cachedHash;
        }

        using (var md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            string hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

            lock (hashCache)
            {
                if (!hashCache.ContainsKey(input))
                {
                    hashCache[input] = hash;
                }
            }

            return hash;
        }
    }

    public bool VerifyMD5Hash(string input, string expectedHash)
    {
        if (!IsValidInput(input) || !IsValidHash(expectedHash))
        {
            throw new ArgumentException("Invalid input. Input must be alphanumeric and within the specified length range.");
        }

        string actualHash = GenerateMD5Hash(input);
        return string.Equals(actualHash, expectedHash, StringComparison.OrdinalIgnoreCase);
    }

    private bool IsValidInput(string input)
    {
        if (input == null || input.Length < MinLength || input.Length > MaxLength)
        {
            return false;
        }

        foreach (char c in input)
        {
            if (!char.IsLetterOrDigit(c))
            {
                return false;
            }
        }

        return true;
    }

    private bool IsValidHash(string hash)
    {
        if (hash == null || hash.Length != 32)
        {
            return false;
        }

        foreach (char c in hash)
        {
            if (!char.IsDigit(c) && !char.IsLetter(c))
            {
                return false;
            }
        }

        return true;
    }
}
