package securedata

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/tls"
	"encoding/json"
	"fmt"
	"net/http"
	"sync/atomic"

	"github.com/go-resty/resty/v2"
)

// CustomData represents the structure of the data retrieved and decrypted.
type CustomData struct {
	ID   uint64 `json:"id"`
	Name string `json:"name"`
}

var (
	nextID uint64
	idMutex sync.Mutex
)

func init() {
	http.DefaultClient = &http.Client{
		Transport: &tls.Config{InsecureSkipVerify: true}, // For simplicity, in production use proper TLS configuration
		Timeout:   5 * time.Second,
	}
}

// LoadSecureData retrieves, decrypts, and deserializes encrypted data from a secure storage service.
func LoadSecureData(encryptedData []byte, key []byte, iv []byte, url string) (*CustomData, error) {
	if len(key) != aes.BlockSize || len(iv) != aes.BlockSize {
		return nil, fmt.Errorf("invalid encryption key or IV length")
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, fmt.Errorf("failed to create cipher block: %w", err)
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	decryptedData := make([]byte, len(encryptedData))
	mode.CryptBlocks(decryptedData, encryptedData)

	var data CustomData
	if err := json.Unmarshal(decryptedData, &data); err != nil {
		return nil, fmt.Errorf("failed to unmarshal decrypted data: %w", err)
	}

	idMutex.Lock()
	data.ID = atomic.AddUint64(&nextID, 1)
	idMutex.Unlock()

	return &data, nil
}
```

