    {
        if (!File.Exists(_databasePath))
        {
            File.Create(_databasePath).Close();
        }
        _connection = new SQLiteConnection($"Data Source={_databasePath};Version=3;");
        _connection.Open();

        using (var command = new SQLiteCommand("CREATE TABLE IF NOT EXISTS Events (Id INTEGER PRIMARY KEY, Data BLOB);", _connection))
        {
            command.ExecuteNonQuery();
        }
    }

    public async Task LoadAndDeserializeAsync(string filePath)
    {
        using (var fileStream = File.OpenRead(filePath))
        {
            await ProcessFileAsync(fileStream);
        }
    }

    private async Task ProcessFileAsync(Stream fileStream)
    {
        var buffer = new byte[4096 * 1024]; // 4MB
        int bytesRead;

        while ((bytesRead = await fileStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            var events = DeserializeEvents(buffer, bytesRead);
            await InsertEventsIntoDatabaseAsync(events);
        }
    }

    private Event[] DeserializeEvents(byte[] data, int length)
    {
        // Placeholder for actual deserialization logic
        // This should be optimized to handle large binary datasets efficiently
        return new Event[0];
