    private async Task InsertEventsIntoDatabaseAsync(Event[] events)
    {
        using (var transaction = _connection.BeginTransaction())
        {
            foreach (var eventItem in events)
            {
                await InsertEventAsync(eventItem, transaction);
            }
            transaction.Commit();
        }
    }

    private async Task InsertEventAsync(Event eventItem, SQLiteTransaction transaction)
    {
        using (var command = new SQLiteCommand("INSERT INTO Events (Data) VALUES (@Data)", _connection, transaction))
        {
            command.Parameters.AddWithValue("@Data", eventItem.Data);
            await command.ExecuteNonQueryAsync();
        }
    }

    public void Dispose()
    {
        if (_connection != null && _connection.State == System.Data.ConnectionState.Open)
        {
            _connection.Close();
        }
    }
}

