    private CollectorRegistry prometheusRegistry = new CollectorRegistry();

    private WeatherDataLibrary() {
        // Private constructor for singleton pattern
    }

    public static WeatherDataLibrary getInstance() {
        if (instance == null) {
            synchronized (WeatherDataLibrary.class) {
                if (instance == null) {
                    instance = new WeatherDataLibrary();
                }
            }
        }
        return instance;
    }

    // Method to get weather data for a location
    public WeatherData getWeatherData(String location, String timeInterval, String unitOfMeasurement) throws IOException, InterruptedException {
        if (circuitBreakerOpen) {
            throw new CircuitBreakerOpenException("Circuit breaker is open");
        }

        try {
            WeatherData cachedData = cache.get(location);
            if (cachedData != null && !isCacheExpired(cachedData)) {
                return cachedData;
            }

            String apiUrl = buildApiUrl(location, timeInterval, unitOfMeasurement);
            Future<WeatherData> future = executorService.submit(new ApiRequestTask(apiUrl));
            WeatherData data = future.get();

            cache.put(location, data);
            prometheusRegistry.register(data.getLatency());
            return data;
        } catch (TimeoutException e) {
            backoffStrategy.backOff();
            throw new TimeoutException("API request timed out");
        } catch (Exception e) {
            circuitBreakerOpen = true;
            prometheusRegistry.registerError();
            return getFallbackWeatherData(location);
        }
    }

    // Helper method to build API URL
    private String buildApiUrl(String location, String timeInterval, String unitOfMeasurement) {
        StringBuilder sb = new StringBuilder("https://weatherapi.com/data/3.0/current.json?key=your_api_key&q=");
        sb.append(URLEncoder.encode(location, StandardCharsets.UTF_8));
        sb.append("&interval=").append(timeInterval);
        sb.append("&units=").append(unitOfMeasurement);
        return sb.toString();
    }

    // Helper method to check if cache data is expired
    private boolean isCacheExpired(WeatherData data) {
        long currentTime = System.currentTimeMillis();
        return (currentTime - data.getTimestamp()) > 3600000; // Cache expires after 1 hour
    }

    // Method to get fallback weather data
    private WeatherData getFallbackWeatherData(String location) {
        // Implement fallback logic here, e.g., use cached data or default values
        return new WeatherData(location, "N/A", "N/A");
    }
}

// Asynchronous task for API requests
class ApiRequestTask implements Callable<WeatherData> {
    private String apiUrl;

    public ApiRequestTask(String apiUrl) {
        this.apiUrl = apiUrl;
    }

    @Override
    public WeatherData call() throws IOException {
        URL url = new URL(apiUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            InputStream inputStream = connection.getInputStream();
            // Parse the JSON response and create WeatherData object
            return parseJsonResponse(inputStream);
        } else {
            throw new IOException("API request failed with response code: " + responseCode);
        }
    }

    // Helper method to parse JSON response
    private WeatherData parseJsonResponse(InputStream inputStream) throws IOException {
        // Implement JSON parsing logic here
        return new WeatherData();
    }
}

// Custom exception for open circuit breaker
class CircuitBreakerOpenException extends Exception {
    public CircuitBreakerOpenException(String message) {
        super(message);
    }
}
```

