using Polly;
using Polly.Retry;

public class Startup
{
    public IConfiguration Configuration { get; }

    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public void ConfigureServices(IServiceCollection services)
    {
        // Add your service dependencies here
        services.AddControllers();

        // Database connection
        services.AddDbContext<YourDbContext>(options =>
            options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

        // Circuit breaker for database operations
        var retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        services.AddSingleton(retryPolicy);

        // Security and rate limiting
        services.AddHttpClient("ExternalService", client =>
        {
            client.DefaultRequestHeaders.Add("Accept", "application/json");
        }).AddHttpMessageHandler<RateLimitingDelegatingHandler>();

        services.AddSingleton<IHttpContextAccessor, HttpContextAccessor>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();

        // Custom middleware for port availability and operational constraints
        app.UseMiddleware<PortAvailabilityMiddleware>();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}

public class PortAvailabilityMiddleware
{
    private readonly RequestDelegate _next;
    private static int _currentPort = 8081;

    public PortAvailabilityMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        while (!IsPortAvailable(_currentPort))
        {
            _currentPort++;
            if (_currentPort > 8100) throw new Exception("No available port found between 8081 and 8100");
        }

        context.Request.Host = new HostString($"localhost:{_currentPort}");
        await _next(context);
    }

    private bool IsPortAvailable(int port)
    {
        try
        {
            using (var tcpListener = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Any, port))
            {
                tcpListener.Start();
                tcpListener.Stop();
                return true;
            }
        }
        catch
        {
            return false;
        }
    }
}

public class RateLimitingDelegatingHandler : DelegatingHandler
{
    private readonly ICircuitBreaker _circuitBreaker;

    public RateLimitingDelegatingHandler(ICircuitBreaker circuitBreaker)
    {
        _circuitBreaker = circuitBreaker;
    }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        var response = await base.SendAsync(request, cancellationToken);

        if (response.StatusCode == System.Net.HttpStatusCode.ServiceUnavailable)
        {
            _circuitBreaker.Open();
        }
        else
        {
            _circuitBreaker.Close();
        }

        return response;
    }
}

public class RateLimitingMiddleware : IMiddleware
{
    private readonly int _limitPerMinute;

    public RateLimitingMiddleware(int limitPerMinute)
    {
        _limitPerMinute = limitPerMinute;
    }

    public async Task InvokeAsync(HttpContext context, RequestDelegate next)
    {
        // Implement rate limiting logic here
        await next(context);
    }
}
