#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(struct Record)
#define MEMORY_LIMIT (MAX_RECORDS * RECORD_SIZE)

typedef struct {
    long offset;
    int key;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_record(long offset, int key) {
    pthread_mutex_lock(&mutex);
    if (record_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory limit reached
    }
    records[record_count].offset = offset;
    records[record_count].key = key;
    record_count++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int get_record(int index, Record *result) {
    if (index < 0 || index >= record_count) {
        return -1; // Invalid index
    }
    *result = records[index];
    return 0;
}

void free_records() {
    pthread_mutex_lock(&mutex);
    record_count = 0;
    pthread_mutex_unlock(&mutex);
}
