# Import necessary libraries
from Crypto.Cipher import DES, AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
from abc import ABC, abstractmethod

# Define an abstract base class for cipher algorithms
class CipherAlgorithm(ABC):
    @abstractmethod
    def encrypt(self, data: bytes, key: bytes) -> bytes:
        pass

    @abstractmethod
    def decrypt(self, data: bytes, key: bytes) -> bytes:
        pass

# Implement DES encryption algorithm
class DESCipher(CipherAlgorithm):
    def encrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = DES.new(key, DES.MODE_ECB)
        return cipher.encrypt(pad(data, DES.block_size))

    def decrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = DES.new(key, DES.MODE_ECB)
        return unpad(cipher.decrypt(data), DES.block_size)

# Implement AES encryption algorithm
class AesCipher(CipherAlgorithm):
    def encrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = AES.new(key, AES.MODE_ECB)
        return cipher.encrypt(pad(data, AES.block_size))

    def decrypt(self, data: bytes, key: bytes) -> bytes:
        cipher = AES.new(key, AES.MODE_ECB)
        return unpad(cipher.decrypt(data), AES.block_size)

# Define a class for the cryptographic service
class CryptographicService:
    def __init__(self):
        self.ciphers = {
            'DES': DESCipher(),
            'AES': AesCipher()
        }
        self.key_management_systems = {}

    def add_cipher_algorithm(self, name: str, algorithm: CipherAlgorithm):
        self.ciphers[name] = algorithm

    def add_key_management_system(self, name: str, system):
        self.key_management_systems[name] = system

    def encrypt(self, data: bytes, algorithm_name: str, key: bytes) -> bytes:
        cipher = self.ciphers.get(algorithm_name)
        if cipher:
            return cipher.encrypt(data, key)
        else:
            raise ValueError(f"Algorithm {algorithm_name} not supported")

    def decrypt(self, data: bytes, algorithm_name: str, key: bytes) -> bytes:
        cipher = self.ciphers.get(algorithm_name)
        if cipher:
            return cipher.decrypt(data, key)
        else:
            raise ValueError(f"Algorithm {algorithm_name} not supported")

# Example usage
service = CryptographicService()
key = get_random_bytes(8)  # DES key size
data = b'Hello, World!'
encrypted_data = service.encrypt(data, 'DES', key)
decrypted_data = service.decrypt(encrypted_data, 'DES', key)

print("Original:", data)
print("Encrypted:", encrypted_data)
print("Decrypted:", decrypted_data)
