#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_log_file> <output_log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *inputFile = fopen(argv[1], "r");
    FILE *outputFile = fopen(argv[2], "w");

    if (!inputFile || !outputFile) {
        perror("Error opening files");
        fclose(inputFile);
        fclose(outputFile);
        return EXIT_FAILURE;
    }

    // Asynchronously process log file contents
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), inputFile)) {
        // Process each log entry and write to output file
        fprintf(outputFile, "%s", buffer);
    }

    fclose(inputFile);
    fclose(outputFile);

    return EXIT_SUCCESS;
}
