#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_N 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_POOL_T;

typedef struct {
    CURL *handle;
    char url[256];
    int max_retries;
    double backoff_factor;
} DB_CONNECTION_T;

NFAPI_CRC_POOL_T *init_crc_pool(size_t initial_capacity) {
    NFAPI_CRC_POOL_T *pool = malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) return NULL;

    pool->pdus = realloc(pool->pdus, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdus) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_crc_pool(NFAPI_CRC_POOL_T *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->mutex);
        free(pool->pdus);
        free(pool);
    }
}

int resize_crc_pool(NFAPI_CRC_POOL_T *pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->mutex);
    pool->pdus = realloc(pool->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdus) {
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }
    pool->capacity = new_capacity;
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

int add_crc_pdu(NFAPI_CRC_POOL_T *pool, unsigned int rx_tag, unsigned short rnti, unsigned char crc_flag) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count >= pool->capacity && resize_crc_pool(pool, pool->capacity * 2) != 0) {
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pdus[pool->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc_flag;
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

DB_CONNECTION_T *init_db_connection(const char *url, int max_retries, double backoff_factor) {
    DB_CONNECTION_T *conn = malloc(sizeof(DB_CONNECTION_T));
    if (!conn) return NULL;

    conn->handle = curl_easy_init();
    if (!conn->handle) {
        free(conn);
        return NULL;
    }

    snprintf(conn->url, sizeof(conn->url), "%s", url);
    conn->max_retries = max_retries;
    conn->backoff_factor = backoff_factor;
    return conn;
}

void destroy_db_connection(DB_CONNECTION_T *conn) {
    if (conn) {
        curl_easy_cleanup(conn->handle);
        free(conn);
    }
}

int persist_rnti(DB_CONNECTION_T *conn, unsigned short rnti) {
    CURLcode res;
    int retries = 0;

    while (retries < conn->max_retries) {
        char url[512];
        snprintf(url, sizeof(url), "%s?rnti=%d", conn->url, rnti);

        curl_easy_setopt(conn->handle, CURLOPT_URL, url);
        res = curl_easy_perform(conn->handle);

        if (res == CURLE_OK) {
            return 0;
        }

        retries++;
        sleep((int)(conn->backoff_factor * retries));
    }

    return -1;
}

unsigned char *compute_md5_hash(const char *file_path, size_t *hash_size) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return NULL;

    unsigned char buffer[8192];
    MD5_CTX md5;
    MD5_Init(&md5);

    while (size_t bytes_read = fread(buffer, 1, sizeof(buffer), file)) {
        MD5_Update(&md5, buffer, bytes_read);
    }

    fclose(file);

    unsigned char *hash = malloc(MD5_DIGEST_LENGTH);
    if (!hash) return NULL;

    MD5_Final(hash, &md5);
    *hash_size = MD5_DIGEST_LENGTH;
    return hash;
}

void cleanup(void *ptr) {
    free(ptr);
}
