void init_crc_indications(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Error: N must be a positive integer.\n");
        exit(EXIT_FAILURE);
    }
    num_credits = N;
    allocated_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
