    if (num_credits == 0) {
        size_t new_allocated_size = allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_crc_indications = realloc(crc_indications, new_allocated_size);
        if (!new_crc_indications) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        crc_indications = new_crc_indications;
        allocated_size = new_allocated_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *indication = &crc_indications[--num_credits];
    pthread_mutex_unlock(&mutex);
    return indication;
}

void free_crc_indication(void* ptr) {
