size_t md5_file(const char *path, unsigned char *digest) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return 0;
    }

    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!mdctx) {
        fclose(file);
        perror("Error creating MD context");
        return 0;
    }

    if (1 != EVP_DigestInit_ex(mdctx, EVP_md5(), NULL)) {
        EVP_MD_CTX_free(mdctx);
        fclose(file);
        perror("Error initializing MD digest");
        return 0;
    }

    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        if (1 != EVP_DigestUpdate(mdctx, buffer, bytesRead)) {
            EVP_MD_CTX_free(mdctx);
            fclose(file);
            perror("Error updating MD digest");
            return 0;
        }
    }

    fclose(file);

    if (1 != EVP_DigestFinal_ex(mdctx, digest, NULL)) {
        EVP_MD_CTX_free(mdctx);
        fprintf(stderr, "Error finalizing MD digest\n");
        return 0;
    }

    EVP_MD_CTX_free(mdctx);
    return 20; // MD5 is 16 bytes
}

void* hash_file(const char *path, const char *algorithm) {
    if (strcmp(algorithm, "MD5") == 0) {
        unsigned char digest[20];
        size_t digest_size = md5_file(path, digest);
        if (digest_size != 0) {
            // Allocate memory and return the digest
            void* hash_result = malloc(digest_size);
            memcpy(hash_result, digest, digest_size);
            return hash_result;
        }
    }
    // Handle other algorithms or errors
    fprintf(stderr, "Error: Unsupported algorithm or file reading failed.\n");
    return NULL;
}

void cleanup() {
    free(crc_indications);
    curl_global_cleanup();
}

