// Function to acquire a PDU from the pool
NFAPI_CRC_INDICATION_PDU_T* acquire_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;

    pthread_mutex_lock(&pool_mutex);
    if (pool_count > 0) {
        pdu = pdu_pool[--pool_count];
