class TimeSeriesDataProcessor {
public:
    TimeSeriesDataProcessor(size_t numThreads = 4)
        : numThreads(numThreads), stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&TimeSeriesDataProcessor::workerThread, this);
        }
    }

    ~TimeSeriesDataProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addDataPoint(const DataPoint& dataPoint) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            dataQueue.push(dataPoint);
        }
        condition.notify_one();
    }

private:
    struct DataPoint {
        // Define the structure of a data point
    };

    void workerThread() {
        while (true) {
            DataPoint dataPoint;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return stop || !dataQueue.empty(); });
                if (stop && dataQueue.empty()) {
                    return;
                }
                dataPoint = dataQueue.front();
                dataQueue.pop();
            }
            process(dataPoint);
        }
    }

    void process(const DataPoint& dataPoint) {
        // Implement data processing logic
    }

    size_t numThreads;
    std::vector<std::thread> workers;
    std::queue<DataPoint> dataQueue;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;
};

