Promise<number> reduceArrayAsync(const Array<number>& numbers, number initialValue, Promise<number> callback) {
    return new Promise((resolve, reject) => {
        let accumulator = initialValue;

        for (let i = 0; i < numbers.length; i++) {
            const currentNumber = numbers[i];
            callback(accumulator, currentNumber).then(value => {
                accumulator = value;
                if (i === numbers.length - 1) {
                    resolve(accumulator);
                }
            }).catch(error => {
                reject(error);
            });
        }
    });
}

