    struct Node* next;
} Node;

Node* head = NULL;
int pdu_count = 0;
time_t last_query_time = 0;
#define QUERY_INTERVAL 3600 // Once an hour

// External RNTI validation function
int validate_RNTI(int RNTI) {
    // Simulate external service delay and potential failure
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    if (ts.tv_sec - last_query_time < QUERY_INTERVAL) return 0; // Too soon

    if ((rand() % 2) == 0) {
        last_query_time = ts.tv_sec;
        return RNTI; // Validation successful
    } else {
        return -1; // Validation failed
    }
}

// Function to create a new PDU
NFAPI_CRC_INDICATION_PDU* create_PDU(int RX_UE_INFORMATION_TAG, int RNTI, char* CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU* pdu = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdu) return NULL; // Memory allocation failed

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    strcpy(pdu->CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);
    pdu->CRCFLAG = CRCFLAG;

    return pdu;
}

// Function to add a new PDU to the list
int add_PDU(NFAPI_CRC_INDICATION_PDU* pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failed

    newNode->data = *pdu;
    newNode->next = head;
    head = newNode;

    pdu_count++;
    return 0;
}

// Function to generate PDUs
int generate_PDUs(int N) {
    srand(time(0)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        int RNTI = rand() % MAX_PDUS + 1; // Generate a unique RNTI
        while (validate_RNTI(RNTI) == -1) { // Retry until validation succeeds
            RNTI = rand() % MAX_PDUS + 1;
