        NFAPI_CRC_INDICATION_PDU* pdu = create_PDU(i, RNTI, "Tag", rand() % 2);
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed for PDU\n");
            return -1;
        }

        if (add_PDU(pdu) != 0) {
            fprintf(stderr, "Failed to add PDU to the list\n");
            free(pdu);
            return -1;
        }
    }

    return 0;
}

int main() {
