class TransactionProcessor {
private:
    std::queue<std::string> transactionsQueue;
    std::vector<PaymentGateway*> gateways;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stopProcessing;

public:
    TransactionProcessor(const std::vector<PaymentGateway*>& _gateways) : gateways(_gateways), stopProcessing(false) {}

    void addTransaction(const std::string& transaction) {
        std::lock_guard<std::mutex> lock(queueMutex);
        transactionsQueue.push(transaction);
        cv.notify_one();
    }

    void startProcessing() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !transactionsQueue.empty() || stopProcessing; });
                if (stopProcessing && transactionsQueue.empty()) break;

                std::string transaction = transactionsQueue.front();
                transactionsQueue.pop();
                lock.unlock();

                for (auto& gateway : gateways) {
                    if (gateway->processTransaction(transaction)) {
                        // Transaction processed successfully
                        break;
                    }
                }
            }
        }).detach();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        cv.notify_all();
    }
};

int main() {
    CreditCardGateway creditCardGateway;
    DigitalWalletGateway digitalWalletGateway;
    BankTransferGateway bankTransferGateway;

