        ObjectInputStream ois = null;
        try {
            FileInputStream fis = new FileInputStream(filePath);
            ois = new ObjectInputStream(fis);
            return (MoSTState) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
            return null;
        } finally {
            if (ois != null) {
                try {
                    ois.close();
