#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    LTE_NAS_TYPE_SMS,
    LTE_NAS_TYPE_LOCATION_UPDATE
} NAS_MESSAGE_TYPE;

typedef struct nas_pdu {
    uint8_t *data;
    size_t length;
} NAS_PDU;

typedef struct nas_message {
    NAS_MESSAGE_TYPE type;
    int mme_id;
    int sgsn_id;
    NAS_PDU pdu;
    pthread_mutex_t lock;
    struct nas_message *next;
} NAS_Message;

NAS_Message* nas_messages = NULL;

pthread_mutex_t nas_messages_lock = PTHREAD_MUTEX_INITIALIZER;

void add_nas_message(NAS_Message* msg) {
    pthread_mutex_lock(&nas_messages_lock);
    NAS_Message** current = &nas_messages;
    while (*current != NULL) {
        current = &((*current)->next);
    }
    *current = msg;
    pthread_mutex_unlock(&nas_messages_lock);
}

NAS_Message* get_nas_message(int mme_id, int sgsn_id) {
    pthread_mutex_lock(&nas_messages_lock);
    NAS_Message* current = nas_messages;
    while (current != NULL) {
        if (current->mme_id == mme_id && current->sgsn_id == sgsn_id) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&nas_messages_lock);
    return current;
}

void remove_nas_message(int mme_id, int sgsn_id) {
    pthread_mutex_lock(&nas_messages_lock);
    NAS_Message** current = &nas_messages;
    while (*current != NULL) {
        if ((*current)->mme_id == mme_id && (*current)->sgsn_id == sgsn_id) {
            NAS_Message* temp = *current;
            *current = (*current)->next;
            pthread_mutex_unlock(&nas_messages_lock);
            pthread_mutex_destroy(&temp->lock);
            free(temp->pdu.data);
            free(temp);
            return;
        }
        current = &((*current)->next);
    }
    pthread_mutex_unlock(&nas_messages_lock);
}
