import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;

public class LTE_NAS_Manager {
    private static final ExecutorService executorService = Executors.newCachedThreadPool();
    private static final BlockingQueue<String> messageQueue = new LinkedBlockingQueue<>();
    private static final ConcurrentHashMap<Integer, byte[]> messageCache = new ConcurrentHashMap<>();

    public void putMessage(int mmeId, int sgsnId, byte[] pdu) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
        String hash = bytesToHex(md.digest(pdu));
        executorService.submit(() -> {
            messageCache.put(hash, pdu);
            if (!executorService.isShutdown()) {
                messageQueue.offer(hash);
            }
        });
    }

    public void deleteMessage(int mmeId, int sgsnId) {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
        String hash = bytesToHex(md.digest(new byte[0]));
        executorService.submit(() -> {
            messageCache.remove(hash);
            if (!executorService.isShutdown()) {
                messageQueue.offer(hash);
            }
        });
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
