	"time"

	"github.com/dgrijalva/jwt-go"
	"golang.org/x/oauth2"
)

type JWTService struct {
	cas         []CA
	cache       *LRUCache
	tracer      Tracer
	logger      Logger
}

func NewJWTService(cas []CA, cacheSize int, tracer Tracer, logger Logger) *JWTService {
	return &JWTService{
		cas:    cas,
		cache:  NewLRUCache(cacheSize),
		tracer: tracer,
		logger: logger,
	}
}

type CA interface {
	SignJWT(token *jwt.Token) (string, error)
	GetQuota() (int, error)
	Priority() int
}

func (s *JWTService) GenerateJWT(claims jwt.Claims) (string, error) {
	ctx := s.tracer.StartSpan("generate_jwt")
	defer ctx.Finish()

	keyID, err := s.selectKeyID()
	if err != nil {
		s.logger.Error(ctx, "Failed to select key ID", err)
		return "", err
	}

	privateKey, ok := s.cache.Get(keyID).(*rsa.PrivateKey)
	if !ok || privateKey == nil {
		var ca CA
		for _, c := range s.cas {
			quota, _ := c.GetQuota()
			if quota > 0 {
				ca = c
				break
			}
		}

		privateKey, err = ca.SignJWT(jwt.NewWithClaims(jwt.SigningMethodRS256, claims))
		if err != nil {
			s.logger.Error(ctx, "Failed to sign JWT", err)
			return "", err
		}

		s.cache.Set(keyID, privateKey, time.Hour)
	} else {
		privateKey = s.cache.Get(keyID).(*rsa.PrivateKey)
	}

	token := jwt.NewWithClaims(jwt.SigningMethodRS256, claims)
	signedToken, err := token.SignedString(privateKey)
	if err != nil {
		s.logger.Error(ctx, "Failed to sign JWT", err)
		return "", err
	}

	return signedToken, nil
}

func (s *JWTService) selectKeyID() (string, error) {
	ctx := s.tracer.StartSpan("select_key_id")
	defer ctx.Finish()

	var selectedCA CA
	minLatency := time.Hour

	for _, ca := range s.cas {
		latency, err := s.measureLatency(ca)
		if err != nil {
			s.logger.Error(ctx, "Failed to measure latency", err)
			continue
		}

		if latency < minLatency || selectedCA == nil {
			minLatency = latency
			selectedCA = ca
		}
	}

	if selectedCA == nil {
		return "", fmt.Errorf("no available CA")
	}

	keyID, err := selectedCA.GetQuota()
	if err != nil {
		s.logger.Error(ctx, "Failed to get quota", err)
		return "", err
	}

	return keyID, nil
}

func (s *JWTService) measureLatency(ca CA) (time.Duration, error) {
	ctx := s.tracer.StartSpan("measure_latency")
	defer ctx.Finish()

	start := time.Now()
	_, err := ca.SignJWT(jwt.NewWithClaims(jwt.SigningMethodRS256, jwt.MapClaims{}))
	elapsed := time.Since(start)

	if err != nil {
		s.logger.Error(ctx, "Failed to measure latency", err)
		return 0, err
	}

	return elapsed, nil
}
