// C Library Code

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NAS_PDU {
    unsigned char *data;
    size_t length;
} NAS_PDU;

typedef enum NAS_MESSAGE_TYPE {
    ATTACH_REQUEST,
    DETACH_REQUEST,
    // Add more types as needed
} NAS_MESSAGE_TYPE;

typedef struct LTE_NAS_Message {
    NAS_MESSAGE_TYPE type;
    int MME_ID;
    int SGSN_ID;
    NAS_PDU *NAS_PDU_buffer;
} LTE_NAS_Message;

typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

typedef struct Collection {
    Record **records;
    size_t count;
    pthread_mutex_t lock;
} Collection;

Collection *create_collection() {
    Collection *collection = malloc(sizeof(Collection));
    collection->records = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_record(Collection *collection, Record *record) {
    pthread_mutex_lock(&collection->lock);
    collection->records = realloc(collection->records, (collection->count + 1) * sizeof(Record *));
    collection->records[collection->count++] = record;
    pthread_mutex_unlock(&collection->lock);
}

void update_record(Collection *collection, int key, Record *new_record) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]);
            collection->records[i] = new_record;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void delete_record(Collection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]);
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->records = realloc(collection->records, collection->count * sizeof(Record *));
            --collection->count;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void destroy_collection(Collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]);
    }
    free(collection->records);
    free(collection);
}
