@SpringBootApplication
@RestController
public class LTE_NAS_Microservice {

    private final CollectionService collectionService = new CollectionService();

    @PostMapping("/records")
    public void addRecord(@Valid @RequestBody Record record) {
        collectionService.addRecord(record);
    }

    @PutMapping("/records/{key}")
    public void updateRecord(@PathVariable int key, @Valid @RequestBody Record record) {
        collectionService.updateRecord(key, record);
    }

    @DeleteMapping("/records/{key}")
    public void deleteRecord(@PathVariable int key) {
        collectionService.deleteRecord(key);
    }
}

class CollectionService {

    private final Collection collection = new Collection();

    public synchronized void addRecord(Record record) {
        collection.add(record);
    }

    public synchronized void updateRecord(int key, Record record) {
        collection.update(key, record);
    }

    public synchronized void deleteRecord(int key) {
        collection.delete(key);
    }
}

class Collection {

    private final List<Record> records = new CopyOnWriteArrayList<>();

    public synchronized void add(Record record) {
        records.add(record);
    }

    public synchronized void update(int key, Record record) {
        for (int i = 0; i < records.size(); ++i) {
            if (records.get(i).getKey() == key) {
                records.set(i, record);
                break;
            }
        }
    }

    public synchronized void delete(int key) {
        records.removeIf(record -> record.getKey() == key);
    }
}

class Record {

    private int key;
    private long offset;
    private int value;

    // Getters and setters
}
