LTE_NAS_Message* create_LTE_NAS_Message(const char* type, int mme_id, int sgsn_id, const unsigned char* pdu) {
    LTE_NAS_Message* msg = malloc(sizeof(LTE_NAS_Message));
    if (msg != NULL) {
