        msg->MME_ID = mme_id;
        msg->SGSN_ID = sgsn_id;
        msg->NAS_PDU = malloc(strlen((char*)pdu));
        if (msg->NAS_PDU != NULL) {
            memcpy(msg->NAS_PDU, pdu, strlen((char*)pdu));
        } else {
            free(msg);
            return NULL;
        }
    }
    return msg;
}

void update_LTE_NAS_Message(LTE_NAS_Message* msg, const char* type, int mme_id, int sgsn_id, const unsigned char* pdu) {
    pthread_mutex_lock(&nas_message_lock);
    strncpy(msg->NAS_MESSAGE_TYPE, type, sizeof(msg->NAS_MESSAGE_TYPE) - 1);
    msg->MME_ID = mme_id;
    msg->SGSN_ID = sgsn_id;
    if (msg->NAS_PDU != NULL) {
        free(msg->NAS_PDU);
    }
    msg->NAS_PDU = malloc(strlen((char*)pdu));
    if (msg->NAS_PDU != NULL) {
        memcpy(msg->NAS_PDU, pdu, strlen((char*)pdu));
    }
    pthread_mutex_unlock(&nas_message_lock);
}

void delete_LTE_NAS_Message(LTE_NAS_Message* msg) {
    pthread_mutex_lock(&nas_message_lock);
    if (msg->NAS_PDU != NULL) {
        free(msg->NAS_PDU);
    }
    free(msg);
    pthread_mutex_unlock(&nas_message_lock);
}
