# Import necessary libraries
from kafka import KafkaConsumer, KafkaProducer
import json
from datetime import datetime
import time
import threading

# Define constants
KAFKA_BOOTSTRAP_SERVERS = 'localhost:9092'
INPUT_TOPIC = 'event_stream'
OUTPUT_TOPIC = 'processed_data'
LOG_LEVEL = 'INFO'

# Initialize Kafka producer and consumer
producer = KafkaProducer(bootstrap_servers=KAFKA_BOOTSTRAP_SERVERS, value_serializer=lambda v: json.dumps(v).encode('utf-8'))
consumer = KafkaConsumer(INPUT_TOPIC, bootstrap_servers=KAFKA_BOOTSTRAP_SERVERS, auto_offset_reset='earliest', enable_auto_commit=True, group_id=None)

# Define data processing function
def process_data(data):
    # Placeholder for actual data processing logic
    return data.upper()

# Define error handling and retry mechanism with exponential backoff
def handle_error(task, max_retries=5, backoff_factor=2, initial_delay=1):
    retries = 0
    while retries < max_retries:
        try:
            task()
            break
        except Exception as e:
            if LOG_LEVEL == 'DEBUG':
                print(f"Error: {e}")
            time.sleep(initial_delay * (backoff_factor ** retries))
            retries += 1

# Define cache strategy with tiered caching
class TieredCache:
    def __init__(self):
        self.level_1_cache = {}
        self.level_2_cache = {}

    def get(self, key):
        if key in self.level_1_cache:
            return self.level_1_cache[key]
        elif key in self.level_2_cache:
            value = self.level_2_cache[key]
            del self.level_2_cache[key]
            self.level_1_cache[key] = value
            return value
        else:
            return None

    def set(self, key, value):
        if len(self.level_1_cache) >= 100:  # Example threshold for cache size
            oldest_key = next(iter(self.level_1_cache))
            del self.level_1_cache[oldest_key]
        self.level_1_cache[key] = value

# Define logging and alerting mechanism
def log_and_alert(message):
    if LOG_LEVEL == 'INFO':
        print(f"Log: {message}")
    elif LOG_LEVEL == 'ERROR':
        print(f"Alert: {message}")

# Main processing loop
cache = TieredCache()
for message in consumer:
    data = json.loads(message.value)
    task = lambda: producer.send(OUTPUT_TOPIC, process_data(data))
    handle_error(task)

# User-friendly interface for monitoring and managing the pipeline
class PipelineMonitor:
    def __init__(self):
        self.running_tasks = {}

    def start_task(self, task_id, task_function):
        if task_id not in self.running_tasks:
            self.running_tasks[task_id] = threading.Thread(target=task_function)
            self.running_tasks[task_id].start()

    def stop_task(self, task_id):
        if task_id in self.running_tasks:
            self.running_tasks[task_id].join()
            del self.running_tasks[task_id]

    def get_status(self):
        return {task_id: 'Running' for task_id in self.running_tasks}

# Example usage
monitor = PipelineMonitor()
monitor.start_task('process_data_task', lambda: handle_error(lambda: producer.send(OUTPUT_TOPIC, process_data(data))))
print(monitor.get_status())
```

