public class LTEManagementService {
    private Map<String, DeviceStatus> deviceStatusMap = new ConcurrentHashMap<>();
    private Queue<LTENASMessage> nasMessageQueue = new ConcurrentLinkedQueue<>();

    public void addDeviceStatus(DeviceStatus status) {
        deviceStatusMap.put(status.getDeviceID(), status);
    }

    public void updateDeviceStatus(String deviceId, DeviceStatus status) {
        deviceStatusMap.computeIfPresent(deviceId, (id, oldStatus) -> {
            oldStatus.setStatus(status.getStatus());
            oldStatus.setLastUpdate(System.currentTimeMillis());
            oldStatus.setConnectionMetrics(status.getConnectionMetrics());
            return oldStatus;
        });
    }

    public void removeDeviceStatus(String deviceId) {
        deviceStatusMap.remove(deviceId);
    }

    public void addNASMessage(LTENASMessage message) {
        nasMessageQueue.add(message);
    }

    public LTENASMessage getAndRemoveNextNASMessage() {
        return nasMessageQueue.poll();
    }

    public static void main(String[] args) {
        LTEManagementService service = new LTEManagementService();
        // Example usage
        DeviceStatus device1 = new DeviceStatus("device1", "Active", System.currentTimeMillis(), new ConnectionMetrics());
        service.addDeviceStatus(device1);

        LTENASMessage message = new LTENASMessage("TypeA", "MME123", "SGSN456", new byte[]{0x01, 0x02});
        service.addNASMessage(message);
