class DNSResolverService {
public:
    DNSResolverService(int max_concurrency, int retry_interval)
        : max_concurrency(max_concurrency), retry_interval(retry_interval),
          stop(false), next_id(0) {}

    ~DNSResolverService() {
        std::unique_lock<std::mutex> lock(mutex);
        stop = true;
        cv.notify_all();
        for (auto& thread : workers) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void resolveHostnameAsync(const std::string& hostname) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            work_queue.push(hostname);
        }
        cv.notify_one();
    }

private:
    int max_concurrency;
    int retry_interval;
