#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

LinkedListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (node == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void append_node(LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    LinkedListNode* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = new_node;
}

int check_unique_rnti(LinkedListNode* head, int RNTI) {
    LinkedListNode* temp = head;
    while (temp != NULL) {
        if (temp->data.RNTI == RNTI) {
            return 0; // Duplicate RNTI found
        }
        temp = temp->next;
    }
    return 1; // Unique RNTI
}

void generate_and_append_pdu(LinkedListNode** head, int N, int (*validate_rnti)(int)) {
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000000;
        pdu.RNTI = rand() % 65536;
        while (!validate_rnti(*head, pdu.RNTI)) {
            pdu.RNTI = rand() % 65536; // Retry if RNTI is not unique
        }
        pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu.CRCFLAG = rand() % 2;
        append_node(head, pdu);
    }
}

void log_pdu_creation(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("Timestamp: %ld, RNTI: %d, CRC Flag: %d\n", time(NULL), pdu.RNTI, pdu.CRCFLAG);
}

void process_pdus(LinkedListNode** head, int N, int (*validate_rnti)(int)) {
    generate_and_append_pdu(head, N, validate_rnti);
    LinkedListNode* temp = *head;
    while (temp != NULL) {
        log_pdu_creation(temp->data);
        temp = temp->next;
    }
}

// Example usage
int main() {
    LinkedListNode* head = NULL;
    int N = 100; // Number of PDUs to generate and process
    process_pdus(&head, N, check_unique_rnti);
    return 0;
}
