class MeasurementManager {
public:
    MeasurementManager(size_t capacity) : capacity_(capacity), records_(capacity, nullptr), next_index_(0) {}

    void insert(const LTE_PHY_MEASUREMENT_RECORD& record) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (next_index_ >= capacity_) {
            throw std::runtime_error("MeasurementManager is at full capacity");
        }
        records_[next_index_] = std::make_shared<LTE_PHY_MEASUREMENT_RECORD>(record);
        next_index_++;
    }

    std::shared_ptr<const LTE_PHY_MEASUREMENT_RECORD> get(size_t index) const {
        if (index >= next_index_) {
            throw std::out_of_range("Index out of range");
        }
        return records_[index];
    }

private:
    size_t capacity_;
    std::vector<std::shared_ptr<LTE_PHY_MEASUREMENT_RECORD>> records_;
    size_t next_index_;
    mutable std::mutex mutex_;
};

