#include <forward_list>
#include <mutex>

class MemoryManager {
public:
    static void insertAfterKey(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
        auto it = list.before_begin();
        for (; it != list.end(); ++it) {
            if (*it == key) {
                break;
            }
        }
        if (it != list.end()) {
            list.insert_after(it, value);
        } else {
            list.push_back(value);
        }
    }
};

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    MemoryManager::insertAfterKey(myList, "banana", "grape");

    for (const auto& item : myList) {
        std::cout << item << " ";
    }

    return 0;
}
