using System;
using System.Net.Http;
using System.Threading.Tasks;
using Polly;
using Polly.CircuitBreaker;
using Polly.Timeout;

public class ContentService
{
    private readonly HttpClient _httpClient;
    private readonly AsyncCircuitBreakerPolicy _breakerPolicy;
    private readonly TimeoutPolicy _timeoutPolicy;

    public ContentService()
    {
        _httpClient = new HttpClient();

        var breakHandler = new EventCountBreakerHandler(5, TimeSpan.FromSeconds(30));
        _breakerPolicy = Policy.BreakerAsync(breakHandler)
            .WithOnBroken(circuit => Console.WriteLine("Circuit is now open"));

        _timeoutPolicy = Policy.TimeoutAsync(TimeSpan.FromSeconds(10), TimeoutStrategy.Pessimistic);
    }

    public async Task UpdatePageSectionAsync(string sectionId, string content)
    {
        var requestUri = "https://api.example.com/update";
        var requestBody = new { SectionId = sectionId, Content = content };

        try
        {
            using (var response = await _timeoutPolicy.ExecuteAsync(() => 
                _breakerPolicy.ExecuteAsync(async () => 
                    await _httpClient.PostAsJsonAsync(requestUri, requestBody))))
            {
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Failed to update page section: {response.StatusCode}");
                }
            }
        }
        catch (BrokenCircuitException)
        {
            Console.WriteLine("Circuit is open, retrying later...");
            await Task.Delay(TimeSpan.FromSeconds(5));
            await UpdatePageSectionAsync(sectionId, content);
        }
    }
}
