from flask import Flask, request, jsonify
import threading
import time

app = Flask(__name__)

# Mock inventory data
inventory = {
    'warehouse1': {'item1': 100, 'item2': 50},
    'warehouse2': {'item1': 75, 'item2': 125}
}

# Lock for thread-safe access to inventory
inventory_lock = threading.Lock()

@app.route('/update_inventory', methods=['POST'])
def update_inventory():
    data = request.get_json()
    with inventory_lock:
        for warehouse, items in data.items():
            if warehouse not in inventory:
                inventory[warehouse] = {}
            for item, quantity in items.items():
                if item in inventory[warehouse]:
                    inventory[warehouse][item] += quantity
                else:
                    inventory[warehouse][item] = quantity
    return jsonify({'status': 'success'}), 200

@app.route('/get_inventory', methods=['GET'])
def get_inventory():
    with inventory_lock:
        return jsonify(inventory), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

This code provides a basic Flask microservice that allows updating and retrieving inventory data across multiple warehouses in a thread-safe manner. It uses a lock to ensure that updates to the shared `inventory` dictionary are atomic, preventing race conditions during peak load periods."]

