typedef struct {
    int RNTI;
    nfapi_crc_indication_rel8_tag_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int deserialize_nfa_pi_crc_indication_pdu(byte_array *byte_array, NFAPI_CRC_INDICATION_PDU_T **pdu) {
    if (byte_array->length == 0 || byte_array->data == NULL) {
        return -1; // Invalid input
    }

    *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu == NULL) {
        return -2; // Memory allocation failed
    }

    memcpy((*pdu)->RNTI, byte_array->data + sizeof(int), sizeof(int));
    memcpy(&(*pdu)->CRC_INDICATION_REL8_TAG, byte_array->data + 2 * sizeof(int), sizeof(nfapi_crc_indication_rel8_tag_t));

    return 0; // Success
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdu[MAX_UE_INSTANCES];
    int i;

    for (i = 0; i < MAX_UE_INSTANCES; i++) {
        pdu[i] = NULL;
        byte_array byte_array = { .length = 16, .data = (byte_t *)malloc(16) };
        if (!byte_array.data) {
            printf("Memory allocation failed\n");
            return -1;
        }

        // Populate the byte array with random data
        for (int j = 0; j < byte_array.length; j++) {
            byte_array.data[j] = rand() % 256;
        }

        if (deserialize_nfa_pi_crc_indication_pdu(&byte_array, &pdu[i]) != 0) {
            printf("Deserialization failed\n");
            free(byte_array.data);
            return -1;
        }

        // Process the pdu here

        free(byte_array.data);
    }

    // Free allocated memory
    for (i = 0; i < MAX_UE_INSTANCES; i++) {
        if (pdu[i]) {
            free(pdu[i]);
        }
    }

    return 0;
}
