void compute_md5(const char *input, unsigned char output[MD5_DIGEST_LENGTH]) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, input, strlen(input));
    MD5_Final(output, &md5);
}

char* get_md5_hash(const char *input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    compute_md5(input, digest);

    char *output = (char *)malloc(33); // 32 characters for the hash + 1 for null terminator
    if (output == NULL) {
        return NULL; // Handle memory allocation failure
    }

    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&output[i*2], "%02x", digest[i]);
    }
    output[32] = '\0'; // Null-terminate the string

    return output;
}

int main() {
    const char *input_string = "Hello, World!";
    char *hash = get_md5_hash(input_string);
    if (hash != NULL) {
        printf("MD5 hash of '%s' is: %s\n", input_string, hash);
        free(hash); // Don't forget to free the allocated memory
    }
    return 0;
}
