// Function to deserialize byte array into a NFAPI_CRC_INDICATION_PDU_T structure
int deserialize_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, const unsigned char *buffer, size_t length) {
    if (length < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Error: buffer too small
    }
    memcpy(pdu, buffer, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG for demonstration
    return 0;
}

// Function to compute MD5 hash of a given string
unsigned char* compute_md5(const char *str) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str, strlen(str));
    MD5_Final(hash, &md5);

    unsigned char *md5_str = (unsigned char *)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&md5_str[i*2], "%02x", hash[i]);
    }
    return md5_str;
}

// Function to load a resource bundle from a specified file and return the number of items
int load_resource_bundle(const char *filename, const char ***items) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return -1; // Error: file not found
    }

    int count = 0;
    while (fgets(*items[count], 256, file)) {
        (*items)[count][strlen((*items)[count]) - 1] = '\0'; // Remove newline character
        count++;
    }
    fclose(file);
    return count;
}

int main() {
    unsigned char buffer[32];
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Deserialize example data
    deserialize_crc_indication_pdu(&pdu, buffer, sizeof(buffer));
    printf("CRCFLAG: %d\n", pdu.CRCFLAG);

    // MD5 hash computation example
    const char *input_str = "Hello, World!";
    unsigned char *md5_hash = compute_md5(input_str);
    printf("MD5 Hash: %s\n", md5_hash);
    free(md5_hash); // Free allocated memory

    return 0;
}
```

