// EncryptionLibrary.java
import javax.crypto.Cipher;
import java.security.KeyPair;
import java.security.KeyStore;
import java.util.HashMap;
import java.util.Map;

public class EncryptionLibrary {
    private Map<String, Cipher> cipherMap = new HashMap<>();
    private KeyStore keyStore;

    public EncryptionLibrary() throws Exception {
        // Initialize the key store and load certificates
        keyStore = KeyStore.getInstance("JKS");
        keyStore.load(new FileInputStream("keystore.jks"), "password".toCharArray());
    }

    public byte[] encrypt(String algorithm, String data) throws Exception {
        Cipher cipher = getOrGenerateCipher(algorithm);
        return cipher.doFinal(data.getBytes());
    }

    public byte[] decrypt(String algorithm, byte[] encryptedData) throws Exception {
        Cipher cipher = getOrGenerateCipher(algorithm);
        cipher.init(Cipher.DECRYPT_MODE, keyStore.getKey("alias", "password".toCharArray()));
        return cipher.doFinal(encryptedData);
    }

    private Cipher getOrGenerateCipher(String algorithm) throws Exception {
        if (!cipherMap.containsKey(algorithm)) {
            Cipher cipher = Cipher.getInstance(algorithm);
            cipherMap.put(algorithm, cipher);
        }
        return cipherMap.get(algorithm);
    }
}
