public class SecurityMetrics {
    private Counter encryptionOperationsCounter;
    private Timer latencyTimer;

    public SecurityMetrics() {
        MetricsFactory metricsFactory = new MetricsFactory();
        this.encryptionOperationsCounter = metricsFactory.createCounter("encryption_operations");
        this.latencyTimer = metricsFactory.createTimer("latency_timer");
    }

    public void recordEncryptionOperation() {
        encryptionOperationsCounter.inc();
    }

    public void recordLatency(long latency) {
        latencyTimer.record(latency, TimeUnit.MILLISECONDS);
    }
