class LogProcessor {
public:
    void process(const std::string& log) {
        // Simulate log processing
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        std::cout << "Processed: " << log << std::endl;
    }
};

class LogSystem {
public:
    LogSystem() : messageBroker(new MessageBroker()) {
        messageBroker->subscribe([this](const std::string& log) {
            processLog(log);
        });
    }

    void startIngestingLogs(const std::vector<std::string>& logs) {
        for (const auto& log : logs) {
            ingestorQueue.push(log);
            ingestCondition.notify_one();
        }
    }

private:
    void ingestLogs() {
        while (true) {
            std::unique_lock<std::mutex> lock(ingestMutex);
            ingestCondition.wait(lock, [this] { return !ingestorQueue.empty(); });
            std::string log = ingestorQueue.front();
            ingestorQueue.pop();
            lock.unlock();

            // Simulate asynchronous log ingestion
            std::thread([log]() {
                LogFile file;
                file.ingest(log);
                messageBroker->publish(log);
            }).detach();
        }
    }

    void processLog(const std::string& log) {
        LogProcessor processor;
        processor.process(log);
    }

    MessageBroker* messageBroker;
    std::queue<std::string> ingestorQueue;
    std::mutex ingestMutex;
    std::condition_variable ingestCondition;

    std::thread ingestThread;
};

int main() {
    LogSystem logSystem;
    logSystem.startIngestingLogs({"Log1", "Log2", "Log3"});
    return 0;
}
