using System.ServiceProcess;
using System.Threading;
using System.Threading.Tasks;

public class DynamicWebsiteManager
{
    private readonly ConcurrentDictionary<string, WebsiteInfo> _websiteInfos = new();
    private readonly ServiceController _iisServiceController;
    private readonly SemaphoreSlim _lock = new(1);

    public DynamicWebsiteManager()
    {
        _iisServiceController = new ServiceController("W3SVC");
    }

    public async Task AddWebsiteAsync(string websiteName, string rootDomain, string targetDirectory)
    {
        await VerifyPrerequisitesAsync(websiteName, rootDomain, targetDirectory);
        lock (_lock)
        {
            if (!_websiteInfos.ContainsKey(websiteName))
            {
                _websiteInfos[websiteName] = new WebsiteInfo
                {
                    Name = websiteName,
                    RootDomain = rootDomain,
                    TargetDirectory = targetDirectory
                };
            }
        }
    }

    private async Task VerifyPrerequisitesAsync(string websiteName, string rootDomain, string targetDirectory)
    {
        await Task.Run(() =>
        {
            if (!Directory.Exists(targetDirectory))
                throw new InvalidOperationException("Target directory does not exist.");

            if (!Directory.GetAccessControl(targetDirectory).GetAccessRules(true, true, typeof(System.Security.Principal.NTAccount)).Any(rule => rule.IdentityReference.Value == Environment.UserDomainName + "\\" + Environment.UserName && rule.FileSystemRights.Write))
                throw new UnauthorizedAccessException("You do not have write permissions to the target directory.");

            if (File.Exists(Path.Combine(targetDirectory, "web.config")) && !IsValidWebConfig(File.ReadAllText(Path.Combine(targetDirectory, "web.config"))))
                throw new InvalidOperationException("Invalid web.config file.");
        });

        lock (_lock)
        {
            if (_websiteInfos.Any(w => w.Value.Name == websiteName || w.Value.RootDomain == rootDomain))
                throw new InvalidOperationException("Website name or root domain already exists.");
        }
    }

    private bool IsValidWebConfig(string configContent)
    {
        // Basic validation logic
        return configContent.Contains("<configuration>");
    }

    public async Task<bool> StartIisServiceAsync()
    {
        if (_iisServiceController.Status == ServiceControllerStatus.Running)
            return true;

        _iisServiceController.Start();
        await _iisServiceController.WaitForStatusAsync(ServiceControllerStatus.Running, TimeSpan.FromSeconds(30));
        return _iisServiceController.Status == ServiceControllerStatus.Running;
    }

    public async Task<bool> MonitorIisHealthAsync()
    {
        try
        {
            Ping pingSender = new();
            PingReply reply = await pingSender.SendPingAsync("127.0.0.1");
            return reply.Status == IPStatus.Success;
        }
        catch
        {
            return false;
        }
    }

    // Additional methods for concurrency, performance optimization, resource management,
    // error handling, logging, scalability, and load balancing can be added here.
}

public class WebsiteInfo
{
    public string Name { get; set; }
    public string RootDomain { get; set; }
    public string TargetDirectory { get; set; }
}
