#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_LOG_SIZE 1024
#define MAX_THREADS 10

typedef enum { INFO, WARNING, ERROR } Severity;

typedef struct {
    time_t timestamp;
    Severity severity;
    char module[64];
    char message[MAX_LOG_SIZE];
} LogEvent;

typedef struct {
    LogEvent *events;
    size_t count;
    pthread_mutex_t mutex;
} LogSystem;

void log_event(LogSystem *log, LogEvent event) {
    pthread_mutex_lock(&log->mutex);
    // Check for duplicates and add if unique
    int is_duplicate = 0;
    for (size_t i = 0; i < log->count; ++i) {
        if (log->events[i].timestamp == event.timestamp &&
            strcmp(log->events[i].module, event.module) == 0 &&
            strcmp(log->events[i].message, event.message) == 0) {
            is_duplicate = 1;
            break;
        }
    }
    if (!is_duplicate) {
        log->events = realloc(log->events, (log->count + 1) * sizeof(LogEvent));
        log->events[log->count++] = event;
    }
    pthread_mutex_unlock(&log->mutex);
}

void *worker(void *arg) {
    LogSystem *log = arg;
    // Simulate logging events
    LogEvent event;
    for (int i = 0; i < 10; ++i) {
        time(&event.timestamp);
        event.severity = INFO;
        snprintf(event.module, sizeof(event.module), "Module%d", rand() % MAX_THREADS);
        snprintf(event.message, sizeof(event.message), "Message %d", i);
        log_event(log, event);
    }
    return NULL;
}

int main() {
    LogSystem log = { .events = NULL, .count = 0 };
    pthread_t threads[MAX_THREADS];

    // Initialize mutex
    pthread_mutex_init(&log.mutex, NULL);

    // Create threads and assign them tasks
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker, &log);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    free(log.events);
    pthread_mutex_destroy(&log.mutex);

    return 0;
}
```

This code provides a basic implementation of a multi-threaded logging system in C. It includes a `LogEvent` structure to represent log entries and a `LogSystem` structure to manage the dynamic array and mutex for thread safety. The `log_event` function is used to add new events, ensuring duplicates are not logged. The `worker` function simulates multiple threads logging events concurrently.

The code initializes the mutex before creating and joining threads. It then cleans up by freeing the allocated memory for log events and destroying the mutex. This example serves as a starting point for further development of a more robust and scalable logging system, including integration with external storage services and additional features like rate limiting and error handling.']

