#include <time.h>
#include <pthread.h>

#define N 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* populateNFAPIArray(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array[i].CRCFLAG = rand() % 2; // 0 or 1
    }

    return NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T array[N];
    pthread_t thread;

    if (pthread_create(&thread, NULL, populateNFAPIArray, array) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        exit(EXIT_FAILURE);
    }

    // Example usage of the array
    for (int i = 0; i < N; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               array[i].RX_UE_INFORMATION_TAG,
               array[i].RNTI,
               array[i].CRC_INDICATION_REL8_TAG,
               array[i].CRCFLAG);
    }

    return 0;
}
```

### Explanation:
1. **Thread Creation**: The function `populateNFAPIArray` is executed in a separate thread to handle the data population concurrently, ensuring minimal impact on the main application's performance.
2. **Random Number Generation**: The `srand(time(NULL))` call seeds the random number generator with the current time, ensuring different sequences across runs.
3. **Memory Management**: The array is allocated on the stack within the `main` function, which minimizes heap fragmentation and leverages cache efficiency for small arrays.
4. **Error Handling**: Basic error handling is included for thread creation and joining using `pthread_create` and `pthread_join`.
5. **Concurrency**: The use of a separate thread ensures that the main application remains responsive while data population occurs concurrently.

This code provides a basic framework for managing an array of `NFAPI_CRC_INDICATION_PDU_T` structures efficiently in a high-performance environment. Further optimizations, such as using a memory pool or asynchronous processing, can be added based on specific requirements and performance benchmarks.']

