#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    INFO,
    WARNING,
    ERROR
} Severity;

typedef struct LogEvent {
    time_t timestamp;
    Severity severity;
    char module[64];
    char message[256];
} LogEvent;

typedef struct {
    LogEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} LogSystem;

void init_log_system(LogSystem *sys, size_t initial_capacity) {
    sys->events = malloc(initial_capacity * sizeof(LogEvent));
    sys->count = 0;
    sys->capacity = initial_capacity;
    pthread_mutex_init(&sys->mutex, NULL);
}

void destroy_log_system(LogSystem *sys) {
    free(sys->events);
    pthread_mutex_destroy(&sys->mutex);
}

void append_log_event(LogSystem *sys, const LogEvent *event) {
    pthread_mutex_lock(&sys->mutex);
    if (sys->count == sys->capacity) {
        size_t new_capacity = sys->capacity ? sys->capacity * 2 : 16;
        sys->events = realloc(sys->events, new_capacity * sizeof(LogEvent));
        sys->capacity = new_capacity;
    }
    memcpy(&sys->events[sys->count], event, sizeof(LogEvent));
    sys->count++;
    pthread_mutex_unlock(&sys->mutex);
}

void* log_thread(void *arg) {
    LogSystem *sys = (LogSystem*)arg;
    // Simulate logging to external storage
    for (size_t i = 0; i < sys->count; ++i) {
        printf("Logging event: %s, %d, %s, %s\n",
               ctime(&sys->events[i].timestamp),
               sys->events[i].severity,
               sys->events[i].module,
               sys->events[i].message);
    }
    return NULL;
}

int main() {
    LogSystem log_sys;
    init_log_system(&log_sys, 10);

    // Example log events
    LogEvent event1 = {time(NULL), INFO, "ModuleA", "This is an info message"};
    LogEvent event2 = {time(NULL), ERROR, "ModuleB", "This is an error message"};

    append_log_event(&log_sys, &event1);
    append_log_event(&log_sys, &event2);

    pthread_t thread;
    pthread_create(&thread, NULL, log_thread, &log_sys);
    pthread_join(thread, NULL);

    destroy_log_system(&log_sys);
    return 0;
}
```

