#define N 10000 // Number of elements per second

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *array[N];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int memory_pool[N];
int pool_index = 0;

void init_memory_pool() {
    for (int i = 0; i < N; i++) {
        memory_pool[i] = i;
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_from_pool() {
    pthread_mutex_lock(&mutex);
    if (pool_index == N) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Pool is empty
    }
    int index = memory_pool[pool_index++];
    pthread_mutex_unlock(&mutex);
    return (NFAPI_CRC_INDICATION_PDU_T*)array[index];
}

void free_to_pool(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutex);
    array[pdu - array] = NULL; // Mark slot as free
    memory_pool[--pool_index] = pdu - array;
    pthread_mutex_unlock(&mutex);
}

void* worker_thread(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_from_pool();
        if (!pdu) break; // Exit thread when pool is empty
        // Populate pdu with data
        generate_random_data(pdu);
        // Process pdu
        process_pdu(pdu);
        free_to_pool(pdu);
    }
    return NULL;
}

void init_library() {
    for (int i = 0; i < N; i++) {
        array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    init_memory_pool();
    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
}

