    private ConcurrentHashMap<String, LogEntry> logCache = new ConcurrentHashMap<>();
    private AtomicInteger deduplicationCounter = new AtomicInteger(0);
    private EventBroker eventBroker = new EventBroker();

    public void logEvent(String module, String message) {
        if (isDuplicate(module, message)) return;
        LogEntry entry = new LogEntry(module, message);
        logCache.putIfAbsent(entry.getKey(), entry);
        publishToExternalStorage(entry);
        publishToEventBroker(entry);
    }

    private boolean isDuplicate(String module, String message) {
        int currentCounter = deduplicationCounter.incrementAndGet();
        if (currentCounter % 1000 == 0) { // Simplified deduplication logic
            logCache.clear(); // Clear cache periodically
        }
        return logCache.containsKey(new LogEntry(module, message).getKey());
    }

