const express = require('express');
const bodyParser = require('body-parser');
const kafka = require('kafka-node');

// Initialize Kafka producer
const client = new kafka.KafkaClient({ kafkaHost: 'localhost:9092' });
const producer = new kafka.HighLevelProducer(client);

producer.on('ready', () => {
  console.log('Kafka producer ready');
});

producer.on('error', (err) => {
  console.error('Kafka producer error:', err);
});

// Initialize Express app
const app = express();
app.use(bodyParser.json());

// Endpoint to receive telemetry data from IoT gateways
app.post('/telemetry', (req, res) => {
  const message = req.body;

  // Send message to Kafka topic
  producer.send([{ topic: 'iot-telemetry', messages: JSON.stringify(message) }], (err, data) => {
    if (err) {
      console.error('Failed to send telemetry data:', err);
      res.status(500).send('Internal Server Error');
    } else {
      console.log('Telemetry data sent successfully:', data);
      res.status(201).send('Data received');
    }
  });
});

// Endpoint to query historical telemetry data
app.get('/telemetry/query', (req, res) => {
  // Logic to query Kafka topic and return results
  res.status(200).json({ message: 'Historical data query endpoint' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
