struct TCPEvent {
    std::string sourceIP;
    std::string destinationIP;
    uint16_t sourcePort;
    uint16_t destinationPort;
    size_t packetSize;
};

// Custom memory pool for efficient memory management
class MemoryPool {
public:
    MemoryPool(size_t numElements) : numElements(numElements), pool(new TCPEvent[numElements]) {}
    ~MemoryPool() { delete[] pool; }

    TCPEvent* allocate() {
        std::lock_guard<std::mutex> lock(mutex);
        if (index >= numElements) return nullptr;
        return &pool[index++];
    }

    void deallocate(TCPEvent* event) {
        std::lock_guard<std::mutex> lock(mutex);
        // Simple implementation, in a real system handle deallocation more carefully
    }

private:
    TCPEvent* pool;
    size_t numElements;
    size_t index = 0;
    std::mutex mutex;
};

// Worker thread function for asynchronous processing
void workerThread(MemoryPool& pool, std::queue<TCPEvent*>& eventQueue, std::condition_variable& condition, std::atomic<bool>& stop) {
    while (true) {
        std::unique_lock<std::condition_variable> lock(condition);
        condition.wait(lock, [&stop]{ return !stop.load() || !eventQueue.empty(); });
        if (!eventQueue.empty()) {
            TCPEvent* event = eventQueue.front();
            eventQueue.pop();
            lock.unlock();

            // Process the event (simplified example)
            std::cout << "Processing event: Source IP=" << event->sourceIP
                      << ", Destination IP=" << event->destinationIP
                      << ", Source Port=" << event->sourcePort
                      << ", Destination Port=" << event->destinationPort
                      << ", Packet Size=" << event->packetSize << std::endl;

            // Simulate database write operation
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        } else if (stop.load()) {
            return;
        }
    }
}

// Main function to demonstrate the library implementation
int main() {
    const size_t maxEventsPerSecond = 10000;
    MemoryPool pool(maxEventsPerSecond * 2); // Double the size for safety margin

    std::queue<TCPEvent*> eventQueue;
    std::condition_variable condition;
    std::atomic<bool> stop(false);

    // Create worker threads
    const size_t numWorkerThreads = 10;
    std::vector<std::thread> workers;
    for (size_t i = 0; i < numWorkerThreads; ++i) {
        workers.emplace_back(workerThread, std::ref(pool), std::ref(eventQueue), std::ref(condition), std::ref(stop));
    }

    // Simulate incoming TCP events
    size_t eventCounter = 0;
    while (eventCounter < maxEventsPerSecond * 10) { // Process for 10 seconds
        if (eventCounter % 10 == 0) {
            condition.notify_all();
        }
        TCPEvent* event = pool.allocate();
        if (event) {
            event->sourceIP = "192.168.1." + std::to_string(eventCounter % 254);
            event->destinationIP = "192.168.1." + std::to_string((eventCounter + 1) % 254);
            event->sourcePort = static_cast<uint16_t>(eventCounter % 65536);
            event->destinationPort = static_cast<uint16_t>((eventCounter + 1) % 65536);
            event->packetSize = (eventCounter % 1024) * 1024;
            eventQueue.push(event);
        }
        ++eventCounter;

        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }

    stop.store(true);
    condition.notify_all();
    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
