#include <thread>

class HTTPRequest {
public:
    std::string url;
    int priority;
};

class HTTPResponse {
public:
    std::string body;
    int status_code;
};

class DynamicHTTPClient {
public:
    void add_request(const HTTPRequest& request) {
        std::lock_guard<std::mutex> lock(mutex_);
        requests_.push(request);
        condition_.notify_one();
    }

    std::shared_ptr<HTTPResponse> get_response() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            if (!responses_.empty()) {
                auto response = responses_.front();
                responses_.pop();
                return response;
            }
            condition_.wait(lock, [this] { return !requests_.empty(); });
        }
    }

private:
    std::queue<HTTPRequest> requests_;
    std::queue<std::shared_ptr<HTTPResponse>> responses_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    DynamicHTTPClient client;

    // Add requests
    client.add_request({"http://example.com/api/v1", 5});
    client.add_request({"http://example.com/api/v2", 3});

    // Get responses
    auto response = client.get_response();
    if (response) {
        std::cout << "Response status code: " << response->status_code << std::endl;
        std::cout << "Response body: " << response->body << std::endl;
    }

    return 0;
}
