#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    uint64_t timestamp;
    char* event_type;
    void* metadata;
} NetworkEventStruct;

typedef struct {
    NetworkEventStruct** events;
    size_t count;
    size_t capacity;
    sem_t semaphore;
    pthread_mutex_t mutex;
} EventManager;

EventManager* create_event_manager(size_t initial_capacity) {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    manager->events = (NetworkEventStruct**)malloc(initial_capacity * sizeof(NetworkEventStruct*));
    manager->count = 0;
    manager->capacity = initial_capacity;
    sem_init(&manager->semaphore, 0, 1);
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_event_manager(EventManager* manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->events[i]);
    }
    free(manager->events);
    sem_destroy(&manager->semaphore);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void add_event(EventManager* manager, NetworkEventStruct* event) {
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->events = realloc(manager->events, new_capacity * sizeof(NetworkEventStruct*));
        manager->capacity = new_capacity;
    }
    pthread_mutex_lock(&manager->mutex);
    manager->events[manager->count++] = event;
    sem_post(&manager->semaphore);
    pthread_mutex_unlock(&manager->mutex);
}

NetworkEventStruct* get_next_event(EventManager* manager) {
    NetworkEventStruct* event = NULL;
    if (sem_wait(&manager->semaphore) == 0) {
        pthread_mutex_lock(&manager->mutex);
        if (manager->count > 0) {
            event = manager->events[--manager->count];
        }
        pthread_mutex_unlock(&manager->mutex);
    }
    return event;
}

