#include <atomic>
#include <condition_variable>
#include <functional>
#include <memory>
#include <mutex>
#include <queue>
#include <thread>

template <typename T>
class ThreadSafeQueue {
public:
    void push(const T& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(value);
        condition_.notify_one();
    }

    void push(T&& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(std::move(value));
        condition_.notify_one();
    }

    bool try_pop(T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        value = std::move(queue_.front());
        queue_.pop();
        return true;
    }

    void wait_and_pop(T& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !queue_.empty(); });
        value = std::move(queue_.front());
        queue_.pop();
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }

private:
    mutable std::mutex mutex_;
    std::queue<T> queue_;
    std::condition_variable condition_;
};

int main() {
    ThreadSafeQueue<Event> event_queue;

    auto producer = [&event_queue]() {
        for (size_t i = 0; i < 50000; ++i) {
            Event event;
            // Initialize event with timestamp, ID, and payload
            event_queue.push(event);
        }
    };

    std::vector<std::thread> consumers(10);
    for (auto& consumer : consumers) {
        consumer = std::thread([&event_queue]() {
            while (true) {
                Event event;
                if (!event_queue.try_pop(event)) {
                    break; // Exit when the queue is empty
                }
                // Process the event
            }
        });
    }

    producer.join();
    for (auto& consumer : consumers) {
        consumer.join();
    }

    return 0;
}
```

