// Define constants for your service
#define MAX_FILES 1000
#define MAX_CONCURRENT_TASKS 100
#define MAX_RULE_RETRIES 3

typedef struct {
    char *file_path;
    char *transformation_rules;
    int priority;
} Task;

Task tasks[MAX_FILES];
int task_count = 0;
sem_t sem_file_processing;
pthread_mutex_t file_lock;
curl_slist *headers = NULL;

void *process_task(void *arg) {
    int index = *(int *)arg;
    free(arg);

    if (index < task_count) {
        Task *task = &tasks[index];

        // Acquire semaphore to ensure thread safety
        sem_wait(&sem_file_processing);
        pthread_mutex_lock(&file_lock);

        // Simulate file processing with external API call
        CURL *curl;
        CURLcode res;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/transform");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, task->transformation_rules);

            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

            curl_easy_cleanup(curl);
            curl_slist_free_all(headers);
        }

        // Release semaphore and mutex
        pthread_mutex_unlock(&file_lock);
        sem_post(&sem_file_processing);

        // Log processing result
        if (res == CURLE_OK) {
            printf("File %s processed successfully.\n", task->file_path);
        } else {
            printf("Error processing file %s: %s\n", task->file_path, curl_easy_strerror(res));
        }
    }

    return NULL;
}

int main() {
    // Initialize semaphore and mutex
    sem_init(&sem_file_processing, 0, MAX_CONCURRENT_TASKS);
    pthread_mutex_init(&file_lock, NULL);

    // Example tasks (replace with actual file paths and rules)
    Task task1 = {"path/to/file1.txt", "{\"rule\": \"transform1\"}", 1};
    Task task2 = {"path/to/file2.txt", "{\"rule\": \"transform2\"}", 2};

    // Add tasks to the queue
    tasks[task_count++] = task1;
    tasks[task_count++] = task2;

    // Create threads for processing tasks
    pthread_t threads[MAX_CONCURRENT_TASKS];
    int thread_ids[MAX_CONCURRENT_TASKS];

    for (int i = 0; i < task_count; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_task, &thread_ids[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < task_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up semaphore and mutex
    sem_destroy(&sem_file_processing);
    pthread_mutex_destroy(&file_lock);

    return 0;
}
```

