extern int validate_rxue_tag(RX_UE_INFORMATION_TAG *tag);
extern void log_error(const char *message);
extern void log_warning(const char *message);

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_nfaapi_crc_pdu(int N, pthread_mutex_t *mutex) {
    if (N <= 0) {
        log_error("Invalid size for allocation");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(mutex);

    for (int i = 0; i < N; ++i) {
        if (validate_rxue_tag(&array[i].rx_ue_info)) {
            array[i].rnti = rand() % 65536; // Example RNTI generation
            array[i].crc_ind_rel8.crcflag = rand() & 1; // Random CRC flag

            if (!validate_rxue_tag(&array[i].rx_ue_info)) {
                log_error("Validation failed for RXUE tag at index: %d", i);
                free(array);
                pthread_mutex_unlock(mutex);
                return NULL;
            }
        } else {
            log_warning("Validation warning for RXUE tag at index: %d", i);
        }
    }

    pthread_mutex_unlock(mutex);
    return array;
}
