class ResourceManager {
public:
    void handleNetworkOperation() {
        // Simulate network operation
        std::cout << "Handling network operation" << std::endl;
    }
};

class DynamicResourcePoolManager {
private:
    std::vector<ResourceManager*> resourcePool;
    std::mutex poolMutex;
    std::condition_variable requestQueueCondition;
    std::queue<std::function<void()>> requestQueue;
    std::atomic<int> activeCount;
    int max_size;
    int load_threshold;

public:
    DynamicResourcePoolManager(int initial_size, int max_size, int load_threshold)
        : max_size(max_size), load_threshold(load_threshold), activeCount(0) {
        resourcePool.reserve(initial_size);
        for (int i = 0; i < initial_size; ++i) {
            resourcePool.push_back(new ResourceManager());
        }
    }

    ~DynamicResourcePoolManager() {
        for (auto& resource : resourcePool) {
            delete resource;
        }
    }

    void submitRequest(std::function<void()> request) {
        std::unique_lock<std::mutex> lock(poolMutex);
        while (resourcePool.size() >= max_size && activeCount > load_threshold) {
            requestQueueCondition.wait(lock, [this] { return resourcePool.size() < max_size || activeCount <= load_threshold; });
        }
        if (activeCount.load() <= load_threshold) {
            auto* resource = getAvailableResource();
            if (resource) {
                std::thread([resource, request]() {
                    std::lock_guard<std::mutex> lock(resource->poolMutex);
                    ++resource->activeCount;
                    request();
                    --resource->activeCount;
                    if (resource->activeCount == 0) {
                        resource->requestQueueCondition.notify_one();
                    }
                }).detach();
            } else {
                requestQueue.push(request);
            }
        } else {
            requestQueue.push(request);
        }
    }

private:
    ResourceManager* getAvailableResource() {
        for (auto& resource : resourcePool) {
            if (resource->activeCount.load() < load_threshold) {
                return resource;
            }
        }
        return nullptr;
    }
};

int main() {
    DynamicResourcePoolManager manager(10, 20, 5);
    manager.submitRequest([] { std::cout << "Request 1" << std::endl; });
    manager.submitRequest([] { std::cout << "Request 2" << std::endl; });

    return 0;
}
