    std::mutex pool_mutex;
    std::condition_variable cv;
    bool is_active;

public:
    DynamicResourcePoolManager(int p, int maxSize, int loadThreshold)
        : P(p), max_size(maxSize), load_threshold(loadThreshold), is_active(true) {
        initializePool();
    }

    ~DynamicResourcePoolManager() {
        for (auto& rm : pool) {
            delete rm;
        }
