    void initializePool() {
        // Dynamically initialize the pool based on initial size and configuration parameters
    }

    ResourceManager* acquireResource() {
        std::unique_lock<std::mutex> lock(pool_mutex);
        cv.wait(lock, [this] { return is_active && pool.size() > 0; });
        ResourceManager* rm = pool.back();
        pool.pop_back();
        return rm;
    }

    void releaseResource(ResourceManager* rm) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        if (pool.size() < max_size) {
            pool.push_back(rm);
            cv.notify_one();
        }
    }

    std::string computeFileHash(const std::string& filePath) {
        std::ifstream file(filePath, std::ios::binary | std::ios::ate);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }
        std::streamsize size = file.tellg();
        file.seekg(0, std::ios::beg);

        unsigned char* buffer = new unsigned char[size];
        file.read(reinterpret_cast<char*>(buffer), size);
        file.close();

        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, buffer, size);
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5_Final(hash, &md5);

        delete[] buffer;

        std::ostringstream oss;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            oss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
        }

        return oss.str();
    }
};

