use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::time::Duration;

#[derive(Serialize, Deserialize)]
struct WeatherData {
    temperature: f32,
    humidity: u8,
}

async fn get_weather(city: web::Path<String>) -> impl Responder {
    let api_key = "your_api_key_here";
    let url = format!("https://api.weather.com/data/2.5/weather?q={}&appid={}", city, api_key);

    match reqwest::get(&url).await {
        Ok(mut response) => {
            if response.status().is_success() {
                match response.json::<WeatherData>().await {
                    Ok(data) => HttpResponse::Ok().json(data),
                    Err(_) => HttpResponse::InternalServerError().finish(),
                }
            } else {
                HttpResponse::ServiceUnavailable().finish()
            }
        },
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/weather/{city}", web::get().to(get_weather))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
