const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const { Pool } = require('pg');

const app = express();
app.use(bodyParser.json());
app.use(cors());

const pool = new Pool({
  user: 'dbuser',
  host: 'database.example.com',
  database: 'mydb',
  password: 'secretpassword',
  port: 5432,
});

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Function to validate business rules from an external configuration service
async function validateBusinessRules(resourceId) {
  try {
    const response = await axios.get(`https://config-service.example.com/rules/${resourceId}`);
    return response.data.rules;
  } catch (error) {
    console.error('Error fetching business rules:', error);
    return null;
  }
}

// Function to handle optimistic concurrency control and conflict resolution
async function updateResource(resourceId, updates) {
  const connection = await pool.connect();
  try {
    // Fetch the current version of the resource
    const result = await connection.query('SELECT * FROM resources WHERE id=$1', [resourceId]);
    const currentVersion = result.rows[0].version;

    // Update the resource with the provided updates and increment the version
    await connection.query(
      'UPDATE resources SET data=jsonb_set(data, $2::text[], $3::jsonb), version=version+1 WHERE id=$4 AND version=$5',
      [resourceId, JSON.stringify(updates.path), JSON.stringify(updates.value), resourceId, currentVersion]
    );

    // Check if the update was successful
    const updatedResult = await connection.query('SELECT * FROM resources WHERE id=$1', [resourceId]);
    return updatedResult.rows[0];
  } catch (error) {
    console.error('Error updating resource:', error);
    throw error;
  } finally {
    connection.release();
  }
}

// API endpoint for updating a resource
app.put('/api/resources/:id', async (req, res) => {
  const { id } = req.params;
  const updates = req.body;

  // Validate business rules
  const businessRules = await validateBusinessRules(id);
  if (!businessRules || !businessRules.validate(updates)) {
    return res.status(403).json({ error: 'Unauthorized update' });
  }

  try {
    const updatedResource = await updateResource(id, updates);
    res.json(updatedResource);
  } catch (error) {
    if (error.code === '23505') { // Unique constraint violation
      return res.status(409).json({ error: 'Conflict updating resource' });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// API endpoint for deleting a resource
app.delete('/api/resources/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const connection = await pool.connect();
    await connection.query('DELETE FROM resources WHERE id=$1', [id]);
    connection.release();
    res.status(204).send();
  } catch (error) {
    console.error('Error deleting resource:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// API endpoint for collaborative editing
app.put('/api/resources/:id/collaborate', async (req, res) => {
  const { id } = req.params;
  const updates = req.body;

  // Validate business rules
  const businessRules = await validateBusinessRules(id);
  if (!businessRules || !businessRules.validate(updates)) {
    return res.status(403).json({ error: 'Unauthorized update' });
  }

  try {
    const updatedResource = await updateResource(id, updates);
    res.json(updatedResource);
  } catch (error) {
    if (error.code === '23505') { // Unique constraint violation
      return res.status(409).json({ error: 'Conflict updating resource' });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.statusCode || 500).json({ error: err.message });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```"]

