const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');
const Ajv = require('ajv');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const PORT = process.env.PORT || 3000;
const UPLOAD_DIR = process.env.UPLOAD_DIR || 'uploads';
const SCHEMA_PATH = process.env.SCHEMA_PATH || 'schema.json';
const ANALYTICS_API_URL = process.env.ANALYTICS_API_URL || 'https://api.example.com/track';

const ajv = new Ajv();
let schema;

fs.readFile(SCHEMA_PATH, 'utf8')
  .then(data => {
    schema = JSON.parse(data);
  })
  .catch(err => {
    console.error('Failed to load schema:', err);
    process.exit(1);
  });

app.post('/upload', async (req, res) => {
  const files = req.files || [];

  for (const file of files) {
    try {
      const content = await fs.readFile(file.path, 'utf8');
      const logs = JSON.parse(content);

      if (!ajv.validate(schema, logs)) {
        return res.status(400).json({ error: 'Invalid logs' });
      }

      await processLogs(logs);
      res.status(201).send(`Processed file ${file.originalname}`);
    } catch (error) {
      console.error('Error processing file:', error);
      res.status(500).send(`Failed to process file ${file.originalname}`);
    }
  }
});

async function processLogs(logs) {
  try {
    const response = await axios.post(ANALYTICS_API_URL, logs, {
      headers: { 'Content-Type': 'application/json' },
      timeout: parseInt(process.env.API_TIMEOUT || 5000),
      retryCount: parseInt(process.env.RETRY_COUNT || 3),
      retryDelay: parseInt(process.env.RETRY_DELAY || 1000)
    });

    if (response.status !== 200) {
      throw new Error(`API call failed with status ${response.status}`);
    }
  } catch (error) {
    console.error('Error processing logs:', error);
    // Implement retry mechanism here
  }
}

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
