use async_trait::async_trait;
use reqwest::{Client, Error as ReqwestError};
use std::time::Duration;
use tokio::sync::Mutex;

#[derive(Clone)]
struct HttpService {
    client: Client,
    base_url: String,
    token: Mutex<String>,
}

#[async_trait]
pub trait HttpClient {
    async fn get(&self, endpoint: &str) -> Result<String, Error>;
    async fn post(&self, endpoint: &str, body: &str) -> Result<String, Error>;
}

#[derive(Debug)]
enum Error {
    Reqwest(ReqwestError),
    ServiceUnavailable,
    TokenExpired,
    RateLimitExceeded,
}

impl From<ReqwestError> for Error {
    fn from(err: ReqwestError) -> Self {
        Error::Reqwest(err)
    }
}

impl HttpClient for HttpService {
    async fn get(&self, endpoint: &str) -> Result<String, Error> {
        let url = format!("{}/{}", self.base_url, endpoint);
        let token = self.token.lock().await;
        let resp = self.client.get(&url).bearer_auth(token.as_str()).send().await?;
        if resp.status().is_success() {
            resp.text().await
        } else {
            Err(Error::Reqwest(RespError.into()))
        }
    }

    async fn post(&self, endpoint: &str, body: &str) -> Result<String, Error> {
        let url = format!("{}/{}", self.base_url, endpoint);
        let token = self.token.lock().await;
        let resp = self.client.post(&url).bearer_auth(token.as_str()).body(body.to_string()).send().await?;
        if resp.status().is_success() {
            resp.text().await
        } else {
            Err(Error::Reqwest(RespError.into()))
        }
    }
}

struct HttpServiceBuilder {
    base_url: String,
    token: String,
}

impl HttpServiceBuilder {
    pub fn new(base_url: &str, token: &str) -> Self {
        HttpServiceBuilder {
            base_url: base_url.to_string(),
            token: token.to_string(),
        }
    }

    pub fn build(self) -> HttpService {
        HttpService {
            client: Client::builder()
                .timeout(Duration::from_secs(10))
                .build()
                .unwrap(),
            base_url: self.base_url,
            token: Mutex::new(self.token),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_get_request() {
        let service = HttpServiceBuilder::new("http://example.com", "token").build();
        let response = service.get("/api/data").await;
        assert!(response.is_ok());
    }

    #[tokio::test]
    async fn test_post_request() {
        let service = HttpServiceBuilder::new("http://example.com", "token").build();
        let response = service.post("/api/data", "{\"key\":\"value\"}").await;
        assert!(response.is_ok());
    }
}
