use rustc_driver::{self, Compilation, Callbacks};
use std::env;
use std::fs;
use std::path::Path;
use std::process;

struct CompilationReport {
    summary: String,
    details: Vec<String>,
}

impl CompilationReport {
    fn new() -> Self {
        CompilationReport {
            summary: "Compilation complete.".to_string(),
            details: Vec::new(),
        }
    }

    fn add_detail(&mut self, detail: &str) {
        self.details.push(detail.to_string());
    }

    fn to_option(self) -> Option<String> {
        if self.details.is_empty() {
            None
        } else {
            Some(format!("{}:\n{}", self.summary, self.details.join("\n")))
        }
    }
}

struct MyCallbacks;

impl Callbacks for MyCallbacks {
    fn diagnostic(&mut self, db: &dyn rustc_errors::Handler, diag: &rustc_errors::Diagnostic) {
        let mut report = CompilationReport::new();
        if diag.level.is_error() || diag.level.is_help() {
            report.add_detail(&diag.message);
            for note in diag.notes.iter() {
                report.add_detail(&note.msg);
            }
            for span in diag.spans.iter() {
                report.add_detail(&format!("{}:{}:{}", span.file_name(), span.line_start, span.column_start));
            }
        } else if diag.level.is_warning() {
            // Suggest improvements or alternative solutions
            report.add_detail(&diag.message);
        }
        println!("{}", report.to_option().unwrap_or_default());
    }

    fn early_callback(&mut self, _diagnostics: &rustc_errors::Handled, _compiler: &rustc_driver::Compiler) -> Compilation {
        Compilation::Continue
    }
}

fn compile_project<P: AsRef<Path>>(project_path: P) -> Option<String> {
    let mut callbacks = MyCallbacks;
    let config = rustc_interface::Config {
        sysroot: None,
        crate_cfg: vec![],
        crate_check_cfg: vec![],
        features: vec![],
        edition: Some(rustc_ast::Edition::Edition2018),
        output_dir: None,
        error_format: rustc_errors::ErrorFormat::HumanReadable(false),
        lint_store: rustc_lint::LintStore::default(),
        lint_opts: vec![],
        codegen_options: vec![],
        fileinput: rustc_driver::FileInput::Source(rustc_ast_pretty::AstPrinter::new()),
        input: rustc_interface::interface::Input::File(PathBuf::from(project_path)),
        output_file: None,
        outdir: None,
        working_dir: Some(PathBuf::from(env::current_dir().unwrap())),
        target_triple: env::var("TARGET").ok(),
        host_triple: Some(rustc_target::spec::HostTriple::host()),
        mode: rustc_interface::interface::CompileMode::CheckCrate,
        lint_passes: vec![],
        lint_store: rustc_lint::LintStore::default(),
        lint_opts: vec![],
        codegen_options: vec![],
        fileinput: rustc_driver::FileInput::Source(rustc_ast_pretty::AstPrinter::new()),
        input: rustc_interface::interface::Input::File(PathBuf::from(project_path)),
        output_file: None,
        outdir: None,
        working_dir: Some(PathBuf::from(env::current_dir().unwrap())),
        target_triple: env::var("TARGET").ok(),
        host_triple: Some(rustc_target::spec::HostTriple::host()),
    };

    match rustc_driver::catch_with_exit_code(|| rustc_interface::run_compiler(&config, &mut callbacks)) {
        Ok(_) => {
            fs::remove_dir_all(project_path.as_ref().join("target")).unwrap_or_else(|_| println!("Failed to clean up build artifacts"));
            Some("Compilation successful.".to_string())
        }
        Err(_) => None,
    }
}

fn main() {
    let project_path = "path/to/your/rust/project";
    match compile_project(project_path) {
        Some(report) => println!("{}", report),
        None => println!("Compilation failed."),
    }
}
```

