#include <pthread.h>
#include <curl/curl.h>

#define MAX_CONCURRENT_REQUESTS 100

typedef struct {
    char url[256];
    int retries;
} Job;

void* parse_html(void* arg) {
    Job* job = (Job*)arg;
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, job->url);
        // Add additional options for parsing here
        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    free(job);
    return NULL;
}

int main(int argc, char *argv[]) {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    Job jobs[MAX_CONCURRENT_REQUESTS];

    if(argc > 1) {
        for(int i = 0; i < argc - 1; i++) {
            strcpy(jobs[i].url, argv[i + 1]);
            jobs[i].retries = 3;
            pthread_create(&threads[i], NULL, parse_html, (void*)&jobs[i]);
        }

        for(int i = 0; i < argc - 1; i++) {
            pthread_join(threads[i], NULL);
        }
    } else {
        fprintf(stderr, "Usage: %s <url> [...]\n", argv[0]);
        return 1;
    }

    curl_global_cleanup();
    return 0;
}
