class DynamicSpatialIndexManager {
public:
    void insertEntry(const std::string& entry) {
        std::lock_guard<std::mutex> lock(mutex_);
        entries_.push_back(entry);
        condition_.notify_one();
    }

    std::vector<std::string> queryData() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this]{ return !entries_.empty(); });
        std::vector<std::string> result = entries_;
        entries_.clear();
        return result;
    }

private:
    std::vector<std::string> entries_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    DynamicSpatialIndexManager manager;

    // Simulate concurrent data insertion
    auto insertFuture = std::async(std::launch::async, [&manager]() {
        for (int i = 0; i < 100000; ++i) {
            manager.insertEntry("Data " + std::to_string(i));
        }
    });

    // Simulate concurrent data querying
    auto queryFuture = std::async(std::launch::async, [&manager]() {
        std::vector<std::string> result = manager.queryData();
        for (const auto& entry : result) {
            std::cout << entry << std::endl;
        }
    });

    insertFuture.get();
    queryFuture.get();

    return 0;
}
