        for (int i = 0; i < NUM_THREADS; ++i) {
            workers.emplace_back(&TimeSeriesApplication::worker, this);
        }
    }

    ~TimeSeriesApplication() {
        running.store(false);
        for (auto& thread : workers) {
            thread.join();
        }
    }

    void addDataStream(DataStream* stream) {
        std::lock_guard<std::mutex> lock(mutex);
        dataStreams.push(stream);
        condition.notify_one();
    }

private:
    void worker() {
        while (running.load()) {
            DataStream* stream = nullptr;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !dataStreams.empty() || !running.load(); });
                if (!dataStreams.empty()) {
                    stream = dataStreams.front();
                    dataStreams.pop();
                }
            }

            if (stream) {
                analyticsEngine.processStream(stream);
                queryProcessor.processStream(stream);
                cacheManager.updateCache(stream);
            }
        }
    }

