import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericRecord;

public class AverageEvenNumberProcessor implements RequestHandler<GenericRecord, String> {

    @Override
    public String handleRequest(GenericRecord input, Context context) {
        long startTime = System.currentTimeMillis();

        int[] numbersArray = (int[]) input.get("numbersArray");
        if (numbersArray == null || numbersArray.length == 0) {
            return "No data or empty array provided";
        }

        double sum = 0;
        int count = 0;
        for (int number : numbersArray) {
            if (number % 2 == 0) {
                sum += number;
                count++;
            }
        }

        double average = count > 0 ? sum / count : 0;

        long endTime = System.currentTimeMillis();
        long processingTime = endTime - startTime;
        context.getLogger().log("Total time taken to compute average: " + processingTime + " ms");

        return String.valueOf(average);
    }
}
