using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SecureHashManager : IDisposable
{
    private readonly ConcurrentDictionary<string, Func<byte[], byte[]>> _hashAlgorithms = new();
    private readonly IExternalLogger _logger;
    private readonly IAnomalyDetectionService _anomalyService;

    public SecureHashManager(IExternalLogger logger, IAnomalyDetectionService anomalyService)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _anomalyService = anomalyService ?? throw new ArgumentNullException(nameof(anomalyService));

        RegisterAlgorithms();
    }

    private void RegisterAlgorithms()
    {
        _hashAlgorithms["MD5"] = data => MD5.Create().ComputeHash(data);
        _hashAlgorithms["SHA1"] = data => SHA1.Create().ComputeHash(data);
        _hashAlgorithms["SHA256"] = data => SHA256.Create().ComputeHash(data);
        _hashAlgorithms["SHA512"] = data => SHA512.Create().ComputeHash(data);
    }

    public byte[] GenerateHash(string algorithm, string input)
    {
        if (!_hashAlgorithms.ContainsKey(algorithm))
            throw new ArgumentException("Unsupported hash algorithm", nameof(algorithm));

        var data = Encoding.UTF8.GetBytes(input);
        try
        {
            var hash = _hashAlgorithms[algorithm](data);
            LogHashEvent(algorithm, input, true);
            return hash;
        }
        catch (Exception ex)
        {
            LogHashEvent(algorithm, input, false, ex.Message);
            throw;
        }
    }

    private void LogHashEvent(string algorithm, string input, bool success, string errorMessage = null)
    {
        var timestamp = DateTime.UtcNow.ToString("O");
        _logger.Log(new HashLogEntry(timestamp, input, algorithm, success, errorMessage));
    }

    public void Dispose()
    {
        // Cleanup resources if needed
    }
}

public class HashLogEntry
{
    public string Timestamp { get; set; }
    public string InputData { get; set; }
    public string Algorithm { get; set; }
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }

    public HashLogEntry(string timestamp, string inputData, string algorithm, bool success, string errorMessage = null)
    {
        Timestamp = timestamp;
        InputData = inputData;
        Algorithm = algorithm;
        Success = success;
        ErrorMessage = errorMessage;
    }
}

public interface IExternalLogger
{
    void Log(HashLogEntry entry);
}

