# Import necessary libraries
from flask import Flask, request, jsonify, g
from functools import wraps
import jwt
import time

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your_secret_key'
app.config['JWT_ALGORITHM'] = 'HS256'

# Rate limiting and adaptive security using a decorator
def rate_limit(limit=100, period=60):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            key = f"rate_limit:{request.remote_addr}"
            current_time = time.time()
            stored_requests = app.redis_client.zrangebyscore(key, 0, current_time - period)

            if len(stored_requests) >= limit:
                return jsonify({"error": "Rate limit exceeded"}), 429

            app.redis_client.zadd(key, {request.remote_addr: current_time})
            return f(*args, **kwargs)
        return wrapper
    return decorator

# OAuth 2.0 and JWT authentication
def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({"error": "Unauthorized"}), 401

        try:
            payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=[app.config['JWT_ALGORITHM']])
            g.user = payload
        except jwt.ExpiredSignatureError:
            return jsonify({"error": "Token expired"}), 401
        except jwt.InvalidTokenError:
            return jsonify({"error": "Invalid token"}), 401

        return f(*args, **kwargs)
    return decorated

# Route to handle a protected resource
@app.route('/protected', methods=['GET'])
@authenticate
@rate_limit(limit=5, period=60)
def protected():
    user = g.user
    return jsonify({"message": "Welcome", "user": user})

if __name__ == '__main__':
    app.run(debug=True)
```

