public:
    DataEngine(APIClient* client) : apiClient(client) {}

    void fetchDataFromSensor(const std::string& sensorId) {
        sensorData.push_back(apiClient->fetchData(sensorId));
    }

    void visualizeData() {
        apiClient->visualizeData(sensorData);
        sensorData.clear();
    }
};

// Scalable system with auto-scaling and container orchestration
class ScalableSystem {
private:
    DataEngine engine;
    std::vector<std::thread> workerThreads;
    std::mutex dataMutex;
    std::condition_variable dataCondVar;

public:
    ScalableSystem(APIClient* client) : engine(client) {}

    void start() {
        for (int i = 0; i < 10; ++i) {
            workerThreads.emplace_back(&ScalableSystem::workerThread, this);
        }

        // Simulate data processing
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            for (const auto& sensorId : {"sensor1", "sensor2"}) {
                engine.fetchDataFromSensor(sensorId);
            }
            dataCondVar.notify_all();
        }
    }

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(dataMutex);
            dataCondVar.wait(lock, [this] { return !engine.sensorData.empty(); });
            engine.visualizeData();
        }
    }
};

int main() {
    APIClient* apiClient = new RESTfulAPIClient; // or WebSocketAPIClient
    ScalableSystem system(apiClient);
    system.start();

    delete apiClient;
    return 0;
}
