import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class CryptoService {

    private static final ConcurrentHashMap<String, SecretKey> secretKeyCache = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<String, Cipher> cipherCache = new ConcurrentHashMap<>();

    public byte[] encrypt(byte[] data, String algorithm, String mode, String padding, byte[] iv) throws Exception {
        SecretKey key = getSecretKey(algorithm);
        Cipher cipher = getCipher(algorithm, mode, padding);
        cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv));
        return cipher.doFinal(data);
    }

    public byte[] decrypt(byte[] data, String algorithm, String mode, String padding, byte[] iv) throws Exception {
        SecretKey key = getSecretKey(algorithm);
        Cipher cipher = getCipher(algorithm, mode, padding);
        cipher.init(Cipher.DECRYPT_MODE, key, new IvParameterSpec(iv));
        return cipher.doFinal(data);
    }

    private SecretKey getSecretKey(String algorithm) throws Exception {
        return secretKeyCache.computeIfAbsent(algorithm, k -> KeyGenerator.getInstance(k).generateKey());
    }

    private Cipher getCipher(String algorithm, String mode, String padding) throws Exception {
        return cipherCache.computeIfAbsent(algorithm + "_" + mode + "_" + padding, k -> Cipher.getInstance(k));
    }
}
```

This code provides a basic structure for a cryptographic service that uses DES and AES encryption with support for multiple modes. It employs caching mechanisms to improve performance by reducing the overhead of generating keys and creating ciphers frequently. The use of `ConcurrentHashMap` ensures thread safety while handling concurrent requests.

To fully implement a scalable, resilient, and secure real-time cryptographic service as described in the task, additional features such as key management, logging, authentication, error handling, monitoring, distributed caching, load balancing, microservices architecture, machine learning, and compliance with regulations would need to be integrated.']

