const producer = new kafka.Producer(client);

producer.on('ready', () => {
  console.log('Kafka Producer ready');
});

// Configuration parameters
let concurrencyLimit = 10;
let memoryAllocation = 512; // in MB
let batchSize = 1000;

app.post('/submit-task', async (req, res) => {
  const { numStructures } = req.body;
  if (!numStructures || numStructures <= 0) {
    return res.status(400).json({ error: 'Invalid number of structures' });
  }

  // Generate tasks
  let tasks = [];
  for (let i = 0; i < concurrencyLimit; i++) {
    tasks.push(generateTask(numStructures));
  }

  try {
    await Promise.all(tasks);
    res.status(200).json({ message: 'Tasks submitted successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to submit tasks' });
  }
});

async function generateTask(numStructures) {
  return new Promise((resolve, reject) => {
    let count = numStructures;
    const producerStream = kafka.Producer.createBatchProducer({
      client,
      partition: 0
    });

    producerStream.on('error', (err) => {
      console.error('Kafka error:', err);
      reject(err);
    });

    producerStream.on('ready', () => {
      for (let i = 0; i < numStructures; i++) {
        const structure = createNFAPI_CRC_INDICATION_PDU_T();
        try {
          producerStream.queue({
            messages: JSON.stringify(structure),
            attributes: 1 // Message is a string
          });
        } catch (error) {
          console.error('Failed to queue message:', error);
          reject(error);
        }
      }

      producerStream.end((err, res) => {
        if (err) {
          console.error('Kafka end error:', err);
          reject(err);
        } else {
          console.log('Task completed successfully');
          resolve();
        }
      });
    });
  });
}

function createNFAPI_CRC_INDICATION_PDU_T() {
  return {
    RX_UE_INFORMATION_TAG: generateRandomString(),
    RNTI: Math.floor(Math.random() * 65536),
    CRC_INDICATION_REL8_TAG: Math.random() < 0.5 ? 'PASS' : 'FAIL'
  };
}

function generateRandomString(length = 10) {
  return crypto.randomBytes(length).toString('hex');
}

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
