const express = require('express');
const kafka = require('kafkajs').Kafka;
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
const kafkaClient = new kafka.Kafka({ clientId: 'nfaapi-microservice', brokers: ['localhost:9092'] });
const producer = kafkaClient.producer();
const consumer = kafkaClient.consumer();

app.use(express.json());

async function loadModules(directory) {
  const modules = [];
  fs.readdirSync(directory).forEach(file => {
    if (path.extname(file) === '.js') {
      const modulePath = path.join(directory, file);
      const module = require(modulePath);
      modules.push({ name: file, exports: module });
    }
  });
  return modules;
}

async function executeFunction(module, functionName, params) {
  const fn = module.exports[functionName];
  if (typeof fn === 'function') {
    return fn(params);
  } else {
    throw new Error(`Function ${functionName} not found in module`);
  }
}

app.post('/process', async (req, res) => {
  const { moduleName, functionName, params } = req.body;
  try {
    const modules = await loadModules('./modules');
    const module = modules.find(m => m.name === `${moduleName}.js`);
    if (!module) {
      return res.status(404).send(`Module ${moduleName} not found`);
    }
    const result = await executeFunction(module, functionName, params);
    res.send(result);
  } catch (error) {
    console.error(error);
    res.status(500).send('Internal Server Error');
  }
});

async function startConsumer() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'nfaapi-tasks', fromBeginning: true });
  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      const { moduleName, functionName, params } = JSON.parse(message.value.toString());
      try {
        const modules = await loadModules('./modules');
        const module = modules.find(m => m.name === `${moduleName}.js`);
        if (!module) {
          console.error(`Module ${moduleName} not found`);
          return;
        }
        const result = await executeFunction(module, functionName, params);
        await producer.send({
          topic: 'nfaapi-results',
          messages: [{ value: JSON.stringify(result) }],
        });
      } catch (error) {
        console.error(error);
      }
    },
  });
}

startConsumer();

app.listen(3000, () => {
  console.log('NFAPI Microservice is running on port 3000');
});
