class DynamicNetworkDeviceManager {
public:
    DynamicNetworkDeviceManager(int maxDevices = 1000)
        : maxDevices(maxDevices), devices(maxDevices, nullptr) {}

    ~DynamicNetworkDeviceManager() {
        for (auto& dev : devices) {
            if (dev) {
                delete dev;
            }
        }
    }

    void connectDevice(int deviceId, const std::string& params) {
        std::lock_guard<std::mutex> lock(mutex);
        if (deviceId >= 0 && deviceId < maxDevices) {
            devices[deviceId] = new NetworkDevice(params);
        }
    }

    void disconnectDevice(int deviceId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (deviceId >= 0 && deviceId < maxDevices) {
            delete devices[deviceId];
            devices[deviceId] = nullptr;
        }
    }

    bool checkStatus(int deviceId) const {
        std::lock_guard<std::mutex> lock(mutex);
        if (deviceId >= 0 && deviceId < maxDevices) {
            return devices[deviceId] != nullptr;
        }
        return false;
    }

private:
    struct NetworkDevice {
        explicit NetworkDevice(const std::string& params) {
            // Simulate device connection
            std::cout << "Connecting device with params: " << params << std::endl;
        }
        ~NetworkDevice() {
            // Simulate device disconnection
            std::cout << "Disconnecting device" << std::endl;
        }
    };

    int maxDevices;
    std::vector<NetworkDevice*> devices;
    mutable std::mutex mutex;
};

int main() {
    DynamicNetworkDeviceManager manager;
    manager.connectDevice(0, "params1");
    manager.disconnectDevice(0);
    std::cout << "Device 0 status: " << (manager.checkStatus(0) ? "Connected" : "Disconnected") << std::endl;
    return 0;
}
