    void connectDevice(size_t deviceId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (deviceId >= maxDevices || devices[deviceId]) {
            throw std::invalid_argument("Invalid device ID or already connected");
        }
        devices[deviceId] = true;
        notifyDeviceChange();
    }

    void disconnectDevice(size_t deviceId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (deviceId >= maxDevices || !devices[deviceId]) {
            throw std::invalid_argument("Invalid device ID or not connected");
        }
        devices[deviceId] = false;
        notifyDeviceChange();
    }

    bool isDeviceConnected(size_t deviceId) const {
        if (deviceId >= maxDevices) {
            throw std::invalid_argument("Invalid device ID");
        }
        return devices[deviceId];
    }

private:
    size_t maxDevices;
    std::vector<bool> devices;
    mutable std::mutex mutex;

