use actix_web::{web, App, HttpResponse, HttpServer};
use oauth2::{AuthorizationCode, ClientId, ClientSecret, TokenResponse};
use kms::KeyManagementSystem;
use x509_certificate::{CertificateGenerator, CertificateRequest};

mod oauth2;
mod kms;
mod x509_certificate;

async fn generate_certificate(req: web::Json<CertificateRequest>, client: web::Data<KeyManagementSystem>) -> HttpResponse {
    let cert = CertificateGenerator::new(&req)
        .with_oauth_client(oauth2::Client::from_id_secret(
            ClientId::new("client_id".to_string()),
            ClientSecret::new("client_secret".to_string()),
        ))
        .generate(&*client);

    match cert {
        Ok(cert) => HttpResponse::Ok().body(cert),
        Err(e) => HttpResponse::InternalServerError().body(format!("Error generating certificate: {}", e)),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .app_data(web::Data::new(KeyManagementSystem::new()))
            .route("/generate-certificate", web::post().to(generate_certificate))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
